    public static SemanticCardPackPreview BuildPreview(
        string abilitiesPath,
        string templatesPath,
        string localizationPath,
        SemanticCardPackRecipe recipe)
    {
        ValidateRecipe(recipe);
        AbilityDocument abilities = AbilityDocument.Load(abilitiesPath).DeepClone();
        TemplateDocument templates = TemplateDocument.Load(templatesPath).DeepClone();
        var preview = new SemanticCardPackPreview
        {
            Abilities = abilities,
            Templates = templates
        };

        int? thunderboltInjectable = null;
        int? pantherMovementInjectable = null;
        foreach (SemanticCardPackOperationRecipe operation in recipe.Operations)
        {
            CardRecord card = CardResolver.ResolveUnique(templates, operation.Card);
            XElement ability = abilities.FindRequiredCardAbility(card.Id);
            XElement template = templates.FindById(card.Id)
                ?? throw new InvalidOperationException($"Template {card.Id} не найден.");

            switch (operation.Type.Trim().ToLowerInvariant())
            {
                case "replaceorderwithdeathwish":
                    ReplaceOrderWithDeathwish(ability, template);
                    RequireCard(card, PrizeWinningCow);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=deathwish>Завещание</keyword>: призовите Черта на место этой карты.";
                    preview.Changes.Add($"{card.DebugName}: Order -> Deathwish; effect preserved.");
                    break;

                case "addalternativepowertarget":
                    AddAlternativePowerTarget(ability, operation.PowerMax > 0 ? operation.PowerMax : 2);
                    RequireCard(card, Epidemic);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Уничтожьте отряд со стоимостью найма {Cost} ед. или с силой 2 ед. или меньше.";
                    preview.Changes.Add($"{card.DebugName}: added Power <= 2 as OR target filter.");
                    break;

                case "addadjacentdamage":
                    AddAdjacentDamage(ability, operation.Amount > 0 ? operation.Amount : 1);
                    RequireCard(card, AlzursThunder);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Нанесите {Damage} ед. урона отряду и по 1 ед. урона смежным с ним отрядам.";
                    preview.Changes.Add($"{card.DebugName}: added adjacent damage 1.");
                    break;

                case "addbleedingtounarmoreddamagedrow":
                    AddBleedingToUnarmoredDamagedRow(ability, operation.Duration > 0 ? operation.Duration : 1);
                    RequireCard(card, Lacerate);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Нанесите по {Damage} ед. урона всем отрядам в ряду, затем добавьте " +
                        "<keyword=bleeding>кровотечение</keyword> на 1 ход всем выжившим отрядам, " +
                        "у которых до урона не было брони.";
                    preview.Warnings.Add(
                        "Lacerate: броня проверяется до нанесения урона; " +
                        "отдельно проверьте в игре взаимодействие со Щитом/неуязвимостью.");
                    preview.Changes.Add($"{card.DebugName}: added Bleeding 1 to survivors that had no armor before damage.");
                    break;

                case "prependpoisonbeforedamage":
                    PrependPoisonBeforeDamage(ability);
                    RequireCard(card, ArachasVenom);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Добавьте <keyword=poison>яд</keyword> отряду и нанесите ему {Damage} ед. урона.\\n" +
                        "<keyword=deathblow>Расправа</keyword>: нанесите по {Damage} ед. урона смежным с ним отрядам.";
                    preview.Changes.Add($"{card.DebugName}: Poison is applied before the existing damage/deathblow chain.");
                    break;

                case "convertswallowtoartifact":
                    ConvertSwallowToArtifact(
                        ability,
                        template,
                        operation.DeployAmount > 0 ? operation.DeployAmount : 2,
                        operation.OrderAmount > 0 ? operation.OrderAmount : 3);
                    RequireCard(card, Swallow);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=deploy>Размещение</keyword>: усильте смежные отряды на 2 ед.\\n" +
                        "<keyword=order>Приказ</keyword>: выберите дружественный отряд. Если это ведьмак, сначала " +
                        "исцелите его. Затем усильте выбранный отряд на 3 ед. Если это ведьмак, также добавьте ему " +
                        "<keyword=infused>настой</keyword> («{InjectableAbility}».).";
                    preview.Changes.Add($"{card.DebugName}: Special -> Artifact with Deploy + Order + Witcher infusion.");
                    break;

                case "boostplayedunit":
                    AddBoostAfterPlay(ability, operation.Amount > 0 ? operation.Amount : 2);
                    if (card.Id == AlzursDoubleCross)
                    {
                        preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                            "Сыграйте сильнейший отряд из вашей колоды и усильте его на 2 ед.";
                    }
                    else if (card.Id == MarchingOrders)
                    {
                        preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                            "Сыграйте слабейший отряд из вашей колоды и усильте его на 2 ед.";
                    }
                    else
                    {
                        throw new InvalidOperationException("BoostPlayedUnit 0.27.9 поддерживает Double-Cross и Marching Orders.");
                    }
                    preview.Changes.Add($"{card.DebugName}: played unit is boosted by 2.");
                    break;

                case "replacewithdynamicpoison":
                    ReplaceWithDynamicPoison(
                        ability,
                        operation.MinTargets > 0 ? operation.MinTargets : 1,
                        operation.MaxTargets > 0 ? operation.MaxTargets : 2);
                    RequireCard(card, ManticoreVenom);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Добавьте <keyword=poison>яд</keyword> до 2 вражеским отрядам, чья сила меньше силы " +
                        "сильнейшего дружественного отряда.";
                    preview.Changes.Add($"{card.DebugName}: dynamic strongest-friendly threshold; choose 1–2 targets.");
                    break;

                case "addwitcherdamageinfusion":
                    RequireCard(card, Thunderbolt);
                    int? existingInfusion = FindExistingInfusionAbilityId(ability);
                    bool createdInfusion = !existingInfusion.HasValue;
                    thunderboltInjectable ??= existingInfusion ?? CreateRandomEnemyDamageInjectable(
                        abilities,
                        operation.Damage > 0 ? operation.Damage : 1);
                    if (createdInfusion)
                    {
                        AddWitcherInfusion(ability, thunderboltInjectable.Value, heal: false);
                        preview.AddedInjectableAbilityId = thunderboltInjectable;
                    }
                    NormalizeInfusionVariableName(ability, thunderboltInjectable.Value);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=deploy>Размещение</keyword>: усильте дружественный отряд на {Boost} ед.\\n" +
                        "<keyword=order>Приказ</keyword>: усильте дружественный отряд на {Boost} ед.\\n" +
                        "Если усиленный отряд был ведьмаком, добавьте ему <keyword=infused>настой</keyword> " +
                        "(«{InjectableAbility}».).";
                    preview.LocalizationEdits[$"{thunderboltInjectable.Value}_name_ia"] = "N/A";
                    preview.LocalizationEdits[$"{thunderboltInjectable.Value}_tooltip_ia"] =
                        "В конце вашего хода нанесите 1 ед. урона случайному вражескому отряду.";
                    preview.Changes.Add(createdInfusion
                        ? $"{card.DebugName}: added Witcher-only random-enemy damage infusion Id={thunderboltInjectable}."
                        : $"{card.DebugName}: existing infusion Id={thunderboltInjectable} reused; no duplicate graph added.");
                    break;

                case "restrictinfusiontoorder":
                    RequireCard(card, Thunderbolt);
                    bool thunderboltSplit = RestrictInfusionToOrder(ability);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=deploy>Размещение</keyword>: усильте дружественный отряд на {Boost} ед.\\n" +
                        "<keyword=order>Приказ</keyword>: усильте дружественный отряд на {Boost} ед. " +
                        "Если это ведьмак, добавьте ему <keyword=infused>настой</keyword> " +
                        "(«{InjectableAbility}».).";
                    preview.Changes.Add(thunderboltSplit
                        ? $"{card.DebugName}: Deploy and Order target/boost branches split; Infusion remains Order-only."
                        : $"{card.DebugName}: Infusion was already restricted to the Order branch.");
                    break;

                case "prependpurifybeforelock":
                    RequireCard(card, DimeritiumShackles);
                    PrependPurifyBeforeLock(ability);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=purify>Очистите</keyword> отряд, затем " +
                        "<keyword=lock>заблокируйте</keyword> его и нанесите ему {Damage} ед. урона.";
                    preview.Changes.Add($"{card.DebugName}: Purify now resolves before Lock and damage.");
                    break;

                case "adddeployboosthandtargets":
                    RequireCard(card, FrancisBedlam);
                    bool addedFrancisDeploy = AddDeployBoostHandTargets(
                        ability,
                        operation.MaxTargets > 0 ? operation.MaxTargets : 2,
                        operation.Amount > 0 ? operation.Amount : 1);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=veil>Покров</keyword>.\\n" +
                        "<keyword=deploy>Размещение</keyword>: усильте 2 отряда в вашей руке на 1 ед.\\n" +
                        "В конце вашего хода усильте слабейший отряд в вашей руке на {Boost} ед.";
                    preview.Changes.Add(addedFrancisDeploy
                        ? $"{card.DebugName}: added Deploy choice boost for 2 units in hand."
                        : $"{card.DebugName}: Deploy choice boost already present; no duplicate graph added.");
                    break;

                case "addinspiredorderdamage":
                    RequireCard(card, AedirnianMauler);
                    bool addedInspiredDamage = AddInspiredOrderDamage(
                        ability,
                        operation.Damage > 0 ? operation.Damage : 4);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=order>Приказ</keyword> (<keyword=melee>рукопашный ряд</keyword>): " +
                        "нанесите {Damage} ед. урона вражескому отряду.\\n" +
                        "<keyword=inspired>Воодушевление</keyword>: вместо этого нанесите {Damage2} ед. урона.";
                    preview.Changes.Add(addedInspiredDamage
                        ? $"{card.DebugName}: added Inspired branch; Order damage becomes 4 instead."
                        : $"{card.DebugName}: Inspired branch already present; no duplicate graph added.");
                    break;

                case "adddeathblowfrosttodestroyedrows":
                    RequireCard(card, Blizzard);
                    bool addedBlizzardDeathblow = AddDeathblowFrostToDestroyedRows(
                        ability,
                        operation.Duration > 0 ? operation.Duration : 1);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Уничтожьте слабейший отряд.\\n" +
                        "<keyword=initiative>Инициатива</keyword>: вместо этого уничтожьте все слабейшие отряды.\\n" +
                        "<keyword=deathblow>Расправа</keyword>: если уничтожен хотя бы 1 отряд в ряду, " +
                        "<keyword=spawn>создайте</keyword> там эффект <keyword=frost>мороза</keyword> на 1 х.";
                    preview.Changes.Add(addedBlizzardDeathblow
                        ? $"{card.DebugName}: added Deathblow frost to every row where at least one unit was destroyed."
                        : $"{card.DebugName}: Deathblow frost already present; no duplicate graph added.");
                    break;

                case "addrowhealbeforeboost":
                    RequireCard(card, ClearSkies);
                    bool addedClearSkiesHeal = AddRowHealBeforeBoost(
                        ability,
                        operation.Amount > 0 ? operation.Amount : 1);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Исцелите все отряды в ряду на 1 ед., затем усильте их на {Boost} ед.";
                    preview.Changes.Add(addedClearSkiesHeal
                        ? $"{card.DebugName}: added row heal before the existing row boost."
                        : $"{card.DebugName}: row heal before boost already present; no duplicate graph added.");
                    break;

                case "replacehailstormwithweatherbonus":
                    RequireCard(card, MerigoldsHailstorm);
                    bool changedHailstorm = ReplaceHailstormWithWeatherBonus(
                        ability,
                        operation.Damage > 0 ? operation.Damage : 1,
                        operation.Amount > 0 ? operation.Amount : 2,
                        operation.Duration > 0 ? operation.Duration : 2);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "Нанесите по {Damage} ед. урона {Maxtargets} вражеским отрядам, затем " +
