                        "<keyword=profit>Выгода</keyword> {Profit}. Увеличьте выгоду на 1 ед. за каждый отряд со способностью <keyword=insanity>Безумие</keyword> в вашей руке.\\n" +
                        igorOriginalTooltip;
                    preview.Changes.Add($"{card.DebugName}: retained safe hand-Madness Profit and removed {removedIgorHooks} experimental end-turn Madness hooks.");
                    break;

                case "rebuilddonarbloodthirstaura":
                    RequireCard(card, DonarAnHindar);
                    int bloodthirstCards = RebuildDonarBloodthirstAura(ability, template, abilities, templates);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=order>Приказ</keyword>: нанесите 2 ед. урона отряду.\\n" +
                        "Пока этот отряд находится на поле, активируйте <keyword=bloodthirst>жажду крови</keyword> у каждой сыгранной вами бронзовой карты.";
                    preview.Changes.Add($"{card.DebugName}: rebuilt with damage Order and Donar-presence bypass for Bloodthirst on {bloodthirstCards} bronze card abilities.");
                    break;

                case "addskjallclashorder":
                    RequireCard(card, Skjall);
                    AddSkjallClashOrder(ability, template);
                    preview.LocalizationEdits[$"{card.Id}_tooltip"] =
                        "<keyword=berserk>Берсерк</keyword> {Berserk}: уничтожьте эту карту.\\n" +
                        "<keyword=order>Приказ</keyword>: устройте <keyword=clash>столкновение</keyword> с вражеским отрядом.";
                    preview.Changes.Add($"{card.DebugName}: added one-use Clash Order while preserving Berserk.");
                    break;

                default:
                    throw new InvalidOperationException($"Неподдерживаемая semantic pack operation: {operation.Type}");
            }

            if (!preview.ChangedCardIds.Contains(card.Id))
                preview.ChangedCardIds.Add(card.Id);
        }

        if (preview.ChangedCardIds.Contains(VattierDeRideaux))
        {
            foreach (int hookedCardId in InstallVattierOpponentDeckLookGrowth(abilities))
            {
                if (!preview.ChangedCardIds.Contains(hookedCardId))
                    preview.ChangedCardIds.Add(hookedCardId);
            }
        }

        if (preview.ChangedCardIds.Contains(LyrianCavalry))
        {
            XElement lyrian = abilities.FindRequiredCardAbility(LyrianCavalry);
            NormalizeAbilityNId(lyrian);
            RequireValidAbilityNId(lyrian, "Final preview normalization");
        }

        // Madam Luiza shares Tribute SubAbility 18 with every Tribute card. Restore that shared
        // graph from Clean only after all card operations, so no experimental game-scope flag can
        // survive and crash Tinboy, Eveline Gallo, Renegade Mage or any other Tribute card.
        if (preview.ChangedCardIds.Contains(MadamLuiza))
        {
            FinalizeMadamLuizaVanillaTribute(abilities, abilitiesPath);
            RequireMadamLuizaVanillaTributeState(abilities, "Final preview normalization");
        }

        EnsureInjectableLocalizations(
            abilities,
            preview.ChangedCardIds,
            localizationPath,
            preview.LocalizationEdits,
            preview.Warnings);

        foreach (int cardId in preview.ChangedCardIds)
        {
            XElement ability = abilities.FindRequiredCardAbility(cardId);
            GraphValidationReport validation = GraphValidator.Validate(ability);
            preview.Validation[cardId] = validation;
            if (!validation.IsValid)
            {
                string errors = string.Join(Environment.NewLine, validation.Issues
                    .Where(issue => issue.Severity == ValidationSeverity.Error)
                    .Select(issue => $"[{issue.Code}] {issue.Message}"));
                throw new InvalidOperationException($"CardAbility {cardId} INVALID:{Environment.NewLine}{errors}");
            }
            foreach (ValidationIssue issue in validation.Issues.Where(i => i.Severity == ValidationSeverity.Warning))
                preview.Warnings.Add($"CardAbility {cardId}: [{issue.Code}] {issue.Message}");
        }

        foreach ((string key, string value) in preview.LocalizationEdits)
        {
            try
            {
                LocalizationService.ValidateLocalizationValue(value);
            }
            catch (InvalidOperationException ex)
            {
                throw new InvalidOperationException($"Localization {key}: {ex.Message}", ex);
            }

            if (key.EndsWith("_tooltip", StringComparison.Ordinal))
            {
                int cardId = int.Parse(key[..key.IndexOf('_')]);
                IReadOnlyList<string> unknown = LocalizationService.FindUnknownPlaceholders(
                    abilities, cardId, value);
                foreach (string placeholder in unknown)
                    preview.Warnings.Add($"{key}: неизвестный placeholder {{{placeholder}}}.");
            }
        }

        return preview;
    }

    public static SemanticCardPackResult ApplyAndSave(
        string abilitiesPath,
        string templatesPath,
        string localizationPath,
        SemanticCardPackRecipe recipe,
        string outputDirectory,
        bool overwrite)
    {
        SemanticCardPackPreview preview = BuildPreview(
            abilitiesPath, templatesPath, localizationPath, recipe);
        string fullOutput = Path.GetFullPath(outputDirectory.Trim().Trim('"'));
        if (Directory.Exists(fullOutput) && !overwrite)
            throw new IOException($"Выходной каталог уже существует: {fullOutput}");
        if (File.Exists(fullOutput))
            throw new IOException($"Путь занят файлом: {fullOutput}");

        string parent = Path.GetDirectoryName(fullOutput)
            ?? throw new InvalidOperationException("Не удалось определить родительский каталог.");
        Directory.CreateDirectory(parent);
        string staging = Path.Combine(parent, "." + Path.GetFileName(fullOutput) + "." + Guid.NewGuid().ToString("N") + ".staging");
        string abilitiesOutput = Path.Combine(staging, "Abilities.modified.xml");
        string templatesOutput = Path.Combine(staging, "Templates.modified.xml");
        string localizationOutput = Path.Combine(staging, "ru-ru.modified.csv");
        string reportOutput = Path.Combine(staging, "semantic-card-pack-report.txt");

        try
        {
            Directory.CreateDirectory(staging);
            if (preview.ChangedCardIds.Contains(LyrianCavalry))
            {
                XElement lyrian = preview.Abilities.FindRequiredCardAbility(LyrianCavalry);
                NormalizeAbilityNId(lyrian);
                RequireValidAbilityNId(lyrian, "Pre-save normalization");
            }
            preview.Abilities.SaveAs(abilitiesOutput, false);

            preview.Templates.SaveAs(templatesOutput, false);
            LocalizationService.ApplyEditsAndSave(
                localizationPath, preview.LocalizationEdits, localizationOutput, false);
            File.WriteAllText(reportOutput, BuildReport(recipe, preview), new UTF8Encoding(false));

            AbilityDocument savedAbilities = AbilityDocument.Load(abilitiesOutput);
            TemplateDocument.Load(templatesOutput);
            if (preview.ChangedCardIds.Contains(MadamLuiza))
                RequireMadamLuizaVanillaTributeState(savedAbilities, "Serialized output validation");
            if (preview.ChangedCardIds.Contains(LyrianCavalry))
            {
                RequireValidAbilityNId(
                    savedAbilities.FindRequiredCardAbility(LyrianCavalry),
                    "Serialized output validation");
            }

            // Always validate the serialized White Frost graph, even when no semantic
            // operation reported it as changed. This catches stale/broken endpoints
            // before the staging directory is promoted.
            GraphValidationReport savedWhiteFrostValidation = GraphValidator.Validate(
                savedAbilities.FindRequiredCardAbility(WhiteFrost));
            if (!savedWhiteFrostValidation.IsValid)
            {
                string errors = string.Join(Environment.NewLine, savedWhiteFrostValidation.Issues
                    .Where(issue => issue.Severity == ValidationSeverity.Error)
                    .Select(issue => $"[{issue.Code}] {issue.Message}"));
                throw new InvalidDataException(
                    $"Сохранённый CardAbility {WhiteFrost} не прошёл повторную проверку:{Environment.NewLine}{errors}");
            }

            foreach (int cardId in preview.ChangedCardIds)
            {
                GraphValidationReport validation = GraphValidator.Validate(
                    savedAbilities.FindRequiredCardAbility(cardId));
                if (!validation.IsValid)
                    throw new InvalidDataException($"Сохранённый CardAbility {cardId} не прошёл повторную проверку.");
            }
            foreach ((string key, string expected) in preview.LocalizationEdits)
            {
                string? actual = LocalizationService.ReadValue(localizationOutput, key);
                if (!string.Equals(actual, expected, StringComparison.Ordinal))
                    throw new InvalidDataException($"Проверка локализации {key} не пройдена.");
            }

            string? backup = null;
            try
            {
                if (Directory.Exists(fullOutput))
                {
                    backup = fullOutput + "." + Guid.NewGuid().ToString("N") + ".backup";
                    Directory.Move(fullOutput, backup);
                }
                Directory.Move(staging, fullOutput);
                if (backup != null && Directory.Exists(backup))
                    Directory.Delete(backup, true);
            }
            catch
            {
                if (!Directory.Exists(fullOutput) && backup != null && Directory.Exists(backup))
                    Directory.Move(backup, fullOutput);
                throw;
            }
        }
        catch
        {
            if (Directory.Exists(staging))
                Directory.Delete(staging, true);
            throw;
        }

        return new SemanticCardPackResult
        {
            OutputDirectory = fullOutput,
            AbilitiesFile = Path.Combine(fullOutput, "Abilities.modified.xml"),
            TemplatesFile = Path.Combine(fullOutput, "Templates.modified.xml"),
            LocalizationFile = Path.Combine(fullOutput, "ru-ru.modified.csv"),
            ReportFile = Path.Combine(fullOutput, "semantic-card-pack-report.txt"),
            Preview = preview
        };
    }

    private static void RestoreSavedCardAbilityFromSource(
        string savedAbilitiesPath,
        string sourceAbilitiesPath,
        int cardId)
    {
        XDocument source = XDocument.Load(sourceAbilitiesPath, LoadOptions.PreserveWhitespace);
        XDocument saved = XDocument.Load(savedAbilitiesPath, LoadOptions.PreserveWhitespace);

        XElement sourceAbility = source.Root?.Elements("Ability").SingleOrDefault(element =>
            string.Equals((string?)element.Attribute("Type"), "CardAbility", StringComparison.Ordinal) &&
            (int?)element.Attribute("Id") == cardId)
            ?? throw new InvalidDataException($"Исходный CardAbility {cardId} не найден.");
        XElement savedAbility = saved.Root?.Elements("Ability").SingleOrDefault(element =>
            string.Equals((string?)element.Attribute("Type"), "CardAbility", StringComparison.Ordinal) &&
            (int?)element.Attribute("Id") == cardId)
            ?? throw new InvalidDataException($"Сохранённый CardAbility {cardId} не найден.");

        GraphValidationReport sourceValidation = GraphValidator.Validate(sourceAbility);
        if (!sourceValidation.IsValid)
        {
            string errors = string.Join(Environment.NewLine, sourceValidation.Issues
                .Where(issue => issue.Severity == ValidationSeverity.Error)
                .Select(issue => $"[{issue.Code}] {issue.Message}"));
            throw new InvalidDataException(
                $"Исходный CardAbility {cardId} повреждён и не может быть использован для восстановления:{Environment.NewLine}{errors}");
        }

        savedAbility.ReplaceWith(new XElement(sourceAbility));
        saved.Save(savedAbilitiesPath, SaveOptions.DisableFormatting);
    }

    private static void EnsureInjectableLocalizations(
        AbilityDocument abilities,
        IEnumerable<int> changedCardIds,
        string localizationPath,
        IReadOnlyDictionary<string, string> localizationEdits,
        ICollection<string> warnings)
    {
        foreach (int cardId in changedCardIds.Distinct())
        {
            XElement ability = abilities.FindRequiredCardAbility(cardId);
            string cardTooltipKey = $"{cardId}_tooltip";
            string cardTooltip = localizationEdits.TryGetValue(cardTooltipKey, out string? editedTooltip)
                ? editedTooltip
                : LocalizationService.ReadValue(localizationPath, cardTooltipKey) ?? "";

            IEnumerable<XElement> variables = ability.Element("TemporaryVariables")?
                .Elements()
                .Where(variable =>
                    string.Equals(
                        (string?)variable.Attribute("Type"),
                        "InjectableAbilityVar",
                        StringComparison.Ordinal))
                ?? Enumerable.Empty<XElement>();

            foreach (XElement variable in variables)
            {
                int injectableId = (int?)variable.Attribute("V") ?? 0;
                string variableName = (string?)variable.Attribute("Name") ?? "";
                if (injectableId <= 0)
                    continue;

                string key = $"{injectableId}_tooltip_ia";
                string? value = localizationEdits.TryGetValue(key, out string? edited)
                    ? edited
                    : LocalizationService.ReadValue(localizationPath, key);
                if (string.IsNullOrWhiteSpace(value))
                {
                    throw new InvalidOperationException(
                        $"Для InjectableAbility Id={injectableId}, используемой картой {cardId}, " +
                        $"отсутствует непустая локализация {key}.");
                }

                if (!string.IsNullOrWhiteSpace(variableName) &&
                    !cardTooltip.Contains($"{{{variableName}}}", StringComparison.Ordinal))
                {
                    warnings.Add(
                        $"{cardId}: tooltip не содержит placeholder {{{variableName}}} " +
                        $"для InjectableAbility Id={injectableId}. Описание настоя не будет показано в тексте карты.");
                }
            }
        }
    }

    private static void ReplaceOrderWithDeathwish(XElement ability, XElement template)
    {
        // Prize-Winning Cow must not transform while already in the graveyard.
        // Rebuild the branch as a native Deathwish: after the Cow dies, summon
        // a Fiend (TemplateId 200320) into the row it occupied.
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);

        KilledEndpoints killed = editor.AddKilledTrigger();
        CardLocationEndpoints location = editor.AddGetCardLocationId(positionType: 2);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        PositionEndpoints position = editor.AddGetRandomLastAvailablePosition();
        SpawnEndpoints spawn = editor.AddSpawnCard(templateId: 200320, count: 1, spawnType: 3);

        editor.AddConnection(killed.CardKilled, location.Card);
        editor.AddConnection(location.Location, position.Location);
        editor.AddConnection(ownerPlayer, position.PlayerId);
        editor.AddConnection(position.Position, spawn.Position);
        editor.AddConnection(killed.CardKilled, spawn.Spawner);
        editor.AddConnection(killed.FlowOutDeath, spawn.FlowIn);

        SetTemplateText(template, "TapActive", "False");
        SetTemplateText(template, "InitalTapCharges", "0");
        SetTemplateText(template, "VisibleTapCharges", "False");
        editor.Finish();
    }

    private static void AddAlternativePowerTarget(XElement ability, int powerMax)
    {
        var editor = new GraphEditor(ability);
        XElement filterList = FindNode(ability, "FilterCardListNode");
        XElement provision = FindNode(ability, "FilterCardProvisionNode");
        int filterInput = Id(filterList.Element("Filters")!.Elements().Single());
        int provisionOut = Id(provision.Element("Out")!);

        // Clean native graph: Provision.Out goes directly into FilterCardList.Filter.
        if (editor.TryRemoveConnection(provisionOut, filterInput))
        {
            NodeEndpoints power = editor.AddFilterCardPower(compareOp: 4, power: powerMax);
            LogicEndpoints logic = editor.AddFilterLogic(orOperation: true);
            editor.AddConnection(provisionOut, logic.Input0);
            editor.AddConnection(power.Out, logic.Input1);
            editor.AddConnection(logic.Out, filterInput);
            editor.Finish();
            return;
        }

        IReadOnlyList<int> incoming = editor.GetIncomingSources(filterInput);
        if (incoming.Count != 1)
        {
            throw new InvalidOperationException(
                $"Epidemic: вход фильтра {filterInput} должен иметь одно соединение, найдено {incoming.Count}. " +
                "Операция не будет угадывать структуру изменённого графа.");
        }

        int currentSource = incoming[0];
        XElement? currentNode = editor.FindNodeOwningEndpoint(currentSource);
        if (currentNode != null &&
            string.Equals((string?)currentNode.Attribute("Type"), "FilterCardLogicNode", StringComparison.Ordinal) &&
            IsProvisionOrPowerFilter(editor, currentNode, provisionOut, powerMax))
        {
            // The 0.27.6/0.27.7 Epidemic change is already present. Re-applying
            // the pack must be a no-op rather than failing on 159 -> 154.
            editor.Finish();
            return;
        }

        // Preserve any existing custom filter by wrapping it in a new OR expression.
        // This makes the operation compatible with cumulative user mod files while
        // still avoiding raw endpoint IDs.
        editor.RemoveConnection(currentSource, filterInput);
        NodeEndpoints fallbackPower = editor.AddFilterCardPower(compareOp: 4, power: powerMax);
        LogicEndpoints fallbackLogic = editor.AddFilterLogic(orOperation: true);
        editor.AddConnection(currentSource, fallbackLogic.Input0);
        editor.AddConnection(fallbackPower.Out, fallbackLogic.Input1);
        editor.AddConnection(fallbackLogic.Out, filterInput);
        editor.Finish();
    }

    private static bool IsProvisionOrPowerFilter(
        GraphEditor editor,
        XElement logicNode,
        int provisionOut,
        int powerMax)
    {
        if ((string?)logicNode.Element("Op")?.Attribute("V") != "1")
            return false;

        XElement? inputs = logicNode.Element("Ins");
        if (inputs == null)
            return false;
        List<int> inputIds = inputs.Elements()
            .Select(element => (int?)element.Attribute("Id"))
            .Where(value => value.HasValue)
            .Select(value => value!.Value)
            .ToList();
        if (inputIds.Count < 2)
            return false;

        bool hasProvision = inputIds.Any(input => editor.HasConnection(provisionOut, input));
        if (!hasProvision)
            return false;

        foreach (int input in inputIds)
        {
            foreach (int source in editor.GetIncomingSources(input))
            {
                XElement? owner = editor.FindNodeOwningEndpoint(source);
                if (owner == null ||
                    !string.Equals((string?)owner.Attribute("Type"), "FilterCardPowerNode", StringComparison.Ordinal))
                    continue;
                if ((string?)owner.Element("Op")?.Attribute("V") != "4")
                    continue;
                XElement? power = owner.Element("Power");
                if (power == null)
                    continue;
                power.SetAttributeValue("V", powerMax);
                return true;
            }
        }
        return false;
    }

    private static void AddAdjacentDamage(XElement ability, int amount)
    {
        var editor = new GraphEditor(ability);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement shape = request.Element("Shape")?.Element("V")
            ?? throw new InvalidDataException("RequestCardTargetsNode не содержит Shape/V.");
        shape.SetAttributeValue("PivotX", "4");
        shape.SetAttributeValue("PivotY", "1");
        shape.SetAttributeValue("Mask", "40960");

        XElement main = FindNode(ability, "ChangePowerNode");
        XElement owner = FindNode(ability, "GetAbilityOwnerNode");
        int selectedTargets = Id(request.Element("SelectedTargets")!);
        int mainFlowOut = Id(main.Element("FlowOut")!);

        XElement? existingSplash = ability.Element("Nodes")!.Elements()
            .Where(node => !ReferenceEquals(node, main))
            .Where(node => string.Equals(
                (string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal))
            .FirstOrDefault(node =>
                (string?)node.Element("Operation")?.Attribute("V") == "1" &&
                (string?)node.Element("Power")?.Attribute("V") == amount.ToString());

        if (existingSplash != null)
        {
            CopyPowerVisualParameters(main, existingSplash);

            // Upgrade old splash chains in place instead of adding a second
            // point of adjacent damage. The explicit GetCardsInShape chain is
            // intentionally independent of RequestCardTargetsNode.TargetsInShape:
            // in-game that output can still include the primary target.
            int splashFlowIn = Id(existingSplash.Element("FlowIn")!);
            IReadOnlyList<int> incoming = editor.GetIncomingSources(splashFlowIn);
            if (incoming.Count == 0)
                editor.AddConnection(mainFlowOut, splashFlowIn);

            int explicitAdjacentTargets = EnsureExplicitAdjacentTargets(editor, existingSplash, selectedTargets);
            editor.RemoveIncomingConnections(Id(existingSplash.Element("Targets")!));
            editor.AddConnection(explicitAdjacentTargets, Id(existingSplash.Element("Targets")!));
            editor.Finish();
            return;
        }

        // Clean native graph: create one splash node and target an explicit
        // adjacent-list query around the selected unit.
        int adjacentTargets = BuildAdjacentTargetsFromSelected(editor, selectedTargets);
        PowerEndpoints splash = editor.AddChangePower(
            amount,
            operation: 1,
            elementType: ReadIntValue(main, "ElementType"),
            attackMethod: ReadIntValue(main, "AttackMethod"),
            effectType: ReadIntValue(main, "EffectType"));
        editor.AddConnection(mainFlowOut, splash.FlowIn);
        editor.AddConnection(adjacentTargets, splash.Targets);
        editor.AddConnection(Id(owner.Element("Out")!), splash.Attacker);
        editor.Finish();
    }

    private static int EnsureExplicitAdjacentTargets(
        GraphEditor editor,
        XElement splashNode,
        int selectedTargets)
    {
        int splashTargets = Id(splashNode.Element("Targets")!);
        foreach (int source in editor.GetIncomingSources(splashTargets))
        {
            XElement? owner = editor.FindNodeOwningEndpoint(source);
            if (IsAdjacentShapeNode(owner))
                return source;
        }

        return BuildAdjacentTargetsFromSelected(editor, selectedTargets);
    }

    private static int BuildAdjacentTargetsFromSelected(GraphEditor editor, int selectedTargets)
    {
        CardElementEndpoints selected = editor.AddCardListGetElement(index: 0);
        CardPositionEndpoints position = editor.AddGetCardPosition(positionType: 0);
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        editor.AddConnection(selectedTargets, selected.List);
        editor.AddConnection(selected.Card, position.Card);
        editor.AddConnection(position.Position, adjacent.Position);
        return adjacent.Cards;
    }

    private static bool IsAdjacentShapeNode(XElement? node)
    {
        XElement? shape = node?.Element("Shape")?.Element("V");
        return node != null &&
            string.Equals((string?)node.Attribute("Type"), "GetCardsInShapeNode", StringComparison.Ordinal) &&
            (string?)shape?.Attribute("PivotX") == "4" &&
            (string?)shape?.Attribute("PivotY") == "1" &&
            (string?)shape?.Attribute("Mask") == "40960";
    }

    private static void PrependPoisonBeforeDamage(XElement ability)
    {
        var editor = new GraphEditor(ability);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement main = FindNode(ability, "ChangePowerNode");
        XElement owner = FindNode(ability, "GetAbilityOwnerNode");
        int success = Id(request.Element("FlowOutSuccess")!);
        int mainInput = Id(main.Element("FlowIn")!);

        IReadOnlyList<int> incoming = editor.GetIncomingSources(mainInput);
        if (incoming.Count == 1)
        {
            XElement? sourceNode = editor.FindNodeOwningEndpoint(incoming[0]);
            if (sourceNode != null &&
                string.Equals((string?)sourceNode.Attribute("Type"), "ChangeTokensNode", StringComparison.Ordinal) &&
                (string?)sourceNode.Element("Tokens")?.Attribute("V") == "64")
            {
                // Poison is already immediately before the native damage node.
                editor.Finish();
                return;
            }
        }

        int previousFlow;
        if (editor.TryRemoveConnection(success, mainInput))
        {
            previousFlow = success;
        }
        else
        {
            if (incoming.Count != 1)
            {
                throw new InvalidOperationException(
                    $"Arachas Venom: вход основного урона {mainInput} должен иметь одно соединение, " +
                    $"найдено {incoming.Count}.");
            }
            previousFlow = incoming[0];
            editor.RemoveConnection(previousFlow, mainInput);
        }

        TokenEndpoints poison = editor.AddPoison();
        editor.AddConnection(previousFlow, poison.FlowIn);
        editor.AddConnection(poison.FlowOut, mainInput);
        editor.AddConnection(Id(request.Element("SelectedTargets")!), poison.Targets);
        editor.AddConnection(Id(owner.Element("Out")!), poison.Attacker);
        editor.Finish();
    }

    private static void PrependPurifyBeforeLock(XElement ability)
    {
        var editor = new GraphEditor(ability);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement lockNode = ability.Element("Nodes")?.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangeTokensNode", StringComparison.Ordinal) &&
            (string?)node.Element("Tokens")?.Attribute("V") == "4")
            ?? throw new InvalidOperationException("Dimeritium Shackles: lock ChangeTokensNode не найден.");

        int success = Id(request.Element("FlowOutSuccess")!);
        int lockInput = Id(lockNode.Element("FlowIn")!);
        int selectedTargets = Id(request.Element("SelectedTargets")!);

        IReadOnlyList<int> incoming = editor.GetIncomingSources(lockInput);
        if (incoming.Count == 1)
        {
            XElement? sourceNode = editor.FindNodeOwningEndpoint(incoming[0]);
            if (IsPurifySubAbility(sourceNode) &&
                editor.HasConnection(selectedTargets, FindPurifyTargets(sourceNode!)))
            {
                editor.Finish();
                return;
            }
        }

        int previousFlow;
        if (editor.TryRemoveConnection(success, lockInput))
        {
            previousFlow = success;
        }
        else
        {
            if (incoming.Count != 1)
            {
                throw new InvalidOperationException(
                    $"Dimeritium Shackles: вход lock {lockInput} должен иметь одно соединение, " +
                    $"найдено {incoming.Count}.");
            }
            previousFlow = incoming[0];
            editor.RemoveConnection(previousFlow, lockInput);
        }

        PurifyEndpoints purify = editor.AddPurifySubAbility();
        editor.AddConnection(previousFlow, purify.FlowIn);
        editor.AddConnection(purify.FlowOut, lockInput);
        editor.AddConnection(selectedTargets, purify.Targets);
        editor.Finish();
    }

    private static bool IsPurifySubAbility(XElement? node) =>
        node != null &&
        string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
        node.Element("SubAbilityID")?.Value == "45";

    private static int FindPurifyTargets(XElement purifyNode)
    {
        XElement? mapping = purifyNode.Element("VarMappings")?.Elements().FirstOrDefault(element =>
            element.Element("Data")?.Attribute("Type")?.Value == "CardListVar" &&
            element.Element("IdOfDataInAbility")?.Value == "34" &&
            element.Element("IsInput")?.Value == "True");
        if (mapping == null)
            throw new InvalidDataException("Purify UseSubAbilityNode не содержит Targets mapping.");
        return Id(mapping.Element("Data")!);
    }

    private static void AddBoostAfterPlay(XElement ability, int amount)
    {
        var editor = new GraphEditor(ability);
        XElement play = FindNode(ability, "PlayCardsNode");
        int playFlowOut = Id(play.Element("FlowOut")!);
        int playedCards = Id(play.Element("CardsToPlay")!);

        bool alreadyApplied = ability.Element("Nodes")!.Elements()
            .Where(node => string.Equals(
                (string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal))
            .Any(node =>
                (string?)node.Element("Operation")?.Attribute("V") == "0" &&
                (string?)node.Element("Power")?.Attribute("V") == amount.ToString() &&
                editor.HasConnection(playFlowOut, Id(node.Element("FlowIn")!)) &&
                editor.HasConnection(playedCards, Id(node.Element("Targets")!)));
        if (alreadyApplied)
        {
            editor.Finish();
            return;
        }

        PowerEndpoints boost = editor.AddChangePower(amount, operation: 0);
        int ownerOut = editor.AddGetAbilityOwner();
        editor.AddConnection(playFlowOut, boost.FlowIn);
        editor.AddConnection(playedCards, boost.Targets);
        editor.AddConnection(ownerOut, boost.Attacker);
        editor.Finish();
    }

    private static void AddBleedingToUnarmoredDamagedRow(XElement ability, int duration)
    {
        var editor = new GraphEditor(ability);
        if (HasStrictBleedingFragment(ability, duration))
        {
            editor.Finish();
            return;
        }

        XElement damage = FindNode(ability, "ChangePowerNode");
        XElement originalCards = FindNode(ability, "GetCardsNode");
        int damageInput = Id(damage.Element("FlowIn")!);
        IReadOnlyList<int> damageInputs = editor.GetIncomingSources(damageInput);
        if (damageInputs.Count != 1)
        {
            throw new InvalidOperationException(
                $"Lacerate: вход основного урона {damageInput} должен иметь одно соединение, найдено {damageInputs.Count}.");
        }
        int flowBeforeDamage = damageInputs[0];
        editor.RemoveConnection(flowBeforeDamage, damageInput);

        GetCardsEndpoints currentCards = editor.AddGetCards();

        foreach ((string fieldName, int newDestination) in new[]
        {
            ("PlayerId", currentCards.PlayerId),
            ("LocationId", currentCards.LocationId)
        })
        {
            int oldDestination = Id(originalCards.Element(fieldName)!);
            int source = editor.Connections.Elements()
                .Where(connection => (int?)connection.Attribute("DstId") == oldDestination)
                .Select(connection => (int)connection.Attribute("SrcId")!)
                .Single();
            editor.AddConnection(source, newDestination);
        }

        int preDamageUnarmoredList = editor.AddCardListVariable("PreDamageUnarmoredTargets");
        int bleedingTargetsList = editor.AddCardListVariable("BleedingTargets");

        ForeachEndpoints preDamageLoop = editor.AddCardListForeach();
        ArmorBranchEndpoints preDamageArmor = editor.AddCardHasArmorBranch();
        ElementListEndpoints preDamageSingleton = editor.AddCardElementToList();
        int preDamageListValue = editor.AddGetCardListVariable(preDamageUnarmoredList);
        CardListAppendEndpoints appendPreDamage = editor.AddCardListAppend();
        editor.AddConnection(flowBeforeDamage, preDamageLoop.FlowIn);
        editor.AddConnection(Id(originalCards.Element("Out")!), preDamageLoop.List);
        editor.AddConnection(preDamageLoop.FlowFor, preDamageArmor.FlowIn);
        editor.AddConnection(preDamageLoop.Element, preDamageArmor.Card);
        editor.AddConnection(preDamageLoop.Element, preDamageSingleton.Card);
        editor.AddConnection(preDamageListValue, appendPreDamage.List);
        editor.AddConnection(preDamageSingleton.List, appendPreDamage.ListToAppend);
        editor.AddConnection(preDamageArmor.FlowFalse, appendPreDamage.FlowIn);
        editor.AddConnection(preDamageLoop.FlowOut, damageInput);

        ForeachEndpoints survivorLoop = editor.AddCardListForeach();
        CardListContainsEndpoints wasPreDamageUnarmored = editor.AddCardListContainsElement();
        BranchEndpoints branch = editor.AddBranch();
        ElementListEndpoints survivorSingleton = editor.AddCardElementToList();
        int preDamageListForContains = editor.AddGetCardListVariable(preDamageUnarmoredList);
        int bleedingTargetsForAppend = editor.AddGetCardListVariable(bleedingTargetsList);
        CardListAppendEndpoints appendSurvivor = editor.AddCardListAppend();
        StatusTimerEndpoints bleeding = editor.AddBleeding(duration);
        int ownerOut = editor.AddGetAbilityOwner();
        int finalBleedingTargets = editor.AddGetCardListVariable(bleedingTargetsList);

        editor.AddConnection(Id(damage.Element("FlowOut")!), survivorLoop.FlowIn);
        editor.AddConnection(currentCards.Out, survivorLoop.List);
        editor.AddConnection(survivorLoop.FlowFor, branch.FlowIn);
        editor.AddConnection(preDamageListForContains, wasPreDamageUnarmored.List);
        editor.AddConnection(survivorLoop.Element, wasPreDamageUnarmored.Element);
        editor.AddConnection(wasPreDamageUnarmored.Result, branch.Condition);
        editor.AddConnection(survivorLoop.Element, survivorSingleton.Card);
        editor.AddConnection(bleedingTargetsForAppend, appendSurvivor.List);
        editor.AddConnection(survivorSingleton.List, appendSurvivor.ListToAppend);
        editor.AddConnection(branch.True, appendSurvivor.FlowIn);
        editor.AddConnection(survivorLoop.FlowOut, bleeding.FlowIn);
        editor.AddConnection(finalBleedingTargets, bleeding.Cards);
        editor.AddConnection(ownerOut, bleeding.Attacker);
        editor.Finish();
    }

    private static bool HasStrictBleedingFragment(XElement ability, int duration)
    {
        bool hasBleeding = ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "BalanceCardStatusTimerNode", StringComparison.Ordinal) &&
            (string?)node.Element("Acceptor")?.Attribute("V") == "16" &&
            (string?)node.Element("Donor")?.Attribute("V") == "32" &&
            (string?)node.Element("DeltaTime")?.Attribute("V") == duration.ToString());
        if (!hasBleeding)
            return false;

        bool hasPreDamageList = ability.Element("TemporaryVariables")?.Elements().Any(variable =>
            string.Equals((string?)variable.Attribute("Type"), "CardListVar", StringComparison.Ordinal) &&
            string.Equals((string?)variable.Attribute("Name"), "PreDamageUnarmoredTargets", StringComparison.Ordinal)) == true;
        bool hasSurvivorIntersection = ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "CardListContainsElementNode", StringComparison.Ordinal));
        return hasPreDamageList && hasSurvivorIntersection;
    }

    private static void ConvertSwallowToArtifact(
        XElement ability,
        XElement template,
        int deployAmount,
        int orderAmount)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);

        SetTemplateText(template, "Type", "8");
        SetTemplateText(template, "Power", "0");
        SetTemplateText(template, "Armor", "0");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "VisibleTapCharges", "False");
        SetTemplateText(template, "SummoningSickness", "True");
        XElement placement = template.Element("Placement")
            ?? throw new InvalidDataException("Template не содержит Placement.");
        placement.SetAttributeValue("PlayerSide", "3");
        placement.SetAttributeValue("OpponentSide", "0");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        int ownerOut = editor.AddGetAbilityOwner();
        PowerEndpoints deployBoost = editor.AddChangePower(deployAmount, operation: 0);
        editor.AddConnection(deploy.To, adjacent.Position);
        editor.AddConnection(deploy.FlowOut, deployBoost.FlowIn);
        editor.AddConnection(adjacent.Cards, deployBoost.Targets);
        editor.AddConnection(ownerOut, deployBoost.Attacker);

        TriggerEndpoints order = editor.AddTappedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints friendly = editor.AddGetCards();
        editor.AddConnection(ownerPlayer, friendly.PlayerId);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(min: 1, max: 1, aiHintE0: 2147483648L);
        editor.AddConnection(order.FlowOut, request.FlowIn);
        editor.AddConnection(friendly.Out, request.ValidTargets);

        // Branch before changing power. A Witcher must be healed first, then
        // boosted, and only then receive the infusion.
        NodeEndpoints witcher = editor.AddFilterCardCategory(
            e0: 2147483648UL, e1: 0, e2: 0);
        FilterListEndpoints filter = editor.AddFilterCardList();
        editor.AddConnection(witcher.Out, filter.Filter);
        editor.AddConnection(request.SelectedTargets, filter.Cards);
        editor.AddConnection(request.Success, filter.FlowIn);

        ResetEndpoints heal = editor.AddResetCards(resetMode: 1);
        editor.AddConnection(filter.Success, heal.FlowIn);
        editor.AddConnection(ownerOut, heal.Attacker);
        editor.AddConnection(filter.FilteredCards, heal.Targets);

        PowerEndpoints witcherBoost = editor.AddChangePower(orderAmount, operation: 0);
        editor.AddConnection(heal.FlowOut, witcherBoost.FlowIn);
        editor.AddConnection(filter.FilteredCards, witcherBoost.Targets);
        editor.AddConnection(ownerOut, witcherBoost.Attacker);

        int variableId = editor.AddInjectableVariable("InjectableAbility", 12);
        int injectableValue = editor.AddGetInjectableVariable(variableId);
        SubAbilityEndpoints infusion = editor.AddInfusionSubAbility();
        editor.AddConnection(witcherBoost.FlowOut, infusion.FlowIn);
        editor.AddConnection(filter.FilteredCards, infusion.Targets);
        editor.AddConnection(injectableValue, infusion.InjectableAbility);

        PowerEndpoints regularBoost = editor.AddChangePower(orderAmount, operation: 0);
        editor.AddConnection(filter.Fail, regularBoost.FlowIn);
        editor.AddConnection(filter.NotFilteredCards, regularBoost.Targets);
        editor.AddConnection(ownerOut, regularBoost.Attacker);
        editor.Finish();
    }

    private static void ReplaceWithDynamicPoison(
        XElement ability,
        int minTargets,
        int maxTargets)
    {
        if (minTargets < 1 || maxTargets < minTargets)
            throw new InvalidOperationException("Manticore target range недействителен.");
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int opponentPlayer = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints friendly = editor.AddGetCards();
        GetCardsEndpoints enemies = editor.AddGetCards();
        editor.AddConnection(ownerPlayer, friendly.PlayerId);
        editor.AddConnection(opponentPlayer, enemies.PlayerId);

        PowerLevelEndpoints strongest = editor.AddFilterPowerLevel(powerFilter: 1, count: 1);
        editor.AddConnection(deploy.FlowOut, strongest.FlowIn);
        editor.AddConnection(friendly.Out, strongest.Cards);
        CardElementEndpoints first = editor.AddCardListGetElement(index: 0);
        editor.AddConnection(strongest.FilteredCards, first.List);
        CardPowerEndpoints strongestPower = editor.AddGetCardPower();
        editor.AddConnection(first.Card, strongestPower.Card);

        NodeEndpoints lowerThan = editor.AddFilterCardPower(compareOp: 2, power: 0);
        editor.AddConnection(strongestPower.Power, lowerThan.PowerInput);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        editor.AddConnection(enemies.Out, eligible.Cards);
        editor.AddConnection(lowerThan.Out, eligible.Filter);
        editor.AddConnection(strongest.Success, eligible.FlowIn);

        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            minTargets, maxTargets, aiHintE0: 8388608L);
        editor.AddConnection(eligible.Success, request.FlowIn);
        editor.AddConnection(eligible.FilteredCards, request.ValidTargets);
        TokenEndpoints poison = editor.AddPoison();
        int ownerOut = editor.AddGetAbilityOwner();
        editor.AddConnection(request.Success, poison.FlowIn);
        editor.AddConnection(request.SelectedTargets, poison.Targets);
        editor.AddConnection(ownerOut, poison.Attacker);
        editor.Finish();
    }

    private static bool AddDeployBoostHandTargets(
        XElement ability,
        int targetCount,
        int amount)
    {
        if (targetCount < 1)
            throw new InvalidOperationException("Francis Bedlam: число целей должно быть положительным.");
        if (ability.Element("Nodes")?.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "PlayedTrigger", StringComparison.Ordinal)) == true)
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints handUnits = editor.AddGetCards(locationId: 8);
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(
            min: targetCount,
            max: targetCount,
            aiHintE0: 2147483648L);
        PowerEndpoints boost = editor.AddChangePower(
            amount,
            operation: 0,
            elementType: 2048,
            attackMethod: 0);
        int owner = editor.AddGetAbilityOwner();

        editor.AddConnection(ownerPlayer, handUnits.PlayerId);
        editor.AddConnection(deploy.FlowOut, choice.FlowIn);
        editor.AddConnection(handUnits.Out, choice.ValidChoices);
        editor.AddConnection(choice.Success, boost.FlowIn);
        editor.AddConnection(choice.SelectedChoices, boost.Targets);
        editor.AddConnection(owner, boost.Attacker);
        editor.Finish();
        return true;
    }

    private static bool AddInspiredOrderDamage(
        XElement ability,
        int inspiredDamage)
    {
        if (UsesSubAbility(ability, "21"))
            return false;

        var editor = new GraphEditor(ability);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement baseDamage = FindNode(ability, "ChangePowerNode");
        int requestSuccess = Id(request.Element("FlowOutSuccess")!);
        int baseDamageFlowIn = Id(baseDamage.Element("FlowIn")!);
        int targetSource = GetSingleIncomingSource(
            editor,
            Id(baseDamage.Element("Targets")!),
            "Aedirnian Mauler damage targets");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(baseDamage.Element("Attacker")!),
            "Aedirnian Mauler damage attacker");

        editor.RemoveConnection(requestSuccess, baseDamageFlowIn);

        InspiredEndpoints inspired = editor.AddInspiredBranchSubAbility();
        editor.AddConnection(requestSuccess, inspired.FlowIn);
        editor.AddConnection(inspired.Regular, baseDamageFlowIn);

        int damage2Variable = editor.EnsureIntVariable("Damage2", inspiredDamage);
        int damage2Value = editor.AddGetIntVariable(damage2Variable);
        PowerEndpoints inspiredDamageNode = editor.AddChangePower(inspiredDamage, operation: 1);
        editor.AddConnection(inspired.Inspired, inspiredDamageNode.FlowIn);
        editor.AddConnection(targetSource, inspiredDamageNode.Targets);
        editor.AddConnection(attackerSource, inspiredDamageNode.Attacker);
        editor.AddConnection(damage2Value, inspiredDamageNode.Power);
        editor.Finish();
        return true;
    }

    private static bool AddDeathblowFrostToDestroyedRows(
        XElement ability,
        int duration)
    {
        if (UsesSubAbility(ability, "11"))
            return false;

        var editor = new GraphEditor(ability);
        XElement destroy = FindNode(ability, "DestroyCardsNode");
        int destroyFlowIn = Id(destroy.Element("FlowIn")!);
        int destroyFlowOut = Id(destroy.Element("FlowOut")!);
        int targetVariable = FindRequiredTemporaryVariableId(ability, "Target", "CardListVar");
        IReadOnlyList<int> destroyFlowSources = editor.GetIncomingSources(destroyFlowIn);
        if (destroyFlowSources.Count == 0)
            throw new InvalidOperationException("Blizzard: вход DestroyCardsNode не имеет flow-соединений.");

        foreach (int source in destroyFlowSources)
            editor.RemoveConnection(source, destroyFlowIn);

        int rowsVariable = editor.AddLocationListVariable("DeathblowFrostRows");
        int targetsForRows = editor.AddGetCardListVariable(targetVariable);
        ForeachEndpoints targetLoop = editor.AddCardListForeach();
        editor.AddConnection(targetsForRows, targetLoop.List);
        foreach (int source in destroyFlowSources)
            editor.AddConnection(source, targetLoop.FlowIn);

        CardPlayerEndpoints cardPlayer = editor.AddGetCardPlayerId(positionType: 0);
        CardLocationEndpoints cardLocation = editor.AddGetCardLocationId(positionType: 0);
        MakeLocationEndpoints row = editor.AddMakeLocation();
        int rowsForContains = editor.AddGetLocationListVariable(rowsVariable);
        LocationListContainsEndpoints contains = editor.AddLocationListContainsElement();
        BranchEndpoints alreadyAdded = editor.AddBranch();
        int rowsForAdd = editor.AddGetLocationListVariable(rowsVariable);
        LocationListAddEndpoints addRow = editor.AddLocationListAdd();

        editor.AddConnection(targetLoop.FlowFor, alreadyAdded.FlowIn);
        editor.AddConnection(targetLoop.Element, cardPlayer.Card);
        editor.AddConnection(targetLoop.Element, cardLocation.Card);
        editor.AddConnection(cardPlayer.PlayerId, row.PlayerId);
        editor.AddConnection(cardLocation.Location, row.LocationId);
        editor.AddConnection(rowsForContains, contains.List);
        editor.AddConnection(row.Location, contains.Element);
        editor.AddConnection(contains.Result, alreadyAdded.Condition);
        editor.AddConnection(alreadyAdded.False, addRow.FlowIn);
        editor.AddConnection(rowsForAdd, addRow.List);
        editor.AddConnection(row.Location, addRow.Element);
        editor.AddConnection(targetLoop.FlowOut, destroyFlowIn);

        DeathblowEndpoints deathblow = editor.AddDeathblowSubAbility();
        int targetsForDeathblow = editor.AddGetCardListVariable(targetVariable);
        editor.AddConnection(destroyFlowOut, deathblow.FlowIn);
        editor.AddConnection(targetsForDeathblow, deathblow.Targets);

        int rowsForFrost = editor.AddGetLocationListVariable(rowsVariable);
        LocationTokenEndpoints frost = editor.AddChangeLocationTokens(
            token: 1,
            duration: duration,
            operation: 0,
            elementType: 32);
        int owner = editor.AddGetAbilityOwner();
        editor.AddConnection(deathblow.Deathblow, frost.FlowIn);
        editor.AddConnection(rowsForFrost, frost.Targets);
        editor.AddConnection(owner, frost.Attacker);
        editor.Finish();
        return true;
    }

    private static bool AddRowHealBeforeBoost(XElement ability, int amount)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                (string?)node.Element("Operation")?.Attribute("V") == "4" &&
                (string?)node.Element("ElementType")?.Attribute("V") == "512"))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        XElement boost = ability.Element("Nodes")!.Elements()
            .Single(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                (string?)node.Element("Operation")?.Attribute("V") == "0");
        int boostFlowIn = Id(boost.Element("FlowIn")!);
        int boostFlowSource = GetSingleIncomingSource(editor, boostFlowIn, "Clear Skies boost flow");
        int targetSource = GetSingleIncomingSource(
            editor,
            Id(boost.Element("Targets")!),
            "Clear Skies row targets");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(boost.Element("Attacker")!),
            "Clear Skies attacker");

        editor.RemoveConnection(boostFlowSource, boostFlowIn);
        PowerEndpoints heal = editor.AddChangePower(
            amount,
            operation: 4,
            elementType: 512,
            attackMethod: 2,
            effectType: 1);
        editor.AddConnection(boostFlowSource, heal.FlowIn);
        editor.AddConnection(heal.FlowOut, boostFlowIn);
        editor.AddConnection(targetSource, heal.Targets);
        editor.AddConnection(attackerSource, heal.Attacker);
        editor.Finish();
        return true;
    }

    private static bool ReplaceHailstormWithWeatherBonus(
        XElement ability,
        int regularDamage,
        int weatherDamage,
        int frostDuration)
    {
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "HailstormFrostRows", StringComparison.Ordinal)))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement damage = FindNode(ability, "ChangePowerNode");
        XElement damageVar = ability.Element("TemporaryVariables")!.Elements()
            .Single(variable =>
                string.Equals((string?)variable.Attribute("Type"), "IntVar", StringComparison.Ordinal) &&
                string.Equals((string?)variable.Attribute("Name"), "Damage", StringComparison.Ordinal));
        damageVar.SetAttributeValue("V", regularDamage);

        int damageFlowIn = Id(damage.Element("FlowIn")!);
        int requestSuccess = Id(request.Element("FlowOutSuccess")!);
        int requestSelected = Id(request.Element("SelectedTargets")!);
        int selectedTargetSource = GetSingleIncomingSource(
            editor,
            Id(damage.Element("Targets")!),
            "Merigold's Hailstorm normal damage targets");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(damage.Element("Attacker")!),
            "Merigold's Hailstorm attacker");

        editor.RemoveConnection(requestSuccess, damageFlowIn);
        editor.RemoveConnection(selectedTargetSource, Id(damage.Element("Targets")!));

        NodeEndpoints rowEffect = editor.AddFilterCardLocationToken(AllRowEffectLocationTokens);
        FilterListEndpoints splitTargets = editor.AddFilterCardList();
        editor.AddConnection(requestSelected, splitTargets.Cards);
        editor.AddConnection(rowEffect.Out, splitTargets.Filter);

        int rowsVariable = editor.AddLocationListVariable("HailstormFrostRows");
        ForeachEndpoints targetLoop = editor.AddCardListForeach();
        editor.AddConnection(requestSuccess, targetLoop.FlowIn);
        editor.AddConnection(requestSelected, targetLoop.List);

        CardPlayerEndpoints cardPlayer = editor.AddGetCardPlayerId(positionType: 0);
        CardLocationEndpoints cardLocation = editor.AddGetCardLocationId(positionType: 0);
        MakeLocationEndpoints row = editor.AddMakeLocation();
        int rowsForContains = editor.AddGetLocationListVariable(rowsVariable);
        LocationListContainsEndpoints contains = editor.AddLocationListContainsElement();
        BranchEndpoints alreadyAdded = editor.AddBranch();
        int rowsForAdd = editor.AddGetLocationListVariable(rowsVariable);
        LocationListAddEndpoints addRow = editor.AddLocationListAdd();

        editor.AddConnection(targetLoop.FlowFor, alreadyAdded.FlowIn);
        editor.AddConnection(targetLoop.Element, cardPlayer.Card);
        editor.AddConnection(targetLoop.Element, cardLocation.Card);
        editor.AddConnection(cardPlayer.PlayerId, row.PlayerId);
        editor.AddConnection(cardLocation.Location, row.LocationId);
        editor.AddConnection(rowsForContains, contains.List);
        editor.AddConnection(row.Location, contains.Element);
        editor.AddConnection(contains.Result, alreadyAdded.Condition);
        editor.AddConnection(alreadyAdded.False, addRow.FlowIn);
        editor.AddConnection(rowsForAdd, addRow.List);
        editor.AddConnection(row.Location, addRow.Element);
        editor.AddConnection(targetLoop.FlowOut, splitTargets.FlowIn);

        int damage2Variable = editor.EnsureIntVariable("Damage2", weatherDamage);
        int damage2Value = editor.AddGetIntVariable(damage2Variable);
        PowerEndpoints bonusDamage = editor.AddChangePower(weatherDamage, operation: 1);
        editor.AddConnection(splitTargets.Success, bonusDamage.FlowIn);
        editor.AddConnection(splitTargets.FilteredCards, bonusDamage.Targets);
        editor.AddConnection(attackerSource, bonusDamage.Attacker);
        editor.AddConnection(damage2Value, bonusDamage.Power);

        editor.AddConnection(bonusDamage.FlowOut, damageFlowIn);
        editor.AddConnection(splitTargets.NotFilteredCards, Id(damage.Element("Targets")!));

        int damageValue = editor.AddGetIntVariable((int)damageVar.Attribute("Id")!);
        PowerEndpoints regularDamageOnly = editor.AddChangePower(regularDamage, operation: 1);
        editor.AddConnection(splitTargets.Fail, regularDamageOnly.FlowIn);
        editor.AddConnection(splitTargets.NotFilteredCards, regularDamageOnly.Targets);
        editor.AddConnection(attackerSource, regularDamageOnly.Attacker);
        editor.AddConnection(damageValue, regularDamageOnly.Power);

        int rowsForFrostAfterBonus = editor.AddGetLocationListVariable(rowsVariable);
        LocationTokenEndpoints frostAfterBonus = editor.AddChangeLocationTokens(
            token: 1,
            duration: frostDuration,
            operation: 0,
            elementType: 32);
        int owner = editor.AddGetAbilityOwner();
        editor.AddConnection(Id(damage.Element("FlowOut")!), frostAfterBonus.FlowIn);
        editor.AddConnection(rowsForFrostAfterBonus, frostAfterBonus.Targets);
        editor.AddConnection(owner, frostAfterBonus.Attacker);

        int rowsForFrostRegularOnly = editor.AddGetLocationListVariable(rowsVariable);
        LocationTokenEndpoints frostRegularOnly = editor.AddChangeLocationTokens(
            token: 1,
            duration: frostDuration,
            operation: 0,
            elementType: 32);
        editor.AddConnection(regularDamageOnly.FlowOut, frostRegularOnly.FlowIn);
        editor.AddConnection(rowsForFrostRegularOnly, frostRegularOnly.Targets);
        editor.AddConnection(owner, frostRegularOnly.Attacker);
        editor.Finish();
        return true;
    }

    private static bool AllowBronzeArtifactTarget(XElement ability)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "DestroyCardsNode", StringComparison.Ordinal)) &&
            ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "FilterCardTierNode", StringComparison.Ordinal) &&
                (string?)node.Element("Tier")?.Attribute("V") == "2") &&
            ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "FilterCardTypeNode", StringComparison.Ordinal) &&
                (string?)node.Element("Type")?.Attribute("V") == "8"))
        {
            return false;
        }

        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int damageVariable = editor.EnsureIntVariable("Damage", 4);
        PlayedEndpoints played = editor.AddPlayedTrigger();
        GetCardsEndpoints battlefield = editor.AddGetCards(cardTypes: 12);

        NodeEndpoints unit = editor.AddFilterCardType(4);
        NodeEndpoints artifact = editor.AddFilterCardType(8);
        NodeEndpoints bronze = editor.AddFilterCardTier(2);
        LogicEndpoints bronzeArtifact = editor.AddFilterLogic(orOperation: false);
        LogicEndpoints unitOrBronzeArtifact = editor.AddFilterLogic(orOperation: true);
        FilterListEndpoints eligibleTargets = editor.AddFilterCardList();
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 8388608L);

        editor.AddConnection(artifact.Out, bronzeArtifact.Input0);
        editor.AddConnection(bronze.Out, bronzeArtifact.Input1);
        editor.AddConnection(unit.Out, unitOrBronzeArtifact.Input0);
        editor.AddConnection(bronzeArtifact.Out, unitOrBronzeArtifact.Input1);
        editor.AddConnection(played.FlowOut, eligibleTargets.FlowIn);
        editor.AddConnection(battlefield.Out, eligibleTargets.Cards);
        editor.AddConnection(unitOrBronzeArtifact.Out, eligibleTargets.Filter);
        editor.AddConnection(eligibleTargets.Success, request.FlowIn);
        editor.AddConnection(eligibleTargets.FilteredCards, request.ValidTargets);

        FilterListEndpoints selectedArtifact = editor.AddFilterCardList();
        editor.AddConnection(request.Success, selectedArtifact.FlowIn);
        editor.AddConnection(request.SelectedTargets, selectedArtifact.Cards);
        editor.AddConnection(bronzeArtifact.Out, selectedArtifact.Filter);

        int owner = editor.AddGetAbilityOwner();
        DestroyEndpoints destroyArtifact = editor.AddDestroyCards(elementType: 16, attackMethod: 0);
        editor.AddConnection(selectedArtifact.Success, destroyArtifact.FlowIn);
        editor.AddConnection(selectedArtifact.FilteredCards, destroyArtifact.Targets);
        editor.AddConnection(owner, destroyArtifact.Attacker);

        int damageValue = editor.AddGetIntVariable(damageVariable);
        PowerEndpoints damageUnit = editor.AddChangePower(
            amount: 4,
            operation: 1,
            elementType: 16,
            attackMethod: 1);
        TokenEndpoints veil = editor.AddChangeTokens(
            token: 8192,
            elementType: 1,
            attackMethod: 0);
        editor.AddConnection(selectedArtifact.Fail, damageUnit.FlowIn);
        editor.AddConnection(selectedArtifact.NotFilteredCards, damageUnit.Targets);
        editor.AddConnection(owner, damageUnit.Attacker);
        editor.AddConnection(damageValue, damageUnit.Power);
        editor.AddConnection(damageUnit.FlowOut, veil.FlowIn);
        editor.AddConnection(selectedArtifact.NotFilteredCards, veil.Targets);
        editor.AddConnection(owner, veil.Attacker);
        editor.Finish();
        return true;
    }

    private static bool AddBasePowerAndPoisonAfterReset(XElement ability, int amount)
    {
        bool hasBasePower = ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            (string?)node.Element("TargetedPower")?.Attribute("V") == "1" &&
            (string?)node.Element("Operation")?.Attribute("V") == "0");
        bool hasPoison = ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangeTokensNode", StringComparison.Ordinal) &&
            (string?)node.Element("Tokens")?.Attribute("V") == "64");
        if (hasBasePower && hasPoison)
            return false;

        var editor = new GraphEditor(ability);
        XElement reset = FindNode(ability, "ResetCardsNode");
        int targetSource = GetSingleIncomingSource(
            editor,
            Id(reset.Element("Targets")!),
            "Mandrake reset targets");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(reset.Element("Attacker")!),
            "Mandrake attacker");

        PowerEndpoints basePower = editor.AddChangePower(
            amount,
            operation: 0,
            elementType: 1024,
            attackMethod: 0,
            effectType: 1,
            targetedPower: 1);
        TokenEndpoints poison = editor.AddPoison();

        editor.AddConnection(Id(reset.Element("FlowOut")!), basePower.FlowIn);
        editor.AddConnection(targetSource, basePower.Targets);
        editor.AddConnection(attackerSource, basePower.Attacker);
        editor.AddConnection(basePower.FlowOut, poison.FlowIn);
        editor.AddConnection(targetSource, poison.Targets);
        editor.AddConnection(attackerSource, poison.Attacker);
        editor.Finish();
        return true;
    }

    private static void RebuildLastWishShufflePlayDiscard(XElement ability, int topCards)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);

        int topCardsVariable = editor.AddCardListVariable("CardList");
        int maxTargetsVariable = editor.EnsureIntVariable("MaxTargets", topCards);

        PlayedEndpoints played = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 14);
        RangeEndpoints range = editor.AddCardListGetRange(length: topCards);
        int maxTargets = editor.AddGetIntVariable(maxTargetsVariable);
        SetVarEndpoints setTopCards = editor.AddSetCardListVariable(topCardsVariable);

        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(played.FlowOut, range.FlowIn);
        editor.AddConnection(deck.Out, range.List);
        editor.AddConnection(maxTargets, range.Length);
        editor.AddConnection(range.FlowOut, setTopCards.FlowIn);
        editor.AddConnection(range.TrimmedList, setTopCards.In);

        CardChoiceEndpoints playChoice = editor.AddRequestCardChoice(
            min: 1,
            max: 1,
            aiHintE0: 67108864L,
            choiceType: 1);
        editor.AddConnection(setTopCards.FlowOut, playChoice.FlowIn);
        editor.AddConnection(setTopCards.Out, playChoice.ValidChoices);

        int topCardsForPlayRemove = editor.AddGetCardListVariable(topCardsVariable);
        RemoveListEndpoints removePlayed = editor.AddCardListRemoveList();
        editor.AddConnection(playChoice.Success, removePlayed.FlowIn);
        editor.AddConnection(topCardsForPlayRemove, removePlayed.List);
        editor.AddConnection(playChoice.SelectedChoices, removePlayed.ListToRemove);

        CardChoiceEndpoints shuffleChoice = editor.AddRequestCardChoice(
            min: 1,
            max: 1,
            aiHintE0: 67108864L,
            choiceType: 1);
        int remainingAfterPlay = editor.AddGetCardListVariable(topCardsVariable);
        editor.AddConnection(removePlayed.FlowOut, shuffleChoice.FlowIn);
        editor.AddConnection(remainingAfterPlay, shuffleChoice.ValidChoices);

        MakeCardPositionEndpoints deckPosition = editor.AddMakeCardPosition(location: 16, index: 0);
        MoveCardsEndpoints shuffleMove = editor.AddMoveCards();
        ShuffleDeckEndpoints shuffleDeck = editor.AddShuffleDeck();
        int topCardsForShuffleRemove = editor.AddGetCardListVariable(topCardsVariable);
        RemoveListEndpoints removeShuffled = editor.AddCardListRemoveList();

        editor.AddConnection(shuffleChoice.Success, deckPosition.FlowIn);
        editor.AddConnection(ownerPlayer, deckPosition.PlayerId);
        editor.AddConnection(deckPosition.FlowOut, shuffleMove.FlowIn);
        editor.AddConnection(shuffleChoice.SelectedChoices, shuffleMove.Cards);
        editor.AddConnection(deckPosition.Position, shuffleMove.Position);
        editor.AddConnection(shuffleMove.FlowOut, shuffleDeck.FlowIn);
        editor.AddConnection(ownerPlayer, shuffleDeck.PlayerId);
        editor.AddConnection(shuffleDeck.FlowOut, removeShuffled.FlowIn);
        editor.AddConnection(topCardsForShuffleRemove, removeShuffled.List);
        editor.AddConnection(shuffleChoice.SelectedChoices, removeShuffled.ListToRemove);

        PlayEndpoints play = editor.AddPlayCards();
        MakeCardPositionEndpoints discardPosition = editor.AddMakeCardPosition(location: 32, index: 0);
        MoveCardsEndpoints discardMove = editor.AddMoveCards();
        int discardCard = editor.AddGetCardListVariable(topCardsVariable);

        editor.AddConnection(removeShuffled.FlowOut, play.FlowIn);
        editor.AddConnection(playChoice.SelectedChoices, play.Cards);
        editor.AddConnection(play.FlowOut, discardPosition.FlowIn);
        editor.AddConnection(ownerPlayer, discardPosition.PlayerId);
        editor.AddConnection(discardPosition.FlowOut, discardMove.FlowIn);
        editor.AddConnection(discardCard, discardMove.Cards);
        editor.AddConnection(discardPosition.Position, discardMove.Position);

        editor.Finish();
    }

    private static bool AddDeployRandomDeckChoiceToTop(XElement ability, int cardCount)
    {
