    private static bool AddHolgerBarricadeBonus(XElement ability)
    {
        if (UsesSubAbility(ability, "29"))
            return false;

        var originalNodes = ability.Element("Nodes")!.Elements().ToList();
        var editor = new GraphEditor(ability);

        int deployDamageBonusVariable = editor.EnsureIntVariable("Damage2Barricade", 3);
        int pirateDamageBonusVariable = editor.EnsureIntVariable("DamageBarricade", 2);
        int boostBonusVariable = editor.EnsureIntVariable("BoostBarricade", 2);

        XElement deployDamageSubAbility = originalNodes.Single(node =>
            string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
            node.Element("SubAbilityID")?.Value == "3");
        int deployFlowIn = GetSubAbilityFlowEndpoint(deployDamageSubAbility, idInAbility: 3, input: true);
        int deployTargets = GetSubAbilityVariableEndpoint(deployDamageSubAbility, idInAbility: 70, input: true);
        int deployFlowSource = GetSingleIncomingSource(editor, deployFlowIn, "Holger deploy damage flow");
        int deployTargetSource = GetSingleIncomingSource(editor, deployTargets, "Holger deploy damage targets");
        editor.RemoveConnection(deployFlowSource, deployFlowIn);

        KeywordBranchEndpoints deployBarricade = editor.AddBarricadeBranchSubAbility();
        editor.AddConnection(deployFlowSource, deployBarricade.FlowIn);
        editor.AddConnection(deployBarricade.Regular, deployFlowIn);

        int deployOwner = editor.AddGetAbilityOwner();
        int deployDamageBonus = editor.AddGetIntVariable(deployDamageBonusVariable);
        PowerEndpoints deployDamage = editor.AddChangePower(
            amount: 3,
            operation: 1,
            elementType: 1,
            attackMethod: 1);
        editor.AddConnection(deployBarricade.Active, deployDamage.FlowIn);
        editor.AddConnection(deployTargetSource, deployDamage.Targets);
        editor.AddConnection(deployOwner, deployDamage.Attacker);
        editor.AddConnection(deployDamageBonus, deployDamage.Power);

        XElement pirateDamageNode = originalNodes.Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            (string?)node.Element("Operation")?.Attribute("V") == "1" &&
            (string?)node.Element("ElementType")?.Attribute("V") == "1" &&
            (string?)node.Element("TargetedPower")?.Attribute("V") == "0");
        int pirateDamageFlowIn = Id(pirateDamageNode.Element("FlowIn")!);
        int pirateRandomFlowOut = GetSingleIncomingSource(editor, pirateDamageFlowIn, "Holger pirate damage random flow");
        XElement pirateRandomNode = editor.FindNodeOwningEndpoint(pirateRandomFlowOut)
            ?? throw new InvalidOperationException("Holger: random enemy node not found.");
        int pirateRandomFlowIn = Id(pirateRandomNode.Element("FlowIn")!);
        int pirateFlowSource = GetSingleIncomingSource(editor, pirateRandomFlowIn, "Holger pirate filter flow");
        int pirateEnemyListSource = GetSingleIncomingSource(
            editor,
            Id(pirateRandomNode.Element("List")!),
            "Holger pirate enemy list");
        int pirateAttackerSource = GetSingleIncomingSource(
            editor,
            Id(pirateDamageNode.Element("Attacker")!),
            "Holger pirate attacker");
        editor.RemoveConnection(pirateFlowSource, pirateRandomFlowIn);

        KeywordBranchEndpoints pirateBarricade = editor.AddBarricadeBranchSubAbility();
        editor.AddConnection(pirateFlowSource, pirateBarricade.FlowIn);
        editor.AddConnection(pirateBarricade.Regular, pirateRandomFlowIn);

        RandomCardEndpoints pirateBonusRandom = editor.AddRandomCard();
        ElementListEndpoints pirateBonusTarget = editor.AddCardElementToList();
        int pirateDamageBonus = editor.AddGetIntVariable(pirateDamageBonusVariable);
