        XElement shipBoostNode = originalNodes.Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            (string?)node.Element("Operation")?.Attribute("V") == "0" &&
