        KeywordBranchEndpoints shipBarricade = editor.AddBarricadeBranchSubAbility();
        editor.AddConnection(shipFlowSource, shipBarricade.FlowIn);
        editor.AddConnection(shipBarricade.Regular, shipBoostFlowIn);

        int boostBonus = editor.AddGetIntVariable(boostBonusVariable);
        PowerEndpoints shipBonusBoost = editor.AddChangePower(
            amount: 2,
            operation: 0,
            elementType: 512,
            attackMethod: 1);
