        editor.AddConnection(shipTargetSource, shipBonusBoost.Targets);
        editor.AddConnection(shipAttackerSource, shipBonusBoost.Attacker);
        editor.AddConnection(boostBonus, shipBonusBoost.Power);

        editor.Finish();
        return true;
    }

    private static bool AddDrownerRowEffectBonusDamage(XElement ability, int damage)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "FilterCardLocationTokenNode", StringComparison.Ordinal) &&
                (string?)node.Element("Token")?.Attribute("V") == AllRowEffectLocationTokens.ToString()))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        XElement baseDamage = ability.Element("Nodes")!.Elements()
            .Single(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                (string?)node.Element("Operation")?.Attribute("V") == "1");
        int targetSource = GetSingleIncomingSource(
            editor,
            Id(baseDamage.Element("Targets")!),
            "Drowner damage target");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(baseDamage.Element("Attacker")!),
            "Drowner attacker");
        int damage2Variable = editor.EnsureIntVariable("Damage2", damage);

        NodeEndpoints rowEffect = editor.AddFilterCardLocationToken(AllRowEffectLocationTokens);
        FilterListEndpoints movedIntoRowEffect = editor.AddFilterCardList();
        int damage2 = editor.AddGetIntVariable(damage2Variable);
        PowerEndpoints bonusDamage = editor.AddChangePower(
            amount: damage,
            operation: 1,
            elementType: 4096,
            attackMethod: 0);

        editor.AddConnection(Id(baseDamage.Element("FlowOut")!), movedIntoRowEffect.FlowIn);
        editor.AddConnection(targetSource, movedIntoRowEffect.Cards);
        editor.AddConnection(rowEffect.Out, movedIntoRowEffect.Filter);
        editor.AddConnection(movedIntoRowEffect.Success, bonusDamage.FlowIn);
        editor.AddConnection(movedIntoRowEffect.FilteredCards, bonusDamage.Targets);
        editor.AddConnection(attackerSource, bonusDamage.Attacker);
        editor.AddConnection(damage2, bonusDamage.Power);
        editor.Finish();
