    private static bool ChangeDrownerRowEffectDamageInstead(XElement ability)
    {
        var editor = new GraphEditor(ability);
        XElement rowEffectFilter = ability.Element("Nodes")!.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "FilterCardLocationTokenNode", StringComparison.Ordinal) &&
            (string?)node.Element("Token")?.Attribute("V") == AllRowEffectLocationTokens.ToString())
            ?? throw new InvalidOperationException("Drowner row-effect filter не найден.");
        int rowEffectFilterOut = Id(rowEffectFilter.Element("Out")!);
        List<XElement> splitTargetCandidates = ability.Element("Nodes")!.Elements()
            .Where(node => string.Equals((string?)node.Attribute("Type"), "FilterCardListNode", StringComparison.Ordinal))
            .Where(node => node.Element("Filters")?.Elements().Any(filterEndpoint =>
                editor.GetIncomingSources(Id(filterEndpoint)).Contains(rowEffectFilterOut)) == true)
            .ToList();
        if (splitTargetCandidates.Count == 0)
            throw new InvalidOperationException("Drowner row-effect target splitter не найден.");
        XElement splitTargets = splitTargetCandidates.First();
        XElement baseDamage = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            (string?)node.Element("Power")?.Attribute("V") == "1");
        XElement rowEffectDamage = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            (string?)node.Element("Power")?.Attribute("V") == "4");
        XElement move = FindNode(ability, "MoveCardsNode");

        int moveFlowOut = Id(move.Element("FlowOut")!);
        int filterFlowIn = Id(splitTargets.Element("FlowIn")!);
        int baseFlowIn = Id(baseDamage.Element("FlowIn")!);
        int baseFlowOut = Id(baseDamage.Element("FlowOut")!);
        int filterSuccess = Id(splitTargets.Element("FlowSuccess")!);
        int filterFail = Id(splitTargets.Element("FlowFail")!);
        int rowEffectDamageFlowIn = Id(rowEffectDamage.Element("FlowIn")!);

        if (editor.HasConnection(moveFlowOut, filterFlowIn) &&
            editor.HasConnection(filterFail, baseFlowIn) &&
            editor.HasConnection(filterSuccess, rowEffectDamageFlowIn) &&
            !editor.HasConnection(baseFlowOut, filterFlowIn))
        {
            return false;
        }

        editor.TryRemoveConnection(moveFlowOut, baseFlowIn);
        editor.TryRemoveConnection(baseFlowOut, filterFlowIn);
        editor.AddConnection(moveFlowOut, filterFlowIn);
        editor.AddConnection(filterFail, baseFlowIn);
        editor.AddConnection(filterSuccess, rowEffectDamageFlowIn);
        editor.Finish();
        return true;
    }

