                string.Equals((string?)variable.Attribute("Name"), "ArchesporeDeathwishCopies", StringComparison.Ordinal)))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        XElement deckCopies = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "FilterCardListNode", StringComparison.Ordinal) &&
            (int?)node.Attribute("Id") == 147);
        XElement summonMove = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "MoveCardsNode", StringComparison.Ordinal) &&
            (int?)node.Attribute("Id") == 459);

        int filterSuccess = Id(deckCopies.Element("FlowSuccess")!);
        int filteredCards = Id(deckCopies.Element("FilteredCards")!);
        int moveFlowIn = Id(summonMove.Element("FlowIn")!);
        int moveCards = Id(summonMove.Element("Cards")!);
        int summonCountVariable = editor.EnsureIntVariable("ArchesporeDeathwishCopies", 1);
        int summonCount = editor.AddGetIntVariable(summonCountVariable);
        RangeEndpoints oneCopy = editor.AddCardListGetRange(length: 1);

        editor.RemoveConnection(filterSuccess, moveFlowIn);
        editor.RemoveConnection(filteredCards, moveCards);
        editor.AddConnection(filterSuccess, oneCopy.FlowIn);
        editor.AddConnection(filteredCards, oneCopy.List);
        editor.AddConnection(summonCount, oneCopy.Length);
        editor.AddConnection(oneCopy.FlowOut, moveFlowIn);
        editor.AddConnection(oneCopy.TrimmedList, moveCards);
        editor.Finish();
        return true;
    }

