    private static bool AddDimunPirateCaptainPirateCharges(XElement ability)
    {
        if (ability.Element("PersistentVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "DimunPirateCaptainBonusCharges", StringComparison.Ordinal)))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        int gainVariable = editor.EnsureIntVariable("DimunPirateChargeGain", 1);
        int bonusChargesVariable = editor.EnsurePersistentIntVariable("DimunPirateCaptainBonusCharges", 0);

        (int successFlow, int? oldAddChargeFlowIn) = FindExistingDimunPirateChargeFragment(ability, editor)
            ?? (AddDimunPiratePlayedFilterFragment(editor, ownerLocation: 1023), null);

        if (oldAddChargeFlowIn.HasValue)
            editor.TryRemoveConnection(successFlow, oldAddChargeFlowIn.Value);

        int previousBonus = editor.AddGetIntVariable(bonusChargesVariable);
        int gainedBonus = editor.AddGetIntVariable(gainVariable);
        IntPlusEndpoints updatedBonus = editor.AddIntPlus();
        SetVarEndpoints rememberBonus = editor.AddSetIntVariable(bonusChargesVariable);

        editor.AddConnection(previousBonus, updatedBonus.A);
        editor.AddConnection(gainedBonus, updatedBonus.B);
        editor.AddConnection(updatedBonus.Result, rememberBonus.In);
        editor.AddConnection(successFlow, rememberBonus.FlowIn);

        AddDimunPirateCurrentChargeOnBoardFragment(editor, gainVariable, oldAddChargeFlowIn);

        AfterMovedEndpoints captainEnteredBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 1,
            triggerPlayer: 3,
            fromLocation: 4095,
            toLocation: 3,
            reason: 255,
            priorityValue: 15);
        int bonusForEntryCheck = editor.AddGetIntVariable(bonusChargesVariable);
        int bonusForEntryValue = editor.AddGetIntVariable(bonusChargesVariable);
        IntBranchEndpoints hasBonus = editor.AddIntBranch();
        int ownerCardList = editor.AddGetAbilityOwnerCardList();
        int owner = editor.AddGetAbilityOwner();
        ChangeTapChargesEndpoints applyRememberedCharges = editor.AddChangeTapCardCharges(operation: 1, value: 0);

        editor.AddConnection(captainEnteredBoard.FlowOut, hasBonus.FlowIn);
        editor.AddConnection(bonusForEntryCheck, hasBonus.A);
        editor.AddConnection(hasBonus.Bigger, applyRememberedCharges.FlowIn);
        editor.AddConnection(ownerCardList, applyRememberedCharges.Targets);
        editor.AddConnection(owner, applyRememberedCharges.Attacker);
        editor.AddConnection(bonusForEntryValue, applyRememberedCharges.Value);

        editor.Finish();
        return true;
    }

    private static (int SuccessFlow, int? AddChargeFlowIn)? FindExistingDimunPirateChargeFragment(
        XElement ability,
        GraphEditor editor)
    {
        XElement? dimunPirateFilter = ability.Element("Nodes")!.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "FilterDefinitionNode", StringComparison.Ordinal) &&
            (string?)node.Element("Definition")?.Element("V")?.Attribute("TemplateId") == DimunPirate.ToString());
        if (dimunPirateFilter == null)
            return null;

        int filterOut = Id(dimunPirateFilter.Element("Out")!);
        XElement? matchingPlayedCard = ability.Element("Nodes")!.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "FilterCardListNode", StringComparison.Ordinal) &&
            editor.GetIncomingSources(Id(node.Element("Filters")!.Element("e0")!)).Contains(filterOut));
        if (matchingPlayedCard == null)
            return null;

        int successFlow = Id(matchingPlayedCard.Element("FlowSuccess")!);
        XElement? addCharge = ability.Element("Nodes")!.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangeTapCardChargesNode", StringComparison.Ordinal) &&
            (string?)node.Element("Operation")?.Attribute("V") == "1" &&
            editor.GetIncomingSources(Id(node.Element("FlowIn")!)).Contains(successFlow));
        if (addCharge == null)
            return null;

        return (successFlow, Id(addCharge.Element("FlowIn")!));
    }

    private static int AddDimunPiratePlayedFilterFragment(GraphEditor editor, int ownerLocation)
    {
        AfterMovedEndpoints playedByOwner = editor.AddAfterMovedTrigger(
            ownerLocation: ownerLocation,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1,
            priorityValue: 15);
        NodeEndpoints dimunPirate = editor.AddFilterDefinition(templateId: DimunPirate);
        FilterListEndpoints matchingPlayedCard = editor.AddFilterCardList();

        editor.AddConnection(playedByOwner.FlowOut, matchingPlayedCard.FlowIn);
        editor.AddConnection(playedByOwner.CardsMoved, matchingPlayedCard.Cards);
        editor.AddConnection(dimunPirate.Out, matchingPlayedCard.Filter);
        return matchingPlayedCard.Success;
    }

    private static void AddDimunPirateCurrentChargeOnBoardFragment(
        GraphEditor editor,
        int gainVariable,
        int? existingAddChargeFlowIn)
    {
        int successFlow = AddDimunPiratePlayedFilterFragment(editor, ownerLocation: 3);

        if (existingAddChargeFlowIn.HasValue)
        {
            editor.AddConnection(successFlow, existingAddChargeFlowIn.Value);
            return;
        }

        int ownerCardList = editor.AddGetAbilityOwnerCardList();
        int owner = editor.AddGetAbilityOwner();
        int gain = editor.AddGetIntVariable(gainVariable);
        ChangeTapChargesEndpoints addCharge = editor.AddChangeTapCardCharges(operation: 1, value: 1);

        editor.AddConnection(successFlow, addCharge.FlowIn);
        editor.AddConnection(ownerCardList, addCharge.Targets);
        editor.AddConnection(owner, addCharge.Attacker);
        editor.AddConnection(gain, addCharge.Value);
    }

