    private static int RemoveRecommendedLocations(XElement ability)
    {
        var editor = new GraphEditor(ability);
        var nodesToRemove = new Dictionary<int, XElement>();
        int fragments = 0;

        void MarkNode(XElement? node)
        {
            if (node == null)
                return;
            nodesToRemove[Id(node)] = node;
        }

        foreach (XElement recommended in ability.Element("Nodes")!.Elements()
                     .Where(node => IsNodeType(node, "ChangeRecommendedLocationsNode"))
                     .ToList())
        {
            bool fragmentFound = false;
            int flowIn = Id(recommended.Element("FlowIn")!);
            foreach (int source in editor.GetIncomingSources(flowIn))
            {
                XElement? trigger = editor.FindNodeOwningEndpoint(source);
                if (IsNodeType(trigger, "OnPlayRefreshLocationTargetsTrigger") &&
                    editor.GetOutgoingTargets(source).All(target => target == flowIn))
                {
                    MarkNode(trigger);
                    fragmentFound = true;
                }
            }

            int locationsIn = Id(recommended.Element("Locations")!);
            foreach (int source in editor.GetIncomingSources(locationsIn))
            {
                XElement? locations = editor.FindNodeOwningEndpoint(source);
                if (!IsNodeType(locations, "GetLocationsNode"))
                    continue;

                fragmentFound = true;
                int locationsOut = Id(locations!.Element("Out")!);
                bool locationsOnlyUsedHere = editor.GetOutgoingTargets(locationsOut)
                    .All(target => target == locationsIn);
                if (!locationsOnlyUsedHere)
                    continue;

                MarkNode(locations);
                int playerMask = Id(locations.Element("PlayerMask")!);
                foreach (int playerSource in editor.GetIncomingSources(playerMask))
                {
                    XElement? ownerPlayer = editor.FindNodeOwningEndpoint(playerSource);
                    if (IsNodeType(ownerPlayer, "GetOwnerPlayerIdNode") &&
                        editor.GetOutgoingTargets(playerSource).All(target => target == playerMask))
                    {
                        MarkNode(ownerPlayer);
                    }
                }
            }

            if (!fragmentFound)
                continue;

            MarkNode(recommended);
            fragments++;
        }

        if (nodesToRemove.Count == 0)
            return 0;

        var endpointIds = nodesToRemove.Values
            .SelectMany(node => node.DescendantsAndSelf())
            .Where(element => element.Attribute("Id") != null)
            .Select(element => (int)element.Attribute("Id")!)
            .ToHashSet();

        foreach (XElement connection in editor.Connections.Elements()
                     .Where(connection =>
                         endpointIds.Contains((int)connection.Attribute("SrcId")!) ||
                         endpointIds.Contains((int)connection.Attribute("DstId")!))
                     .ToList())
        {
            connection.Remove();
        }

        foreach (XElement node in nodesToRemove.Values)
            node.Remove();

        editor.Finish();
        return fragments;
    }

    private static void RebuildWyvernScaleShieldArtifactCounter(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);

        int boostVariable = editor.EnsureIntVariable("Boost", 4);
        int boost2Variable = editor.EnsureIntVariable("Boost2", 1);
        editor.EnsureIntVariable("Counter", 1);

        SetTemplateText(template, "Type", "8");
        SetTemplateText(template, "Power", "0");
        SetTemplateText(template, "Armor", "0");
        SetTemplateText(template, "InitialTimer", "1");
        SetTemplateText(template, "InitalTapCharges", "0");
        SetTemplateText(template, "TapActive", "False");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");
        XElement placement = template.Element("Placement")
            ?? throw new InvalidDataException("Template не содержит Placement.");
        placement.SetAttributeValue("PlayerSide", "3");
        placement.SetAttributeValue("OpponentSide", "0");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints friendlyUnits = editor.AddGetCards();
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 2147483648L);
        int owner = editor.AddGetAbilityOwner();
        int boost = editor.AddGetIntVariable(boostVariable);
        PowerEndpoints deployBoost = editor.AddChangePower(4, operation: 0);
        TokenEndpoints deployShield = editor.AddChangeTokens(token: 2, elementType: 1, attackMethod: 0);

        editor.AddConnection(ownerPlayer, friendlyUnits.PlayerId);
        editor.AddConnection(deploy.FlowOut, request.FlowIn);
        editor.AddConnection(friendlyUnits.Out, request.ValidTargets);
        editor.AddConnection(request.Success, deployBoost.FlowIn);
        editor.AddConnection(request.SelectedTargets, deployBoost.Targets);
        editor.AddConnection(owner, deployBoost.Attacker);
        editor.AddConnection(boost, deployBoost.Power);
        editor.AddConnection(deployBoost.FlowOut, deployShield.FlowIn);
        editor.AddConnection(request.SelectedTargets, deployShield.Targets);
        editor.AddConnection(owner, deployShield.Attacker);

        AfterMovedEndpoints nextPlayedUnit = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1);
        NodeEndpoints unit = editor.AddFilterCardType(cardType: 4);
        FilterListEndpoints playedUnits = editor.AddFilterCardList();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCardList = editor.AddGetAbilityOwnerCardList();
        CardTimerEndpoints counter = editor.AddGetCardTimer();
        IntBranchEndpoints counterAvailable = editor.AddIntBranch();
        int ownerForNextUnit = editor.AddGetAbilityOwner();
        int boost2 = editor.AddGetIntVariable(boost2Variable);
        PowerEndpoints nextBoost = editor.AddChangePower(1, operation: 0);
        TokenEndpoints nextShield = editor.AddChangeTokens(token: 2, elementType: 1, attackMethod: 0);
        ChangeCardTimerEndpoints spendCounter = editor.AddChangeCardTimer(operation: 0, value: 1);

        editor.AddConnection(nextPlayedUnit.FlowOut, playedUnits.FlowIn);
        editor.AddConnection(nextPlayedUnit.CardsMoved, playedUnits.Cards);
        editor.AddConnection(unit.Out, playedUnits.Filter);
        editor.AddConnection(ownerCard, counter.Card);
        editor.AddConnection(counter.Timer, counterAvailable.A);
        editor.AddConnection(playedUnits.Success, counterAvailable.FlowIn);
        editor.AddConnection(counterAvailable.Bigger, nextBoost.FlowIn);
        editor.AddConnection(playedUnits.FilteredCards, nextBoost.Targets);
        editor.AddConnection(ownerForNextUnit, nextBoost.Attacker);
        editor.AddConnection(boost2, nextBoost.Power);
        editor.AddConnection(nextBoost.FlowOut, nextShield.FlowIn);
        editor.AddConnection(playedUnits.FilteredCards, nextShield.Targets);
        editor.AddConnection(ownerForNextUnit, nextShield.Attacker);
        editor.AddConnection(nextShield.FlowOut, spendCounter.FlowIn);
        editor.AddConnection(ownerCardList, spendCounter.Cards);

        editor.Finish();
