    private static bool AddYarpenBarricadeDeployDamage(XElement ability)
    {
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "Damage2", StringComparison.Ordinal)))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        int barricadeDamageVariable = editor.EnsureIntVariable("Damage2", 5);
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        int selectedTargets = Id(request.Element("SelectedTargets")!);
        XElement deployDamage = ability.Element("Nodes")!.Elements()
            .Where(node => string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal))
            .Single(node =>
                (string?)node.Element("Operation")?.Attribute("V") == "1" &&
                editor.GetIncomingSources(Id(node.Element("Targets")!)).Contains(selectedTargets));

        int deployFlowIn = Id(deployDamage.Element("FlowIn")!);
        int flowSource = GetSingleIncomingSource(editor, deployFlowIn, "Yarpen deploy damage flow");
        int targetSource = GetSingleIncomingSource(
            editor,
            Id(deployDamage.Element("Targets")!),
            "Yarpen deploy damage targets");
        int attackerSource = GetSingleIncomingSource(
            editor,
            Id(deployDamage.Element("Attacker")!),
            "Yarpen deploy damage attacker");
        editor.RemoveConnection(flowSource, deployFlowIn);

        KeywordBranchEndpoints barricade = editor.AddBarricadeBranchSubAbility();
        int damage2 = editor.AddGetIntVariable(barricadeDamageVariable);
        PowerEndpoints barricadeHit = editor.AddChangePower(5, operation: 1);

        editor.AddConnection(flowSource, barricade.FlowIn);
        editor.AddConnection(barricade.Regular, deployFlowIn);
        editor.AddConnection(barricade.Active, barricadeHit.FlowIn);
        editor.AddConnection(targetSource, barricadeHit.Targets);
        editor.AddConnection(attackerSource, barricadeHit.Attacker);
        editor.AddConnection(damage2, barricadeHit.Power);
        editor.Finish();
        return true;
    }

    private static bool AddVriheddOfficerBondedBonus(XElement ability)
    {
        bool alreadyPresent = ability.Element("TemporaryVariables")!.Elements().Any(variable =>
            string.Equals((string?)variable.Attribute("Name"), "BondedDamage", StringComparison.Ordinal) ||
            string.Equals((string?)variable.Attribute("Name"), "BondedBoost", StringComparison.Ordinal));
        if (alreadyPresent)
            return false;

        int bondedVariableId = FindRequiredTemporaryVariableId(ability, "Bonded", "BoolVar");
        var editor = new GraphEditor(ability);

        XElement damage = ability.Element("Nodes")!.Elements()
            .Where(node => IsNodeType(node, "ChangePowerNode"))
            .Single(node =>
                (string?)node.Element("Operation")?.Attribute("V") == "1" &&
                (string?)node.Element("ElementType")?.Attribute("V") == "1");
        XElement boost = ability.Element("Nodes")!.Elements()
            .Where(node => IsNodeType(node, "ChangePowerNode"))
            .Single(node =>
                (string?)node.Element("Operation")?.Attribute("V") == "0" &&
                (string?)node.Element("ElementType")?.Attribute("V") == "2048");

        int damageFlowIn = Id(damage.Element("FlowIn")!);
        int boostFlowIn = Id(boost.Element("FlowIn")!);
        int damageSuccess = GetSingleIncomingSource(editor, damageFlowIn, "Vrihedd damage flow");
        int boostSuccess = GetSingleIncomingSource(editor, boostFlowIn, "Vrihedd boost flow");
        int damageTargets = GetSingleIncomingSource(editor, Id(damage.Element("Targets")!), "Vrihedd damage targets");
        int boostTargets = GetSingleIncomingSource(editor, Id(boost.Element("Targets")!), "Vrihedd boost targets");
        int damageAttacker = GetSingleIncomingSource(editor, Id(damage.Element("Attacker")!), "Vrihedd damage attacker");
        int boostAttacker = GetSingleIncomingSource(editor, Id(boost.Element("Attacker")!), "Vrihedd boost attacker");

        editor.RemoveConnection(damageSuccess, damageFlowIn);
        editor.RemoveConnection(boostSuccess, boostFlowIn);

        int bondedDamageVariable = editor.EnsureIntVariable("BondedDamage", 3);
        int bondedBoostVariable = editor.EnsureIntVariable("BondedBoost", 3);
        int bondedForDamage = editor.AddGetBoolVariable(bondedVariableId);
        int bondedForBoost = editor.AddGetBoolVariable(bondedVariableId);
        BranchEndpoints damageBranch = editor.AddBranch();
        BranchEndpoints boostBranch = editor.AddBranch();
        PowerEndpoints bondedDamage = editor.AddChangePower(
            amount: 3,
            operation: 1,
            elementType: 1,
            attackMethod: 1);
        PowerEndpoints bondedBoost = editor.AddChangePower(
            amount: 3,
            operation: 0,
            elementType: 2048,
            attackMethod: 1);
        int bondedDamageValue = editor.AddGetIntVariable(bondedDamageVariable);
        int bondedBoostValue = editor.AddGetIntVariable(bondedBoostVariable);

        editor.AddConnection(damageSuccess, damageBranch.FlowIn);
        editor.AddConnection(bondedForDamage, damageBranch.Condition);
        editor.AddConnection(damageBranch.False, damageFlowIn);
        editor.AddConnection(damageBranch.True, bondedDamage.FlowIn);
        editor.AddConnection(damageTargets, bondedDamage.Targets);
        editor.AddConnection(damageAttacker, bondedDamage.Attacker);
        editor.AddConnection(bondedDamageValue, bondedDamage.Power);
        foreach (int target in editor.GetOutgoingTargets(Id(damage.Element("FlowOut")!)))
            editor.AddConnection(bondedDamage.FlowOut, target);

        editor.AddConnection(boostSuccess, boostBranch.FlowIn);
        editor.AddConnection(bondedForBoost, boostBranch.Condition);
        editor.AddConnection(boostBranch.False, boostFlowIn);
        editor.AddConnection(boostBranch.True, bondedBoost.FlowIn);
        editor.AddConnection(boostTargets, bondedBoost.Targets);
        editor.AddConnection(boostAttacker, bondedBoost.Attacker);
        editor.AddConnection(bondedBoostValue, bondedBoost.Power);

        editor.Finish();
        return true;
    }

