        IntPlusEndpoints requiredScore = editor.AddIntPlus();
        IntBranchEndpoints compare = editor.AddIntBranch();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        PositionEndpoints position = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summon = editor.AddMoveCards();

        editor.AddConnection(ownerPlayerForTrigger, endTurn.PlayerFilter);
        editor.AddConnection(ownerPlayerForScore, ownerScore.PlayerId);
        editor.AddConnection(opponentPlayer, opponentScore.PlayerId);
        editor.AddConnection(opponentScore.Score, requiredScore.A);
        editor.AddConnection(lead, requiredScore.B);
        editor.AddConnection(endTurn.FlowOut, compare.FlowIn);
        editor.AddConnection(ownerScore.Score, compare.A);
        editor.AddConnection(requiredScore.Result, compare.B);
        editor.AddConnection(ownerPlayerForScore, position.PlayerId);
        editor.AddConnection(compare.Bigger, summon.FlowIn);
        editor.AddConnection(compare.Equal, summon.FlowIn);
