    private static bool AddOlgierdRoundStartGraveyardReturn(
        XElement ability,
        int normalReduction,
        int irisReduction)
    {
        if (normalReduction < 1 || irisReduction < 1)
            throw new InvalidOperationException("Olgierd: base-power reductions must be positive.");
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "Iris", StringComparison.Ordinal)))
