        int ownerPlayer = editor.AddGetOwnerPlayerId();
        InitialDeckEndpoints initialDeck = editor.AddGetInitialDeckDefinitions();
        int irisList = editor.AddGetCardDefinitionListVariable(irisDefinitions);
        DefinitionFilterEndpoints irisFilter = editor.AddFilterCardDefinitionList();
        DefinitionListFilterEndpoints hasIris = editor.AddFilterCardDefinitionListNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int owner = editor.AddGetAbilityOwner();
        PositionEndpoints meleePosition = editor.AddGetRandomLastAvailablePosition(location: 1);
        MoveCardsEndpoints moveWithIris = editor.AddMoveCards();
        MoveCardsEndpoints moveWithoutIris = editor.AddMoveCards();
        PowerEndpoints reduceWithIris = editor.AddChangePower(
            amount: irisReduction,
            operation: 1,
            elementType: 1024,
            attackMethod: 0,
            targetedPower: 1);
        PowerEndpoints reduceWithoutIris = editor.AddChangePower(
            amount: normalReduction,
            operation: 1,
            elementType: 1024,
            attackMethod: 0,
            targetedPower: 1);

        editor.AddConnection(ownerPlayer, initialDeck.PlayerId);
        editor.AddConnection(irisList, irisFilter.Definitions);
        editor.AddConnection(roundStart.FlowOut, hasIris.FlowIn);
        editor.AddConnection(initialDeck.Out, hasIris.Definitions);
        editor.AddConnection(irisFilter.Out, hasIris.Filter);
        editor.AddConnection(ownerPlayer, meleePosition.PlayerId);

        editor.AddConnection(hasIris.Success, moveWithIris.FlowIn);
        editor.AddConnection(ownerCards, moveWithIris.Cards);
        editor.AddConnection(meleePosition.Position, moveWithIris.Position);
        editor.AddConnection(moveWithIris.FlowOut, reduceWithIris.FlowIn);
        editor.AddConnection(ownerCards, reduceWithIris.Targets);
        editor.AddConnection(owner, reduceWithIris.Attacker);

        editor.AddConnection(hasIris.Fail, moveWithoutIris.FlowIn);
        editor.AddConnection(ownerCards, moveWithoutIris.Cards);
        editor.AddConnection(meleePosition.Position, moveWithoutIris.Position);
        editor.AddConnection(moveWithoutIris.FlowOut, reduceWithoutIris.FlowIn);
        editor.AddConnection(ownerCards, reduceWithoutIris.Targets);
        editor.AddConnection(owner, reduceWithoutIris.Attacker);
        editor.Finish();
        return true;
    }

