    private static bool AddGimpyBombDamageBonus(XElement ability)
    {
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "GimpyGerwinReferenceV2", StringComparison.Ordinal)))
        {
            return false;
        }

        var editor = new GraphEditor(ability);
        int gimpyDefinitions = editor.AddCardDefinitionListVariable("GimpyGerwinReferenceV2", GimpyGerwin);
        XElement gimpyVariable = editor.TemporaryVariables.Elements().Single(variable =>
            (int?)variable.Attribute("Id") == gimpyDefinitions);
        gimpyVariable.SetAttributeValue("HideInTooltip", "True");

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        InitialDeckEndpoints initialDeck = editor.AddGetInitialDeckDefinitions(unique: true);
        int gimpyList = editor.AddGetCardDefinitionListVariable(gimpyDefinitions);
        CardDefinitionListLengthEndpoints gimpyCount = editor.AddCardDefinitionListLength();

        editor.AddConnection(ownerPlayer, initialDeck.PlayerId);
        editor.AddConnection(gimpyList, initialDeck.Definitions);
        editor.AddConnection(initialDeck.Out, gimpyCount.List);

        List<(int Endpoint, int Literal)> damageInputs = new();
        foreach (XElement node in ability.Element("Nodes")!.Elements().ToList())
        {
            if (string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                (string?)node.Element("Operation")?.Attribute("V") == "1")
            {
                XElement power = node.Element("Power")!;
                damageInputs.Add((Id(power), (int?)power.Attribute("V") ?? 0));
            }

            if (!string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal))
                continue;
            foreach (XElement mapping in node.Element("VarMappings")?.Elements() ?? Enumerable.Empty<XElement>())
            {
                XElement? data = mapping.Element("Data");
                if (data == null ||
                    !string.Equals((string?)data.Attribute("Type"), "IntVar", StringComparison.Ordinal) ||
                    !string.Equals(mapping.Element("IsInput")?.Value, "True", StringComparison.OrdinalIgnoreCase) ||
                    !((string?)data.Attribute("Name") ?? "").Contains("damage", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }
                damageInputs.Add((Id(data), (int?)data.Attribute("V") ?? 0));
            }
        }

        foreach ((int endpoint, int literal) in damageInputs.DistinctBy(item => item.Endpoint))
        {
            IReadOnlyList<int> sources = editor.GetIncomingSources(endpoint);
            int baseValue;
            if (sources.Count == 1)
            {
                baseValue = sources[0];
                editor.RemoveConnection(baseValue, endpoint);
            }
            else if (sources.Count == 0)
            {
                int baseVariable = editor.EnsureIntVariable($"GimpyBaseDamage{endpoint}", literal);
                baseValue = editor.AddGetIntVariable(baseVariable);
            }
            else
            {
                throw new InvalidOperationException(
                    $"Bomb {ability.Attribute("Id")}: damage input {endpoint} has {sources.Count} sources.");
            }

            IntPlusEndpoints plus = editor.AddIntPlus();
            editor.AddConnection(baseValue, plus.A);
            editor.AddConnection(gimpyCount.Length, plus.B);
            editor.AddConnection(plus.Result, endpoint);
        }

        editor.Finish();
        return true;
    }

