        editor.AddConnection(random.Card, singleton.Card);
        editor.AddConnection(random.FlowOut, boost.FlowIn);
        editor.AddConnection(singleton.List, boost.Targets);
        editor.AddConnection(owner, boost.Attacker);
        foreach (int target in downstream)
        {
            editor.AddConnection(deathblow.Fail, target);
            editor.AddConnection(constructs.Fail, target);
            editor.AddConnection(boost.FlowOut, target);
        }
        editor.Finish();
        return true;
    }

