    private static bool UsesSubAbility(XElement ability, string subAbilityId) =>
        ability.Element("Nodes")?.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
            node.Element("SubAbilityID")?.Value == subAbilityId) == true;

    private static int GetSubAbilityFlowEndpoint(
        XElement subAbilityNode,
        int idInAbility,
        bool input)
    {
        XElement mapping = subAbilityNode.Element("ConnectionMappings")?.Elements()
            .Single(element =>
                (int?)element.Element("IdOfDataInAbility") == idInAbility &&
                string.Equals((string?)element.Element("IsInput"), input ? "True" : "False", StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                $"SubAbility {subAbilityNode.Element("SubAbilityID")?.Value}: FlowConnector {idInAbility} не найден.");
        return (int?)mapping.Element("Data")?.Attribute("Id")
            ?? throw new InvalidDataException("ConnectionMapping/Data не содержит Id.");
    }

    private static int GetSubAbilityVariableEndpoint(
        XElement subAbilityNode,
        int idInAbility,
        bool input)
    {
        XElement mapping = subAbilityNode.Element("VarMappings")?.Elements()
            .Single(element =>
                (int?)element.Element("IdOfDataInAbility") == idInAbility &&
                string.Equals((string?)element.Element("IsInput"), input ? "True" : "False", StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                $"SubAbility {subAbilityNode.Element("SubAbilityID")?.Value}: variable {idInAbility} не найдена.");
        return (int?)mapping.Element("Data")?.Attribute("Id")
            ?? throw new InvalidDataException("VarMapping/Data не содержит Id.");
    }

    private static int FindRequiredTemporaryVariableId(XElement ability, string name, string type)
    {
        XElement? variable = ability.Element("TemporaryVariables")?.Elements().FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Name"), name, StringComparison.Ordinal) &&
            string.Equals((string?)element.Attribute("Type"), type, StringComparison.Ordinal));
        return (int?)variable?.Attribute("Id")
            ?? throw new InvalidOperationException($"Temporary variable {name} ({type}) не найдена.");
    }

    private static int GetSingleIncomingSource(GraphEditor editor, int destination, string context)
    {
        IReadOnlyList<int> sources = editor.GetIncomingSources(destination);
        if (sources.Count != 1)
            throw new InvalidOperationException(
                $"{context}: ожидалось одно входящее соединение в Id={destination}, найдено {sources.Count}.");
        return sources[0];
    }

    private static int? FindExistingInfusionAbilityId(XElement ability)
    {
        bool usesInfusion = ability.Element("Nodes")?.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
            node.Element("SubAbilityID")?.Value == "46") == true;
        if (!usesInfusion)
            return null;

        XElement? variable = ability.Element("TemporaryVariables")?.Elements().FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Type"), "InjectableAbilityVar", StringComparison.Ordinal) &&
            int.TryParse((string?)element.Attribute("V"), out _));
        return (int?)variable?.Attribute("V");
    }

    private static void NormalizeInfusionVariableName(XElement ability, int injectableAbilityId)
    {
        foreach (XElement variable in ability.Element("TemporaryVariables")?.Elements() ?? Enumerable.Empty<XElement>())
        {
            if (string.Equals((string?)variable.Attribute("Type"), "InjectableAbilityVar", StringComparison.Ordinal) &&
                (int?)variable.Attribute("V") == injectableAbilityId)
            {
                variable.SetAttributeValue("Name", "InjectableAbility");
            }
        }
    }

    private static void AddWitcherInfusion(
        XElement ability,
        int injectableAbilityId,
        bool heal)
    {
        var editor = new GraphEditor(ability);
        XElement boost = FindNode(ability, "ChangePowerNode");
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        AddWitcherInfusionBranch(
            editor,
            Id(boost.Element("FlowOut")!),
            Id(request.Element("SelectedTargets")!),
            injectableAbilityId,
            heal);
        editor.Finish();
    }

    private static void AddWitcherInfusionBranch(
        GraphEditor editor,
        int sourceFlow,
        int selectedTargets,
        int injectableAbilityId,
        bool heal)
    {
        NodeEndpoints witcher = editor.AddFilterCardCategory(
            e0: 2147483648UL, e1: 0, e2: 0);
        FilterListEndpoints filter = editor.AddFilterCardList();
        editor.AddConnection(witcher.Out, filter.Filter);
        editor.AddConnection(selectedTargets, filter.Cards);
        editor.AddConnection(sourceFlow, filter.FlowIn);

        int flow = filter.Success;
        int ownerOut = editor.AddGetAbilityOwner();
        if (heal)
        {
            ResetEndpoints reset = editor.AddResetCards(resetMode: 1);
            editor.AddConnection(flow, reset.FlowIn);
            editor.AddConnection(ownerOut, reset.Attacker);
            editor.AddConnection(filter.FilteredCards, reset.Targets);
            flow = reset.FlowOut;
        }

        int variableId = editor.AddInjectableVariable("InjectableAbility", injectableAbilityId);
        int injectableValue = editor.AddGetInjectableVariable(variableId);
        SubAbilityEndpoints infusion = editor.AddInfusionSubAbility();
        editor.AddConnection(flow, infusion.FlowIn);
        editor.AddConnection(filter.FilteredCards, infusion.Targets);
        editor.AddConnection(injectableValue, infusion.InjectableAbility);
    }

    private static bool RestrictInfusionToOrder(XElement ability)
    {
        var editor = new GraphEditor(ability);
        XElement nodes = ability.Element("Nodes")
            ?? throw new InvalidDataException("Ability не содержит Nodes.");

        XElement playedTrigger = nodes.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "PlayedTrigger", StringComparison.Ordinal));
        XElement tappedTrigger = nodes.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "TappedTrigger", StringComparison.Ordinal));
        int playedFlow = Id(playedTrigger.Element("FlowOut")!);
        int tappedFlow = Id(tappedTrigger.Element("FlowOut")!);

        List<XElement> requests = nodes.Elements().Where(node =>
            string.Equals((string?)node.Attribute("Type"), "RequestCardTargetsNode", StringComparison.Ordinal))
            .ToList();

        XElement? sharedRequest = requests.SingleOrDefault(request =>
        {
            int flowIn = Id(request.Element("FlowIn")!);
            IReadOnlyList<int> sources = editor.GetIncomingSources(flowIn);
            return sources.Contains(playedFlow) && sources.Contains(tappedFlow);
        });

        if (sharedRequest == null)
        {
            bool hasDeployRequest = requests.Any(request =>
                editor.GetIncomingSources(Id(request.Element("FlowIn")!)).Contains(playedFlow));
            bool hasOrderRequest = requests.Any(request =>
                editor.GetIncomingSources(Id(request.Element("FlowIn")!)).Contains(tappedFlow));
            if (hasDeployRequest && hasOrderRequest)
                return false;

            throw new InvalidOperationException(
                "Thunderbolt: не найдена общая ветка выбора цели для Размещения и Приказа.");
        }

        int sharedRequestFlowIn = Id(sharedRequest.Element("FlowIn")!);
        int sharedRequestSuccess = Id(sharedRequest.Element("FlowOutSuccess")!);
        int sharedSelectedTargets = Id(sharedRequest.Element("SelectedTargets")!);
        int sharedValidTargets = Id(sharedRequest.Element("ValidTargets")!);

        XElement orderBoost = nodes.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
            editor.HasConnection(sharedRequestSuccess, Id(node.Element("FlowIn")!)) &&
            editor.HasConnection(sharedSelectedTargets, Id(node.Element("Targets")!)));

        int orderBoostFlowOut = Id(orderBoost.Element("FlowOut")!);
        XElement infusionFilter = nodes.Elements().SingleOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "FilterCardListNode", StringComparison.Ordinal) &&
            editor.HasConnection(orderBoostFlowOut, Id(node.Element("FlowIn")!)))
            ?? throw new InvalidOperationException(
                "Thunderbolt: после общего усиления не найдена ветка проверки ведьмака для настоя.");

        XElement infusionNode = nodes.Elements().SingleOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
            node.Element("SubAbilityID")?.Value == "46")
            ?? throw new InvalidOperationException("Thunderbolt: узел добавления настоя не найден.");
        int infusionFlowIn = Id(infusionNode.Element("ConnectionMappings")!.Elements()
            .Single(mapping =>
                mapping.Element("IdOfDataInAbility")?.Value == "5" &&
                mapping.Element("IsInput")?.Value == "True")
            .Element("Data")!);
        int infusionFilterSuccess = Id(infusionFilter.Element("FlowSuccess")!);
        if (!editor.HasConnection(infusionFilterSuccess, infusionFlowIn))
        {
            throw new InvalidOperationException(
                "Thunderbolt: ветка проверки ведьмака не соединена с добавлением настоя.");
        }

        int minTargets = ReadIntValue(sharedRequest, "MinTargets");
        int maxTargets = ReadIntValue(sharedRequest, "MaxTargets");
        long aiHint = ReadLongNestedValue(sharedRequest, "AIHint", "e0");
        TargetRequestEndpoints deployRequest = editor.AddRequestCardTargets(
            minTargets,
            maxTargets,
            aiHint);

        foreach (int validTargetsSource in editor.GetIncomingSources(sharedValidTargets))
            editor.AddConnection(validTargetsSource, deployRequest.ValidTargets);

        int boostAmount = ReadIntValue(orderBoost, "Power");
        int boostOperation = ReadIntValue(orderBoost, "Operation");
        int boostElementType = ReadIntValue(orderBoost, "ElementType");
        int boostAttackMethod = ReadIntValue(orderBoost, "AttackMethod");
        int boostEffectType = ReadIntValue(orderBoost, "EffectType");
        int boostTargetedPower = ReadIntValue(orderBoost, "TargetedPower");
        PowerEndpoints deployBoost = editor.AddChangePower(
            boostAmount,
            boostOperation,
            boostElementType,
            boostAttackMethod,
            boostEffectType,
            boostTargetedPower);

        editor.RemoveConnection(playedFlow, sharedRequestFlowIn);
        editor.AddConnection(playedFlow, deployRequest.FlowIn);
        editor.AddConnection(deployRequest.Success, deployBoost.FlowIn);
        editor.AddConnection(deployRequest.SelectedTargets, deployBoost.Targets);

        foreach (int attackerSource in editor.GetIncomingSources(Id(orderBoost.Element("Attacker")!)))
            editor.AddConnection(attackerSource, deployBoost.Attacker);
        foreach (int powerSource in editor.GetIncomingSources(Id(orderBoost.Element("Power")!)))
            editor.AddConnection(powerSource, deployBoost.Power);

        editor.Finish();
        return true;
    }

    private static void CopyPowerVisualParameters(XElement source, XElement target)
    {
        foreach (string fieldName in new[] { "ElementType", "AttackMethod", "EffectType" })
        {
            XElement sourceField = source.Element(fieldName)
                ?? throw new InvalidDataException($"{source.Attribute("Type")}.{fieldName} не найден.");
            XElement targetField = target.Element(fieldName)
                ?? throw new InvalidDataException($"{target.Attribute("Type")}.{fieldName} не найден.");
            targetField.SetAttributeValue("V", (string?)sourceField.Attribute("V") ?? "0");
        }
    }

    private static int ReadIntValue(XElement node, string childName)
    {
        XElement child = node.Element(childName)
            ?? throw new InvalidDataException($"{node.Attribute("Type")}.{childName} не найден.");
        return int.TryParse((string?)child.Attribute("V"), out int value)
            ? value
            : throw new InvalidDataException($"{node.Attribute("Type")}.{childName} не содержит числового V.");
    }

    private static long ReadLongNestedValue(XElement node, string containerName, string childName)
    {
        XElement child = node.Element(containerName)?.Element("V")?.Element(childName)
            ?? throw new InvalidDataException(
                $"{node.Attribute("Type")}.{containerName}/V/{childName} не найден.");
        return long.TryParse((string?)child.Attribute("V"), out long value)
            ? value
            : throw new InvalidDataException(
                $"{node.Attribute("Type")}.{containerName}/V/{childName} не содержит числового V.");
    }

    private static int CreateRandomEnemyDamageInjectable(
        AbilityDocument document,
        int damage)
    {
        XElement root = document.Document.Root
            ?? throw new InvalidDataException("Abilities.xml не содержит root.");
        int injectableId = root.Elements("Ability")
            .Where(element => (string?)element.Attribute("Type") == "InjectableAbility")
            .Select(element => (int?)element.Attribute("Id") ?? 0)
            .DefaultIfEmpty(0)
            .Max() + 1;

        var ability = new XElement("Ability",
            new XAttribute("Type", "InjectableAbility"),
            new XAttribute("NId", 1),
            new XAttribute("Id", injectableId),
            new XAttribute("TributeVarID", 0),
            new XAttribute("ProfitVarID", 0),
            new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("Nodes"),
            new XElement("Connections"));
        var editor = new GraphEditor(ability);
        TurnTriggerEndpoints trigger = editor.AddAfterOwnerTurnTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        editor.AddConnection(ownerPlayer, trigger.PlayerFilter);
        int opponentPlayer = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(ignoreTokens: 8);
        editor.AddConnection(opponentPlayer, enemies.PlayerId);
        CardListBranchEndpoints branch = editor.AddCardListBranch();
        editor.AddConnection(trigger.FlowOut, branch.FlowIn);
        editor.AddConnection(enemies.Out, branch.List);
        RandomCardEndpoints random = editor.AddRandomCard();
        editor.AddConnection(branch.True, random.FlowIn);
        editor.AddConnection(enemies.Out, random.List);
        ElementListEndpoints singleton = editor.AddCardElementToList();
        editor.AddConnection(random.Card, singleton.Card);
        PowerEndpoints hit = editor.AddChangePower(damage, operation: 1);
        editor.AddConnection(random.FlowOut, hit.FlowIn);
        editor.AddConnection(singleton.List, hit.Targets);
        int ownerOut = editor.AddGetAbilityOwner();
        editor.AddConnection(ownerOut, hit.Attacker);
        editor.Finish();
        root.Add(ability);
        return injectableId;
    }

    private static bool EnsureAglaisIthlinneAbilitiesSwapped(
        XElement aglaisAbility,
        XElement ithlinneAbility)
    {
        bool aglaisHasIthlinneGraph =
            aglaisAbility.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "RequestCardChoiceNode", StringComparison.Ordinal)) &&
            aglaisAbility.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "Boost", StringComparison.Ordinal));
        bool ithlinneHasAglaisGraph =
            ithlinneAbility.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "AfterTurnTrigger", StringComparison.Ordinal)) &&
            ithlinneAbility.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "IntForeachNode", StringComparison.Ordinal));

        if (aglaisHasIthlinneGraph && ithlinneHasAglaisGraph)
            return false;

        bool aglaisHasOriginalGraph =
            aglaisAbility.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "AfterTurnTrigger", StringComparison.Ordinal));
        bool ithlinneHasOriginalGraph =
            ithlinneAbility.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "RequestCardChoiceNode", StringComparison.Ordinal));
        if (!aglaisHasOriginalGraph || !ithlinneHasOriginalGraph)
        {
            throw new InvalidOperationException(
                "Aglais/Ithlinne: neither the original pair nor the already-swapped pair was recognized.");
        }

        XElement aglaisSnapshot = new(aglaisAbility);
        XElement ithlinneSnapshot = new(ithlinneAbility);
        ReplaceCardAbilityDefinition(aglaisAbility, ithlinneSnapshot);
        ReplaceCardAbilityDefinition(ithlinneAbility, aglaisSnapshot);
        return true;
    }

    private static bool EnsureSheTrollHasOriginalImlerithAbility(
        XElement sheTrollAbility,
        XElement currentImlerithAbility)
    {
        static bool IsOriginalImlerithGraph(XElement ability) =>
            ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "DrawCardsNode", StringComparison.Ordinal)) &&
            ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "RequestCardChoiceNode", StringComparison.Ordinal)) &&
            ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "MoveCardsNode", StringComparison.Ordinal));

        if (IsOriginalImlerithGraph(sheTrollAbility))
            return false;
        if (!IsOriginalImlerithGraph(currentImlerithAbility))
        {
            throw new InvalidOperationException(
                "She-Troll: current Imlerith no longer contains the original draw/discard graph and She-Troll has not been migrated.");
        }

        ReplaceCardAbilityDefinition(sheTrollAbility, new XElement(currentImlerithAbility));
        return true;
    }

    private static void ReplaceCardAbilityDefinition(XElement target, XElement source)
    {
        string type = (string?)target.Attribute("Type") ?? "CardAbility";
        string id = (string?)target.Attribute("Id")
            ?? throw new InvalidDataException("Target CardAbility does not contain Id.");

        target.RemoveAttributes();
        foreach (XAttribute attribute in source.Attributes())
        {
            if (attribute.Name.LocalName is "Type" or "Id")
                continue;
            target.SetAttributeValue(attribute.Name, attribute.Value);
        }
        target.SetAttributeValue("Type", type);
        target.SetAttributeValue("Id", id);

        target.RemoveNodes();
        foreach (XElement child in source.Elements())
            target.Add(new XElement(child));
    }


    private static void RebuildImlerithFrostClashDuel(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);

        // Deploy: boost by Frost duration in the opposite row.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int ownerEntity = editor.AddGetAbilityOwner();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        CardLocationEndpoints ownerRow = editor.AddGetCardLocationId(positionType: 0);
        MakeLocationEndpoints oppositeRow = editor.AddMakeLocation();
        LocationTimerEndpoints frostDuration = editor.AddGetLocationTimer();
        GetLocationsEndpoints opponentFrostRows = editor.AddGetLocations(tokenMask: 1, locationMask: 3);
        LocationListContainsEndpoints oppositeHasFrost = editor.AddLocationListContainsElement();
        BranchEndpoints frostBranch = editor.AddBranch();
        PowerEndpoints deployBoost = editor.AddChangePower(
            amount: 0,
            operation: 0,
            elementType: 512,
            attackMethod: 1);

        editor.AddConnection(ownerCard, ownerRow.Card);
        editor.AddConnection(opponent, oppositeRow.PlayerId);
        editor.AddConnection(ownerRow.Location, oppositeRow.LocationId);
        editor.AddConnection(oppositeRow.Location, frostDuration.Location);
        editor.AddConnection(opponent, opponentFrostRows.PlayerMask);
        editor.AddConnection(opponentFrostRows.Out, oppositeHasFrost.List);
        editor.AddConnection(oppositeRow.Location, oppositeHasFrost.Element);
        editor.AddConnection(deploy.FlowOut, frostBranch.FlowIn);
        editor.AddConnection(oppositeHasFrost.Result, frostBranch.Condition);
        editor.AddConnection(frostBranch.True, deployBoost.FlowIn);
        editor.AddConnection(ownerEntity, deployBoost.Attacker);
        editor.AddConnection(ownerCards, deployBoost.Targets);
        editor.AddConnection(frostDuration.Timer, deployBoost.Power);

        // Order: choose an enemy, Clash normally or run an inline Duel under Dominance.
        TriggerEndpoints order = editor.AddTappedTrigger();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 8_388_608L);
        CardElementEndpoints targetCard = editor.AddCardListGetElement(index: 0);
        KeywordBranchEndpoints dominance = editor.AddDominanceBranchSubAbility();

        int imlerithClashPowerVariable = editor.EnsureIntVariable("ImlerithClashPower", 0);
        int enemyClashPowerVariable = editor.EnsureIntVariable("ImlerithEnemyClashPower", 0);
        CardPowerEndpoints imlerithPower = editor.AddGetCardPower();
        CardPowerEndpoints enemyPower = editor.AddGetCardPower();
        SetVarEndpoints snapshotImlerithPower = editor.AddSetIntVariable(imlerithClashPowerVariable);
        SetVarEndpoints snapshotEnemyPower = editor.AddSetIntVariable(enemyClashPowerVariable);
        int savedImlerithPower = editor.AddGetIntVariable(imlerithClashPowerVariable);
        int savedEnemyPower = editor.AddGetIntVariable(enemyClashPowerVariable);
        PowerEndpoints clashEnemy = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 4096,
            attackMethod: 0);
        PowerEndpoints clashImlerith = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 4096,
            attackMethod: 0);
        DeathblowEndpoints deathblow = editor.AddDeathblowSubAbility();

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, targetCard.List);
        editor.AddConnection(target.Success, dominance.FlowIn);

        editor.AddConnection(ownerCard, imlerithPower.Card);
        editor.AddConnection(targetCard.Card, enemyPower.Card);
        editor.AddConnection(dominance.Regular, snapshotImlerithPower.FlowIn);
        editor.AddConnection(imlerithPower.Power, snapshotImlerithPower.In);
        editor.AddConnection(snapshotImlerithPower.FlowOut, snapshotEnemyPower.FlowIn);
        editor.AddConnection(enemyPower.Power, snapshotEnemyPower.In);
        editor.AddConnection(snapshotEnemyPower.FlowOut, clashEnemy.FlowIn);
        editor.AddConnection(ownerEntity, clashEnemy.Attacker);
        editor.AddConnection(target.SelectedTargets, clashEnemy.Targets);
        editor.AddConnection(savedImlerithPower, clashEnemy.Power);
        editor.AddConnection(clashEnemy.FlowOut, clashImlerith.FlowIn);
        editor.AddConnection(ownerEntity, clashImlerith.Attacker);
        editor.AddConnection(ownerCards, clashImlerith.Targets);
        editor.AddConnection(savedEnemyPower, clashImlerith.Power);
        editor.AddConnection(clashImlerith.FlowOut, deathblow.FlowIn);
        editor.AddConnection(target.SelectedTargets, deathblow.Targets);

        // Native Duel SubAbility 20 has no mapped FlowOut when the target reaches 0 power:
        // its target-power IntBranch Equal/Smaller outputs are intentionally unconnected.
        // Therefore no caller-side post-Duel check can run on a successful kill. Reproduce the
        // native loop inline and attach the Hound spawn directly to those terminal branches.
        int duelLoopVariable = editor.EnsureIntVariable("ImlerithDuelLoop", 0);
        int duelDamageVariable = editor.EnsureIntVariable("ImlerithDuelDamage", 0);

        SetVarEndpoints resetDuelLoop = editor.AddSetIntVariable(duelLoopVariable);
        SetEndpointValue(ability, resetDuelLoop.In, "0");

        CardPowerEndpoints duelImlerithPower = editor.AddGetCardPower();
        SetVarEndpoints snapshotDuelImlerithPower = editor.AddSetIntVariable(duelDamageVariable);
        int savedDuelImlerithPower = editor.AddGetIntVariable(duelDamageVariable);
        PowerEndpoints duelStrikeEnemy = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 1,
            attackMethod: 1);
        CardPowerEndpoints enemyPowerAfterDuelHit = editor.AddGetCardPower();
        IntBranchEndpoints enemyAliveAfterDuelHit = editor.AddIntBranch();
        SetEndpointValue(ability, enemyAliveAfterDuelHit.B, "0");

        SetVarEndpoints snapshotDuelEnemyPower = editor.AddSetIntVariable(duelDamageVariable);
        int savedDuelEnemyPower = editor.AddGetIntVariable(duelDamageVariable);
        PowerEndpoints duelStrikeImlerith = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 1,
            attackMethod: 1);
        CardPowerEndpoints imlerithPowerAfterDuelHit = editor.AddGetCardPower();
        IntBranchEndpoints imlerithAliveAfterDuelHit = editor.AddIntBranch();
        SetEndpointValue(ability, imlerithAliveAfterDuelHit.B, "0");

        int duelLoopValue = editor.AddGetIntVariable(duelLoopVariable);
        IntPlusEndpoints increaseDuelLoop = editor.AddIntPlus();
        SetEndpointValue(ability, increaseDuelLoop.B, "1");
        SetVarEndpoints saveDuelLoop = editor.AddSetIntVariable(duelLoopVariable);
        IntBranchEndpoints duelLoopLimit = editor.AddIntBranch();
        SetEndpointValue(ability, duelLoopLimit.B, "10");

        editor.AddConnection(dominance.Active, resetDuelLoop.FlowIn);
        editor.AddConnection(resetDuelLoop.FlowOut, snapshotDuelImlerithPower.FlowIn);
        editor.AddConnection(ownerCard, duelImlerithPower.Card);
        editor.AddConnection(duelImlerithPower.Power, snapshotDuelImlerithPower.In);
        editor.AddConnection(snapshotDuelImlerithPower.FlowOut, duelStrikeEnemy.FlowIn);
        editor.AddConnection(ownerCard, duelStrikeEnemy.Attacker);
        editor.AddConnection(target.SelectedTargets, duelStrikeEnemy.Targets);
        editor.AddConnection(savedDuelImlerithPower, duelStrikeEnemy.Power);

        editor.AddConnection(duelStrikeEnemy.FlowOut, enemyAliveAfterDuelHit.FlowIn);
        editor.AddConnection(targetCard.Card, enemyPowerAfterDuelHit.Card);
        editor.AddConnection(enemyPowerAfterDuelHit.Power, enemyAliveAfterDuelHit.A);
        editor.AddConnection(enemyAliveAfterDuelHit.Bigger, snapshotDuelEnemyPower.FlowIn);
        editor.AddConnection(enemyPowerAfterDuelHit.Power, snapshotDuelEnemyPower.In);

        editor.AddConnection(snapshotDuelEnemyPower.FlowOut, duelStrikeImlerith.FlowIn);
        editor.AddConnection(targetCard.Card, duelStrikeImlerith.Attacker);
        editor.AddConnection(ownerCards, duelStrikeImlerith.Targets);
        editor.AddConnection(savedDuelEnemyPower, duelStrikeImlerith.Power);

        editor.AddConnection(duelStrikeImlerith.FlowOut, imlerithAliveAfterDuelHit.FlowIn);
        editor.AddConnection(ownerCard, imlerithPowerAfterDuelHit.Card);
        editor.AddConnection(imlerithPowerAfterDuelHit.Power, imlerithAliveAfterDuelHit.A);

        editor.AddConnection(imlerithAliveAfterDuelHit.Bigger, saveDuelLoop.FlowIn);
        editor.AddConnection(duelLoopValue, increaseDuelLoop.A);
        editor.AddConnection(increaseDuelLoop.Result, saveDuelLoop.In);
        editor.AddConnection(saveDuelLoop.FlowOut, duelLoopLimit.FlowIn);
        editor.AddConnection(saveDuelLoop.Out, duelLoopLimit.A);
        editor.AddConnection(duelLoopLimit.Smaller, snapshotDuelImlerithPower.FlowIn);

        // Deathblow: spawn a 1-power Wild Hunt Hound immediately to Imlerith's right.
        AdjacentPositionEndpoints right = editor.AddGetCardPositionOnRight();
        SpawnEndpoints hound = editor.AddSpawnCard(WildHuntHound, count: 1, spawnType: 3);
        PowerEndpoints setHoundPower = editor.AddChangePower(
            amount: 1,
            operation: 2,
            elementType: 1024,
            attackMethod: 0);
        editor.AddConnection(ownerCard, right.Card);
        editor.AddConnection(deathblow.Deathblow, hound.FlowIn);
        editor.AddConnection(enemyAliveAfterDuelHit.Equal, hound.FlowIn);
        editor.AddConnection(enemyAliveAfterDuelHit.Smaller, hound.FlowIn);
        editor.AddConnection(ownerCard, hound.Spawner);
        editor.AddConnection(right.Position, hound.Position);
        editor.AddConnection(hound.FlowOut, setHoundPower.FlowIn);
        editor.AddConnection(ownerEntity, setHoundPower.Attacker);
        editor.AddConnection(hound.SpawnedCards, setHoundPower.Targets);

        editor.Finish();
    }

    private static bool RestoreWhiteFrostLeaderFrost(XElement ability)
    {
        XElement nodes = ability.Element("Nodes")
            ?? throw new InvalidOperationException("White Frost: Nodes container is missing.");
        XElement connections = ability.Element("Connections")
            ?? throw new InvalidOperationException("White Frost: Connections container is missing.");

        XElement node = nodes.Elements().Single(element =>
            string.Equals((string?)element.Attribute("Type"), "ChangeLocationTokensNode", StringComparison.Ordinal));
        XElement tokens = node.Element("Tokens")
            ?? throw new InvalidOperationException("White Frost: ChangeLocationTokensNode has no Tokens field.");
        XElement overrideTime = node.Element("OverrideTime")
            ?? throw new InvalidOperationException("White Frost: ChangeLocationTokensNode has no OverrideTime field.");

        bool changed = (string?)tokens.Attribute("V") != "1" ||
            (string?)overrideTime.Attribute("V") != "0";
        tokens.SetAttributeValue("V", "1");
        overrideTime.SetAttributeValue("V", "0");

        XElement counterVariable = ability.Element("TemporaryVariables")!.Elements().Single(variable =>
            string.Equals((string?)variable.Attribute("Name"), "counter", StringComparison.OrdinalIgnoreCase));
        int counterVariableId = (int?)counterVariable.Attribute("Id")
            ?? throw new InvalidOperationException("White Frost: counter variable has no Id.");
        XElement counterGetter = nodes.Elements().Single(element =>
            string.Equals((string?)element.Attribute("Type"), "GetVarNode", StringComparison.Ordinal) &&
            (int?)element.Attribute("VarId") == counterVariableId);
        int counterOutput = (int?)counterGetter.Element("Out")?.Attribute("Id")
            ?? throw new InvalidOperationException("White Frost: counter getter has no output endpoint.");
        int durationInput = (int?)overrideTime.Attribute("Id")
            ?? throw new InvalidOperationException("White Frost: OverrideTime has no endpoint Id.");

        var endpointIds = nodes.DescendantsAndSelf()
            .Attributes("Id")
            .Select(attribute => int.TryParse(attribute.Value, out int value) ? value : -1)
            .Where(value => value >= 0)
            .ToHashSet();

        // Remove stale connections first. Earlier repair attempts could leave a link to
        // the old OverrideTime endpoint after another operation replaced the weather node.
        foreach (XElement connection in connections.Elements().ToList())
        {
            int? source = (int?)connection.Attribute("SrcId");
            int? destination = (int?)connection.Attribute("DstId");
            if (!source.HasValue || !destination.HasValue ||
                !endpointIds.Contains(source.Value) || !endpointIds.Contains(destination.Value))
            {
                connection.Remove();
                changed = true;
            }
        }

        // The duration input must have exactly one incoming edge, from the native
        // `counter` getter. Replace any duplicate or foreign incoming edges atomically.
        List<XElement> durationConnections = connections.Elements()
            .Where(connection => (int?)connection.Attribute("DstId") == durationInput)
            .ToList();
        bool durationIsExact = durationConnections.Count == 1 &&
            (int?)durationConnections[0].Attribute("SrcId") == counterOutput;
        if (!durationIsExact)
        {
            foreach (XElement connection in durationConnections)
                connection.Remove();

            int nextId = ability.DescendantsAndSelf()
                .Attributes("Id")
                .Select(attribute => int.TryParse(attribute.Value, out int value) ? value : 0)
                .DefaultIfEmpty(0)
                .Max() + 1;
            connections.Add(new XElement("e",
                new XAttribute("Type", "Connection"),
                new XAttribute("Id", nextId),
                new XAttribute("SrcId", counterOutput),
                new XAttribute("DstId", durationInput)));
            changed = true;
        }

        GraphValidationReport validation = GraphValidator.Validate(ability);
        if (!validation.IsValid)
        {
            string errors = string.Join(Environment.NewLine, validation.Issues
                .Where(issue => issue.Severity == ValidationSeverity.Error)
                .Select(issue => $"[{issue.Code}] {issue.Message}"));
            throw new InvalidOperationException(
                $"White Frost graph remains invalid after repair:{Environment.NewLine}{errors}");
        }

        return changed;
    }

    private static bool AddPrinceStennisRandomBronzeKnightOrder(
        XElement ability,
        XElement template)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
                string.Equals((string?)node.Attribute("Type"), "TappedTrigger", StringComparison.Ordinal)))
        {
            return false;
        }

        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        TriggerEndpoints order = editor.AddTappedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 2,
            ignoreOwner: true);
        NodeEndpoints knight = editor.AddFilterCardCategory(e0: 0, e1: 32_768, e2: 0);
        FilterListEndpoints filter = editor.AddFilterCardList();
        RandomCardEndpoints random = editor.AddRandomCard();
        ElementListEndpoints oneCard = editor.AddCardElementToList();
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(order.FlowOut, filter.FlowIn);
        editor.AddConnection(deck.Out, filter.Cards);
        editor.AddConnection(knight.Out, filter.Filter);
        editor.AddConnection(filter.Success, random.FlowIn);
        editor.AddConnection(filter.FilteredCards, random.List);
        editor.AddConnection(random.FlowOut, play.FlowIn);
        editor.AddConnection(random.Card, oneCard.Card);
        editor.AddConnection(oneCard.List, play.Cards);
        editor.Finish();
        return true;
    }


    private static void RebuildMilaenMovementGrowth(XElement ability)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int damageVariable = editor.EnsurePersistentIntVariable("Damage", 0);
        int friendlyMovedVariable = editor.EnsurePersistentIntVariable("FriendlyMoved", 0);
        int enemyMovedVariable = editor.EnsurePersistentIntVariable("EnemyMoved", 0);

        // Match native Patience cards: a referenced persistent value is visible through
        // [{Damage}] without a HideInTooltip override. Internal turn flags stay hidden.
        XElement damageVar = ability.Element("PersistentVariables")!.Elements().Single(variable =>
            (int?)variable.Attribute("Id") == damageVariable);
        damageVar.Attribute("HideInTooltip")?.Remove();
        foreach (XElement flag in ability.Element("PersistentVariables")!.Elements().Where(variable =>
            (int?)variable.Attribute("Id") == friendlyMovedVariable ||
            (int?)variable.Attribute("Id") == enemyMovedVariable))
        {
            flag.SetAttributeValue("HideInTooltip", "True");
        }

        // Deploy damage, initially 0 and permanently increased by enemy-movement turns.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 8_388_608L);
        int ownerEntity = editor.AddGetAbilityOwner();
        int currentDamage = editor.AddGetIntVariable(damageVariable);
        PowerEndpoints damage = editor.AddChangePower(amount: 0, operation: 1);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(deploy.FlowOut, request.FlowIn);
        editor.AddConnection(enemies.Out, request.ValidTargets);
        editor.AddConnection(request.Success, damage.FlowIn);
        editor.AddConnection(request.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(currentDamage, damage.Power);

        // Before the owner's turn, discard movement events collected during the opponent's turn.
        // This lets the movement triggers use the native TriggerPlayer=3 ("any") setting while the
        // end-turn effect still counts only events that happened during Milaen's owner's turn.
        TurnTriggerEndpoints beginTurn = editor.AddBeforeTurnTrigger(ownerLocation: 24);
        int ownerForBeginTurn = editor.AddGetOwnerPlayerId();
        SetVarEndpoints beginResetFriendly = editor.AddSetIntVariable(friendlyMovedVariable);
        SetVarEndpoints beginResetEnemy = editor.AddSetIntVariable(enemyMovedVariable);
        SetEndpointValue(ability, beginResetFriendly.In, "0");
        SetEndpointValue(ability, beginResetEnemy.In, "0");
        editor.AddConnection(ownerForBeginTurn, beginTurn.PlayerFilter);
        editor.AddConnection(beginTurn.FlowOut, beginResetFriendly.FlowIn);
        editor.AddConnection(beginResetFriendly.FlowOut, beginResetEnemy.FlowIn);

        // Follow the exact Dol Blathanna Sentry pattern: both side-specific movement triggers use
        // TriggerPlayer=3, while dynamic owner/opponent ids are connected to FromPlayer and ToPlayer.
        // TriggerPlayer=1 suppressed the enemy-side trigger in game, even during the owner's turn.
        int ownerForMovement = editor.AddGetOwnerPlayerId();
        int opponentForMovement = editor.AddGetOwnerOpponentPlayerId();

        AfterMovedEndpoints enemyMoved = editor.AddAfterMovedTrigger(
            ownerLocation: 24,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 3,
            toLocation: 3,
            reason: 2);
        SetVarEndpoints setEnemyMoved = editor.AddSetIntVariable(enemyMovedVariable);
        SetEndpointValue(ability, setEnemyMoved.In, "1");
        editor.AddConnection(opponentForMovement, enemyMoved.FromPlayer);
        editor.AddConnection(opponentForMovement, enemyMoved.ToPlayer);
        editor.AddConnection(enemyMoved.FlowOut, setEnemyMoved.FlowIn);

        AfterMovedEndpoints friendlyMoved = editor.AddAfterMovedTrigger(
            ownerLocation: 24,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 3,
            toLocation: 3,
            reason: 2);
        SetVarEndpoints setFriendlyMoved = editor.AddSetIntVariable(friendlyMovedVariable);
        SetEndpointValue(ability, setFriendlyMoved.In, "1");
        editor.AddConnection(ownerForMovement, friendlyMoved.FromPlayer);
        editor.AddConnection(ownerForMovement, friendlyMoved.ToPlayer);
        editor.AddConnection(friendlyMoved.FlowOut, setFriendlyMoved.FlowIn);

        // End of turn: enemy movement has priority; otherwise friendly-only movement boosts Milaen.
        TurnTriggerEndpoints endTurn = editor.AddAfterTurnTrigger(ownerLocation: 24);
        int ownerForEndTurn = editor.AddGetOwnerPlayerId();
        int enemyMovedValue = editor.AddGetIntVariable(enemyMovedVariable);
        IntBranchEndpoints enemyMovedBranch = editor.AddIntBranch();
        int friendlyMovedValue = editor.AddGetIntVariable(friendlyMovedVariable);
        IntBranchEndpoints friendlyMovedBranch = editor.AddIntBranch();
        int damageForIncrease = editor.AddGetIntVariable(damageVariable);
        IntPlusEndpoints increaseDamage = editor.AddIntPlus();
        SetEndpointValue(ability, increaseDamage.B, "1");
        SetVarEndpoints saveDamage = editor.AddSetIntVariable(damageVariable);
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        PowerEndpoints boost = editor.AddChangePower(amount: 1, operation: 0);
        SetVarEndpoints resetFriendly = editor.AddSetIntVariable(friendlyMovedVariable);
        SetVarEndpoints resetEnemy = editor.AddSetIntVariable(enemyMovedVariable);
        SetEndpointValue(ability, resetFriendly.In, "0");
        SetEndpointValue(ability, resetEnemy.In, "0");

        editor.AddConnection(ownerForEndTurn, endTurn.PlayerFilter);
        editor.AddConnection(endTurn.FlowOut, enemyMovedBranch.FlowIn);
        editor.AddConnection(enemyMovedValue, enemyMovedBranch.A);
        editor.AddConnection(enemyMovedBranch.Bigger, saveDamage.FlowIn);
        editor.AddConnection(damageForIncrease, increaseDamage.A);
        editor.AddConnection(increaseDamage.Result, saveDamage.In);
        editor.AddConnection(saveDamage.FlowOut, resetFriendly.FlowIn);

        editor.AddConnection(enemyMovedBranch.Equal, friendlyMovedBranch.FlowIn);
        editor.AddConnection(enemyMovedBranch.Smaller, friendlyMovedBranch.FlowIn);
        editor.AddConnection(friendlyMovedValue, friendlyMovedBranch.A);
        editor.AddConnection(friendlyMovedBranch.Bigger, boost.FlowIn);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(ownerCards, boost.Targets);
        editor.AddConnection(boost.FlowOut, resetFriendly.FlowIn);
        editor.AddConnection(friendlyMovedBranch.Equal, resetFriendly.FlowIn);
        editor.AddConnection(friendlyMovedBranch.Smaller, resetFriendly.FlowIn);
        editor.AddConnection(resetFriendly.FlowOut, resetEnemy.FlowIn);
        editor.Finish();
    }

    private static void RebuildBlueMountainEliteMovementSummon(XElement ability)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int movedVariable = editor.EnsurePersistentIntVariable("MovedThisTurn", 0);

        TurnTriggerEndpoints beginTurn = editor.AddBeforeTurnTrigger(ownerLocation: 16);
        int ownerForBeginTurn = editor.AddGetOwnerPlayerId();
        SetVarEndpoints reset = editor.AddSetIntVariable(movedVariable);
        SetEndpointValue(ability, reset.In, "0");
        editor.AddConnection(ownerForBeginTurn, beginTurn.PlayerFilter);
        editor.AddConnection(beginTurn.FlowOut, reset.FlowIn);

        AfterMovedEndpoints moved = editor.AddAfterMovedTrigger(
            ownerLocation: 16,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 3,
            toLocation: 3,
            reason: 2);
        CardListLengthEndpoints movedCount = editor.AddCardListLength();
        int previousCount = editor.AddGetIntVariable(movedVariable);
        IntPlusEndpoints total = editor.AddIntPlus();
        SetVarEndpoints saveCount = editor.AddSetIntVariable(movedVariable);
        IntBranchEndpoints threshold = editor.AddIntBranch();
        SetEndpointValue(ability, threshold.B, "4");

        editor.AddConnection(moved.CardsMoved, movedCount.List);
        editor.AddConnection(previousCount, total.A);
        editor.AddConnection(movedCount.Length, total.B);
        editor.AddConnection(moved.FlowOut, saveCount.FlowIn);
        editor.AddConnection(total.Result, saveCount.In);
        editor.AddConnection(saveCount.FlowOut, threshold.FlowIn);
        editor.AddConnection(saveCount.Out, threshold.A);

        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints sameTemplate = editor.AddFilterCardTemplateId(BlueMountainElite);
        FilterListEndpoints copies = editor.AddFilterCardList();
        PositionEndpoints position = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summon = editor.AddMoveCards();

        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(threshold.Bigger, copies.FlowIn);
        editor.AddConnection(threshold.Equal, copies.FlowIn);
        editor.AddConnection(deck.Out, copies.Cards);
        editor.AddConnection(sameTemplate.Out, copies.Filter);
        editor.AddConnection(owner, position.PlayerId);
        editor.AddConnection(copies.Success, summon.FlowIn);
        editor.AddConnection(copies.FilteredCards, summon.Cards);
        editor.AddConnection(position.Position, summon.Position);
        editor.Finish();
    }


    private static int EnsurePantherMovementInjectable(AbilityDocument document)
    {
        XElement root = document.Document.Root
            ?? throw new InvalidDataException("Abilities.xml не содержит root.");
        XElement? ability = root.Elements("Ability").FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Type"), "InjectableAbility", StringComparison.Ordinal) &&
            (int?)element.Attribute("Id") == PantherMovementInjectable);
        if (ability == null)
        {
            ability = new XElement("Ability",
                new XAttribute("Type", "InjectableAbility"),
                new XAttribute("NId", 1),
                new XAttribute("Id", PantherMovementInjectable),
                new XAttribute("TributeVarID", 0),
                new XAttribute("ProfitVarID", 0),
                new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
                new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
                new XElement("Nodes"),
                new XElement("Connections"));
            root.Add(ability);
        }
        else
        {
            ClearAbilityGraph(ability, clearVariables: true);
        }

        var editor = new GraphEditor(ability);
        TurnTriggerEndpoints endTurn = editor.AddAfterTurnTrigger(ownerLocation: 3);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        CardLocationEndpoints currentRow = editor.AddGetCardLocationId(positionType: 0);
        LocationNegateEndpoints otherRow = editor.AddLocationIdNegate(locationMask: 3);
        PositionEndpoints destination = editor.AddGetRandomLastAvailablePosition(location: 0);
        MoveCardsEndpoints move = editor.AddMoveCards();

        editor.AddConnection(ownerPlayer, endTurn.PlayerFilter);
        editor.AddConnection(ownerCard, currentRow.Card);
        editor.AddConnection(currentRow.Location, otherRow.In);
        editor.AddConnection(ownerPlayer, destination.PlayerId);
        editor.AddConnection(otherRow.Out, destination.Location);
        editor.AddConnection(endTurn.FlowOut, move.FlowIn);
        editor.AddConnection(ownerCards, move.Cards);
        editor.AddConnection(destination.Position, move.Position);
        editor.Finish();
        return PantherMovementInjectable;
    }

    private static void RebuildPantherMovementInfusion(XElement ability, int injectableId)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int infusionVariable = editor.AddInjectableVariable("PantherInfusion", injectableId);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        int injectable = editor.AddGetInjectableVariable(infusionVariable);
        SubAbilityEndpoints infusion = editor.AddInfusionSubAbility();
        editor.AddConnection(deploy.FlowOut, request.FlowIn);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(enemies.Out, request.ValidTargets);
        editor.AddConnection(request.Success, infusion.FlowIn);
        editor.AddConnection(request.SelectedTargets, infusion.Targets);
        editor.AddConnection(injectable, infusion.InjectableAbility);

        // This trigger is intentionally not limited to Panther's owner's turn.
        // Native AfterMovedTrigger side filters identify the opponent-owned card,
        // so Bleeding is applied whenever that enemy unit is moved on either turn.
        AfterMovedEndpoints enemyMoved = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 3,
            toLocation: 3,
            reason: 2);
        editor.AddConnection(opponent, enemyMoved.FromPlayer);
        editor.AddConnection(opponent, enemyMoved.ToPlayer);
        StatusTimerEndpoints bleeding = editor.AddBleeding(1);
        int ownerEntity = editor.AddGetAbilityOwner();
        editor.AddConnection(enemyMoved.FlowOut, bleeding.FlowIn);
        editor.AddConnection(enemyMoved.CardsMoved, bleeding.Cards);
        editor.AddConnection(ownerEntity, bleeding.Attacker);
        editor.Finish();
    }

    private static bool AddStickySituationTrapDeckAdvance(XElement ability)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "AfterGameInitializedTrigger", StringComparison.Ordinal)))
            return false;

        var editor = new GraphEditor(ability);
        TriggerEndpoints start = editor.AddAfterGameInitializedTrigger(ownerLocation: 16);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        InitialDeckEndpoints initialDeck = editor.AddGetInitialDeckDefinitions(unique: false);
        NodeEndpoints trap = editor.AddFilterCardDefinitionCategory(70_368_744_177_664UL, 0, 0);
        DefinitionListFilterEndpoints traps = editor.AddFilterCardDefinitionListNode();
        CardDefinitionListLengthEndpoints trapCount = editor.AddCardDefinitionListLength();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        CardPositionEndpoints currentPosition = editor.AddGetCardPosition(positionType: 0);
        BreakCardPositionEndpoints splitPosition = editor.AddBreakCardPosition();
        IntMinusEndpoints shiftedIndex = editor.AddIntMinus();
        IntMaxEndpoints clampedIndex = editor.AddIntMax(constantB: 0);
        MakeCardPositionEndpoints destination = editor.AddMakeCardPosition(location: 0, index: 0);
        MoveCardsEndpoints move = editor.AddMoveCards();

        editor.AddConnection(ownerPlayer, initialDeck.PlayerId);
        editor.AddConnection(initialDeck.Out, traps.Definitions);
        editor.AddConnection(trap.Out, traps.Filter);
        editor.AddConnection(start.FlowOut, traps.FlowIn);
        editor.AddConnection(traps.FilteredDefinitions, trapCount.List);
        editor.AddConnection(traps.Success, splitPosition.FlowIn);
        editor.AddConnection(ownerCard, currentPosition.Card);
        editor.AddConnection(currentPosition.Position, splitPosition.Position);
        editor.AddConnection(splitPosition.Index, shiftedIndex.A);
        editor.AddConnection(trapCount.Length, shiftedIndex.B);
        editor.AddConnection(shiftedIndex.Result, clampedIndex.A);
        editor.AddConnection(splitPosition.PlayerId, destination.PlayerId);
        editor.AddConnection(splitPosition.Location, destination.Location);
        editor.AddConnection(clampedIndex.Result, destination.Index);
        editor.AddConnection(splitPosition.FlowOut, destination.FlowIn);
        editor.AddConnection(destination.FlowOut, move.FlowIn);
        editor.AddConnection(ownerCards, move.Cards);
        editor.AddConnection(destination.Position, move.Position);
        editor.Finish();
        return true;
    }

    private static void RebuildDryadEnchantressOrdersDevotionSummon(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");
        var editor = new GraphEditor(ability);

        // Symbiosis is represented by the native marker SubAbility 38.
        int symbiosisNode = editor.NewId();
        editor.AddNode(new XElement("e",
            new XAttribute("Type", "UseSubAbilityNode"),
            new XAttribute("Id", symbiosisNode),
            new XAttribute("X", 0), new XAttribute("Y", 0),
            new XElement("SubAbilityID", "38")));

        TriggerEndpoints order = editor.AddTappedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints friendly = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10);
        TargetRequestEndpoints armorTarget = editor.AddRequestCardTargets(1, 1, 2_147_483_648L);
        ArmorEndpoints armor = editor.AddChangeArmor(2, operation: 0);
        TargetRequestEndpoints vitalityTarget = editor.AddRequestCardTargets(1, 1, 2_147_483_648L);
        StatusTimerEndpoints vitality = editor.AddVitality(2);
        editor.AddConnection(ownerPlayer, friendly.PlayerId);
        editor.AddConnection(order.FlowOut, row.FlowIn);
        editor.AddConnection(row.Melee, armorTarget.FlowIn);
        editor.AddConnection(friendly.Out, armorTarget.ValidTargets);
        editor.AddConnection(armorTarget.Success, armor.FlowIn);
        editor.AddConnection(armorTarget.SelectedTargets, armor.Targets);
        editor.AddConnection(ownerEntity, armor.Attacker);
        editor.AddConnection(row.Ranged, vitalityTarget.FlowIn);
        editor.AddConnection(friendly.Out, vitalityTarget.ValidTargets);
        editor.AddConnection(vitalityTarget.Success, vitality.FlowIn);
        editor.AddConnection(vitalityTarget.SelectedTargets, vitality.Cards);
        editor.AddConnection(ownerEntity, vitality.Attacker);

        // Devotion end-turn summon while this copy is in deck.
        TurnTriggerEndpoints endTurn = editor.AddAfterTurnTrigger(ownerLocation: 16);
        KeywordBranchEndpoints devotion = editor.AddDevotionBranchSubAbility();
        editor.AddConnection(ownerPlayer, endTurn.PlayerFilter);
        editor.AddConnection(endTurn.FlowOut, devotion.FlowIn);

        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 0, locationId: 32, cardTypes: 14, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints nature = editor.AddFilterCardCategory(0, 33_554_432UL, 0);
        FilterListEndpoints natureCards = editor.AddFilterCardList();
        CardListLengthEndpoints natureCount = editor.AddCardListLength();
        IntBranchEndpoints atLeastEight = editor.AddIntBranch();
        SetEndpointValue(ability, atLeastEight.B, "8");
        editor.AddConnection(ownerPlayer, graveyard.PlayerId);
        editor.AddConnection(devotion.Active, natureCards.FlowIn);
        editor.AddConnection(graveyard.Out, natureCards.Cards);
        editor.AddConnection(nature.Out, natureCards.Filter);
        editor.AddConnection(natureCards.FilteredCards, natureCount.List);
        editor.AddConnection(natureCards.Success, atLeastEight.FlowIn);
        editor.AddConnection(natureCount.Length, atLeastEight.A);

        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0, locationId: 16, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints sameTemplateDeck = editor.AddFilterCardTemplateId(DryadEnchantress);
        FilterListEndpoints deckCopies = editor.AddFilterCardList();
        RangeEndpoints oneCopy = editor.AddCardListGetRange(length: 1);
        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(atLeastEight.Bigger, deckCopies.FlowIn);
        editor.AddConnection(atLeastEight.Equal, deckCopies.FlowIn);
        editor.AddConnection(deck.Out, deckCopies.Cards);
        editor.AddConnection(sameTemplateDeck.Out, deckCopies.Filter);
        editor.AddConnection(deckCopies.Success, oneCopy.FlowIn);
        editor.AddConnection(deckCopies.FilteredCards, oneCopy.List);

        // Only the first deck copy is allowed to execute the summon branch. This
        // prevents two identical copies in deck from both resolving the same end-turn event.
        CardElementEndpoints firstDeckCopy = editor.AddCardListGetElement(index: 0);
        int abilityOwnerCard = editor.AddGetAbilityOwnerCardNode();
        CompareCardsEndpoints isFirstDeckCopy = editor.AddCompareCards();
        editor.AddConnection(oneCopy.TrimmedList, firstDeckCopy.List);
        editor.AddConnection(oneCopy.FlowOut, isFirstDeckCopy.FlowIn);
        editor.AddConnection(firstDeckCopy.Card, isFirstDeckCopy.A);
        editor.AddConnection(abilityOwnerCard, isFirstDeckCopy.B);

        GetCardsEndpoints board = editor.AddGetCards(
            ignoreTokens: 0, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints sameTemplateBoard = editor.AddFilterCardTemplateId(DryadEnchantress);
        FilterListEndpoints boardCopies = editor.AddFilterCardList();
        editor.AddConnection(ownerPlayer, board.PlayerId);
        editor.AddConnection(isFirstDeckCopy.Same, boardCopies.FlowIn);
        editor.AddConnection(board.Out, boardCopies.Cards);
        editor.AddConnection(sameTemplateBoard.Out, boardCopies.Filter);

        PositionEndpoints randomRow = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints randomSummon = editor.AddMoveCards();
        editor.AddConnection(ownerPlayer, randomRow.PlayerId);
        editor.AddConnection(boardCopies.Fail, randomSummon.FlowIn);
        editor.AddConnection(oneCopy.TrimmedList, randomSummon.Cards);
        editor.AddConnection(randomRow.Position, randomSummon.Position);

        // If copies occupy only one row, summon to the other one. If both rows
        // already contain an Enchantress, no valid row exists and nothing is moved.
        NodeEndpoints meleeLocation = editor.AddFilterCardLocationId(locationId: 1);
        FilterListEndpoints meleeCopies = editor.AddFilterCardList();
        NodeEndpoints rangedLocation = editor.AddFilterCardLocationId(locationId: 2);
        FilterListEndpoints rangedCopies = editor.AddFilterCardList();
        PositionEndpoints meleeRow = editor.AddGetRandomLastAvailablePosition(location: 1);
        MoveCardsEndpoints meleeSummon = editor.AddMoveCards();
        PositionEndpoints rangedRow = editor.AddGetRandomLastAvailablePosition(location: 2);
        MoveCardsEndpoints rangedSummon = editor.AddMoveCards();

        editor.AddConnection(boardCopies.Success, meleeCopies.FlowIn);
        editor.AddConnection(boardCopies.FilteredCards, meleeCopies.Cards);
        editor.AddConnection(meleeLocation.Out, meleeCopies.Filter);
        editor.AddConnection(meleeCopies.Success, rangedCopies.FlowIn);
        editor.AddConnection(boardCopies.FilteredCards, rangedCopies.Cards);
        editor.AddConnection(rangedLocation.Out, rangedCopies.Filter);

        // No copy in melee means all existing copies are in ranged: summon melee.
        editor.AddConnection(ownerPlayer, meleeRow.PlayerId);
        editor.AddConnection(meleeCopies.Fail, meleeSummon.FlowIn);
        editor.AddConnection(oneCopy.TrimmedList, meleeSummon.Cards);
        editor.AddConnection(meleeRow.Position, meleeSummon.Position);

        // Melee occupied and ranged empty: summon ranged. Ranged success means
        // both rows are occupied, so that path deliberately has no summon.
        editor.AddConnection(ownerPlayer, rangedRow.PlayerId);
        editor.AddConnection(rangedCopies.Fail, rangedSummon.FlowIn);
        editor.AddConnection(oneCopy.TrimmedList, rangedSummon.Cards);
        editor.AddConnection(rangedRow.Position, rangedSummon.Position);
        editor.Finish();
    }

    private static bool AddElvenScoutForceFriendlySpring(XElement ability)
    {
        // Migration marker for 0.27.44. The previous implementation deferred a
        // ForceCardTriggerNode through AfterDeployAbilityTrigger. That works for
        // Springs without a request (for example Deception), but the engine does
        // not open the target/choice UI of a forced face-down Trap. Targeted
        // Springs are therefore reproduced explicitly while the Trap itself
        // remains face down. Other Springs retain the native forced-trigger path.
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
            string.Equals((string?)variable.Attribute("Name"), "ElvenScoutTargetedSpringV2", StringComparison.Ordinal)))
            return false;

        var editor = new GraphEditor(ability);
        int migrationMarker = editor.EnsureIntVariable("ElvenScoutTargetedSpringV2", 1);
        XElement marker = ability.Element("TemporaryVariables")!.Elements().Single(element =>
            (int?)element.Attribute("Id") == migrationMarker);
        marker.SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int abilityOwner = editor.AddGetAbilityOwner();
        GetCardsEndpoints artifacts = editor.AddGetCards(
            ignoreTokens: 0, locationId: 3, cardTypes: 8, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints trapCategory = editor.AddFilterCardCategory(70_368_744_177_664UL, 0, 0);
        FilterListEndpoints traps = editor.AddFilterCardList();
        NodeEndpoints faceDown = editor.AddFilterCardTokens(token: 8, negate: true);
        FilterListEndpoints faceDownTraps = editor.AddFilterCardList();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 0);
        CardElementEndpoints selectedTrap = editor.AddCardListGetElement(index: 0);

        editor.AddConnection(ownerPlayer, artifacts.PlayerId);
        editor.AddConnection(deploy.FlowOut, traps.FlowIn);
        editor.AddConnection(artifacts.Out, traps.Cards);
        editor.AddConnection(trapCategory.Out, traps.Filter);
        editor.AddConnection(traps.Success, faceDownTraps.FlowIn);
        editor.AddConnection(traps.FilteredCards, faceDownTraps.Cards);
        editor.AddConnection(faceDown.Out, faceDownTraps.Filter);
        editor.AddConnection(faceDownTraps.Success, target.FlowIn);
        editor.AddConnection(faceDownTraps.FilteredCards, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, selectedTrap.List);

        // Branch 1: Incinerating Trap. Its native Spring requests any unit and
        // deals Damage2=3. Reproducing that branch directly avoids the engine's
        // refusal to open RequestCardTargetsNode from a forced face-down Trap.
        NodeEndpoints incineratingTemplate = editor.AddFilterCardTemplateId(IncineratingTrap);
        FilterListEndpoints incinerating = editor.AddFilterCardList();
        GetCardsEndpoints units = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        TargetRequestEndpoints incineratingTarget = editor.AddRequestCardTargets(
            min: 1, max: 1, aiHintE0: 8_388_608);
        PowerEndpoints incineratingDamage = editor.AddChangePower(
            amount: 3, operation: 1, elementType: 16, attackMethod: 1);

        editor.AddConnection(target.Success, incinerating.FlowIn);
        editor.AddConnection(target.SelectedTargets, incinerating.Cards);
        editor.AddConnection(incineratingTemplate.Out, incinerating.Filter);
        editor.AddConnection(incinerating.Success, incineratingTarget.FlowIn);
        editor.AddConnection(units.Out, incineratingTarget.ValidTargets);
        editor.AddConnection(incineratingTarget.Success, incineratingDamage.FlowIn);
        editor.AddConnection(incineratingTarget.SelectedTargets, incineratingDamage.Targets);
        editor.AddConnection(abilityOwner, incineratingDamage.Attacker);

        // Branch 2: Sticky Situation. Its Spring chooses a unit in hand,
        // boosts it by boost2=6, then locks the selected Trap. The Trap is not
        // moved, replayed or revealed by this implementation.
        NodeEndpoints stickyTemplate = editor.AddFilterCardTemplateId(StickySituation);
        FilterListEndpoints sticky = editor.AddFilterCardList();
        GetCardsEndpoints handUnits = editor.AddGetCards(
            ignoreTokens: 0, locationId: 8, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        CardChoiceEndpoints stickyChoice = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        PowerEndpoints stickyBoost = editor.AddChangePower(
            amount: 6, operation: 0, elementType: 2048, attackMethod: 0);
        TokenEndpoints stickyLock = editor.AddChangeTokens(
            token: 4, elementType: 1, attackMethod: 0, effectType: 0, operation: 0);

        editor.AddConnection(incinerating.Fail, sticky.FlowIn);
        editor.AddConnection(target.SelectedTargets, sticky.Cards);
        editor.AddConnection(stickyTemplate.Out, sticky.Filter);
        editor.AddConnection(sticky.Success, stickyChoice.FlowIn);
        editor.AddConnection(ownerPlayer, handUnits.PlayerId);
        editor.AddConnection(handUnits.Out, stickyChoice.ValidChoices);
        editor.AddConnection(stickyChoice.Success, stickyBoost.FlowIn);
        editor.AddConnection(stickyChoice.SelectedChoices, stickyBoost.Targets);
        editor.AddConnection(abilityOwner, stickyBoost.Attacker);
        editor.AddConnection(stickyBoost.FlowOut, stickyLock.FlowIn);
        editor.AddConnection(stickyChoice.Fail, stickyLock.FlowIn);
        editor.AddConnection(abilityOwner, stickyLock.Attacker);
        editor.AddConnection(target.SelectedTargets, stickyLock.Targets);

        // Branch 3: Crushing Trap. Its Spring chooses a row and damages every
        // unit in it by Damage2=1. This also remains fully face down.
        NodeEndpoints crushingTemplate = editor.AddFilterCardTemplateId(CrushingTrap);
        FilterListEndpoints crushing = editor.AddFilterCardList();
        LocationTargetRequestEndpoints crushingRow = editor.AddRequestLocationTargets(
            min: 1, max: 1, validPlayers: 3, validTargets: 3, aiHintE0: 0);
        LocationElementEndpoints selectedRow = editor.AddLocationListGetElement(index: 0);
        LocationCardsEndpoints rowUnits = editor.AddGetLocationCards(cardType: 4);
        PowerEndpoints crushingDamage = editor.AddChangePower(
            amount: 1, operation: 1, elementType: 1, attackMethod: 2);

        editor.AddConnection(sticky.Fail, crushing.FlowIn);
        editor.AddConnection(target.SelectedTargets, crushing.Cards);
        editor.AddConnection(crushingTemplate.Out, crushing.Filter);
        editor.AddConnection(crushing.Success, crushingRow.FlowIn);
        editor.AddConnection(crushingRow.Locations, selectedRow.List);
        editor.AddConnection(selectedRow.Location, rowUnits.Location);
        editor.AddConnection(crushingRow.Success, crushingDamage.FlowIn);
        editor.AddConnection(rowUnits.Cards, crushingDamage.Targets);
        editor.AddConnection(abilityOwner, crushingDamage.Attacker);

        // All Springs without their own target/choice request continue to use
        // the native EForceTriggerType=2 path, which is verified in game by
        // Deception and other non-interactive Traps.
        ForceCardTriggerEndpoints forceSpring = editor.AddForceCardTrigger(triggerType: 2);
        editor.AddConnection(crushing.Fail, forceSpring.FlowIn);
        editor.AddConnection(selectedTrap.Card, forceSpring.Card);

        editor.Finish();
        return true;
    }

    private static void RebuildDolBlathannaBomberTrapHandPlay(XElement ability)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        GetLastAvailableIndexEndpoints lastHandIndex = editor.AddGetLastAvailableIndex();
        MakeCardPositionEndpoints handPosition = editor.AddMakeCardPosition(location: 8, index: 0);
        SpawnEndpoints trap = editor.AddSpawnCard(IncineratingTrap, count: 1, spawnType: 3);
        GetCardsEndpoints hand = editor.AddGetCards(
            ignoreTokens: 0, locationId: 8, cardTypes: 14, cardTiers: 10, ignoreOwner: false);
        CardChoiceEndpoints choose = editor.AddRequestCardChoice(min: 1, max: 1, aiHintE0: 0, choiceType: 4);
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(owner, handPosition.PlayerId);
        editor.AddConnection(lastHandIndex.Index, handPosition.Index);
        editor.AddConnection(deploy.FlowOut, handPosition.FlowIn);
        editor.AddConnection(handPosition.FlowOut, trap.FlowIn);
        editor.AddConnection(ownerCard, trap.Spawner);
        editor.AddConnection(handPosition.Position, trap.Position);
        editor.AddConnection(owner, hand.PlayerId);
        editor.AddConnection(trap.FlowOut, choose.FlowIn);
        editor.AddConnection(hand.Out, choose.ValidChoices);
        editor.AddConnection(choose.Success, play.FlowIn);
        editor.AddConnection(choose.SelectedChoices, play.Cards);
        editor.Finish();
    }

    private static bool AddToruvielRandomBronzeElfOrder(XElement ability, XElement template)
    {
        if (ability.Element("Nodes")!.Elements().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "TappedTrigger", StringComparison.Ordinal)))
            return false;

        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");
        var editor = new GraphEditor(ability);
        TriggerEndpoints order = editor.AddTappedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0, locationId: 16, cardTypes: 4, cardTiers: 2, ignoreOwner: false);
        NodeEndpoints elf = editor.AddFilterCardCategory(549_755_813_888UL, 0, 0);
        FilterListEndpoints elves = editor.AddFilterCardList();
        RandomCardEndpoints random = editor.AddRandomCard();
        ElementListEndpoints oneCard = editor.AddCardElementToList();
        PlayEndpoints play = editor.AddPlayCards();
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(order.FlowOut, elves.FlowIn);
        editor.AddConnection(deck.Out, elves.Cards);
        editor.AddConnection(elf.Out, elves.Filter);
        editor.AddConnection(elves.Success, random.FlowIn);
        editor.AddConnection(elves.FilteredCards, random.List);
        editor.AddConnection(random.Card, oneCard.Card);
        editor.AddConnection(random.FlowOut, play.FlowIn);
        editor.AddConnection(oneCard.List, play.Cards);
        editor.Finish();
        return true;
    }


    private static void DisableOrderTemplate(XElement template)
    {
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "0");
        SetTemplateText(template, "TapActive", "False");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");
    }

    private static void RestoreCleanGraphForMigrationMarker(
        XElement ability,
        XElement template,
        string abilitiesPath,
        string templatesPath,
        int cardId,
        string obsoleteMarker,
        string currentMarker)
    {
        bool hasCurrent = ability.Descendants().Any(e =>
            string.Equals((string?)e.Attribute("Name"), currentMarker, StringComparison.Ordinal));
        if (hasCurrent)
            return;

        bool hasObsolete = ability.Descendants().Any(e =>
            string.Equals((string?)e.Attribute("Name"), obsoleteMarker, StringComparison.Ordinal));
        if (!hasObsolete)
            return;

        XElement cleanAbility = TryLoadCleanCardAbilityReference(abilitiesPath, cardId)
            ?? throw new InvalidOperationException(
                $"Clean CardAbility {cardId} required for migration from {obsoleteMarker} was not found.");
        XElement cleanTemplate = TryLoadCleanTemplateReference(templatesPath, cardId)
            ?? throw new InvalidOperationException(
                $"Clean Template {cardId} required for migration from {obsoleteMarker} was not found.");
        CopyAbilityGraphAndOrderTemplate(ability, template, cleanAbility, cleanTemplate);
    }

    private static void EnsureTamaraOriginalAbility(
        XElement ability,
        XElement template,
        string abilitiesPath,
        string templatesPath)
    {
        bool hasBoost = ability.Element("TemporaryVariables")?.Elements().Any(variable =>
            string.Equals((string?)variable.Attribute("Name"), "Boost", StringComparison.Ordinal) &&
            (string?)variable.Attribute("V") == "1") == true;
        bool hasTribute = ability.Element("TemporaryVariables")?.Elements().Any(variable =>
            string.Equals((string?)variable.Attribute("Name"), "Tribute", StringComparison.Ordinal) &&
            (string?)variable.Attribute("V") == "3") == true;
        bool hasTributeBranch = ability.Descendants().Any(node =>
            string.Equals((string?)node.Attribute("Type"), "UseSubAbilityNode", StringComparison.Ordinal) &&
            string.Equals(node.Element("SubAbilityID")?.Value, "18", StringComparison.Ordinal));
        bool hasBothBoostBranches = ability.Descendants().Count(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal)) >= 2;
        if (hasBoost && hasTribute && hasTributeBranch && hasBothBoostBranches)
            return;

        XElement cleanAbility = TryLoadCleanCardAbilityReference(abilitiesPath, TamaraStrenger)
            ?? throw new InvalidOperationException(
                "Clean Tamara CardAbility required to restore Deploy/Tribute was not found.");
        XElement cleanTemplate = TryLoadCleanTemplateReference(templatesPath, TamaraStrenger)
            ?? throw new InvalidOperationException(
                "Clean Tamara Template required to restore Deploy/Tribute was not found.");
        CopyAbilityGraphAndOrderTemplate(ability, template, cleanAbility, cleanTemplate);
    }

    private static XElement? TryLoadCleanCardAbilityReference(
        string abilitiesPath,
        int cardId)
    {
        string? cleanPath = TryResolveCleanReferencePath(abilitiesPath, "Abilities.xml");
        if (cleanPath is null)
            return null;

        XDocument clean = XDocument.Load(cleanPath, LoadOptions.PreserveWhitespace);
        return clean.Root?
            .Elements("Ability")
            .FirstOrDefault(ability =>
                string.Equals((string?)ability.Attribute("Type"), "CardAbility", StringComparison.Ordinal)
                && (int?)ability.Attribute("Id") == cardId);
    }

    private static XElement? TryLoadCleanSubAbilityReference(
        string abilitiesPath,
        int abilityId)
    {
        string? cleanPath = TryResolveCleanReferencePath(abilitiesPath, "Abilities.xml");
        if (cleanPath is null)
            return null;

        XDocument clean = XDocument.Load(cleanPath, LoadOptions.PreserveWhitespace);
        return clean.Root?
            .Elements("Ability")
            .FirstOrDefault(ability =>
                string.Equals((string?)ability.Attribute("Type"), "SubAbility", StringComparison.Ordinal) &&
                (int?)ability.Attribute("AbilityID") == abilityId);
    }

    private static XElement? TryLoadCleanTemplateReference(
        string templatesPath,
        int cardId)
    {
        string? cleanPath = TryResolveCleanReferencePath(templatesPath, "Templates.xml");
        if (cleanPath is null)
            return null;

        XDocument clean = XDocument.Load(cleanPath, LoadOptions.PreserveWhitespace);
        return clean.Root?
            .Elements("Template")
            .FirstOrDefault(template => (int?)template.Attribute("Id") == cardId);
    }

    private static string? TryResolveCleanReferencePath(
        string inputPath,
        string fileName)
    {
        string directory = Path.GetDirectoryName(Path.GetFullPath(inputPath))
            ?? Directory.GetCurrentDirectory();
        string? parent = Directory.GetParent(directory)?.FullName;

        foreach (string candidate in new[]
                 {
                     Path.Combine(directory, "Clean", fileName),
                     parent is null ? string.Empty : Path.Combine(parent, "Clean", fileName)
                 })
        {
            if (!string.IsNullOrWhiteSpace(candidate) && File.Exists(candidate))
                return candidate;
        }

        return null;
    }

    private static int GetMaximumLocalAbilityId(XElement ability)
    {
        return ability.Elements()
            .Where(element => element.Name.LocalName is
                "TemporaryVariables" or "PersistentVariables" or "Nodes" or "Connections")
            .SelectMany(element => element.DescendantsAndSelf())
            .Select(element =>
            {
                return int.TryParse((string?)element.Attribute("Id"), out int id)
                    ? id
                    : (int?)null;
            })
            .Where(id => id.HasValue)
            .Select(id => id!.Value)
            .DefaultIfEmpty(0)
            .Max();
    }

    private static void NormalizeAbilityNId(XElement ability)
    {
        ability.SetAttributeValue("NId", GetMaximumLocalAbilityId(ability) + 1);
    }

    private static void RequireValidAbilityNId(XElement ability, string context)
    {
        int maximum = GetMaximumLocalAbilityId(ability);
        int nId = (int?)ability.Attribute("NId") ?? 0;
        if (nId <= maximum)
        {
            throw new InvalidDataException(
                $"{context}: CardAbility {ability.Attribute("Id")?.Value} NId={nId} " +
                $"должен быть больше максимального локального Id={maximum}.");
        }
    }


    private static void CopyAbilityGraphAndOrderTemplate(
        XElement targetAbility,
        XElement targetTemplate,
        XElement sourceAbility,
        XElement sourceTemplate)
    {
        foreach (string containerName in new[]
                 {
                     "TemporaryVariables", "PersistentVariables", "Nodes", "Connections"
                 })
        {
            XElement sourceContainer = sourceAbility.Element(containerName)
                ?? throw new InvalidOperationException(
                    $"Source CardAbility {sourceAbility.Attribute("Id")?.Value} has no {containerName}.");
            XElement targetContainer = targetAbility.Element(containerName)
                ?? throw new InvalidOperationException(
                    $"Target CardAbility {targetAbility.Attribute("Id")?.Value} has no {containerName}.");
            targetContainer.ReplaceWith(new XElement(sourceContainer));
        }

        NormalizeAbilityNId(targetAbility);

        foreach (string field in new[]
                 {
                     "InitialTimer", "ResetInInactive", "InitalTapCharges", "TapActive",
                     "SummoningSickness", "VisibleTapCharges"
                 })
        {
            SetTemplateText(targetTemplate, field, sourceTemplate.Element(field)?.Value
                ?? throw new InvalidOperationException(
                    $"Source Template {sourceTemplate.Attribute("Id")?.Value} has no {field}."));
        }
    }


    private static void RebuildVesRandomBronzeHumanDeploy(
        XElement ability,
        XElement template)
    {
        XElement nodes = ability.Element("Nodes")
            ?? throw new InvalidOperationException("Ves CardAbility не содержит Nodes.");
        XElement connections = ability.Element("Connections")
            ?? throw new InvalidOperationException("Ves CardAbility не содержит Connections.");

        XElement deployTrigger = nodes.Elements()
            .SingleOrDefault(node => (string?)node.Attribute("Type") == "PlayedTrigger")
            ?? throw new InvalidOperationException("Ves Deploy PlayedTrigger не найден или неоднозначен.");
        int deployFlow = Id(deployTrigger.Element("FlowOut")
            ?? throw new InvalidOperationException("Ves PlayedTrigger не содержит FlowOut."));

        // Replace only the Deploy continuation. The original Order graph and
        // its template configuration must remain untouched.
        foreach (XElement connection in connections.Elements()
                     .Where(connection => (int?)connection.Attribute("SrcId") == deployFlow)
                     .ToList())
        {
            connection.Remove();
        }

        var editor = new GraphEditor(ability);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 2,
            ignoreOwner: false);
        NodeEndpoints human = editor.AddFilterCardCategory(0, 16_384UL, 0);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        RandomCardEndpoints random = editor.AddRandomCard();
        ElementListEndpoints singleton = editor.AddCardElementToList();
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(deployFlow, eligible.FlowIn);
        editor.AddConnection(deck.Out, eligible.Cards);
        editor.AddConnection(human.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, random.FlowIn);
        editor.AddConnection(eligible.FilteredCards, random.List);
        editor.AddConnection(random.Card, singleton.Card);
        editor.AddConnection(random.FlowOut, play.FlowIn);
        editor.AddConnection(singleton.List, play.Cards);
        editor.Finish();
    }

    private static void RebuildDamnedSorceressAdjacentSpecterDamage(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Damage", 1);
        editor.EnsureIntVariable("MaxTargets", 1);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        CardPositionEndpoints ownerPosition = editor.AddGetCardPosition(positionType: 0);
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        NodeEndpoints specter = editor.AddFilterCardCategory(16_777_216UL, 0, 0);
        FilterListEndpoints adjacentSpecters = editor.AddFilterCardList();
        CardListLengthEndpoints adjacentCount = editor.AddCardListLength();
        IntPlusEndpoints scaledValue = editor.AddIntPlus();
        SetEndpointValue(ability, scaledValue.B, "1");

        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 3,
            aiHintE0: 8_388_608L);
        XElement requestNode = editor.FindNodeOwningEndpoint(request.FlowIn)
            ?? throw new InvalidOperationException("Damned Sorceress target request node not found.");
        int requestMaxTargets = Id(requestNode.Element("MaxTargets")!);
        int attacker = editor.AddGetAbilityOwner();
        PowerEndpoints damage = editor.AddChangePower(amount: 1, operation: 1);

        editor.AddConnection(ownerCard, ownerPosition.Card);
        editor.AddConnection(ownerPosition.Position, adjacent.Position);
        editor.AddConnection(deploy.FlowOut, adjacentSpecters.FlowIn);
        editor.AddConnection(adjacent.Cards, adjacentSpecters.Cards);
        editor.AddConnection(specter.Out, adjacentSpecters.Filter);
        editor.AddConnection(adjacentSpecters.FilteredCards, adjacentCount.List);
        editor.AddConnection(adjacentCount.Length, scaledValue.A);

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(adjacentSpecters.Success, request.FlowIn);
        editor.AddConnection(adjacentSpecters.Fail, request.FlowIn);
        editor.AddConnection(enemies.Out, request.ValidTargets);
        editor.AddConnection(scaledValue.Result, requestMaxTargets);
        editor.AddConnection(request.Success, damage.FlowIn);
        editor.AddConnection(request.SelectedTargets, damage.Targets);
        editor.AddConnection(attacker, damage.Attacker);
        editor.AddConnection(scaledValue.Result, damage.Power);
        editor.Finish();
    }


    private static void RebuildBanArdTutorNextPatienceCharge(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Boost", 1);
        editor.EnsureIntVariable("Patience", 1);
        editor.EnsureIntVariable("Charges", 1);
        int patienceArmedVar = editor.EnsurePersistentIntVariable("BanArdPatienceArmed", 0);
        int chargeArmedVar = editor.EnsurePersistentIntVariable("BanArdChargeArmed", 0);
        foreach (XElement variable in ability.Element("PersistentVariables")!.Elements().Where(variable =>
                     (int?)variable.Attribute("Id") == patienceArmedVar ||
                     (int?)variable.Attribute("Id") == chargeArmedVar))
        {
            variable.SetAttributeValue("HideInTooltip", "True");
        }

        // Deploy only arms one of the two modes according to the row.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        SetVarEndpoints armPatience = editor.AddSetIntVariable(patienceArmedVar);
        SetVarEndpoints disarmChargeOnMelee = editor.AddSetIntVariable(chargeArmedVar);
        SetVarEndpoints armCharge = editor.AddSetIntVariable(chargeArmedVar);
        SetVarEndpoints disarmPatienceOnRanged = editor.AddSetIntVariable(patienceArmedVar);
        SetEndpointValue(ability, armPatience.In, "1");
        SetEndpointValue(ability, disarmChargeOnMelee.In, "0");
        SetEndpointValue(ability, armCharge.In, "1");
        SetEndpointValue(ability, disarmPatienceOnRanged.In, "0");
        editor.AddConnection(deploy.FlowOut, row.FlowIn);
        editor.AddConnection(row.Melee, armPatience.FlowIn);
        editor.AddConnection(armPatience.FlowOut, disarmChargeOnMelee.FlowIn);
        editor.AddConnection(row.Ranged, armCharge.FlowIn);
        editor.AddConnection(armCharge.FlowOut, disarmPatienceOnRanged.FlowIn);

        // PlayedTrigger is too early for filters that inspect the newly played
        // card's active SubAbilities / tap-charge configuration. Follow the
        // native "next played unit" pattern (BattleAbility 37): wait until the
        // card has moved to the owner's board with EMoveReason=Played.
        AfterMovedEndpoints playedToBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        editor.AddConnection(ownerPlayer, playedToBoard.ToPlayer);

        int patienceArmed = editor.AddGetIntVariable(patienceArmedVar);
        IntBranchEndpoints patienceMode = editor.AddIntBranch();
        SetEndpointValue(ability, patienceMode.B, "0");
        editor.AddConnection(playedToBoard.FlowOut, patienceMode.FlowIn);
        editor.AddConnection(patienceArmed, patienceMode.A);

        NodeEndpoints unit = editor.AddFilterCardType(4);
        NodeEndpoints hasPatience = editor.AddFilterHasSubAbility(40);
        LogicEndpoints patienceEligibleFilter = editor.AddFilterLogic(orOperation: false);
        editor.AddConnection(unit.Out, patienceEligibleFilter.Input0);
        editor.AddConnection(hasPatience.Out, patienceEligibleFilter.Input1);
        FilterListEndpoints patienceEligible = editor.AddFilterCardList();
        editor.AddConnection(patienceMode.Bigger, patienceEligible.FlowIn);
        editor.AddConnection(playedToBoard.CardsMoved, patienceEligible.Cards);
        editor.AddConnection(patienceEligibleFilter.Out, patienceEligible.Filter);

        int tutorEntity = editor.AddGetAbilityOwner();
        PowerEndpoints patienceBoost = editor.AddChangePower(amount: 1, operation: 0);
        CardElementEndpoints patienceCard = editor.AddCardListGetElement(index: 0);
        ForceCardTriggerEndpoints addPatience = editor.AddForceCardTrigger(triggerType: 5);
        SetVarEndpoints clearPatience = editor.AddSetIntVariable(patienceArmedVar);
        SetEndpointValue(ability, clearPatience.In, "0");
        editor.AddConnection(patienceEligible.Success, patienceBoost.FlowIn);
        editor.AddConnection(patienceEligible.FilteredCards, patienceBoost.Targets);
        editor.AddConnection(tutorEntity, patienceBoost.Attacker);
        editor.AddConnection(patienceEligible.FilteredCards, patienceCard.List);
        editor.AddConnection(patienceCard.Card, addPatience.Card);
        editor.AddConnection(patienceBoost.FlowOut, addPatience.FlowIn);
        editor.AddConnection(addPatience.FlowOut, clearPatience.FlowIn);

        int chargeArmed = editor.AddGetIntVariable(chargeArmedVar);
        IntBranchEndpoints chargeMode = editor.AddIntBranch();
        SetEndpointValue(ability, chargeMode.B, "0");
        editor.AddConnection(patienceMode.Equal, chargeMode.FlowIn);
        editor.AddConnection(chargeArmed, chargeMode.A);

        NodeEndpoints mage = editor.AddFilterCardCategory(16_384UL, 0, 0);
        NodeEndpoints visibleCharges = editor.AddFilterTapCardVisibleCharges(true);
        LogicEndpoints chargeEligibleFilter = editor.AddFilterLogic(orOperation: false);
        editor.AddConnection(mage.Out, chargeEligibleFilter.Input0);
        editor.AddConnection(visibleCharges.Out, chargeEligibleFilter.Input1);
        FilterListEndpoints chargeEligible = editor.AddFilterCardList();
        editor.AddConnection(chargeMode.Bigger, chargeEligible.FlowIn);
        editor.AddConnection(playedToBoard.CardsMoved, chargeEligible.Cards);
        editor.AddConnection(chargeEligibleFilter.Out, chargeEligible.Filter);

        PowerEndpoints chargeBoost = editor.AddChangePower(amount: 1, operation: 0);
        // `CardsMoved` is safe for power changes, but newly played cards can still
        // have their tap-charge state re-initialized after the move event.  Re-read
        // the same physical card from the owner's board by CardId before changing
        // tap charges; this mirrors native "modify charges on cards already in a
        // location" graphs such as Engineer.
        CardElementEndpoints movedChargeCard = editor.AddCardListGetElement(index: 0);
        CardIdEndpoints movedChargeCardId = editor.AddGetCardId();
        GetCardsEndpoints ownerBoardCards = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints samePhysicalCard = editor.AddFilterCardId();
        FilterListEndpoints refreshedChargeTarget = editor.AddFilterCardList();
        ChangeTapChargesEndpoints addCharge = editor.AddChangeTapCardCharges(operation: 1, value: 1);
        SetVarEndpoints clearCharge = editor.AddSetIntVariable(chargeArmedVar);
        SetEndpointValue(ability, clearCharge.In, "0");

        editor.AddConnection(chargeEligible.Success, chargeBoost.FlowIn);
        editor.AddConnection(chargeEligible.FilteredCards, chargeBoost.Targets);
        editor.AddConnection(tutorEntity, chargeBoost.Attacker);

        editor.AddConnection(chargeEligible.FilteredCards, movedChargeCard.List);
        editor.AddConnection(movedChargeCard.Card, movedChargeCardId.Card);
        editor.AddConnection(ownerPlayer, ownerBoardCards.PlayerId);
        editor.AddConnection(movedChargeCardId.CardId, samePhysicalCard.PowerInput);
        editor.AddConnection(chargeBoost.FlowOut, refreshedChargeTarget.FlowIn);
        editor.AddConnection(ownerBoardCards.Out, refreshedChargeTarget.Cards);
        editor.AddConnection(samePhysicalCard.Out, refreshedChargeTarget.Filter);

        editor.AddConnection(refreshedChargeTarget.Success, addCharge.FlowIn);
        editor.AddConnection(refreshedChargeTarget.FilteredCards, addCharge.Targets);
        editor.AddConnection(tutorEntity, addCharge.Attacker);
        editor.AddConnection(addCharge.FlowOut, clearCharge.FlowIn);
        editor.AddConnection(refreshedChargeTarget.Fail, clearCharge.FlowIn);
        editor.Finish();
    }

    private static void RebuildDethmoldDeathblowSpellCharges(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "True");

        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Damage", 1);
        editor.EnsureIntVariable("Charges", 1);
        editor.EnsureIntVariable("ChargeGain", 1);

        TriggerEndpoints order = editor.AddTappedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(
            min: 1, max: 1, aiHintE0: 8_388_608L);
        int ownerEntity = editor.AddGetAbilityOwner();
        PowerEndpoints damage = editor.AddChangePower(amount: 1, operation: 1);
        DeathblowEndpoints deathblow = editor.AddDeathblowSubAbility();

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.Success, damage.FlowIn);
        editor.AddConnection(target.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(damage.FlowOut, deathblow.FlowIn);
        editor.AddConnection(target.SelectedTargets, deathblow.Targets);

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 32,
            cardTypes: 2,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints spell = editor.AddFilterCardCategory(1_048_576UL, 0, 0);
        FilterListEndpoints eligibleSpell = editor.AddFilterCardList();
        RandomCardEndpoints randomSpell = editor.AddRandomCard();
        ElementListEndpoints oneSpell = editor.AddCardElementToList();
        PlayEndpoints playSpell = editor.AddPlayCards();
        editor.AddConnection(ownerPlayer, graveyard.PlayerId);
        editor.AddConnection(deathblow.Deathblow, eligibleSpell.FlowIn);
        editor.AddConnection(graveyard.Out, eligibleSpell.Cards);
        editor.AddConnection(spell.Out, eligibleSpell.Filter);
        editor.AddConnection(eligibleSpell.Success, randomSpell.FlowIn);
        editor.AddConnection(eligibleSpell.FilteredCards, randomSpell.List);
        editor.AddConnection(randomSpell.Card, oneSpell.Card);
        editor.AddConnection(randomSpell.FlowOut, playSpell.FlowIn);
        editor.AddConnection(oneSpell.List, playSpell.Cards);

        // Use the same post-move "card was played onto my board" pattern as
        // native charge engines such as Fat Helga. PlayedTrigger on the ability
        // owner fired for Dethmold himself and was unreliable for later Mages.
        AfterMovedEndpoints playedGoldMage = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 252,
            toLocation: 379,
            reason: 1);
        editor.AddConnection(ownerPlayer, playedGoldMage.ToPlayer);

        NodeEndpoints mage = editor.AddFilterCardCategory(16_384UL, 0, 0);
        NodeEndpoints gold = editor.AddFilterCardTier(8);
        NodeEndpoints notDethmold = editor.AddFilterCardTemplateId(Dethmold, negate: true);
        LogicEndpoints goldMage = editor.AddFilterLogic(orOperation: false);
        LogicEndpoints otherGoldMage = editor.AddFilterLogic(orOperation: false);
        editor.AddConnection(mage.Out, goldMage.Input0);
        editor.AddConnection(gold.Out, goldMage.Input1);
        editor.AddConnection(goldMage.Out, otherGoldMage.Input0);
        editor.AddConnection(notDethmold.Out, otherGoldMage.Input1);

        FilterListEndpoints eligibleGoldMage = editor.AddFilterCardList();
        editor.AddConnection(playedGoldMage.FlowOut, eligibleGoldMage.FlowIn);
        editor.AddConnection(playedGoldMage.CardsMoved, eligibleGoldMage.Cards);
        editor.AddConnection(otherGoldMage.Out, eligibleGoldMage.Filter);

        int ownerCardList = editor.AddGetAbilityOwnerCardList();
        ChangeTapChargesEndpoints gainCharge =
            editor.AddChangeTapCardCharges(operation: 1, value: 1);
        editor.AddConnection(eligibleGoldMage.Success, gainCharge.FlowIn);
        editor.AddConnection(ownerCardList, gainCharge.Targets);
        editor.AddConnection(ownerEntity, gainCharge.Attacker);
        editor.Finish();
    }

    private static void RebuildPhilippaBlindFuryAdjacentMageSpells(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        CardPositionEndpoints position = editor.AddGetCardPosition(positionType: 0);
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        NodeEndpoints mage = editor.AddFilterCardCategory(16_384UL, 0, 0);
        FilterListEndpoints adjacentMages = editor.AddFilterCardList();
        int ownerPlayer = editor.AddGetOwnerPlayerId();

        editor.AddConnection(ownerCard, position.Card);
        editor.AddConnection(position.Position, adjacent.Position);
        editor.AddConnection(deploy.FlowOut, adjacentMages.FlowIn);
        editor.AddConnection(adjacent.Cards, adjacentMages.Cards);
        editor.AddConnection(mage.Out, adjacentMages.Filter);

        // The base spell is always bronze.
        int baseSpellOut = AddRandomSpellPlay(
            editor,
            new[] { adjacentMages.Success, adjacentMages.Fail },
            ownerPlayer,
            tier: 2);

        // Each adjacent Mage adds one more spell matching that Mage's colour/tier.
        ForeachEndpoints eachMage = editor.AddCardListForeach();
        ElementListEndpoints mageSingleton = editor.AddCardElementToList();
        NodeEndpoints gold = editor.AddFilterCardTier(8);
        FilterListEndpoints isGoldMage = editor.AddFilterCardList();
        editor.AddConnection(baseSpellOut, eachMage.FlowIn);
        editor.AddConnection(adjacentMages.FilteredCards, eachMage.List);
        editor.AddConnection(eachMage.Element, mageSingleton.Card);
        editor.AddConnection(eachMage.FlowFor, isGoldMage.FlowIn);
        editor.AddConnection(mageSingleton.List, isGoldMage.Cards);
        editor.AddConnection(gold.Out, isGoldMage.Filter);
        _ = AddRandomSpellPlay(editor, isGoldMage.Success, ownerPlayer, tier: 8);
        _ = AddRandomSpellPlay(editor, isGoldMage.Fail, ownerPlayer, tier: 2);
        editor.Finish();
    }


    private static void RebuildKeiraMetzGraveyardPatienceCreate(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int patienceVar = editor.EnsurePersistentIntVariable("MaxTargets", 0);
        XElement patienceVariable = ability.Element("PersistentVariables")!.Elements()
            .Single(variable => (int?)variable.Attribute("Id") == patienceVar);
        patienceVariable.Attribute("HideInTooltip")?.Remove();
        editor.EnsureIntVariable("CopyTargets", 2);
        int uniqueSpellsVar = editor.AddEmptyCardDefinitionListVariable(
            "KeiraUniqueSpells",
            hideInTooltip: true);

        // Deploy: collect unique Spell definitions represented in the graveyard.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 32,
            cardTypes: 10,
            cardTiers: 10,
            ignoreOwner: true);
        NodeEndpoints spellCategory = editor.AddFilterCardCategory(1_048_576UL, 0, 0);
        FilterListEndpoints graveyardSpells = editor.AddFilterCardList();
        editor.AddConnection(ownerPlayer, graveyard.PlayerId);
        editor.AddConnection(deploy.FlowOut, graveyardSpells.FlowIn);
        editor.AddConnection(graveyard.Out, graveyardSpells.Cards);
        editor.AddConnection(spellCategory.Out, graveyardSpells.Filter);

        ForeachEndpoints uniqueLoop = editor.AddCardListForeach();
        CardDefinitionEndpoints uniqueDefinition = editor.AddGetCardDefinition();
        int uniqueDefinitionsForContains =
            editor.AddGetCardDefinitionListVariable(uniqueSpellsVar);
        DefinitionContainsEndpoints containsDefinition =
            editor.AddCardDefinitionListContainsElement(ignorePremium: true);
        BranchEndpoints isAlreadyUnique = editor.AddBranch();
        int uniqueDefinitionsForAdd =
            editor.AddGetCardDefinitionListVariable(uniqueSpellsVar);
        DefinitionAddEndpoints addUniqueDefinition = editor.AddCardDefinitionListAdd();
        int uniqueDefinitionsForLength =
            editor.AddGetCardDefinitionListVariable(uniqueSpellsVar);
        CardDefinitionListLengthEndpoints uniqueCount = editor.AddCardDefinitionListLength();
        SetVarEndpoints setPatience = editor.AddSetIntVariable(patienceVar);

        editor.AddConnection(graveyardSpells.Success, uniqueLoop.FlowIn);
        editor.AddConnection(graveyardSpells.FilteredCards, uniqueLoop.List);
        editor.AddConnection(uniqueLoop.Element, uniqueDefinition.Card);
        editor.AddConnection(uniqueDefinitionsForContains, containsDefinition.List);
        editor.AddConnection(uniqueDefinition.Definition, containsDefinition.Element);
        editor.AddConnection(uniqueLoop.FlowFor, isAlreadyUnique.FlowIn);
        editor.AddConnection(containsDefinition.Result, isAlreadyUnique.Condition);
        editor.AddConnection(isAlreadyUnique.False, addUniqueDefinition.FlowIn);
        editor.AddConnection(uniqueDefinitionsForAdd, addUniqueDefinition.List);
        editor.AddConnection(uniqueDefinition.Definition, addUniqueDefinition.Element);
        editor.AddConnection(uniqueLoop.FlowOut, setPatience.FlowIn);
        editor.AddConnection(uniqueDefinitionsForLength, uniqueCount.List);
        editor.AddConnection(uniqueCount.Length, setPatience.In);

        SetVarEndpoints clearPatience = editor.AddSetIntVariable(patienceVar);
        SetEndpointValue(ability, clearPatience.In, "0");
        editor.AddConnection(graveyardSpells.Fail, clearPatience.FlowIn);

        // After setting the initial Patience value, choose up to two physical Spells
        // in the graveyard and create copies of them in the deck.
        CardListLengthEndpoints graveyardSpellCount = editor.AddCardListLength();
        IntMinEndpoints copyCount = editor.AddIntMin(constantB: 2);
        CardChoiceEndpoints copyChoice = editor.AddRequestCardChoice(
            min: 1,
            max: 2,
            aiHintE0: 0,
            choiceType: 0);
        editor.AddConnection(graveyardSpells.FilteredCards, graveyardSpellCount.List);
        editor.AddConnection(graveyardSpellCount.Length, copyCount.A);
        editor.AddConnection(copyCount.Result, copyChoice.MinChoices);
        editor.AddConnection(copyCount.Result, copyChoice.MaxChoices);
        editor.AddConnection(setPatience.FlowOut, copyChoice.FlowIn);
        editor.AddConnection(graveyardSpells.FilteredCards, copyChoice.ValidChoices);

        ForeachEndpoints copyLoop = editor.AddCardListForeach();
        CardDefinitionEndpoints copyDefinition = editor.AddGetCardDefinition();
        MakeCardPositionEndpoints deckPosition = editor.AddMakeCardPosition(location: 16, index: 0);
        DynamicSpawnEndpoints spawnCopy = editor.AddDynamicSpawnCard(count: 1, spawnType: 3);
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        ShuffleDeckEndpoints shuffleDeck = editor.AddShuffleDeck();

        editor.AddConnection(copyChoice.Success, copyLoop.FlowIn);
        editor.AddConnection(copyChoice.SelectedChoices, copyLoop.List);
        editor.AddConnection(copyLoop.Element, copyDefinition.Card);
        editor.AddConnection(copyLoop.FlowFor, deckPosition.FlowIn);
        editor.AddConnection(ownerPlayer, deckPosition.PlayerId);
        editor.AddConnection(deckPosition.FlowOut, spawnCopy.FlowIn);
        editor.AddConnection(ownerCard, spawnCopy.Spawner);
        editor.AddConnection(deckPosition.Position, spawnCopy.Position);
        editor.AddConnection(copyDefinition.Definition, spawnCopy.Definition);
        editor.AddConnection(copyLoop.FlowOut, shuffleDeck.FlowIn);
        editor.AddConnection(ownerPlayer, shuffleDeck.PlayerId);

        // Patience continues to grow through the native Patience subability.
        TurnTriggerEndpoints afterTurn = editor.AddAfterTurnTrigger(ownerLocation: 3);
        PatienceEndpoints patience = editor.AddPatienceSubAbility();
        int currentPatience = editor.AddGetIntVariable(patienceVar);
        int patienceDelta = editor.AddGetBlackboardInt(27);
        IntPlusEndpoints increase = editor.AddIntPlus();
        SetVarEndpoints storeIncrease = editor.AddSetIntVariable(patienceVar);
        editor.AddConnection(ownerPlayer, afterTurn.PlayerFilter);
        editor.AddConnection(afterTurn.FlowOut, patience.FlowIn);
        editor.AddConnection(patience.Success, storeIncrease.FlowIn);
        editor.AddConnection(currentPatience, increase.A);
        editor.AddConnection(patienceDelta, increase.B);
        editor.AddConnection(increase.Result, storeIncrease.In);

        // Order: create and immediately play a Spell that was not in the initial deck
        // and whose provision cost is no greater than current Patience.
        TriggerEndpoints order = editor.AddTappedTrigger();
        CardDefinitionsEndpoints allSpells = editor.AddGetCardsDefinitions(
            faction: 127,
            tier: 10,
            cardType: 10,
            categoryE0: 1_048_576UL,
            categoryE1: 0,
            categoryE2: 0);
        DefinitionProvisionEndpoints affordable = editor.AddFilterCardDefinitionProvision(
            compareOp: 4,
            provision: 0);
        DefinitionListFilterEndpoints affordableSpells = editor.AddFilterCardDefinitionListNode();
        int orderChoicesVar = editor.AddEmptyCardDefinitionListVariable(
            "KeiraOrderChoices",
            hideInTooltip: true);
        SetVarEndpoints storeOrderChoices =
            editor.AddSetCardDefinitionListVariable(orderChoicesVar);
        int orderChoicesForRemoval = editor.AddGetCardDefinitionListVariable(orderChoicesVar);
        InitialDeckEndpoints initialDeck = editor.AddGetInitialDeckDefinitions(unique: true);
        DefinitionRemoveListEndpoints removeInitialDeck = editor.AddCardDefinitionListRemoveList();
        int orderChoicesForBranch = editor.AddGetCardDefinitionListVariable(orderChoicesVar);
        DefinitionListBranchEndpoints hasOrderChoices = editor.AddCardDefinitionListBranch();
        int orderChoicesForCreate = editor.AddGetCardDefinitionListVariable(orderChoicesVar);
        CreatePlayEndpoints createAndPlay = editor.AddCreateAndPlaySubAbility();

        editor.AddConnection(currentPatience, affordable.Provision);
        editor.AddConnection(order.FlowOut, affordableSpells.FlowIn);
        editor.AddConnection(allSpells.Out, affordableSpells.Definitions);
        editor.AddConnection(affordable.Out, affordableSpells.Filter);
        editor.AddConnection(ownerPlayer, initialDeck.PlayerId);
        editor.AddConnection(affordableSpells.Success, storeOrderChoices.FlowIn);
        editor.AddConnection(affordableSpells.FilteredDefinitions, storeOrderChoices.In);
        editor.AddConnection(storeOrderChoices.FlowOut, removeInitialDeck.FlowIn);
        editor.AddConnection(orderChoicesForRemoval, removeInitialDeck.List);
        editor.AddConnection(initialDeck.Out, removeInitialDeck.ListToRemove);
        editor.AddConnection(removeInitialDeck.FlowOut, hasOrderChoices.FlowIn);
        editor.AddConnection(orderChoicesForBranch, hasOrderChoices.List);
        // SubAbility 44 already contains the single RequestTemplateChoice used by
        // GWENT's create-and-play flow. Feeding a prior RequestTemplateChoice into
        // it made the user select the same Spell twice.
        editor.AddConnection(hasOrderChoices.True, createAndPlay.FlowIn);
        editor.AddConnection(orderChoicesForCreate, createAndPlay.Definitions);

        editor.Finish();
    }

    private static void RebuildCintrianEnchantressSpellweaverCharges(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Restoration", 2);
        editor.EnsureIntVariable("Restoration2", 4);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints friendly = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 2_147_483_648L);
        KeywordBranchEndpoints bonded = editor.AddBondedBranchSubAbility();
        int ownerEntity = editor.AddGetAbilityOwner();

        editor.AddConnection(deploy.FlowOut, row.FlowIn);
        editor.AddConnection(ownerPlayer, friendly.PlayerId);
        editor.AddConnection(row.Ranged, request.FlowIn);
        editor.AddConnection(friendly.Out, request.ValidTargets);
        editor.AddConnection(request.Success, bonded.FlowIn);

        AddCintrianEnchantressTargetEffect(
            editor, bonded.Regular, request.SelectedTargets, ownerEntity, amount: 2);
        AddCintrianEnchantressTargetEffect(
            editor, bonded.Active, request.SelectedTargets, ownerEntity, amount: 4);

        editor.Finish();
    }

    private static void AddCintrianEnchantressTargetEffect(
        GraphEditor editor,
        int entryFlow,
        int selectedTargets,
        int ownerEntity,
        int amount)
    {
        NodeEndpoints spellweaver = editor.AddFilterCardTemplateId(CintrianSpellweaver);
        FilterListEndpoints isSpellweaver = editor.AddFilterCardList();
        ChangeTapChargesEndpoints charges = editor.AddChangeTapCardCharges(operation: 1, value: amount);
        StatusTimerEndpoints vitality = editor.AddVitality(amount);

        editor.AddConnection(entryFlow, isSpellweaver.FlowIn);
        editor.AddConnection(selectedTargets, isSpellweaver.Cards);
        editor.AddConnection(spellweaver.Out, isSpellweaver.Filter);

        editor.AddConnection(isSpellweaver.Success, charges.FlowIn);
        editor.AddConnection(selectedTargets, charges.Targets);
        editor.AddConnection(ownerEntity, charges.Attacker);

        editor.AddConnection(isSpellweaver.Fail, vitality.FlowIn);
        editor.AddConnection(selectedTargets, vitality.Cards);
        editor.AddConnection(ownerEntity, vitality.Attacker);
    }

