    private static void AddOdrinGoldenFrothDeploy(XElement ability)
    {
        // Odrin's original CardAbility has no graph. Rebuild this addition
        // unconditionally so older cumulative outputs using SubAbility 44 are
        // migrated instead of being skipped by the presence of PlayedTrigger.
        ClearAbilityGraph(ability, clearVariables: false);

        var editor = new GraphEditor(ability);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        MakeCardPositionEndpoints staging =
            editor.AddMakeCardPosition(location: 256, index: 0);
        SpawnEndpoints froth = editor.AddSpawnCard(
            templateId: GoldenFroth,
            count: 1,
            spawnType: 3);
        PlayEndpoints play = editor.AddPlayCards();

        // This is the native fixed "create and play" pattern used by cards such
        // as Nauzicaa Sergeant: spawn directly into the play staging location,
        // then pass the spawned physical card to PlayCardsNode. No hand spawn
        // and no intermediate template-choice request are involved.
        editor.AddConnection(deploy.FlowOut, staging.FlowIn);
        editor.AddConnection(ownerPlayer, staging.PlayerId);
        editor.AddConnection(staging.FlowOut, froth.FlowIn);
        editor.AddConnection(ownerCard, froth.Spawner);
        editor.AddConnection(staging.Position, froth.Position);
        editor.AddConnection(froth.FlowOut, play.FlowIn);
        editor.AddConnection(froth.SpawnedCards, play.Cards);
        editor.Finish();
    }

