    private static void RebuildMadKiyanRowTribalDamage(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int boostsVar = editor.EnsureIntVariable("KiyanBoosts", 0);
        XElement boostsVariable = ability.Element("TemporaryVariables")!.Elements()
            .Single(variable => (int?)variable.Attribute("Id") == boostsVar);
        boostsVariable.SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int ownerLocation = editor.AddGetAbilityOwnerLocation();
        LocationCardsEndpoints rowUnits = editor.AddGetLocationCards(cardType: 4);

        NodeEndpoints cursed = editor.AddFilterCardCategory(33_554_432UL, 0, 0);
        FilterListEndpoints cursedUnits = editor.AddFilterCardList();
        CardListLengthEndpoints cursedCount = editor.AddCardListLength();
        IntBranchEndpoints cursedPositive = editor.AddIntBranch();
        SetEndpointValue(ability, cursedPositive.B, "0");
        SetVarEndpoints storeCursed = editor.AddSetIntVariable(boostsVar);

        NodeEndpoints witcher = editor.AddFilterCardCategory(2_147_483_648UL, 0, 0);
        FilterListEndpoints witcherUnits = editor.AddFilterCardList();
        CardListLengthEndpoints witcherCount = editor.AddCardListLength();
        IntBranchEndpoints witcherPositive = editor.AddIntBranch();
        SetEndpointValue(ability, witcherPositive.B, "0");
        SetVarEndpoints storeWitcher = editor.AddSetIntVariable(boostsVar);

        int currentBoosts = editor.AddGetIntVariable(boostsVar);
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCardList = editor.AddGetAbilityOwnerCardList();
        PowerEndpoints selfBoost = editor.AddChangePower(amount: 0, operation: 0);

        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints request = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 8_388_608L);
        PowerEndpoints damage = editor.AddChangePower(amount: 0, operation: 1);

        editor.AddConnection(deploy.FlowOut, row.FlowIn);
        editor.AddConnection(ownerLocation, rowUnits.Location);

        editor.AddConnection(row.Melee, cursedUnits.FlowIn);
        editor.AddConnection(rowUnits.Cards, cursedUnits.Cards);
        editor.AddConnection(cursed.Out, cursedUnits.Filter);
        editor.AddConnection(cursedUnits.FilteredCards, cursedCount.List);
        editor.AddConnection(cursedUnits.Success, cursedPositive.FlowIn);
        editor.AddConnection(cursedUnits.Fail, cursedPositive.FlowIn);
        editor.AddConnection(cursedCount.Length, cursedPositive.A);
        editor.AddConnection(cursedPositive.Bigger, storeCursed.FlowIn);
        editor.AddConnection(cursedCount.Length, storeCursed.In);

        editor.AddConnection(row.Ranged, witcherUnits.FlowIn);
        editor.AddConnection(rowUnits.Cards, witcherUnits.Cards);
        editor.AddConnection(witcher.Out, witcherUnits.Filter);
        editor.AddConnection(witcherUnits.FilteredCards, witcherCount.List);
        editor.AddConnection(witcherUnits.Success, witcherPositive.FlowIn);
        editor.AddConnection(witcherUnits.Fail, witcherPositive.FlowIn);
        editor.AddConnection(witcherCount.Length, witcherPositive.A);
        editor.AddConnection(witcherPositive.Bigger, storeWitcher.FlowIn);
        editor.AddConnection(witcherCount.Length, storeWitcher.In);

        editor.AddConnection(storeCursed.FlowOut, selfBoost.FlowIn);
        editor.AddConnection(storeWitcher.FlowOut, selfBoost.FlowIn);
        editor.AddConnection(ownerCardList, selfBoost.Targets);
        editor.AddConnection(ownerEntity, selfBoost.Attacker);
        editor.AddConnection(currentBoosts, selfBoost.Power);

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(selfBoost.FlowOut, request.FlowIn);
        editor.AddConnection(enemies.Out, request.ValidTargets);
        editor.AddConnection(request.Success, damage.FlowIn);
        editor.AddConnection(request.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(currentBoosts, damage.Power);

        editor.Finish();
    }

    private static void AddTemplateToken(XElement template, int token)
    {
        XElement tokens = template.Element("Tokens")
            ?? throw new InvalidDataException("Template не содержит Tokens.");
        int current = int.TryParse(tokens.Value, out int value) ? value : 0;
        tokens.Value = (current | token).ToString();
    }

    private static void RebuildAnCraiteMarauderGraveyardScaling(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
