        editor.AddConnection(enemies.Out, randomEnemy.List);
        editor.AddConnection(randomEnemy.Card, oneEnemy.Card);
        editor.AddConnection(randomEnemy.FlowOut, oneDamage.FlowIn);
        editor.AddConnection(oneEnemy.List, oneDamage.Targets);
        editor.AddConnection(ownerEntity, oneDamage.Attacker);

        AfterMovedEndpoints enteredGraveyard = editor.AddAfterMovedTrigger(
            ownerLocation: 32, triggerCard: 1, triggerPlayer: 3,
            fromLocation: 4095, toLocation: 32, reason: 255);
        int oldDamage = editor.AddGetIntVariable(damageVar);
        IntPlusEndpoints increasedDamage = editor.AddIntPlus();
        SetEndpointValue(ability, increasedDamage.B, "1");
        SetVarEndpoints storeDamage = editor.AddSetIntVariable(damageVar);
        editor.AddConnection(ownerPlayer, enteredGraveyard.FromPlayer);
        editor.AddConnection(ownerPlayer, enteredGraveyard.ToPlayer);
        editor.AddConnection(oldDamage, increasedDamage.A);
        editor.AddConnection(enteredGraveyard.FlowOut, storeDamage.FlowIn);
        editor.AddConnection(increasedDamage.Result, storeDamage.In);

        AfterMovedEndpoints leftGraveyard = editor.AddAfterMovedTrigger(
            ownerLocation: 1019, triggerCard: 1, triggerPlayer: 3,
            fromLocation: 32, toLocation: 4095, reason: 255);
        StrengthenEndpoints strengthen = editor.AddStrengthenSubAbility(1);
        editor.AddConnection(ownerPlayer, leftGraveyard.FromPlayer);
        editor.AddConnection(ownerPlayer, leftGraveyard.ToPlayer);
        editor.AddConnection(leftGraveyard.FlowOut, strengthen.FlowIn);
        editor.AddConnection(leftGraveyard.CardsMoved, strengthen.Targets);
        editor.Finish();
    }

