    private static void AddFlaminicaBronzeBeastGraveyardPlay(XElement ability)
    {
        if (ability.Descendants().Any(element =>
                string.Equals((string?)element.Attribute("Name"), "FlaminicaBeastReviveV1", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("FlaminicaBeastReviveV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 0, locationId: 32, cardTypes: 4, cardTiers: 2, ignoreOwner: false);
        NodeEndpoints beast = editor.AddFilterCardCategory(4096UL, 0, 0);
        NodeEndpoints provision4 = editor.AddFilterCardProvision(compareOp: 0, provision: 4);
        LogicEndpoints eligibleFilter = editor.AddFilterLogic(orOperation: false);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        int setPowerArmed = editor.EnsurePersistentIntVariable("FlaminicaSetPowerArmed", 0);
        SetVarEndpoints armSetPower = editor.AddSetIntVariable(setPowerArmed);
        SetEndpointValue(ability, armSetPower.In, "1");
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(ownerPlayer, graveyard.PlayerId);
        editor.AddConnection(beast.Out, eligibleFilter.Input0);
        editor.AddConnection(provision4.Out, eligibleFilter.Input1);
        editor.AddConnection(deploy.FlowOut, eligible.FlowIn);
        editor.AddConnection(graveyard.Out, eligible.Cards);
        editor.AddConnection(eligibleFilter.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, choice.FlowIn);
        editor.AddConnection(eligible.FilteredCards, choice.ValidChoices);
        editor.AddConnection(choice.Success, armSetPower.FlowIn);
        editor.AddConnection(armSetPower.FlowOut, play.FlowIn);
        editor.AddConnection(choice.SelectedChoices, play.Cards);

        // PlayCards resolves asynchronously.  Wait until the selected graveyard
        // card physically arrives on the owner's board, then set that moved card
        // to exactly 1 power and disarm the one-shot migration flag.
        AfterMovedEndpoints playedBeastToBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 32,
            toLocation: 3,
            reason: 1);
        int armedValue = editor.AddGetIntVariable(setPowerArmed);
        IntBranchEndpoints armedBranch = editor.AddIntBranch();
        SetEndpointValue(ability, armedBranch.B, "0");
        PowerEndpoints setPower = editor.AddChangePower(
            amount: 1, operation: 2, elementType: 1, attackMethod: 0);
        SetVarEndpoints disarmSetPower = editor.AddSetIntVariable(setPowerArmed);
        SetEndpointValue(ability, disarmSetPower.In, "0");

        editor.AddConnection(ownerPlayer, playedBeastToBoard.ToPlayer);
        editor.AddConnection(playedBeastToBoard.FlowOut, armedBranch.FlowIn);
        editor.AddConnection(armedValue, armedBranch.A);
        editor.AddConnection(armedBranch.Bigger, setPower.FlowIn);
        editor.AddConnection(playedBeastToBoard.CardsMoved, setPower.Targets);
        editor.AddConnection(ownerEntity, setPower.Attacker);
        editor.AddConnection(setPower.FlowOut, disarmSetPower.FlowIn);
        editor.Finish();
    }

    private static void AddSeaSerpentWeatherRowDamage(XElement ability)
    {
        if (ability.Descendants().Any(element =>
                string.Equals((string?)element.Attribute("Name"), "SeaSerpentWeatherDamageV1", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("SeaSerpentWeatherDamageV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement target = FindNode(ability, "RequestCardTargetsNode");
        XElement baseDamage = ability.Element("Nodes")!.Elements().Single(node =>
            IsNodeType(node, "ChangePowerNode") &&
            (string?)node.Element("Operation")?.Attribute("V") == "1");
        int baseFlowIn = Id(baseDamage.Element("FlowIn")!);
        int oldFlow = GetSingleIncomingSource(editor, baseFlowIn, "Sea Serpent base damage flow");
        editor.RemoveConnection(oldFlow, baseFlowIn);

        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        CardLocationEndpoints targetRowId = editor.AddGetCardLocationId(positionType: 0);
        MakeLocationEndpoints targetRow = editor.AddMakeLocation();
        GetLocationsEndpoints rainStormRows = editor.AddGetLocations(tokenMask: 68, locationMask: 3);
        LocationListContainsEndpoints hasRainOrStorm = editor.AddLocationListContainsElement();
        BranchEndpoints weatherBranch = editor.AddBranch();
        LocationTimerEndpoints duration = editor.AddGetLocationTimer();
        IntPlusEndpoints increasedDamage = editor.AddIntPlus();
        int originalDamageValue = GetSingleIncomingSource(
            editor, Id(baseDamage.Element("Power")!), "Sea Serpent base damage value");
        PowerEndpoints weatherDamage = editor.AddChangePower(
            amount: 0, operation: 1, elementType: 1, attackMethod: 1);

        editor.AddConnection(Id(target.Element("SelectedTargets")!), selected.List);
        editor.AddConnection(selected.Card, targetRowId.Card);
        editor.AddConnection(opponent, targetRow.PlayerId);
        editor.AddConnection(targetRowId.Location, targetRow.LocationId);
        editor.AddConnection(opponent, rainStormRows.PlayerMask);
        editor.AddConnection(rainStormRows.Out, hasRainOrStorm.List);
        editor.AddConnection(targetRow.Location, hasRainOrStorm.Element);
        editor.AddConnection(targetRow.Location, duration.Location);
        editor.AddConnection(oldFlow, weatherBranch.FlowIn);
        editor.AddConnection(hasRainOrStorm.Result, weatherBranch.Condition);
        editor.AddConnection(weatherBranch.False, baseFlowIn);
        editor.AddConnection(weatherBranch.True, weatherDamage.FlowIn);
        editor.AddConnection(originalDamageValue, increasedDamage.A);
        editor.AddConnection(duration.Timer, increasedDamage.B);
        editor.AddConnection(increasedDamage.Result, weatherDamage.Power);
        editor.AddConnection(Id(target.Element("SelectedTargets")!), weatherDamage.Targets);
        editor.AddConnection(ownerEntity, weatherDamage.Attacker);
        foreach (int downstream in editor.GetOutgoingTargets(Id(baseDamage.Element("FlowOut")!)))
            editor.AddConnection(weatherDamage.FlowOut, downstream);
        editor.Finish();
    }

    private static void AddGiantBoarOpeningDamage(XElement ability)
    {
        XElement? markerV2 = ability.Element("TemporaryVariables")?.Elements().FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Name"), "GiantBoarOpeningDamageV2", StringComparison.Ordinal));
        if (markerV2 != null)
            return;

        XElement? markerV1 = ability.Element("TemporaryVariables")?.Elements().FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Name"), "GiantBoarOpeningDamageV1", StringComparison.Ordinal));
        if (markerV1 != null)
        {
            var migration = new GraphEditor(ability);
            List<XElement> targetRequests = ability.Element("Nodes")!.Elements()
                .Where(node => IsNodeType(node, "RequestCardTargetsNode") &&
                               (((string?)node.Element("MinTargets")?.Attribute("V") == "2" &&
                                 (string?)node.Element("MaxTargets")?.Attribute("V") == "2") ||
                                ((string?)node.Element("MinTargets")?.Attribute("V") == "1" &&
                                 (string?)node.Element("MaxTargets")?.Attribute("V") == "1")))
                .ToList();
            HashSet<int> targetInputs = targetRequests
                .Select(node => Id(node.Element("ValidTargets")!))
                .ToHashSet();
            XElement? migratedBattlefield = ability.Element("Nodes")!.Elements().FirstOrDefault(node =>
                IsNodeType(node, "GetCardsNode") &&
                (string?)node.Element("LocationId")?.Attribute("V") == "3" &&
                (string?)node.Element("CardTypes")?.Attribute("V") == "4" &&
                (string?)node.Element("CardTiers")?.Attribute("V") == "10" &&
                (string?)node.Element("Ignore")?.Attribute("V") == "264" &&
                targetInputs.Count(input => migration.HasConnection(Id(node.Element("Out")!), input)) == 2);
            if (migratedBattlefield == null)
                throw new InvalidOperationException("Giant Boar V1 target pool was not found for migration.");

            migration.RemoveIncomingConnections(Id(migratedBattlefield.Element("PlayerId")!));
            migratedBattlefield.Element("IgnoreOwner")!.SetAttributeValue("V", "False");
            markerV1.SetAttributeValue("Name", "GiantBoarOpeningDamageV2");
            migration.Finish();
            return;
        }

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("GiantBoarOpeningDamageV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement row = FindNode(ability, "OwnerLocationBranchNode");
        int meleeFlow = Id(row.Element("Melee")!);
        int rangedFlow = Id(row.Element("Ranged")!);
        int meleeOriginal = editor.GetOutgoingTargets(meleeFlow).Single();
        int rangedOriginal = editor.GetOutgoingTargets(rangedFlow).Single();
        editor.RemoveConnection(meleeFlow, meleeOriginal);
        editor.RemoveConnection(rangedFlow, rangedOriginal);

        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints battlefield = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        TargetRequestEndpoints meleeTargets = editor.AddRequestCardTargets(2, 2, 8_388_608L);
        PowerEndpoints meleeDamage = editor.AddChangePower(1, 1, 1, 1);
        TargetRequestEndpoints rangedTarget = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        PowerEndpoints rangedDamage = editor.AddChangePower(2, 1, 1, 1);

        editor.AddConnection(meleeFlow, meleeTargets.FlowIn);
        editor.AddConnection(battlefield.Out, meleeTargets.ValidTargets);
        editor.AddConnection(meleeTargets.Success, meleeDamage.FlowIn);
        editor.AddConnection(meleeTargets.SelectedTargets, meleeDamage.Targets);
        editor.AddConnection(ownerEntity, meleeDamage.Attacker);
        editor.AddConnection(meleeDamage.FlowOut, meleeOriginal);
        editor.AddConnection(meleeTargets.Fail, meleeOriginal);

        editor.AddConnection(rangedFlow, rangedTarget.FlowIn);
        editor.AddConnection(battlefield.Out, rangedTarget.ValidTargets);
        editor.AddConnection(rangedTarget.Success, rangedDamage.FlowIn);
        editor.AddConnection(rangedTarget.SelectedTargets, rangedDamage.Targets);
        editor.AddConnection(ownerEntity, rangedDamage.Attacker);
        editor.AddConnection(rangedDamage.FlowOut, rangedOriginal);
        editor.AddConnection(rangedTarget.Fail, rangedOriginal);
        editor.Finish();
    }

    private static void RebuildDerranDualZealOrders(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Damage", 3);
        int marker = editor.EnsureIntVariable("DerranDualOrdersV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        TriggerEndpoints order = editor.AddTappedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        PowerEndpoints selfDamage = editor.AddChangePower(3, 1, 16384, 0);
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        editor.AddConnection(order.FlowOut, selfDamage.FlowIn);
        editor.AddConnection(ownerEntity, selfDamage.Attacker);
        editor.AddConnection(ownerCards, selfDamage.Targets);
        editor.AddConnection(selfDamage.FlowOut, row.FlowIn);

        // Ranged: preserve the original deck-to-graveyard effect as a Zeal Order.
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0, locationId: 16, cardTypes: 30, cardTiers: 10, ignoreOwner: false);
        CardChoiceEndpoints deckChoice = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        MakeCardPositionEndpoints deckGrave = editor.AddMakeCardPosition(location: 32, index: 0);
        MoveCardsEndpoints mill = editor.AddMoveCards();
        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(row.Ranged, deckChoice.FlowIn);
        editor.AddConnection(deck.Out, deckChoice.ValidChoices);
        editor.AddConnection(deckChoice.Success, deckGrave.FlowIn);
        editor.AddConnection(ownerPlayer, deckGrave.PlayerId);
        editor.AddConnection(deckGrave.FlowOut, mill.FlowIn);
        editor.AddConnection(deckChoice.SelectedChoices, mill.Cards);
        editor.AddConnection(deckGrave.Position, mill.Position);

        // Melee: discard a chosen hand card, then either recreate a bronze unit
        // in hand or draw one card for every other discarded card.
        GetCardsEndpoints hand = editor.AddGetCards(
            ignoreTokens: 0, locationId: 8, cardTypes: 30, cardTiers: 10, ignoreOwner: false);
        CardChoiceEndpoints handChoice = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        CardElementEndpoints chosenCard = editor.AddCardListGetElement(0);
        CardDefinitionEndpoints chosenDefinition = editor.AddGetCardDefinition();
        NodeEndpoints bronze = editor.AddFilterCardTier(2);
        NodeEndpoints unit = editor.AddFilterCardType(4);
        LogicEndpoints bronzeUnit = editor.AddFilterLogic(orOperation: false);
        FilterListEndpoints classify = editor.AddFilterCardList();
        editor.AddConnection(ownerPlayer, hand.PlayerId);
        editor.AddConnection(row.Melee, handChoice.FlowIn);
        editor.AddConnection(hand.Out, handChoice.ValidChoices);
        editor.AddConnection(handChoice.SelectedChoices, chosenCard.List);
        editor.AddConnection(chosenCard.Card, chosenDefinition.Card);
        editor.AddConnection(bronze.Out, bronzeUnit.Input0);
        editor.AddConnection(unit.Out, bronzeUnit.Input1);
        editor.AddConnection(handChoice.Success, classify.FlowIn);
        editor.AddConnection(handChoice.SelectedChoices, classify.Cards);
        editor.AddConnection(bronzeUnit.Out, classify.Filter);

        MakeCardPositionEndpoints bronzeGrave = editor.AddMakeCardPosition(location: 32, index: 0);
        MoveCardsEndpoints discardBronze = editor.AddMoveCards();
        MakeCardPositionEndpoints copyHand = editor.AddMakeCardPosition(location: 8, index: 0);
        DynamicSpawnEndpoints spawnCopy = editor.AddDynamicSpawnCard(count: 1, spawnType: 3);
        editor.AddConnection(classify.Success, bronzeGrave.FlowIn);
        editor.AddConnection(ownerPlayer, bronzeGrave.PlayerId);
        editor.AddConnection(bronzeGrave.FlowOut, discardBronze.FlowIn);
        editor.AddConnection(handChoice.SelectedChoices, discardBronze.Cards);
        editor.AddConnection(bronzeGrave.Position, discardBronze.Position);
        editor.AddConnection(discardBronze.FlowOut, copyHand.FlowIn);
        editor.AddConnection(ownerPlayer, copyHand.PlayerId);
        editor.AddConnection(copyHand.FlowOut, spawnCopy.FlowIn);
        editor.AddConnection(ownerCard, spawnCopy.Spawner);
        editor.AddConnection(copyHand.Position, spawnCopy.Position);
        editor.AddConnection(chosenDefinition.Definition, spawnCopy.Definition);

        MakeCardPositionEndpoints otherGrave = editor.AddMakeCardPosition(location: 32, index: 0);
        MoveCardsEndpoints discardOther = editor.AddMoveCards();
        DrawEndpoints draw = editor.AddDrawCards(1);
        editor.AddConnection(classify.Fail, otherGrave.FlowIn);
        editor.AddConnection(ownerPlayer, otherGrave.PlayerId);
        editor.AddConnection(otherGrave.FlowOut, discardOther.FlowIn);
        editor.AddConnection(handChoice.SelectedChoices, discardOther.Cards);
        editor.AddConnection(otherGrave.Position, discardOther.Position);
        editor.AddConnection(discardOther.FlowOut, draw.FlowIn);
        editor.AddConnection(ownerPlayer, draw.PlayerId);
        editor.Finish();
    }

    private static void RebuildYoanaDiscardBoostDistribution(XElement ability, XElement template)
