    private static void RebuildUlfhedinnRowEffectBloodthirst(XElement ability)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int bloodthirstValue = editor.EnsureIntVariable("bloodthirst", 3);
        int marker = editor.EnsureIntVariable("UlfhedinnRowEffectBloodthirstV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        BloodthirstEndpoints bloodthirst = editor.AddBloodthirstBranch(count: 0);
        int threshold = editor.AddGetIntVariable(bloodthirstValue);
        editor.AddConnection(deploy.FlowOut, bloodthirst.FlowIn);
        editor.AddConnection(opponent, bloodthirst.Player);
        editor.AddConnection(threshold, bloodthirst.Count);
        editor.AddConnection(opponent, enemies.PlayerId);

        // Natural Bloodthirst branch.
        TargetRequestEndpoints activeTarget = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        int activeTargetsVariable = editor.AddCardListVariable("UlfhedinnActiveTargets");
        SetVarEndpoints saveActiveTarget = editor.AddSetCardListVariable(activeTargetsVariable);
        int activeTargetsForAppend = editor.AddGetCardListVariable(activeTargetsVariable);
        int completeActiveTargets = editor.AddGetCardListVariable(activeTargetsVariable);
        CardElementEndpoints activeCard = editor.AddCardListGetElement(0);
        CardPositionEndpoints activePosition = editor.AddGetCardPosition(0);
        ShapeEndpoints activeAdjacent = editor.AddGetCardsInShape();
        CardListAppendEndpoints activeCombined = editor.AddCardListAppend();
        ForeachEndpoints activeEach = editor.AddCardListForeach();
        ElementListEndpoints activeOne = editor.AddCardElementToList();
        CardPowerEndpoints activePower = editor.AddGetCardPower();
        IntDivideEndpoints activeHalf = editor.AddIntDivide(2, 2);
        PowerEndpoints activeDamage = editor.AddChangePower(0, 1, 32, 0);
        editor.AddConnection(bloodthirst.Active, activeTarget.FlowIn);
        editor.AddConnection(enemies.Out, activeTarget.ValidTargets);
        editor.AddConnection(activeTarget.Success, saveActiveTarget.FlowIn);
        editor.AddConnection(activeTarget.SelectedTargets, saveActiveTarget.In);
        editor.AddConnection(completeActiveTargets, activeCard.List);
        editor.AddConnection(activeCard.Card, activePosition.Card);
        editor.AddConnection(activePosition.Position, activeAdjacent.Position);
        editor.AddConnection(saveActiveTarget.FlowOut, activeCombined.FlowIn);
        editor.AddConnection(activeTargetsForAppend, activeCombined.List);
        editor.AddConnection(activeAdjacent.Cards, activeCombined.ListToAppend);
        editor.AddConnection(activeCombined.FlowOut, activeEach.FlowIn);
        editor.AddConnection(completeActiveTargets, activeEach.List);
        editor.AddConnection(activeEach.Element, activeOne.Card);
        editor.AddConnection(activeEach.Element, activePower.Card);
        editor.AddConnection(activePower.Power, activeHalf.Value);
        editor.AddConnection(activeEach.FlowFor, activeDamage.FlowIn);
        editor.AddConnection(activeOne.List, activeDamage.Targets);
        editor.AddConnection(ownerEntity, activeDamage.Attacker);
        editor.AddConnection(activeHalf.Result, activeDamage.Power);

        // Regular branch: target once, then upgrade to the active branch if the
        // selected row currently contains any row effect.
        TargetRequestEndpoints regularTarget = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        CardElementEndpoints regularCard = editor.AddCardListGetElement(0);
        CardLocationEndpoints regularRowId = editor.AddGetCardLocationId(positionType: 0);
        MakeLocationEndpoints regularRow = editor.AddMakeLocation();
        GetLocationsEndpoints effectRows = editor.AddGetLocations(
            tokenMask: AllRowEffectLocationTokens, locationMask: 3);
        LocationListContainsEndpoints hasEffect = editor.AddLocationListContainsElement();
        BranchEndpoints effectBranch = editor.AddBranch();
        editor.AddConnection(bloodthirst.Regular, regularTarget.FlowIn);
        editor.AddConnection(enemies.Out, regularTarget.ValidTargets);
        editor.AddConnection(regularTarget.SelectedTargets, regularCard.List);
        editor.AddConnection(regularCard.Card, regularRowId.Card);
        editor.AddConnection(opponent, regularRow.PlayerId);
        editor.AddConnection(regularRowId.Location, regularRow.LocationId);
        editor.AddConnection(opponent, effectRows.PlayerMask);
        editor.AddConnection(effectRows.Out, hasEffect.List);
        editor.AddConnection(regularRow.Location, hasEffect.Element);
        editor.AddConnection(regularTarget.Success, effectBranch.FlowIn);
        editor.AddConnection(hasEffect.Result, effectBranch.Condition);

        // No row effect: half-damage only the chosen unit.
        CardPowerEndpoints singlePower = editor.AddGetCardPower();
        IntDivideEndpoints singleHalf = editor.AddIntDivide(2, 2);
        PowerEndpoints singleDamage = editor.AddChangePower(0, 1, 32, 0);
        editor.AddConnection(regularCard.Card, singlePower.Card);
        editor.AddConnection(singlePower.Power, singleHalf.Value);
        editor.AddConnection(effectBranch.False, singleDamage.FlowIn);
        editor.AddConnection(regularTarget.SelectedTargets, singleDamage.Targets);
        editor.AddConnection(ownerEntity, singleDamage.Attacker);
        editor.AddConnection(singleHalf.Result, singleDamage.Power);

        // Row effect: selected unit plus its adjacent units.
        int effectTargetsVariable = editor.AddCardListVariable("UlfhedinnEffectTargets");
        SetVarEndpoints saveEffectTarget = editor.AddSetCardListVariable(effectTargetsVariable);
        int effectTargetsForAppend = editor.AddGetCardListVariable(effectTargetsVariable);
        int completeEffectTargets = editor.AddGetCardListVariable(effectTargetsVariable);
        CardElementEndpoints effectCard = editor.AddCardListGetElement(0);
        CardPositionEndpoints effectPosition = editor.AddGetCardPosition(0);
        ShapeEndpoints effectAdjacent = editor.AddGetCardsInShape();
        CardListAppendEndpoints effectCombined = editor.AddCardListAppend();
        ForeachEndpoints effectEach = editor.AddCardListForeach();
        ElementListEndpoints effectOne = editor.AddCardElementToList();
        CardPowerEndpoints effectPower = editor.AddGetCardPower();
        IntDivideEndpoints effectHalf = editor.AddIntDivide(2, 2);
        PowerEndpoints effectDamage = editor.AddChangePower(0, 1, 32, 0);
