    private static void AddBrokvarHunterAdjacentBeastDamage(XElement ability)
    {
        if (ability.Descendants().Any(element =>
                string.Equals((string?)element.Attribute("Name"), "BrokvarAdjacentBeastDamageV1", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("BrokvarAdjacentBeastDamageV1", 1);
        editor.TemporaryVariables.Elements().First(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement tapped = FindNode(ability, "TappedTrigger");
        XElement damage = ability.Element("Nodes")!.Elements().First(node =>
            IsNodeType(node, "ChangePowerNode") &&
            (string?)node.Element("Operation")?.Attribute("V") == "1");
        int tappedOut = Id(tapped.Element("FlowOut")!);
        IReadOnlyList<int> oldTargets = editor.GetOutgoingTargets(tappedOut);
        if (oldTargets.Count != 1)
            throw new InvalidDataException("Brokvar Hunter TappedTrigger должен иметь один выход.");
        int oldTarget = oldTargets[0];
        editor.RemoveConnection(tappedOut, oldTarget);

        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        CardPositionEndpoints position = editor.AddGetCardPosition(0);
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        NodeEndpoints beast = editor.AddFilterCardCategory(4096UL, 0, 0);
        FilterListEndpoints adjacentBeasts = editor.AddFilterCardList();
        CardListLengthEndpoints beastCount = editor.AddCardListLength();
        IntPlusEndpoints totalDamage = editor.AddIntPlus();
        int damagePower = Id(damage.Element("Power")!);
        int baseDamage = GetSingleIncomingSource(editor, damagePower, "Brokvar Hunter base damage");
        editor.RemoveIncomingConnections(damagePower);

        editor.AddConnection(ownerCard, position.Card);
        editor.AddConnection(position.Position, adjacent.Position);
        editor.AddConnection(tappedOut, adjacentBeasts.FlowIn);
        editor.AddConnection(adjacent.Cards, adjacentBeasts.Cards);
        editor.AddConnection(beast.Out, adjacentBeasts.Filter);
        editor.AddConnection(adjacentBeasts.Success, oldTarget);
        editor.AddConnection(adjacentBeasts.Fail, oldTarget);
        editor.AddConnection(adjacentBeasts.FilteredCards, beastCount.List);
        editor.AddConnection(baseDamage, totalDamage.A);
        editor.AddConnection(beastCount.Length, totalDamage.B);
        editor.AddConnection(totalDamage.Result, damagePower);
        editor.Finish();
    }

