    private static void AddTuirseachAxemanDiscardSummonClash(XElement ability)
    {
        EnsureAbilityContainers(ability);

        bool v4AlreadyAdded = ability.Descendants().Any(element =>
            string.Equals((string?)element.Attribute("Name"), "AxemanSelfDiscardSummonClashV4", StringComparison.Ordinal));
        if (v4AlreadyAdded)
            return;

        // V1-V3 listened for every unit discarded by the owner while Axeman
        // was on the board. The intended effect is the vanilla self-discard
        // lifecycle used by Tuirseach Skirmisher (152313): this ability becomes
        // active in the graveyard, TriggerCard=Self, and summons the ability
        // owner itself when that card is discarded. Remove the complete legacy
        // append segment and rebuild from that proven graph.
        XElement? legacyMarker = ability.Element("TemporaryVariables")!.Elements().FirstOrDefault(element =>
            string.Equals((string?)element.Attribute("Name"), "AxemanDiscardSummonClashV1", StringComparison.Ordinal) ||
            string.Equals((string?)element.Attribute("Name"), "AxemanDiscardSummonClashV2", StringComparison.Ordinal) ||
            string.Equals((string?)element.Attribute("Name"), "AxemanDiscardSummonClashV3", StringComparison.Ordinal));
        if (legacyMarker != null)
        {
            int cutoffId = Id(legacyMarker);
            XElement nodes = ability.Element("Nodes")!;
            XElement connections = ability.Element("Connections")!;
            List<XElement> legacyNodes = nodes.Elements()
                .Where(node => ((int?)node.Attribute("Id") ?? 0) > cutoffId)
                .ToList();
            HashSet<int> removedEndpointIds = legacyNodes
                .SelectMany(node => node.DescendantsAndSelf())
                .Where(element => element.Attribute("Id") != null)
                .Select(element => (int)element.Attribute("Id")!)
                .ToHashSet();

            foreach (XElement connection in connections.Elements()
                         .Where(connection =>
                             removedEndpointIds.Contains((int?)connection.Attribute("SrcId") ?? -1) ||
                             removedEndpointIds.Contains((int?)connection.Attribute("DstId") ?? -1))
                         .ToList())
            {
                connection.Remove();
            }
            foreach (XElement node in legacyNodes)
                node.Remove();
            legacyMarker.Remove();
        }

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("AxemanSelfDiscardSummonClashV4", 1);
        editor.TemporaryVariables.Elements().First(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();

        // Exact self-discard trigger copied from the working vanilla ability
        // on Tuirseach Skirmisher (152313).
        AfterMovedEndpoints discardedSelf = editor.AddAfterMovedTrigger(
            ownerLocation: 32,
            triggerCard: 1,
            triggerPlayer: 3,
            fromLocation: 8,
            toLocation: 32,
            reason: 6);
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        SummonOwnRowEndpoints summonMelee = editor.AddSummonMeleeRowSubAbility();
        CardElementEndpoints summonedAxeman = editor.AddCardListGetElement(0);

        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        PowerLevelEndpoints strongest = editor.AddFilterPowerLevel(1, 1);
        CardElementEndpoints strongestCard = editor.AddCardListGetElement(0);
        ClashEndpoints clash = editor.AddClashSubAbility(1);

        editor.AddConnection(ownerPlayer, discardedSelf.FromPlayer);
        editor.AddConnection(ownerPlayer, discardedSelf.ToPlayer);
        editor.AddConnection(discardedSelf.FlowOut, summonMelee.FlowIn);
        editor.AddConnection(ownerCards, summonMelee.CardsIn);
        editor.AddConnection(ownerCards, summonedAxeman.List);

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(summonMelee.FlowOut, strongest.FlowIn);
        editor.AddConnection(enemies.Out, strongest.Cards);
        editor.AddConnection(strongest.Success, clash.FlowIn);
        editor.AddConnection(strongest.FilteredCards, strongestCard.List);
        editor.AddConnection(summonedAxeman.Card, clash.CardA);
        editor.AddConnection(strongestCard.Card, clash.CardB);
        editor.Finish();
    }


