    private static void RebuildYagaGraveyardConsume(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "0");
        SetTemplateText(template, "TapActive", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("YagaGraveyardConsumeV5", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        // Aerondight / The Brute / Milaen style: this persistent value is shown
        // directly in the sentence as the current maximum power of a valid target.
        int sabbathPowerLimit = editor.EnsurePersistentIntVariable("Boost", 0);
        editor.PersistentVariables.Elements().Single(v => (int?)v.Attribute("Id") == sabbathPowerLimit)
            .Attribute("HideInTooltip")?.Remove();
        int selectedPowerVariable = editor.EnsureIntVariable("YagaSelectedPower", 0);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == selectedPowerVariable)
            .SetAttributeValue("HideInTooltip", "True");
        int selectedDefinitionVariable = editor.AddEmptyCardDefinitionListVariable(
            "YagaSelectedDefinition", hideInTooltip: true);

        int owner = editor.AddGetOwnerPlayerId();
        TriggerEndpoints roundStart = editor.AddBeforeRoundTrigger(ownerLocation: 379);
        SetVarEndpoints reset = editor.AddSetIntVariable(sabbathPowerLimit);
        SetEndpointValue(ability, reset.In, "0");
        editor.AddConnection(roundStart.FlowOut, reset.FlowIn);

        TurnTriggerEndpoints turn = editor.AddAfterTurnTrigger(ownerLocation: 379, priorityValue: -15);
        KeywordBranchEndpoints sabbath = editor.AddSabbathBranchSubAbility();
        int current = editor.AddGetIntVariable(sabbathPowerLimit);
        IntPlusEndpoints plus = editor.AddIntPlus();
        SetEndpointValue(ability, plus.B, "1");
        SetVarEndpoints store = editor.AddSetIntVariable(sabbathPowerLimit);
        editor.AddConnection(owner, turn.PlayerFilter);
        editor.AddConnection(turn.FlowOut, sabbath.FlowIn);
        editor.AddConnection(sabbath.Active, store.FlowIn);
        editor.AddConnection(current, plus.A);
        editor.AddConnection(plus.Result, store.In);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();

        // Match working vanilla opponent-graveyard selectors. IgnoreOwner=True is
        // required even when PlayerId is the opponent; token mask 8 excludes invalid entries.
        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 8, locationId: 32, cardTypes: 4, cardTiers: 2, ignoreOwner: true);
        NodeEndpoints powerLimit = editor.AddFilterCardPower(compareOp: 4, power: 0);
        int currentPowerLimit = editor.AddGetIntVariable(sabbathPowerLimit);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(
            1, 1, 0, choiceType: 0, revealChoices: false);
        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        CardPowerEndpoints selectedPower = editor.AddGetCardPower();
        CardDefinitionEndpoints selectedDefinition = editor.AddGetCardDefinition();
        SetVarEndpoints savePower = editor.AddSetIntVariable(selectedPowerVariable);
        DefinitionElementToListEndpoints selectedDefinitionList =
            editor.AddCardDefinitionElementToList();
        SetVarEndpoints saveDefinition =
            editor.AddSetCardDefinitionListVariable(selectedDefinitionVariable);

        BanishEndpoints banish = editor.AddBanishCards(elementType: 1, attackMethod: 0);
        PowerEndpoints consumeBoost = editor.AddChangePower(0, 0, 1024, 0);
        int savedPower = editor.AddGetIntVariable(selectedPowerVariable);
        CardLocationEndpoints ownerRow = editor.AddGetCardLocationId(positionType: 0);
        PositionEndpoints position = editor.AddGetRandomLastAvailablePosition();
        DynamicSpawnEndpoints copy = editor.AddDynamicSpawnCard(count: 1, spawnType: 3);
        int savedDefinitions = editor.AddGetCardDefinitionListVariable(selectedDefinitionVariable);
        DefinitionElementEndpoints savedDefinition = editor.AddCardDefinitionListGetElement(0);

        editor.AddConnection(opponent, graveyard.PlayerId);
        editor.AddConnection(currentPowerLimit, powerLimit.PowerInput);
        editor.AddConnection(deploy.FlowOut, eligible.FlowIn);
        editor.AddConnection(graveyard.Out, eligible.Cards);
        editor.AddConnection(powerLimit.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, choice.FlowIn);
        editor.AddConnection(eligible.FilteredCards, choice.ValidChoices);
        editor.AddConnection(choice.SelectedChoices, selected.List);
        editor.AddConnection(selected.Card, selectedPower.Card);
        editor.AddConnection(selected.Card, selectedDefinition.Card);
        editor.AddConnection(choice.Success, savePower.FlowIn);
        editor.AddConnection(selectedPower.Power, savePower.In);
        editor.AddConnection(selectedDefinition.Definition, selectedDefinitionList.Element);
        editor.AddConnection(savePower.FlowOut, saveDefinition.FlowIn);
        editor.AddConnection(selectedDefinitionList.List, saveDefinition.In);
        editor.AddConnection(saveDefinition.FlowOut, banish.FlowIn);
        editor.AddConnection(ownerEntity, banish.Attacker);
        editor.AddConnection(choice.SelectedChoices, banish.Targets);

        editor.AddConnection(banish.FlowOut, consumeBoost.FlowIn);
        editor.AddConnection(ownerEntity, consumeBoost.Attacker);
        editor.AddConnection(ownerCards, consumeBoost.Targets);
        editor.AddConnection(savedPower, consumeBoost.Power);
        editor.AddConnection(ownerCard, ownerRow.Card);
        editor.AddConnection(owner, position.PlayerId);
        editor.AddConnection(ownerRow.Location, position.Location);
        editor.AddConnection(savedDefinitions, savedDefinition.List);
        editor.AddConnection(consumeBoost.FlowOut, copy.FlowIn);
        editor.AddConnection(ownerCard, copy.Spawner);
        editor.AddConnection(position.Position, copy.Position);
        editor.AddConnection(savedDefinition.Element, copy.Definition);
        editor.Finish();
    }

    private static void RebuildEndregaQueenWarriorPlay(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Element("TemporaryVariables")!.Elements().Any(variable =>
                string.Equals((string?)variable.Attribute("Name"), "EndregaQueenWarriorPlayV1", StringComparison.Ordinal)))
        {
            return;
        }
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("EndregaQueenWarriorPlayV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        XElement played = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "PlayedTrigger", StringComparison.Ordinal));
        int playedFlow = Id(played.Element("FlowOut")!);
        List<int> deployDestinations = ability.Element("Connections")!.Elements()
            .Where(connection => (int?)connection.Attribute("SrcId") == playedFlow)
            .Select(connection => (int)connection.Attribute("DstId")!)
            .ToList();
        foreach (int destination in deployDestinations)
            editor.TryRemoveConnection(playedFlow, destination);
        int definitions = editor.AddCardDefinitionListVariable("EndregaWarriorChoice", EndregaWarrior);
        int definitionList = editor.AddGetCardDefinitionListVariable(definitions);
        CreatePlayEndpoints createAndPlay = editor.AddCreateAndPlaySubAbility();
        editor.AddConnection(playedFlow, createAndPlay.FlowIn);
        editor.AddConnection(definitionList, createAndPlay.Definitions);
        editor.Finish();
    }

    private static void AddNativeThriveMechanic(GraphEditor editor)
    {
        // Exact vanilla Wyvern/Werecat Thrive graph. The trigger's player fields
        // deliberately remain at their native constant values; connecting ToPlayer
        // changes the event match and prevents Thrive from firing in this build.
        AfterMovedEndpoints playedUnit = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1);
        ThriveEndpoints thrive = editor.AddThriveSubAbility(boost: 1);
        editor.AddConnection(playedUnit.FlowOut, thrive.FlowIn);
        editor.AddConnection(playedUnit.CardsMoved, thrive.Cards);
    }

    private static int CombineCardFiltersOr(GraphEditor editor, params int[] filters)
    {
        if (filters.Length == 0)
            throw new InvalidOperationException("At least one card filter is required.");
        int combined = filters[0];
        for (int i = 1; i < filters.Length; i++)
        {
            LogicEndpoints next = editor.AddFilterLogic(orOperation: true);
            editor.AddConnection(combined, next.Input0);
            editor.AddConnection(filters[i], next.Input1);
            combined = next.Out;
        }
        return combined;
    }

    private static int CombineCardFiltersAnd(GraphEditor editor, params int[] filters)
    {
        if (filters.Length == 0)
            throw new InvalidOperationException("At least one card filter is required.");
        int combined = filters[0];
        for (int i = 1; i < filters.Length; i++)
        {
            LogicEndpoints next = editor.AddFilterLogic(orOperation: false);
            editor.AddConnection(combined, next.Input0);
            editor.AddConnection(filters[i], next.Input1);
            combined = next.Out;
        }
        return combined;
    }

    private static IReadOnlyList<int> AppendPredatorActivationSynergies(
        XElement ability,
        GraphEditor editor,
        IEnumerable<int> activationFlows,
        string markerName)
    {
        int marker = editor.EnsureIntVariable(markerName, 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        // Execute shared Predator reactions as one deterministic chain before the
        // card's main effect. Parallel FlowOut fan-out is not reliable in runtime:
        // a retaliation such as Vulnerability can interrupt the remaining branches.
        GetCardsEndpoints handAndDeck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 24,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints addaDefinition = editor.AddFilterCardTemplateId(AddaStriga);
        FilterListEndpoints addaCopies = editor.AddFilterCardList();
        PowerEndpoints addaBoost = editor.AddChangePower(
            amount: 1,
            operation: 0,
            elementType: 512,
            attackMethod: 0);
        editor.AddConnection(ownerPlayer, handAndDeck.PlayerId);
        editor.AddConnection(handAndDeck.Out, addaCopies.Cards);
        editor.AddConnection(addaDefinition.Out, addaCopies.Filter);
        foreach (int flow in activationFlows.Distinct())
            editor.AddConnection(flow, addaCopies.FlowIn);
        editor.AddConnection(addaCopies.Success, addaBoost.FlowIn);
        editor.AddConnection(addaCopies.FilteredCards, addaBoost.Targets);
        editor.AddConnection(ownerEntity, addaBoost.Attacker);

        GetCardsEndpoints friendlyBoard = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints wyvernOnBoardDefinition = editor.AddFilterCardTemplateId(Wyvern);
        FilterListEndpoints wyvernOnBoard = editor.AddFilterCardList();
        editor.AddConnection(ownerPlayer, friendlyBoard.PlayerId);
        editor.AddConnection(friendlyBoard.Out, wyvernOnBoard.Cards);
        editor.AddConnection(wyvernOnBoardDefinition.Out, wyvernOnBoard.Filter);
        editor.AddConnection(addaCopies.Fail, wyvernOnBoard.FlowIn);
        editor.AddConnection(addaBoost.FlowOut, wyvernOnBoard.FlowIn);

        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints deckWyvernDefinition = editor.AddFilterCardTemplateId(Wyvern);
        FilterListEndpoints deckWyverns = editor.AddFilterCardList();
        CardElementEndpoints firstWyvern = editor.AddCardListGetElement(index: 0);
        ElementListEndpoints oneWyvern = editor.AddCardElementToList();
        PositionEndpoints randomFriendlyRow = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summon = editor.AddMoveCards();
        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(wyvernOnBoard.Fail, deckWyverns.FlowIn);
        editor.AddConnection(deck.Out, deckWyverns.Cards);
        editor.AddConnection(deckWyvernDefinition.Out, deckWyverns.Filter);
        editor.AddConnection(deckWyverns.FilteredCards, firstWyvern.List);
        editor.AddConnection(firstWyvern.Card, oneWyvern.Card);
        editor.AddConnection(ownerPlayer, randomFriendlyRow.PlayerId);
        editor.AddConnection(deckWyverns.Success, summon.FlowIn);
        editor.AddConnection(oneWyvern.List, summon.Cards);
        editor.AddConnection(randomFriendlyRow.Position, summon.Position);

        // Every returned flow means all optional shared reactions are complete.
        // The caller connects them to its actual Predator effect.
        return new[] { wyvernOnBoard.Success, deckWyverns.Fail, summon.FlowOut };
    }

    private static void RebuildForktailPredatorCharges(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "True");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("ForktailPredatorChargesV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int runtimeMarker = editor.EnsureIntVariable("ForktailPredatorPreDamageSynergyV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == runtimeMarker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Damage", 1);
        editor.EnsureIntVariable("PredatorDamage", 2);
        editor.EnsureIntVariable("Charges", 1);

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        TriggerEndpoints order = editor.AddTappedTrigger();
        GetCardsEndpoints enemies = editor.AddGetCards();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        CardPowerEndpoints targetPower = editor.AddGetCardPower();
        CardPowerEndpoints selfPower = editor.AddGetCardPower();
        IntBranchEndpoints predator = editor.AddIntBranch();
        PowerEndpoints regularDamage = editor.AddChangePower(1, 1, 1, 1);
        PowerEndpoints predatorDamage = editor.AddChangePower(2, 1, 1, 1);
        DeathblowEndpoints deathblow = editor.AddDeathblowSubAbility();

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, selected.List);
        editor.AddConnection(selected.Card, targetPower.Card);
        editor.AddConnection(ownerCard, selfPower.Card);
        editor.AddConnection(target.Success, predator.FlowIn);
        editor.AddConnection(targetPower.Power, predator.A);
        editor.AddConnection(selfPower.Power, predator.B);
        editor.AddConnection(predator.Equal, regularDamage.FlowIn);
        editor.AddConnection(predator.Bigger, regularDamage.FlowIn);
        editor.AddConnection(target.SelectedTargets, regularDamage.Targets);
        editor.AddConnection(target.SelectedTargets, predatorDamage.Targets);
        editor.AddConnection(ownerEntity, regularDamage.Attacker);
        editor.AddConnection(ownerEntity, predatorDamage.Attacker);
        editor.AddConnection(regularDamage.FlowOut, deathblow.FlowIn);
        editor.AddConnection(predatorDamage.FlowOut, deathblow.FlowIn);
        editor.AddConnection(target.SelectedTargets, deathblow.Targets);

        GetCardsEndpoints handUnits = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 8,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        CardChoiceEndpoints handChoice = editor.AddRequestCardChoice(1, 1, 2_147_483_648L);
        PowerEndpoints handBoost = editor.AddChangePower(1, 0, 512, 0);
        editor.AddConnection(ownerPlayer, handUnits.PlayerId);
        editor.AddConnection(deathblow.Deathblow, handChoice.FlowIn);
        editor.AddConnection(handUnits.Out, handChoice.ValidChoices);
        editor.AddConnection(handChoice.Success, handBoost.FlowIn);
        editor.AddConnection(handChoice.SelectedChoices, handBoost.Targets);
        editor.AddConnection(ownerEntity, handBoost.Attacker);

        // Gain one charge whenever the owner plays any known Predator card.
        AfterMovedEndpoints played = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 3,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1,
            priorityValue: 15);
        editor.AddConnection(ownerPlayer, played.ToPlayer);
        int[] predatorIds =
        {
            AddaStriga, Cockatrice, Werewolf, KikimoreStalker,
            Forktail, Hybrid, Slyzard, Wyvern, Werecat
        };
        int[] predatorFilters = predatorIds
            .Select(id => editor.AddFilterCardTemplateId(id).Out)
            .ToArray();
        int anyPredator = CombineCardFiltersOr(editor, predatorFilters);
        FilterListEndpoints playedPredator = editor.AddFilterCardList();
        ChangeTapChargesEndpoints gainCharge = editor.AddChangeTapCardCharges(operation: 1, value: 1);
        editor.AddConnection(played.FlowOut, playedPredator.FlowIn);
        editor.AddConnection(played.CardsMoved, playedPredator.Cards);
        editor.AddConnection(anyPredator, playedPredator.Filter);
        editor.AddConnection(playedPredator.Success, gainCharge.FlowIn);
        editor.AddConnection(ownerEntity, gainCharge.Attacker);
        editor.AddConnection(ownerCards, gainCharge.Targets);

        IReadOnlyList<int> predatorReady = AppendPredatorActivationSynergies(
            ability,
            editor,
            new[] { predator.Smaller },
            "ForktailPredatorSynergyV2");
        foreach (int flow in predatorReady)
            editor.AddConnection(flow, predatorDamage.FlowIn);
        editor.Finish();
    }

