        TargetRequestEndpoints consumeTarget = editor.AddRequestCardTargets(1, 1, 0);
        CardElementEndpoints consumed = editor.AddCardListGetElement(0);
        CardPowerEndpoints consumedPower = editor.AddGetCardPower();
        SetVarEndpoints savePower = editor.AddSetIntVariable(consumedPowerVar);
        DestroyEndpoints consume = editor.AddDestroyCards(16_384, 0, removalType: 1);
        editor.AddConnection(ownerPlayer, friendly.PlayerId);
