        editor.AddConnection(friendly.Out, consumeTarget.ValidTargets);
        editor.AddConnection(consumeTarget.SelectedTargets, consumed.List);
        editor.AddConnection(consumed.Card, consumedPower.Card);
        editor.AddConnection(consumeTarget.Success, savePower.FlowIn);
        editor.AddConnection(consumedPower.Power, savePower.In);
        editor.AddConnection(savePower.FlowOut, consume.FlowIn);
        editor.AddConnection(consumeTarget.SelectedTargets, consume.Targets);
        editor.AddConnection(ownerEntity, consume.Attacker);

        int savedPowerForSelf = editor.AddGetIntVariable(consumedPowerVar);
        PowerEndpoints selfConsumeBoost = editor.AddChangePower(
            amount: 0,
            operation: 0,
            elementType: 1024,
            attackMethod: 0);
        editor.AddConnection(consume.FlowOut, selfConsumeBoost.FlowIn);
        editor.AddConnection(ownerEntity, selfConsumeBoost.Attacker);
        editor.AddConnection(ownerCards, selfConsumeBoost.Targets);
        editor.AddConnection(savedPowerForSelf, selfConsumeBoost.Power);

        GetCardsEndpoints hand = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 8,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints beast = editor.AddFilterCardCategory(4096UL, 0, 0);
        FilterListEndpoints handBeasts = editor.AddFilterCardList();
        CardChoiceEndpoints beastChoice = editor.AddRequestCardChoice(1, 1, 2_147_483_648L);
        int savedPower = editor.AddGetIntVariable(consumedPowerVar);
        IntDivideEndpoints half = editor.AddIntDivide(divisor: 2, rounding: 2);
        // Hand boosts use the same combat metadata as the native Alpha Werewolf branch.
        PowerEndpoints boost = editor.AddChangePower(
            amount: 0,
            operation: 0,
            elementType: 1024,
            attackMethod: 0,
            effectType: 1);
        editor.AddConnection(ownerPlayer, hand.PlayerId);
        editor.AddConnection(selfConsumeBoost.FlowOut, handBeasts.FlowIn);
        editor.AddConnection(hand.Out, handBeasts.Cards);
        editor.AddConnection(beast.Out, handBeasts.Filter);
        editor.AddConnection(handBeasts.Success, beastChoice.FlowIn);
        editor.AddConnection(handBeasts.FilteredCards, beastChoice.ValidChoices);
        editor.AddConnection(savedPower, half.Value);
        editor.AddConnection(beastChoice.Success, boost.FlowIn);
        editor.AddConnection(beastChoice.SelectedChoices, boost.Targets);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(half.Result, boost.Power);

        TriggerEndpoints order = editor.AddTappedTrigger();
        CardPowerEndpoints selfPower = editor.AddGetCardPower();
        GetCardsEndpoints enemies = editor.AddGetCards();
        NodeEndpoints lower = editor.AddFilterCardPower(compareOp: 2, power: 0);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        PowerEndpoints damage = editor.AddChangePower(2, 1, 1, 1);
        editor.AddConnection(ownerCard, selfPower.Card);
        editor.AddConnection(selfPower.Power, lower.PowerInput);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, eligible.FlowIn);
        editor.AddConnection(enemies.Out, eligible.Cards);
        editor.AddConnection(lower.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, target.FlowIn);
        editor.AddConnection(eligible.FilteredCards, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        IReadOnlyList<int> predatorReady = AppendPredatorActivationSynergies(
            ability,
            editor,
            new[] { target.Success },
            "SlyzardPredatorSynergyV2");
        foreach (int flow in predatorReady)
            editor.AddConnection(flow, damage.FlowIn);
        editor.Finish();
    }

