    private static void AddWereratRatPoison(XElement ability)
    {
        // MyProject already contains the verified V2 graph. Cumulative recipes may be
        // applied to that project again, so never append a second global trigger.
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "WereratRatPoisonV2", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("WereratRatPoisonV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int usedVar = editor.EnsurePersistentIntVariable("WereratRatPoisonUsedThisTurn", 0);
        editor.PersistentVariables.Elements().Single(v => (int?)v.Attribute("Id") == usedVar)
            .SetAttributeValue("HideInTooltip", "True");
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        TurnTriggerEndpoints turnStart = editor.AddBeforeTurnTrigger(ownerLocation: 3);
        SetVarEndpoints reset = editor.AddSetIntVariable(usedVar);
        SetEndpointValue(ability, reset.In, "0");
        editor.AddConnection(ownerPlayer, turnStart.PlayerFilter);
        editor.AddConnection(turnStart.FlowOut, reset.FlowIn);

        // KilledTrigger only observes the ability owner dying. Global destruction
        // is represented by the native board -> graveyard AfterMoved pattern.
        AfterMovedEndpoints destroyed = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 187,
            toLocation: 32,
            reason: 6);
        editor.AddConnection(ownerPlayer, destroyed.FromPlayer);
        NodeEndpoints rat = editor.AddFilterCardTemplateId(Rat);
        FilterListEndpoints isRat = editor.AddFilterCardList();
        editor.AddConnection(destroyed.FlowOut, isRat.FlowIn);
        editor.AddConnection(destroyed.CardsMoved, isRat.Cards);
        editor.AddConnection(rat.Out, isRat.Filter);

        int used = editor.AddGetIntVariable(usedVar);
        IntBranchEndpoints unused = editor.AddIntBranch();
        SetEndpointValue(ability, unused.B, "0");
        editor.AddConnection(isRat.Success, unused.FlowIn);
        editor.AddConnection(used, unused.A);

        GetCardsEndpoints enemies = editor.AddGetCards();
        RandomCardEndpoints randomEnemy = editor.AddRandomCard();
        ElementListEndpoints oneEnemy = editor.AddCardElementToList();
        TokenEndpoints poison = editor.AddPoison();
        SetVarEndpoints markUsed = editor.AddSetIntVariable(usedVar);
        SetEndpointValue(ability, markUsed.In, "1");
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(unused.Equal, randomEnemy.FlowIn);
        editor.AddConnection(enemies.Out, randomEnemy.List);
        editor.AddConnection(randomEnemy.Card, oneEnemy.Card);
        editor.AddConnection(randomEnemy.FlowOut, poison.FlowIn);
        editor.AddConnection(oneEnemy.List, poison.Targets);
        editor.AddConnection(ownerEntity, poison.Attacker);
        editor.AddConnection(poison.FlowOut, markUsed.FlowIn);
        editor.Finish();
    }

