            cardTypes: 4,
            cardTiers: 2,
            ignoreOwner: false);
        NodeEndpoints beast = editor.AddFilterCardCategory(4096UL, 0, 0);
        FilterListEndpoints bronzeBeasts = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0);
        PowerEndpoints boostBeforePlay = editor.AddChangePower(
            amount: 2,
