        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(deploy.FlowOut, bronzeBeasts.FlowIn);
        editor.AddConnection(deck.Out, bronzeBeasts.Cards);
        editor.AddConnection(beast.Out, bronzeBeasts.Filter);
        editor.AddConnection(bronzeBeasts.Success, choice.FlowIn);
        editor.AddConnection(bronzeBeasts.FilteredCards, choice.ValidChoices);
        // Boost the physical deck card before PlayCardsNode. Its Deploy/other
        // on-play ability therefore observes the already boosted power.
        editor.AddConnection(choice.Success, boostBeforePlay.FlowIn);
        editor.AddConnection(choice.SelectedChoices, boostBeforePlay.Targets);
        editor.AddConnection(ownerEntity, boostBeforePlay.Attacker);
        editor.AddConnection(boostBeforePlay.FlowOut, play.FlowIn);
