        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        CardPowerEndpoints targetPower = editor.AddGetCardPower();
        CardPowerEndpoints selfPower = editor.AddGetCardPower();
        IntBranchEndpoints predator = editor.AddIntBranch();
        PowerEndpoints singleDamage = editor.AddChangePower(1, 1, 1, 1);
        CardLocationEndpoints targetRow = editor.AddGetCardLocationId(positionType: 0);
        GetCardsEndpoints rowEnemies = editor.AddGetCards();
        PowerEndpoints rowDamage = editor.AddChangePower(1, 1, 1, 2);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, selected.List);
        editor.AddConnection(selected.Card, targetPower.Card);
        editor.AddConnection(ownerCard, selfPower.Card);
        editor.AddConnection(target.Success, predator.FlowIn);
        editor.AddConnection(targetPower.Power, predator.A);
        editor.AddConnection(selfPower.Power, predator.B);
        editor.AddConnection(predator.Equal, singleDamage.FlowIn);
        editor.AddConnection(predator.Bigger, singleDamage.FlowIn);
        editor.AddConnection(target.SelectedTargets, singleDamage.Targets);
        editor.AddConnection(ownerEntity, singleDamage.Attacker);
        editor.AddConnection(selected.Card, targetRow.Card);
        editor.AddConnection(opponent, rowEnemies.PlayerId);
        editor.AddConnection(targetRow.Location, rowEnemies.LocationId);
        editor.AddConnection(rowEnemies.Out, rowDamage.Targets);
        editor.AddConnection(ownerEntity, rowDamage.Attacker);
        IReadOnlyList<int> predatorReady = AppendPredatorActivationSynergies(
            ability,
            editor,
            new[] { predator.Smaller },
            "WerecatPredatorSynergyV2");
        foreach (int flow in predatorReady)
            editor.AddConnection(flow, rowDamage.FlowIn);
        editor.Finish();
    }

