    private static int InstallLegacyPredatorSynergyHooks(AbilityDocument abilities)
    {
        int count = 0;
        foreach (int cardId in new[] { Cockatrice, Werewolf, KikimoreStalker })
        {
            XElement cardAbility = abilities.FindRequiredCardAbility(cardId);
            EnsureAbilityContainers(cardAbility);
            if (cardAbility.Descendants().Any(e =>
                    (string?)e.Attribute("Name") == "LegacyPredatorSynergyV1"))
                continue;
            var editor = new GraphEditor(cardAbility);
            var activationFlows = new List<int>();
            if (cardId == Cockatrice)
            {
                XElement poison = cardAbility.Element("Nodes")!.Elements().Single(n =>
                    IsNodeType(n, "ChangeTokensNode") &&
                    (string?)n.Element("Tokens")?.Attribute("V") == "64");
                activationFlows.Add(Id(poison.Element("FlowOut")!));
            }
            else if (cardId == Werewolf)
            {
                XElement boost = cardAbility.Element("Nodes")!.Elements().Single(n =>
                    IsNodeType(n, "ChangePowerNode") &&
                    (string?)n.Element("Operation")?.Attribute("V") == "0");
                activationFlows.Add(Id(boost.Element("FlowOut")!));
            }
            else
            {
                foreach (XElement effect in cardAbility.Element("Nodes")!.Elements().Where(n =>
                             IsNodeType(n, "ChangePowerNode") &&
                             ((string?)n.Element("Operation")?.Attribute("V") == "1" ||
                              (string?)n.Element("Operation")?.Attribute("V") == "0")))
                {
                    activationFlows.Add(Id(effect.Element("FlowOut")!));
                }
            }
            AppendPredatorActivationSynergies(
                cardAbility,
                editor,
                activationFlows,
                "LegacyPredatorSynergyV1");
            editor.Finish();
            count++;
        }
        return count;
    }

