        SetVarEndpoints saveInitialPower = editor.AddSetIntVariable(destroyedBasePower);
        DestroyEndpoints destroy = editor.AddDestroyCards(
            elementType: 1,
            attackMethod: 1,
            removalType: 0);

        editor.AddConnection(ownerPlayer, friendlyUnits.PlayerId);
        editor.AddConnection(order.FlowOut, eligibleFriendly.FlowIn);
        editor.AddConnection(friendlyUnits.Out, eligibleFriendly.Cards);
        editor.AddConnection(cursedUnit.Out, eligibleFriendly.Filter);
        editor.AddConnection(eligibleFriendly.Success, friendlyTarget.FlowIn);
        editor.AddConnection(eligibleFriendly.FilteredCards, friendlyTarget.ValidTargets);
        editor.AddConnection(friendlyTarget.SelectedTargets, selectedFriendly.List);
        editor.AddConnection(selectedFriendly.Card, initialPower.Card);

        GetCardsEndpoints enemyUnits = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints enemyTarget = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        int damageValue = editor.AddGetIntVariable(destroyedBasePower);
        PowerEndpoints damage = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 1,
            attackMethod: 1);
        int boostValue = editor.AddGetIntVariable(destroyedBasePower);
        PowerEndpoints boost = editor.AddChangePower(
            amount: 0,
            operation: 0,
            elementType: 512,
            attackMethod: 0);

        editor.AddConnection(opponent, enemyUnits.PlayerId);
        editor.AddConnection(friendlyTarget.Success, enemyTarget.FlowIn);
        editor.AddConnection(enemyUnits.Out, enemyTarget.ValidTargets);
        editor.AddConnection(enemyTarget.Success, saveInitialPower.FlowIn);
        editor.AddConnection(initialPower.Power, saveInitialPower.In);
        editor.AddConnection(saveInitialPower.FlowOut, destroy.FlowIn);
        editor.AddConnection(ownerEntity, destroy.Attacker);
        editor.AddConnection(friendlyTarget.SelectedTargets, destroy.Targets);
        editor.AddConnection(destroy.FlowOut, damage.FlowIn);
        editor.AddConnection(enemyTarget.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(damageValue, damage.Power);
        editor.AddConnection(damage.FlowOut, boost.FlowIn);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(ownerCards, boost.Targets);
        editor.AddConnection(boostValue, boost.Power);
        editor.Finish();
    }

    private static void RebuildBloodyFlailSoldierBleed(XElement ability, XElement template)
    {
        EnsureAbilityContainers(ability);
        DisableOrderTemplate(template);

        XElement? v2Marker = ability.Descendants().FirstOrDefault(e =>
            string.Equals((string?)e.Attribute("Name"), "BloodyFlailSoldierPlayV2", StringComparison.Ordinal));
        if (v2Marker != null)
            return;

        XElement bleed = ability.Element("TemporaryVariables")!.Elements().Single(variable =>
            string.Equals((string?)variable.Attribute("Type"), "IntVar", StringComparison.Ordinal) &&
            string.Equals((string?)variable.Attribute("Name"), "Bleed", StringComparison.Ordinal));
        bleed.SetAttributeValue("V", "4");

        XElement deploy = ability.Element("Nodes")!.Elements().Single(node => IsNodeType(node, "PlayedTrigger"));
        XElement target = ability.Element("Nodes")!.Elements().Single(node => IsNodeType(node, "RequestCardTargetsNode"));
        int deployFlow = Id(deploy.Element("FlowOut")!);
        int targetFlow = Id(target.Element("FlowIn")!);

        var editor = new GraphEditor(ability);
        editor.RemoveConnection(deployFlow, targetFlow);
        int marker = editor.EnsureIntVariable("BloodyFlailSoldierPlayV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

