        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 2,
            ignoreOwner: false);
        NodeEndpoints soldier = editor.AddFilterCardCategory(67_108_864UL, 0, 0);
        NodeEndpoints provisionFour = editor.AddFilterCardProvision(compareOp: 0, provision: 4);
