        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(
            min: 1,
            max: 1,
            aiHintE0: 0,
            choiceType: 0,
            revealChoices: true);
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(soldier.Out, soldierAndProvision.Input0);
        editor.AddConnection(provisionFour.Out, soldierAndProvision.Input1);
        editor.AddConnection(ownerPlayer, deck.PlayerId);
        editor.AddConnection(deployFlow, eligible.FlowIn);
