    private static void AddVandergriftsBladeAdjacentCursedDamage(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "VandergriftsBladeAdjacentCursedV1", StringComparison.Ordinal)))
        {
            return;
        }

        XElement damageNode = ability.Element("Nodes")!.Elements().Single(node =>
            IsNodeType(node, "ChangePowerNode") &&
            string.Equals((string?)node.Element("Operation")?.Attribute("V"), "1", StringComparison.Ordinal));
        XElement targetNode = ability.Element("Nodes")!.Elements().Single(node => IsNodeType(node, "RequestCardTargetsNode"));
        int targetSuccess = Id(targetNode.Element("FlowOutSuccess")!);
        int damageFlow = Id(damageNode.Element("FlowIn")!);
        int damagePower = Id(damageNode.Element("Power")!);
        XElement damageVariable = ability.Element("TemporaryVariables")!.Elements().Single(variable =>
            string.Equals((string?)variable.Attribute("Name"), "Damage", StringComparison.Ordinal));
        int damageVariableId = (int)damageVariable.Attribute("Id")!;

        var editor = new GraphEditor(ability);
        editor.RemoveConnection(targetSuccess, damageFlow);
        editor.RemoveIncomingConnections(damagePower);
        int marker = editor.EnsureIntVariable("VandergriftsBladeAdjacentCursedV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        CardPositionEndpoints ownerPosition = editor.AddGetCardPosition(positionType: 0);
        ShapeEndpoints adjacent = editor.AddGetCardsInShape();
        NodeEndpoints cursed = editor.AddFilterCardCategory(33_554_432UL, 0, 0);
        FilterListEndpoints adjacentCursed = editor.AddFilterCardList();
        CardListLengthEndpoints count = editor.AddCardListLength();
        int baseDamage = editor.AddGetIntVariable(damageVariableId);
        IntPlusEndpoints totalDamage = editor.AddIntPlus();

        editor.AddConnection(ownerCard, ownerPosition.Card);
        editor.AddConnection(ownerPosition.Position, adjacent.Position);
        editor.AddConnection(targetSuccess, adjacentCursed.FlowIn);
        editor.AddConnection(adjacent.Cards, adjacentCursed.Cards);
        editor.AddConnection(cursed.Out, adjacentCursed.Filter);
        editor.AddConnection(adjacentCursed.Success, damageFlow);
        editor.AddConnection(adjacentCursed.Fail, damageFlow);
        editor.AddConnection(adjacentCursed.FilteredCards, count.List);
        editor.AddConnection(baseDamage, totalDamage.A);
        editor.AddConnection(count.Length, totalDamage.B);
        editor.AddConnection(totalDamage.Result, damagePower);
        editor.Finish();
    }

    private static GraceEndpoints AddGraceMechanic(
        XElement ability,
        GraphEditor editor,
        int graceVariable)
    {
        AfterMovedEndpoints enteredBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 1,
            triggerPlayer: 3,
            fromLocation: 379,
            toLocation: 3,
            reason: 3);
        AfterChangePowerEndpoints powerChanged = editor.AddAfterChangePowerTrigger(
            ownerLocation: 3,
            targetCard: 1,
            powerOp: 5);
        ChangedStatusEndpoints statusChanged = editor.AddAfterChangedCardStatusTrigger(
            ownerLocation: 3,
            targetCard: 1,
            operationValue: 1,
            statusMask: 4);
        GraceEndpoints grace = editor.AddGraceSubAbility();
        int threshold = editor.AddGetIntVariable(graceVariable);

        editor.AddConnection(enteredBoard.FlowOut, grace.FlowIn);
        editor.AddConnection(powerChanged.FlowOut, grace.FlowIn);
        editor.AddConnection(statusChanged.FlowOut, grace.FlowIn);
        editor.AddConnection(threshold, grace.Power);
        return grace;
    }

