    private static void ReplaceSabrinasInfernoSpecterImmunityWithCursed(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "SabrinasInfernoCursedImmunityV1", StringComparison.Ordinal)))
        {
            return;
        }

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("SabrinasInfernoCursedImmunityV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        List<XElement> exclusions = ability.Element("Nodes")!.Elements()
            .Where(node => IsNodeType(node, "FilterCardCategoryNode") &&
                           string.Equals((string?)node.Element("Negate")?.Attribute("V"), "True", StringComparison.Ordinal) &&
                           string.Equals((string?)node.Element("CardCategory")?.Element("V")?.Element("e0")?.Attribute("V"),
                               "16777216", StringComparison.Ordinal))
            .ToList();
        if (exclusions.Count != 2)
        {
            throw new InvalidOperationException(
                $"Sabrina's Inferno expected two Specter exclusions, found {exclusions.Count}.");
        }
        foreach (XElement exclusion in exclusions)
        {
            exclusion.Element("CardCategory")!.Element("V")!.Element("e0")!
                .SetAttributeValue("V", "33554432");
        }
        editor.Finish();
    }

