    private static void AddFrancescaLastBronzeElfDeploy(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e => (string?)e.Attribute("Name") == "FrancescaLastBronzeElfDeployV2"))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("FrancescaLastBronzeElfDeployV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int lastBronzeElf = editor.EnsurePersistentCardDefinitionListVariable("FrancescaLastBronzeElf");

        // Track the definition at the moment a bronze Elf is played. This is independent
        // from the global blackboard layout and remains available while Francesca is in deck/hand.
        AfterMovedEndpoints played = editor.AddAfterMovedTrigger(
            ownerLocation: 379, triggerCard: 2, triggerPlayer: 3,
            fromLocation: 4095, toLocation: 3, reason: 1);
        NodeEndpoints unit = editor.AddFilterCardType(4);
        NodeEndpoints bronze = editor.AddFilterCardTier(2);
        NodeEndpoints elf = editor.AddFilterCardCategory(549_755_813_888UL, 0, 0);
        int bronzeUnit = CombineCardFiltersAnd(editor, unit.Out, bronze.Out);
        int bronzeElf = CombineCardFiltersAnd(editor, bronzeUnit, elf.Out);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardElementEndpoints first = editor.AddCardListGetElement(0);
        CardDefinitionEndpoints definition = editor.AddGetCardDefinition();
        DefinitionElementToListEndpoints oneDefinition = editor.AddCardDefinitionElementToList();
        SetVarEndpoints remember = editor.AddSetCardDefinitionListVariable(lastBronzeElf);
        editor.AddConnection(played.FlowOut, eligible.FlowIn);
        editor.AddConnection(played.CardsMoved, eligible.Cards);
        editor.AddConnection(bronzeElf, eligible.Filter);
        editor.AddConnection(eligible.FilteredCards, first.List);
        editor.AddConnection(first.Card, definition.Card);
        editor.AddConnection(definition.Definition, oneDefinition.Element);
        editor.AddConnection(eligible.Success, remember.FlowIn);
        editor.AddConnection(oneDefinition.List, remember.In);

        // Deploy creates and immediately plays the most recently remembered bronze Elf.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int remembered = editor.AddGetCardDefinitionListVariable(lastBronzeElf);
        CardDefinitionListLengthEndpoints length = editor.AddCardDefinitionListLength();
        IntBranchEndpoints available = editor.AddIntBranch();
        CreatePlayEndpoints createPlay = editor.AddCreateAndPlaySubAbility();
        editor.AddConnection(remembered, length.List);
        editor.AddConnection(deploy.FlowOut, available.FlowIn);
        editor.AddConnection(length.Length, available.A);
        editor.AddConnection(available.Bigger, createPlay.FlowIn);
        editor.AddConnection(remembered, createPlay.Definitions);
        editor.Finish();
    }

