    private static void RebuildIorvethsGambitTrap(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "Type", "8");
        SetTemplateText(template, "Tokens", "8");
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "0");
        SetTemplateText(template, "TapActive", "False");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");
        XElement placement = template.Element("Placement")!;
        placement.SetAttributeValue("PlayerSide", "3");
        placement.SetAttributeValue("OpponentSide", "0");
        XElement primary = template.Element("PrimaryCategory")!;
        primary.Element("e0")!.SetAttributeValue("V", "70368744177664");
        primary.Element("e1")!.SetAttributeValue("V", "0");
        primary.Element("e2")!.SetAttributeValue("V", "0");
        XElement? kind = template.Element("Kind");
        if (kind == null)
            template.Element("Rarity")!.AddAfterSelf(new XElement("Kind", "1"));
        else
            kind.Value = "1";

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("IorvethsGambitTrapV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        // Spring: reveal and deal 4 to a chosen enemy unit.
        TriggerEndpoints spring = editor.AddAmbushRevealedTrigger();
        TokenEndpoints revealSpring = editor.AddChangeTokens(token: 8, operation: 1, elementType: 1, attackMethod: 0);
        GetCardsEndpoints enemies = editor.AddGetCards();
        TargetRequestEndpoints springTarget = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        PowerEndpoints springDamage = editor.AddChangePower(4, 1, 16, 1);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(spring.FlowOut, revealSpring.FlowIn);
        editor.AddConnection(ownerEntity, revealSpring.Attacker);
        editor.AddConnection(ownerCards, revealSpring.Targets);
        editor.AddConnection(revealSpring.FlowOut, springTarget.FlowIn);
        editor.AddConnection(enemies.Out, springTarget.ValidTargets);
        editor.AddConnection(springTarget.Success, springDamage.FlowIn);
        editor.AddConnection(ownerEntity, springDamage.Attacker);
        editor.AddConnection(springTarget.SelectedTargets, springDamage.Targets);

        // Ambush: opponent plays a unit; reveal, damage a random enemy and summon a face-down bronze Trap.
        AfterMovedEndpoints opponentPlayed = editor.AddAfterMovedTrigger(
            ownerLocation: 3, triggerCard: 2, triggerPlayer: 2,
            fromLocation: 4095, toLocation: 3, reason: 1,
            priorityValue: 0, isAmbushing: true);
        editor.AddConnection(opponent, opponentPlayed.ToPlayer);
        NodeEndpoints unit = editor.AddFilterCardType(4);
        FilterListEndpoints playedUnit = editor.AddFilterCardList();
        TokenEndpoints revealAmbush = editor.AddChangeTokens(token: 8, operation: 1, elementType: 1, attackMethod: 0);
        GetCardsEndpoints randomEnemies = editor.AddGetCards();
        RandomCardEndpoints randomEnemy = editor.AddRandomCard();
        ElementListEndpoints randomEnemyList = editor.AddCardElementToList();
        PowerEndpoints ambushDamage = editor.AddChangePower(3, 1, 16, 1);
        editor.AddConnection(opponentPlayed.FlowOut, playedUnit.FlowIn);
        editor.AddConnection(opponentPlayed.CardsMoved, playedUnit.Cards);
        editor.AddConnection(unit.Out, playedUnit.Filter);
        editor.AddConnection(playedUnit.Success, revealAmbush.FlowIn);
        editor.AddConnection(ownerEntity, revealAmbush.Attacker);
        editor.AddConnection(ownerCards, revealAmbush.Targets);
        editor.AddConnection(opponent, randomEnemies.PlayerId);
        editor.AddConnection(revealAmbush.FlowOut, randomEnemy.FlowIn);
        editor.AddConnection(randomEnemies.Out, randomEnemy.List);
        editor.AddConnection(randomEnemy.Card, randomEnemyList.Card);
        editor.AddConnection(randomEnemy.FlowOut, ambushDamage.FlowIn);
        editor.AddConnection(ownerEntity, ambushDamage.Attacker);
        editor.AddConnection(randomEnemyList.List, ambushDamage.Targets);

        GetCardsEndpoints deckTraps = editor.AddGetCards(ignoreTokens: 0, locationId: 16, cardTypes: 8, cardTiers: 2, ignoreOwner: false);
        NodeEndpoints trapCategory = editor.AddFilterCardCategory(70_368_744_177_664UL, 0, 0);
        FilterListEndpoints eligibleDeckTraps = editor.AddFilterCardList();
        RandomCardEndpoints randomTrap = editor.AddRandomCard();
        ElementListEndpoints randomTrapList = editor.AddCardElementToList();
        TokenEndpoints hideTrap = editor.AddChangeTokens(token: 8, operation: 0, elementType: 1, attackMethod: 0);
        CardLocationEndpoints currentRow = editor.AddGetCardLocationId(positionType: 0);
        PositionEndpoints trapPosition = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summonTrap = editor.AddMoveCards();
        editor.AddConnection(owner, deckTraps.PlayerId);
        editor.AddConnection(ambushDamage.FlowOut, eligibleDeckTraps.FlowIn);
        editor.AddConnection(deckTraps.Out, eligibleDeckTraps.Cards);
        editor.AddConnection(trapCategory.Out, eligibleDeckTraps.Filter);
        editor.AddConnection(eligibleDeckTraps.Success, randomTrap.FlowIn);
        editor.AddConnection(eligibleDeckTraps.FilteredCards, randomTrap.List);
        editor.AddConnection(randomTrap.Card, randomTrapList.Card);
        editor.AddConnection(randomTrap.FlowOut, hideTrap.FlowIn);
        editor.AddConnection(ownerEntity, hideTrap.Attacker);
        editor.AddConnection(randomTrapList.List, hideTrap.Targets);
        editor.AddConnection(ownerCard, currentRow.Card);
        editor.AddConnection(owner, trapPosition.PlayerId);
        editor.AddConnection(currentRow.Location, trapPosition.Location);
        editor.AddConnection(hideTrap.FlowOut, summonTrap.FlowIn);
        editor.AddConnection(randomTrapList.List, summonTrap.Cards);
        editor.AddConnection(trapPosition.Position, summonTrap.Position);

        // At the end of the owner's turn, turn face-down and transform into a random other Trap from deck.
        TurnTriggerEndpoints endTurn = editor.AddAfterTurnTrigger(ownerLocation: 3, priorityValue: 0, isAmbushing: false);
        editor.AddConnection(owner, endTurn.PlayerFilter);
        GetCardsEndpoints transformCandidates = editor.AddGetCards(ignoreTokens: 0, locationId: 16, cardTypes: 8, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints transformTrapCategory = editor.AddFilterCardCategory(70_368_744_177_664UL, 0, 0);
        NodeEndpoints notSelf = editor.AddFilterCardTemplateId(IorvethsGambit, negate: true);
        int otherTrap = CombineCardFiltersAnd(editor, transformTrapCategory.Out, notSelf.Out);
        FilterListEndpoints eligibleTransforms = editor.AddFilterCardList();
        RandomCardEndpoints randomTransform = editor.AddRandomCard();
        CardDefinitionEndpoints transformDefinition = editor.AddGetCardDefinition();
        TransformEndpoints transform = editor.AddTransformCards(resetMode: -1);
        TokenEndpoints hideOwner = editor.AddChangeTokens(token: 8, operation: 0, elementType: 1, attackMethod: 0);
        editor.AddConnection(owner, transformCandidates.PlayerId);
        editor.AddConnection(endTurn.FlowOut, eligibleTransforms.FlowIn);
        editor.AddConnection(transformCandidates.Out, eligibleTransforms.Cards);
        editor.AddConnection(otherTrap, eligibleTransforms.Filter);
        editor.AddConnection(eligibleTransforms.Success, randomTransform.FlowIn);
        editor.AddConnection(eligibleTransforms.FilteredCards, randomTransform.List);
        editor.AddConnection(randomTransform.Card, transformDefinition.Card);
        editor.AddConnection(randomTransform.FlowOut, hideOwner.FlowIn);
        editor.AddConnection(ownerEntity, hideOwner.Attacker);
        editor.AddConnection(ownerCards, hideOwner.Targets);
