    private static void RebuildDolBlathannaBowmanRows(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e => (string?)e.Attribute("Name") == "DolBlathannaBowmanRowsV1"))
            return;
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("DolBlathannaBowmanRowsV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        foreach (XElement damage in ability.Element("Nodes")!.Elements()
                     .Where(n => (string?)n.Attribute("Type") == "ChangePowerNode" &&
                                 (string?)n.Element("Operation")?.Attribute("V") == "1"))
        {
            XElement power = damage.Element("Power")!;
            int current = int.Parse((string?)power.Attribute("V") ?? "0");
            power.SetAttributeValue("V", current * 2);
        }

        XElement played = ability.Element("Nodes")!.Elements().Single(n => (string?)n.Attribute("Type") == "PlayedTrigger");
        int playedFlow = Id(played.Element("FlowOut")!);
        XElement targetRequest = ability.Element("Nodes")!.Elements().Single(n => (string?)n.Attribute("Type") == "RequestCardTargetsNode");
        int targetFlow = Id(targetRequest.Element("FlowIn")!);
        editor.TryRemoveConnection(playedFlow, targetFlow);
        OwnerLocationBranchEndpoints rows = editor.AddOwnerLocationBranch();
        editor.AddConnection(playedFlow, rows.FlowIn);
        editor.AddConnection(rows.Melee, targetFlow);

        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints hand = editor.AddGetCards(ignoreTokens: 0, locationId: 8, cardTypes: 2, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints waylay = editor.AddFilterCardTemplateId(Waylay);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0, revealChoices: true);
        PlayEndpoints play = editor.AddPlayCards();
        DrawEndpoints draw = editor.AddDrawCards(1);
        editor.AddConnection(owner, hand.PlayerId);
        editor.AddConnection(rows.Ranged, eligible.FlowIn);
        editor.AddConnection(hand.Out, eligible.Cards);
        editor.AddConnection(waylay.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, choice.FlowIn);
        editor.AddConnection(eligible.FilteredCards, choice.ValidChoices);
        editor.AddConnection(choice.Success, play.FlowIn);
        editor.AddConnection(choice.SelectedChoices, play.Cards);
        editor.AddConnection(play.FlowOut, draw.FlowIn);
        editor.AddConnection(owner, draw.PlayerId);
        editor.Finish();
    }

    private static void AddGrovekeeperActivateVitalityOrder(XElement ability, XElement template)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e => (string?)e.Attribute("Name") == "GrovekeeperActivateVitalityV1"))
            return;
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("GrovekeeperActivateVitalityV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        TriggerEndpoints order = editor.AddTappedTrigger();
        GetCardsEndpoints friendly = editor.AddGetCards(ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints vitality = editor.AddFilterCardTokens(32);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 0);
        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(order.FlowOut, eligible.FlowIn);
        editor.AddConnection(friendly.Out, eligible.Cards);
        editor.AddConnection(vitality.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, target.FlowIn);
        editor.AddConnection(eligible.FilteredCards, target.ValidTargets);

        int nextFlow = target.Success;
        for (int i = 0; i < 3; i++)
        {
            NodeEndpoints stillVital = editor.AddFilterCardTokens(32);
            FilterListEndpoints active = editor.AddFilterCardList();
            PowerEndpoints boost = editor.AddChangePower(1, 0, 2048, 1);
            StatusTimerEndpoints consumeTick = editor.AddActivateVitality(duration: 1);
            editor.AddConnection(nextFlow, active.FlowIn);
            editor.AddConnection(target.SelectedTargets, active.Cards);
            editor.AddConnection(stillVital.Out, active.Filter);
            editor.AddConnection(active.Success, boost.FlowIn);
            editor.AddConnection(ownerEntity, boost.Attacker);
            editor.AddConnection(active.FilteredCards, boost.Targets);
            editor.AddConnection(boost.FlowOut, consumeTick.FlowIn);
            editor.AddConnection(ownerEntity, consumeTick.Attacker);
            editor.AddConnection(active.FilteredCards, consumeTick.Cards);
            nextFlow = consumeTick.FlowOut;
        }
        editor.Finish();
    }

