    private static int AddOwnerAppliedStatusGate(
        GraphEditor editor,
        ChangedStatusEndpoints statusChanged,
        int ownerPlayer)
    {
        AttackEntityEndpoints attacker = editor.AddAttackGetAttacker();
        EntityPlayerEndpoints attackerPlayer = editor.AddGetEntityPlayerId();
        PlayerIdCompareEndpoints isOwner = editor.AddPlayerIdCompare(compareOp: 0);
        BranchEndpoints gate = editor.AddBranch();

        editor.AddConnection(statusChanged.CardStatusAttack, attacker.Attack);
        editor.AddConnection(attacker.Entity, attackerPlayer.Entity);
        editor.AddConnection(ownerPlayer, isOwner.A);
        editor.AddConnection(attackerPlayer.PlayerId, isOwner.B);
        editor.AddConnection(isOwner.Result, gate.Condition);
        editor.AddConnection(statusChanged.FlowOut, gate.FlowIn);
        return gate.True;
    }

    private static void RebuildImperaBrigadeSpyOrder(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("ImperaBrigadeSpyOrderV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Boost", 1);

        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        // Deploy: boost by the number of enemy Spying units.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        GetCardsEndpoints enemies = editor.AddGetCards();
        NodeEndpoints spying = editor.AddFilterCardTokens(token: 128);
        FilterListEndpoints enemySpies = editor.AddFilterCardList();
        CardListLengthEndpoints spyCount = editor.AddCardListLength();
        PowerEndpoints deployBoost = editor.AddChangePower(0, 0, 512, 0);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(deploy.FlowOut, enemySpies.FlowIn);
        editor.AddConnection(enemies.Out, enemySpies.Cards);
        editor.AddConnection(spying.Out, enemySpies.Filter);
        editor.AddConnection(enemySpies.FilteredCards, spyCount.List);
        editor.AddConnection(enemySpies.Success, deployBoost.FlowIn);
        editor.AddConnection(enemySpies.Fail, deployBoost.FlowIn);
        editor.AddConnection(ownerEntity, deployBoost.Attacker);
        editor.AddConnection(ownerCards, deployBoost.Targets);
        editor.AddConnection(spyCount.Length, deployBoost.Power);

        // Order: damage an enemy Spying unit by the current amount boosted.
        TriggerEndpoints order = editor.AddTappedTrigger();
        FilterListEndpoints orderSpies = editor.AddFilterCardList();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        CardPowerEndpoints currentPower = editor.AddGetCardPower(powerType: 0);
        CardPowerEndpoints initialPower = editor.AddGetCardPower(powerType: 1);
        IntMinusEndpoints boostedBy = editor.AddIntMinus();
        IntMaxEndpoints nonNegativeBoost = editor.AddIntMax(constantB: 0);
        PowerEndpoints orderDamage = editor.AddChangePower(0, 1, 1, 1);
        editor.AddConnection(order.FlowOut, orderSpies.FlowIn);
        editor.AddConnection(enemies.Out, orderSpies.Cards);
        editor.AddConnection(spying.Out, orderSpies.Filter);
        editor.AddConnection(orderSpies.Success, target.FlowIn);
        editor.AddConnection(orderSpies.FilteredCards, target.ValidTargets);
        editor.AddConnection(ownerCard, currentPower.Card);
        editor.AddConnection(ownerCard, initialPower.Card);
        editor.AddConnection(currentPower.Power, boostedBy.A);
        editor.AddConnection(initialPower.Power, boostedBy.B);
        editor.AddConnection(boostedBy.Result, nonNegativeBoost.A);
        editor.AddConnection(target.Success, orderDamage.FlowIn);
        editor.AddConnection(ownerEntity, orderDamage.Attacker);
        editor.AddConnection(target.SelectedTargets, orderDamage.Targets);
        editor.AddConnection(nonNegativeBoost.Result, orderDamage.Power);

        // Whenever an enemy unit gains Spying, boost by the number of affected units.
        ChangedStatusEndpoints gainedSpying = editor.AddAfterChangedCardStatusTrigger(
            ownerLocation: 3,
            targetCard: 2,
            operationValue: 0,
            statusMask: 128);
        CardAttackTargetsEndpoints spyingTargets = editor.AddCardAttackGetTargets();
        CardListLengthEndpoints gainedCount = editor.AddCardListLength();
        IntBranchEndpoints anyGained = editor.AddIntBranch();
        PowerEndpoints passiveBoost = editor.AddChangePower(0, 0, 512, 0);
        editor.AddConnection(opponent, gainedSpying.PlayerMask);
        editor.AddConnection(gainedSpying.CardStatusAttack, spyingTargets.Attack);
        editor.AddConnection(spyingTargets.Targets, gainedCount.List);
        editor.AddConnection(gainedSpying.FlowOut, anyGained.FlowIn);
        editor.AddConnection(gainedCount.Length, anyGained.A);
        editor.AddConnection(anyGained.Bigger, passiveBoost.FlowIn);
        editor.AddConnection(ownerEntity, passiveBoost.Attacker);
        editor.AddConnection(ownerCards, passiveBoost.Targets);
        editor.AddConnection(gainedCount.Length, passiveBoost.Power);
        editor.Finish();
    }

    private static void InstallDucalGuardAssimilationImmediateSummon(AbilityDocument abilities)
    {
        XElement assimilateSubAbility = abilities.Document.Root?.Elements("Ability")
            .SingleOrDefault(element =>
                string.Equals((string?)element.Attribute("Type"), "SubAbility", StringComparison.Ordinal) &&
                (int?)element.Attribute("AbilityID") == 8)
            ?? throw new InvalidOperationException("SubAbility 8 (Assimilate) не найдена.");

        EnsureAbilityContainers(assimilateSubAbility);
        if (assimilateSubAbility.Descendants().Any(element =>
                string.Equals((string?)element.Attribute("Name"),
                    "DucalGuardAssimilationImmediateSummonV9", StringComparison.Ordinal)))
        {
            return;
        }

        var editor = new GraphEditor(assimilateSubAbility);
        int marker = editor.EnsureIntVariable("DucalGuardAssimilationImmediateSummonV9", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement boostNode = assimilateSubAbility.Element("Nodes")!.Elements()
            .Single(node =>
                IsNodeType(node, "ChangePowerNode") &&
                string.Equals((string?)node.Element("Operation")?.Attribute("V"), "0", StringComparison.Ordinal));
        XElement emitNode = assimilateSubAbility.Element("Nodes")!.Elements()
            .Single(node =>
                IsNodeType(node, "EmitMessageNode") &&
                string.Equals((string?)node.Element("Message")?.Attribute("V"), "assimilate",
                    StringComparison.Ordinal));

        int boostFlowOut = Id(boostNode.Element("FlowOut")!);
        int emitFlowIn = Id(emitNode.Element("FlowIn")!);

        // Restore a single controlled continuation even when this operation is
        // applied over a previously generated V8 graph.  Detached legacy nodes
        // are harmless and no longer participate in runtime flow.
        foreach (int target in editor.GetOutgoingTargets(boostFlowOut))
        {
            editor.RemoveConnection(boostFlowOut, target);
        }
        editor.RemoveIncomingConnections(emitFlowIn);

        int owner = editor.AddGetOwnerPlayerId();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        // SubAbility 8 is invoked separately by every Assimilate card.  Therefore
        // its ability owner is the exact card whose Assimilate has just resolved.
        NodeEndpoints ownerIsGuard = editor.AddFilterCardTemplateId(DucalGuard);
        FilterListEndpoints currentGuard = editor.AddFilterCardList();
        editor.AddConnection(boostFlowOut, currentGuard.FlowIn);
        editor.AddConnection(ownerCards, currentGuard.Cards);
        editor.AddConnection(ownerIsGuard.Out, currentGuard.Filter);
        editor.AddConnection(currentGuard.Fail, emitFlowIn);

        // If this was Ducal Guard's own Assimilate, immediately summon one copy
        // from the owner's deck to a random available friendly row.
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints sameCard = editor.AddFilterCardTemplateId(DucalGuard);
        FilterListEndpoints deckCopies = editor.AddFilterCardList();
        RandomCardEndpoints randomCopy = editor.AddRandomCard();
        ElementListEndpoints oneCopy = editor.AddCardElementToList();
        PositionEndpoints randomRow = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summon = editor.AddMoveCards();

        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(currentGuard.Success, deckCopies.FlowIn);
        editor.AddConnection(deck.Out, deckCopies.Cards);
        editor.AddConnection(sameCard.Out, deckCopies.Filter);
        editor.AddConnection(deckCopies.Fail, emitFlowIn);
        editor.AddConnection(deckCopies.Success, randomCopy.FlowIn);
        editor.AddConnection(deckCopies.FilteredCards, randomCopy.List);
        editor.AddConnection(randomCopy.Card, oneCopy.Card);
        editor.AddConnection(owner, randomRow.PlayerId);
        editor.AddConnection(randomCopy.FlowOut, summon.FlowIn);
        editor.AddConnection(oneCopy.List, summon.Cards);
        editor.AddConnection(randomRow.Position, summon.Position);
        editor.AddConnection(summon.FlowOut, emitFlowIn);
        editor.Finish();
    }

    private static void RebuildDucalGuardAssimilationSummon(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
