    private static void EnsureCahirStartingDeckCeallachVeil(XElement cahirAbility)
    {
        EnsureAbilityContainers(cahirAbility);
        if (cahirAbility.Descendants().Any(e =>
                (string?)e.Attribute("Name") == "CahirStartingDeckCeallachVeilV3"))
            return;

        var editor = new GraphEditor(cahirAbility);
        int marker = editor.EnsureIntVariable("CahirStartingDeckCeallachVeilV3", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int condition = editor.EnsurePersistentIntVariable("CeallachWasInInitialDeck", 0);
        editor.PersistentVariables.Elements().Single(v => (int?)v.Attribute("Id") == condition)
            .SetAttributeValue("HideInTooltip", "True");

        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        // At game initialization every original deck card is in hand or deck.
        // Querying those live card entities avoids the server crash caused by
        // injecting GetInitialDeckDefinitions into Cahir/Ceallach abilities.
        TriggerEndpoints gameStart = editor.AddAfterGameInitializedTrigger(ownerLocation: 379);
        GetCardsEndpoints handAndDeck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 24,
            cardTypes: 30,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints ceallach = editor.AddFilterCardTemplateId(CeallachDyffryn);
        FilterListEndpoints deckHasCeallach = editor.AddFilterCardList();
        SetVarEndpoints rememberCondition = editor.AddSetIntVariable(condition);
        SetEndpointValue(cahirAbility, rememberCondition.In, "1");
        editor.AddConnection(owner, handAndDeck.PlayerId);
        editor.AddConnection(gameStart.FlowOut, deckHasCeallach.FlowIn);
        editor.AddConnection(handAndDeck.Out, deckHasCeallach.Cards);
        editor.AddConnection(ceallach.Out, deckHasCeallach.Filter);
        editor.AddConnection(deckHasCeallach.Success, rememberCondition.FlowIn);

        // Apply Veil only after Cahir has safely entered the battlefield.
        AfterMovedEndpoints entersBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 1,
            triggerPlayer: 1,
            fromLocation: 4095,
            toLocation: 3,
            reason: 1);
        int remembered = editor.AddGetIntVariable(condition);
        IntBranchEndpoints enabled = editor.AddIntBranch();
        TokenEndpoints veil = editor.AddChangeTokens(
            token: 8192,
            elementType: 1,
            attackMethod: 0);
        editor.AddConnection(entersBoard.FlowOut, enabled.FlowIn);
        editor.AddConnection(remembered, enabled.A);
        editor.AddConnection(enabled.Bigger, veil.FlowIn);
        editor.AddConnection(ownerEntity, veil.Attacker);
        editor.AddConnection(ownerCards, veil.Targets);
        editor.Finish();
    }

