    private static void AddVreemdeSoldierDuelOrder(XElement ability, XElement template)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e => (string?)e.Attribute("Name") == "VreemdeSoldierDuelOrderV1"))
            return;

        SetTemplateText(template, "InitialTimer", "-1");
