        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        TriggerEndpoints order = editor.AddTappedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();

        GetCardsEndpoints friendly = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 2, ignoreOwner: false);
        NodeEndpoints soldier = editor.AddFilterCardCategory(67_108_864UL, 0, 0);
        FilterListEndpoints eligibleSoldiers = editor.AddFilterCardList();
        TargetRequestEndpoints soldierChoice = editor.AddRequestCardTargets(1, 1, 0);

        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        RandomCardEndpoints randomEnemy = editor.AddRandomCard();
        ElementListEndpoints enemyList = editor.AddCardElementToList();
        DuelEndpoints duel = editor.AddDuelSubAbility();

        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, eligibleSoldiers.FlowIn);
        editor.AddConnection(friendly.Out, eligibleSoldiers.Cards);
        editor.AddConnection(soldier.Out, eligibleSoldiers.Filter);
        editor.AddConnection(eligibleSoldiers.Success, soldierChoice.FlowIn);
        editor.AddConnection(eligibleSoldiers.FilteredCards, soldierChoice.ValidTargets);
        editor.AddConnection(soldierChoice.Success, randomEnemy.FlowIn);
        editor.AddConnection(enemies.Out, randomEnemy.List);
        editor.AddConnection(randomEnemy.Card, enemyList.Card);
        editor.AddConnection(randomEnemy.FlowOut, duel.FlowIn);
        editor.AddConnection(enemyList.List, duel.Targets);
        editor.AddConnection(soldierChoice.SelectedTargets, duel.Duelist);

        // Keep the Order disabled when either side lacks a legal participant.
        TriggerEndpoints refresh = editor.AddRefreshTargetsTrigger(0);
        FilterListEndpoints refreshSoldiers = editor.AddFilterCardList();
        CardListBranchEndpoints enemyAvailable = editor.AddCardListBranch();
        ChangeTapActiveEndpoints enable = editor.AddChangeOwnerTapActive(true);
        ChangeTapActiveEndpoints disable = editor.AddChangeOwnerTapActive(false);
        editor.AddConnection(refresh.FlowOut, refreshSoldiers.FlowIn);
        editor.AddConnection(friendly.Out, refreshSoldiers.Cards);
        editor.AddConnection(soldier.Out, refreshSoldiers.Filter);
        editor.AddConnection(refreshSoldiers.Success, enemyAvailable.FlowIn);
        editor.AddConnection(enemies.Out, enemyAvailable.List);
        editor.AddConnection(enemyAvailable.True, enable.FlowIn);
        editor.AddConnection(enemyAvailable.False, disable.FlowIn);
        editor.AddConnection(refreshSoldiers.Fail, disable.FlowIn);
        editor.Finish();
    }

