        FilterListEndpoints ownerCreatedCards = editor.AddFilterCardList();
        CardListLengthEndpoints ownerCount = editor.AddCardListLength();

        GetCardsEndpoints friendly = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 0);
        PowerEndpoints boostTarget = editor.AddChangePower(
            amount: 0, operation: 0, elementType: 512, attackMethod: 0);
        PowerEndpoints boostSelf = editor.AddChangePower(
            amount: 0, operation: 0, elementType: 512, attackMethod: 0);

        editor.AddConnection(opponent, opponentDeck.PlayerId);
        editor.AddConnection(opponent, opponentCreated.PowerInput);
        editor.AddConnection(deploy.FlowOut, opponentCreatedCards.FlowIn);
        editor.AddConnection(opponentDeck.Out, opponentCreatedCards.Cards);
        editor.AddConnection(opponentCreated.Out, opponentCreatedCards.Filter);
        editor.AddConnection(opponentCreatedCards.FilteredCards, opponentCount.List);

        editor.AddConnection(owner, ownerDeck.PlayerId);
        editor.AddConnection(owner, ownerCreated.PowerInput);
        editor.AddConnection(opponentCreatedCards.Success, ownerCreatedCards.FlowIn);
        editor.AddConnection(opponentCreatedCards.Fail, ownerCreatedCards.FlowIn);
        editor.AddConnection(ownerDeck.Out, ownerCreatedCards.Cards);
        editor.AddConnection(ownerCreated.Out, ownerCreatedCards.Filter);
        editor.AddConnection(ownerCreatedCards.FilteredCards, ownerCount.List);

        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(ownerCreatedCards.Success, target.FlowIn);
        editor.AddConnection(ownerCreatedCards.Fail, target.FlowIn);
        editor.AddConnection(friendly.Out, target.ValidTargets);
        editor.AddConnection(target.Success, boostTarget.FlowIn);
        editor.AddConnection(target.SelectedTargets, boostTarget.Targets);
        editor.AddConnection(ownerEntity, boostTarget.Attacker);
        editor.AddConnection(opponentCount.Length, boostTarget.Power);
        editor.AddConnection(boostTarget.FlowOut, boostSelf.FlowIn);
        editor.AddConnection(ownerCards, boostSelf.Targets);
        editor.AddConnection(ownerEntity, boostSelf.Attacker);
        editor.AddConnection(ownerCount.Length, boostSelf.Power);
        editor.Finish();
    }

    private static void RebuildBattleStationsMachineSoldierPlay(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("BattleStationsTokenFirstV6", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints played = editor.AddPlayedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        // V6 reverses the sequence completely.  SubAbility 44 first shows one
        // native create choice between Imperial Marine and Imperial Fleet and
        // immediately plays the selected token.  Its PlayedCard output is then
        // used to decide which bronze deck card may be played next.
        int tokenChoicesVar = editor.AddCardDefinitionListVariable(
            "BattleStationsTokenChoices", ImperialMarine, ImperialFleet);
        int tokenChoices = editor.AddGetCardDefinitionListVariable(tokenChoicesVar);
        CreatePlayEndpoints createToken = editor.AddCreateAndPlaySubAbility();
        editor.AddConnection(played.FlowOut, createToken.FlowIn);
        editor.AddConnection(tokenChoices, createToken.Definitions);

        NodeEndpoints imperialMarine = editor.AddFilterCardTemplateId(ImperialMarine);
        FilterListEndpoints createdMarine = editor.AddFilterCardList();
        editor.AddConnection(createToken.FlowOut, createdMarine.FlowIn);
        editor.AddConnection(createToken.PlayedCards, createdMarine.Cards);
        editor.AddConnection(imperialMarine.Out, createdMarine.Filter);

        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0, locationId: 16, cardTypes: 4, cardTiers: 2, ignoreOwner: false);
        editor.AddConnection(owner, deck.PlayerId);

        // Imperial Marine -> play a bronze Machine.
        NodeEndpoints machine = editor.AddFilterCardCategory(2_199_023_255_552UL, 0, 0);
        FilterListEndpoints machines = editor.AddFilterCardList();
        CardChoiceEndpoints machineChoice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0);
        PlayEndpoints playMachine = editor.AddPlayCards();
        ArmorEndpoints armorMarine = editor.AddChangeArmor(amount: 2, operation: 0);
        ArmorEndpoints armorMachine = editor.AddChangeArmor(amount: 2, operation: 0);

        editor.AddConnection(createdMarine.Success, machines.FlowIn);
        editor.AddConnection(deck.Out, machines.Cards);
        editor.AddConnection(machine.Out, machines.Filter);
        editor.AddConnection(machines.Success, machineChoice.FlowIn);
        editor.AddConnection(machines.FilteredCards, machineChoice.ValidChoices);
        editor.AddConnection(machineChoice.Success, playMachine.FlowIn);
        editor.AddConnection(machineChoice.SelectedChoices, playMachine.Cards);
        editor.AddConnection(playMachine.FlowOut, armorMarine.FlowIn);
        editor.AddConnection(ownerEntity, armorMarine.Attacker);
        editor.AddConnection(createToken.PlayedCards, armorMarine.Targets);
        editor.AddConnection(armorMarine.FlowOut, armorMachine.FlowIn);
        editor.AddConnection(ownerEntity, armorMachine.Attacker);
        editor.AddConnection(machineChoice.SelectedChoices, armorMachine.Targets);

        // Imperial Fleet -> play a bronze Soldier.
        NodeEndpoints soldier = editor.AddFilterCardCategory(67_108_864UL, 0, 0);
        FilterListEndpoints soldiers = editor.AddFilterCardList();
        CardChoiceEndpoints soldierChoice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0);
        PlayEndpoints playSoldier = editor.AddPlayCards();
        ArmorEndpoints armorFleet = editor.AddChangeArmor(amount: 2, operation: 0);
        ArmorEndpoints armorSoldier = editor.AddChangeArmor(amount: 2, operation: 0);

        editor.AddConnection(createdMarine.Fail, soldiers.FlowIn);
        editor.AddConnection(deck.Out, soldiers.Cards);
        editor.AddConnection(soldier.Out, soldiers.Filter);
        editor.AddConnection(soldiers.Success, soldierChoice.FlowIn);
        editor.AddConnection(soldiers.FilteredCards, soldierChoice.ValidChoices);
        editor.AddConnection(soldierChoice.Success, playSoldier.FlowIn);
        editor.AddConnection(soldierChoice.SelectedChoices, playSoldier.Cards);
        editor.AddConnection(playSoldier.FlowOut, armorFleet.FlowIn);
        editor.AddConnection(ownerEntity, armorFleet.Attacker);
        editor.AddConnection(createToken.PlayedCards, armorFleet.Targets);
        editor.AddConnection(armorFleet.FlowOut, armorSoldier.FlowIn);
        editor.AddConnection(ownerEntity, armorSoldier.Attacker);
        editor.AddConnection(soldierChoice.SelectedChoices, armorSoldier.Targets);
        editor.Finish();
    }

    private static void AddCatrionaEpidemicOrder(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e => (string?)e.Attribute("Name") == "CatrionaEpidemicOrderV1"))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("CatrionaEpidemicOrderV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement poison = ability.Element("Nodes")!.Elements().Single(node =>
            string.Equals((string?)node.Attribute("Type"), "ChangeTokensNode", StringComparison.Ordinal) &&
            string.Equals((string?)node.Element("Tokens")?.Attribute("V"), "64", StringComparison.Ordinal));
        int poisonFlowOut = Id(poison.Element("FlowOut")!);

        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        CardPowerEndpoints remainingCharges = editor.AddGetTapCardCharges();
        IntBranchEndpoints atLeastFourBeforeUse = editor.AddIntBranch();
        SetEndpointValue(ability, atLeastFourBeforeUse.B, "3");
        int epidemicDefinitions = editor.AddCardDefinitionListVariable("CatrionaEpidemic", Epidemic);
        int epidemicList = editor.AddGetCardDefinitionListVariable(epidemicDefinitions);
        CreatePlayEndpoints createEpidemic = editor.AddCreateAndPlaySubAbility();

        editor.AddConnection(ownerCard, remainingCharges.Card);
        editor.AddConnection(poisonFlowOut, atLeastFourBeforeUse.FlowIn);
        editor.AddConnection(remainingCharges.Power, atLeastFourBeforeUse.A);
        editor.AddConnection(atLeastFourBeforeUse.Bigger, createEpidemic.FlowIn);
        editor.AddConnection(atLeastFourBeforeUse.Equal, createEpidemic.FlowIn);
        editor.AddConnection(epidemicList, createEpidemic.Definitions);
        editor.Finish();
    }

    private static void RebuildLeoBonhartRows(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("LeoBonhartRowsV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Power", 9);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(deploy.FlowOut, row.FlowIn);

        // Melee: current power 9-or-less target OR any Witcher.
        NodeEndpoints lowPower = editor.AddFilterCardPower(compareOp: 5, power: 10);
        NodeEndpoints witcher = editor.AddFilterCardCategory(2_147_483_648UL, 0, 0);
        int lowPowerOrWitcher = CombineCardFiltersOr(editor, lowPower.Out, witcher.Out);
        FilterListEndpoints meleeEligible = editor.AddFilterCardList();
        TargetRequestEndpoints meleeTarget = editor.AddRequestCardTargets(1, 1, 0);
        DestroyEndpoints meleeDestroy = editor.AddDestroyCards(elementType: 1, attackMethod: 1, removalType: 0);
        editor.AddConnection(row.Melee, meleeEligible.FlowIn);
        editor.AddConnection(enemies.Out, meleeEligible.Cards);
        editor.AddConnection(lowPowerOrWitcher, meleeEligible.Filter);
        editor.AddConnection(meleeEligible.Success, meleeTarget.FlowIn);
        editor.AddConnection(meleeEligible.FilteredCards, meleeTarget.ValidTargets);
        editor.AddConnection(meleeTarget.Success, meleeDestroy.FlowIn);
        editor.AddConnection(ownerEntity, meleeDestroy.Attacker);
        editor.AddConnection(meleeTarget.SelectedTargets, meleeDestroy.Targets);

        // Ranged: Seize a Locked enemy, then destroy the same physical card.
        NodeEndpoints locked = editor.AddFilterCardTokens(4);
        FilterListEndpoints rangedEligible = editor.AddFilterCardList();
        TargetRequestEndpoints rangedTarget = editor.AddRequestCardTargets(1, 1, 0);
        SeizeEndpoints seize = editor.AddSeizeSubAbility();
        DestroyEndpoints rangedDestroy = editor.AddDestroyCards(elementType: 1, attackMethod: 1, removalType: 0);
        editor.AddConnection(row.Ranged, rangedEligible.FlowIn);
        editor.AddConnection(enemies.Out, rangedEligible.Cards);
        editor.AddConnection(locked.Out, rangedEligible.Filter);
        editor.AddConnection(rangedEligible.Success, rangedTarget.FlowIn);
        editor.AddConnection(rangedEligible.FilteredCards, rangedTarget.ValidTargets);
        editor.AddConnection(rangedTarget.Success, seize.FlowIn);
        editor.AddConnection(rangedTarget.SelectedTargets, seize.Targets);
        editor.AddConnection(seize.FlowOut, rangedDestroy.FlowIn);
        editor.AddConnection(ownerEntity, rangedDestroy.Attacker);
        editor.AddConnection(rangedTarget.SelectedTargets, rangedDestroy.Targets);
        editor.Finish();
    }

    private static void RebuildShilardDisloyalGrowth(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("ShilardDisloyalGrowthV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        NodeEndpoints disloyal = editor.AddFilterCardPlacement(playerSide: 2, location: 3);
        NodeEndpoints unit = editor.AddFilterCardType(4);
        int disloyalUnit = CombineCardFiltersAnd(editor, disloyal.Out, unit.Out);

        // Deploy: choose and play a bronze Disloyal unit from the owner's deck.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0, locationId: 16, cardTypes: 4, cardTiers: 2, ignoreOwner: false);
        FilterListEndpoints deckDisloyal = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0);
