        editor.AddConnection(deckDisloyal.Success, choice.FlowIn);
        editor.AddConnection(deckDisloyal.FilteredCards, choice.ValidChoices);
        editor.AddConnection(choice.Success, play.FlowIn);
        editor.AddConnection(choice.SelectedChoices, play.Cards);

        // Hand/deck/board passive: every played Disloyal unit ordinarily Boosts this copy by 1.
        AfterMovedEndpoints playedDisloyal = editor.AddAfterMovedTrigger(
