        editor.AddConnection(disloyalUnit, playedDisloyalUnit.Filter);
        editor.AddConnection(playedDisloyalUnit.Success, boost.FlowIn);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(ownerCards, boost.Targets);
        editor.Finish();
