    private static void RebuildJanCalveitMoveTopFour(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("JanCalveitTopFourV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        int owner = editor.AddGetOwnerPlayerId();

        // Deploy: choose exactly four cards and move them to the top of the deck.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        GetCardsEndpoints deck = editor.AddGetCards(ignoreTokens: 0, locationId: 16, cardTypes: 14, cardTiers: 10, ignoreOwner: false);
        CardChoiceEndpoints choose = editor.AddRequestCardChoice(4, 4, 0, choiceType: 0, revealChoices: true);
        MakeCardPositionEndpoints top = editor.AddMakeCardPosition(location: 16, index: 0);
        MoveCardsEndpoints move = editor.AddMoveCards();
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(deploy.FlowOut, choose.FlowIn);
        editor.AddConnection(deck.Out, choose.ValidChoices);
        editor.AddConnection(choose.Success, top.FlowIn);
        editor.AddConnection(owner, top.PlayerId);
        editor.AddConnection(top.FlowOut, move.FlowIn);
        editor.AddConnection(choose.SelectedChoices, move.Cards);
        editor.AddConnection(top.Position, move.Position);

        // Native passive preserved: at game start, move Calveit upward by the number of
        // Tactics in the owner's starting deck, clamped to deck index zero.
        TriggerEndpoints init = editor.AddAfterGameInitializedTrigger(ownerLocation: 16);
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        CardPositionEndpoints currentPosition = editor.AddGetCardPosition(positionType: 0);
        BreakCardPositionEndpoints splitPosition = editor.AddBreakCardPosition();
        InitialDeckEndpoints initialTactics = editor.AddGetInitialDeckDefinitions(unique: false);
        XElement initialNode = editor.FindNodeOwningEndpoint(initialTactics.Out)!;
        XElement category = initialNode.Element("Category")!.Element("V")!;
        category.Element("e0")!.SetAttributeValue("V", "2048");
        category.Element("e1")!.SetAttributeValue("V", "0");
        category.Element("e2")!.SetAttributeValue("V", "0");
        CardDefinitionListLengthEndpoints tacticCount = editor.AddCardDefinitionListLength();
        IntMinusEndpoints shiftedIndex = editor.AddIntMinus();
        IntMaxEndpoints clampedIndex = editor.AddIntMax(constantB: 0);
        MakeCardPositionEndpoints shiftedPosition = editor.AddMakeCardPosition(location: 16, index: 0);
        MoveCardsEndpoints reposition = editor.AddMoveCards();

        editor.AddConnection(owner, initialTactics.PlayerId);
        editor.AddConnection(ownerCard, currentPosition.Card);
        editor.AddConnection(currentPosition.Position, splitPosition.Position);
        editor.AddConnection(init.FlowOut, splitPosition.FlowIn);
        editor.AddConnection(initialTactics.Out, tacticCount.List);
        editor.AddConnection(splitPosition.Index, shiftedIndex.A);
        editor.AddConnection(tacticCount.Length, shiftedIndex.B);
        editor.AddConnection(shiftedIndex.Result, clampedIndex.A);
        editor.AddConnection(splitPosition.FlowOut, shiftedPosition.FlowIn);
        editor.AddConnection(splitPosition.PlayerId, shiftedPosition.PlayerId);
        editor.AddConnection(splitPosition.Location, shiftedPosition.Location);
        editor.AddConnection(clampedIndex.Result, shiftedPosition.Index);
        editor.AddConnection(shiftedPosition.FlowOut, reposition.FlowIn);
        editor.AddConnection(ownerCards, reposition.Cards);
        editor.AddConnection(shiftedPosition.Position, reposition.Position);
        editor.Finish();
    }

