    private static void RebuildArdalTacticBudget(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        var editor = new GraphEditor(ability);
        int maxProvisionVar = editor.EnsurePersistentIntVariable("MaxProvision", 0);
        int remainingVar = editor.EnsureIntVariable("ArdalRemainingProvision", 0);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == remainingVar)
            .SetAttributeValue("HideInTooltip", "True");
        int marker = editor.EnsureIntVariable("ArdalExactProvisionBudgetV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        TriggerEndpoints init = editor.AddAfterGameInitializedTrigger(ownerLocation: 379);
        int owner = editor.AddGetOwnerPlayerId();
        InitialDeckEndpoints initial = editor.AddGetInitialDeckDefinitions(unique: false);
        XElement initialNode = editor.FindNodeOwningEndpoint(initial.Out)!;
        initialNode.Element("Tier")!.SetAttributeValue("V", "10");
        initialNode.Element("Type")!.SetAttributeValue("V", "14");
        XElement category = initialNode.Element("Category")!.Element("V")!;
        category.Element("e0")!.SetAttributeValue("V", "2048");
        category.Element("e1")!.SetAttributeValue("V", "0");
        category.Element("e2")!.SetAttributeValue("V", "0");
        CardDefinitionListLengthEndpoints tacticCount = editor.AddCardDefinitionListLength();
        SetVarEndpoints saveMax = editor.AddSetIntVariable(maxProvisionVar);
        editor.AddConnection(owner, initial.PlayerId);
        editor.AddConnection(init.FlowOut, saveMax.FlowIn);
        editor.AddConnection(initial.Out, tacticCount.List);
        editor.AddConnection(tacticCount.Length, saveMax.In);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int maxProvision = editor.AddGetIntVariable(maxProvisionVar);
        SetVarEndpoints startBudget = editor.AddSetIntVariable(remainingVar);
        editor.AddConnection(deploy.FlowOut, startBudget.FlowIn);
        editor.AddConnection(maxProvision, startBudget.In);
        int continuation = startBudget.FlowOut;

        // Each iteration filters every deck card by Provision <= remaining budget.
        // FilterProvisionLevelNode is intentionally not used: it selects highest/lowest
        // cards and does not implement a numeric affordability comparison.
        for (int i = 0; i < 5; i++)
        {
            GetCardsEndpoints deck = editor.AddGetCards(ignoreTokens: 0, locationId: 16, cardTypes: 14, cardTiers: 10, ignoreOwner: false);
            NodeEndpoints affordable = editor.AddFilterCardProvision(compareOp: 4, provision: 0);
            FilterListEndpoints affordableCards = editor.AddFilterCardList();
            CardChoiceEndpoints choose = editor.AddRequestCardChoice(0, 1, 0, choiceType: 0, revealChoices: true);
            CardElementEndpoints chosen = editor.AddCardListGetElement(0);
            CardProvisionEndpoints provision = editor.AddGetCardTemplateProvision();
            int remainingForFilter = editor.AddGetIntVariable(remainingVar);
            int remainingForSubtract = editor.AddGetIntVariable(remainingVar);
            IntMinusEndpoints subtract = editor.AddIntMinus();
            SetVarEndpoints saveRemaining = editor.AddSetIntVariable(remainingVar);
            PlayEndpoints play = editor.AddPlayCards();

            editor.AddConnection(owner, deck.PlayerId);
            editor.AddConnection(continuation, affordableCards.FlowIn);
            editor.AddConnection(deck.Out, affordableCards.Cards);
            editor.AddConnection(remainingForFilter, affordable.PowerInput);
            editor.AddConnection(affordable.Out, affordableCards.Filter);
            editor.AddConnection(affordableCards.Success, choose.FlowIn);
            editor.AddConnection(affordableCards.FilteredCards, choose.ValidChoices);
            editor.AddConnection(choose.SelectedChoices, chosen.List);
            editor.AddConnection(chosen.Card, provision.Card);
            editor.AddConnection(remainingForSubtract, subtract.A);
            editor.AddConnection(provision.Provision, subtract.B);
            editor.AddConnection(choose.Success, saveRemaining.FlowIn);
            editor.AddConnection(subtract.Result, saveRemaining.In);
            editor.AddConnection(saveRemaining.FlowOut, play.FlowIn);
            editor.AddConnection(choose.SelectedChoices, play.Cards);
            continuation = play.FlowOut;
        }
        editor.Finish();
    }

    private static void AddTiborFlankingAndStartingPower(XElement ability)
    {
        var editor = new GraphEditor(ability);
        RemoveTiborLegacyDrawDamage(editor);
        if (editor.TemporaryVariables.Elements().Any(v => (string?)v.Attribute("Name") == "TiborFlankingStartPowerV1"))
        {
            editor.Finish();
            return;
        }
        int marker = editor.EnsureIntVariable("TiborFlankingStartPowerV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        XElement? afterTurn = editor.Nodes.Elements().FirstOrDefault(n => (string?)n.Attribute("Type") == "AfterTurnTrigger");
        if (afterTurn != null)
        {
            int afterTurnOut = Id(afterTurn.Element("FlowOut")!);
            List<int> oldTargets = editor.GetOutgoingTargets(afterTurnOut).ToList();
            foreach (int target in oldTargets) editor.RemoveConnection(afterTurnOut, target);
            FlankingEndpoints flanking = editor.AddFlankingSubAbility();
            IntForeachEndpoints repeats = editor.AddIntForeach(start: 0, num: 1);
            editor.AddConnection(afterTurnOut, flanking.FlowIn);
            editor.AddConnection(flanking.FlowOut, repeats.FlowIn);
            editor.AddConnection(flanking.Trigger, repeats.Num);
            foreach (int target in oldTargets) editor.AddConnection(repeats.FlowFor, target);
        }

        TriggerEndpoints init = editor.AddAfterGameInitializedTrigger(ownerLocation: 379);
        int owner = editor.AddGetOwnerPlayerId();
        InitialDeckEndpoints initial = editor.AddGetInitialDeckDefinitions(unique: false);
        XElement initialNode = editor.FindNodeOwningEndpoint(initial.Out)!;
        initialNode.Element("Tier")!.SetAttributeValue("V", "2");
        initialNode.Element("Type")!.SetAttributeValue("V", "4");
        XElement category = initialNode.Element("Category")!.Element("V")!;
        category.Element("e0")!.SetAttributeValue("V", "67108864");
        category.Element("e1")!.SetAttributeValue("V", "0");
        category.Element("e2")!.SetAttributeValue("V", "0");
        CardDefinitionListLengthEndpoints count = editor.AddCardDefinitionListLength();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int ownerEntity = editor.AddGetAbilityOwner();
        PowerEndpoints setBase = editor.AddChangePower(amount: 0, operation: 2, elementType: 128, attackMethod: 0, targetedPower: 1);
        editor.AddConnection(owner, initial.PlayerId);
        editor.AddConnection(initial.Out, count.List);
        editor.AddConnection(init.FlowOut, setBase.FlowIn);
        editor.AddConnection(ownerEntity, setBase.Attacker);
        editor.AddConnection(ownerCards, setBase.Targets);
        editor.AddConnection(count.Length, setBase.Power);
        editor.Finish();
    }

    private static void RemoveTiborLegacyDrawDamage(GraphEditor editor)
    {
        XElement? draw = editor.Nodes.Elements().FirstOrDefault(node =>
            (string?)node.Attribute("Type") == "DrawCardsNode");
        if (draw == null)
        {
            editor.TemporaryVariables.Elements()
                .Where(variable => (string?)variable.Attribute("Name") == "Damage")
                .Remove();
            return;
        }

        var component = new Dictionary<int, XElement>();
        var queue = new Queue<XElement>();
        queue.Enqueue(draw);
        while (queue.Count > 0)
        {
            XElement node = queue.Dequeue();
            int nodeId = (int)node.Attribute("Id")!;
            if (!component.TryAdd(nodeId, node))
                continue;

            HashSet<int> endpointIds = node.DescendantsAndSelf()
                .Where(element => element.Attribute("Id") != null)
                .Select(element => (int)element.Attribute("Id")!)
                .ToHashSet();
            foreach (XElement connection in editor.Connections.Elements())
            {
                int source = (int)connection.Attribute("SrcId")!;
                int target = (int)connection.Attribute("DstId")!;
                int? other = endpointIds.Contains(source) ? target : endpointIds.Contains(target) ? source : null;
                if (other == null)
                    continue;
                XElement? otherNode = editor.FindNodeOwningEndpoint(other.Value);
                if (otherNode != null && !component.ContainsKey((int)otherNode.Attribute("Id")!))
                    queue.Enqueue(otherNode);
            }
        }

        HashSet<int> removedEndpoints = component.Values
            .SelectMany(node => node.DescendantsAndSelf())
            .Where(element => element.Attribute("Id") != null)
            .Select(element => (int)element.Attribute("Id")!)
            .ToHashSet();
        editor.Connections.Elements()
            .Where(connection => removedEndpoints.Contains((int)connection.Attribute("SrcId")!) ||
                                 removedEndpoints.Contains((int)connection.Attribute("DstId")!))
            .Remove();
        foreach (XElement node in component.Values)
            node.Remove();
        editor.TemporaryVariables.Elements()
            .Where(variable => (string?)variable.Attribute("Name") == "Damage")
            .Remove();
    }

    private static void RebuildLethoLeaderLockAndTrio(
        XElement ability,
        XElement template,
        AbilityDocument abilities)
    {
        EnsureTimedLeaderLockStatusAbility(abilities);
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        SetTemplateText(template, "InitialTimer", "3");
        SetTemplateText(template, "ResetInInactive", "True");
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("LethoLeaderLockTrioV3", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        GetCardsEndpoints ownLeader = editor.AddGetCards(ignoreTokens: 0, locationId: 64, cardTypes: 1, cardTiers: 1, ignoreOwner: false);
        GetCardsEndpoints enemyLeader = editor.AddGetCards(ignoreTokens: 0, locationId: 64, cardTypes: 1, cardTiers: 1, ignoreOwner: false);
        CardListAppendEndpoints leaders = editor.AddCardListAppend();
        TokenEndpoints lockLeaders = editor.AddChangeTokens(token: 4, elementType: 1, attackMethod: 0, operation: 0);
        editor.AddConnection(owner, ownLeader.PlayerId);
        editor.AddConnection(opponent, enemyLeader.PlayerId);
        editor.AddConnection(ownLeader.Out, leaders.List);
        editor.AddConnection(enemyLeader.Out, leaders.ListToAppend);
        editor.AddConnection(deploy.FlowOut, leaders.FlowIn);
        editor.AddConnection(leaders.FlowOut, lockLeaders.FlowIn);
        editor.AddConnection(ownerEntity, lockLeaders.Attacker);
        editor.AddConnection(leaders.List, lockLeaders.Targets);

        // Lock the strongest friendly and enemy units before attempting to attach
        // status timers to leader cards. Some leader-card timer operations do not
        // reliably emit FlowOut, which previously prevented this entire branch.
        GetCardsEndpoints friendly = editor.AddGetCards(ignoreTokens: 0, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: true);
        PowerLevelEndpoints strongestFriendly = editor.AddFilterPowerLevel(powerFilter: 1, count: 1);
        GetCardsEndpoints enemies = editor.AddGetCards(ignoreTokens: 0, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        PowerLevelEndpoints strongestEnemy = editor.AddFilterPowerLevel(powerFilter: 1, count: 1);
        CardListAppendEndpoints strongestUnits = editor.AddCardListAppend();
        TokenEndpoints lockUnits = editor.AddChangeTokens(token: 4, elementType: 1, attackMethod: 0, operation: 0);
        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(lockLeaders.FlowOut, strongestFriendly.FlowIn);
        editor.AddConnection(friendly.Out, strongestFriendly.Cards);
        editor.AddConnection(strongestFriendly.Success, strongestEnemy.FlowIn);
        editor.AddConnection(strongestFriendly.Fail, strongestEnemy.FlowIn);
        editor.AddConnection(enemies.Out, strongestEnemy.Cards);
        editor.AddConnection(strongestFriendly.FilteredCards, strongestUnits.List);
        editor.AddConnection(strongestEnemy.FilteredCards, strongestUnits.ListToAppend);
        editor.AddConnection(strongestEnemy.Success, strongestUnits.FlowIn);
        editor.AddConnection(strongestEnemy.Fail, strongestUnits.FlowIn);
        editor.AddConnection(strongestUnits.FlowOut, lockUnits.FlowIn);
        editor.AddConnection(ownerEntity, lockUnits.Attacker);
        editor.AddConnection(strongestUnits.List, lockUnits.Targets);

        GetCardsEndpoints ownerZones = editor.AddGetCards(ignoreTokens: 0, locationId: 27, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints serrit = editor.AddFilterCardTemplateId(Serrit);
        NodeEndpoints auckes = editor.AddFilterCardTemplateId(Auckes);
        LogicEndpoints trioFilter = editor.AddFilterLogic(orOperation: true);
        FilterListEndpoints trio = editor.AddFilterCardList();
        StrengthenEndpoints strengthen = editor.AddStrengthenSubAbility(2);
        editor.AddConnection(owner, ownerZones.PlayerId);
        editor.AddConnection(serrit.Out, trioFilter.Input0);
        editor.AddConnection(auckes.Out, trioFilter.Input1);
        editor.AddConnection(ownerZones.Out, trio.Cards);
        editor.AddConnection(trioFilter.Out, trio.Filter);
        editor.AddConnection(lockUnits.FlowOut, trio.FlowIn);
        editor.AddConnection(trio.Success, strengthen.FlowIn);
        editor.AddConnection(trio.FilteredCards, strengthen.Targets);

        // Independent timed Lock on both leader cards. This is intentionally after
        // the unit-lock branch so any leader-specific timer limitation cannot block it.
        ChangeStatusTimerEndpoints leaderLockTimer = editor.AddChangeCardStatusTimer(status: 4, operation: 2, value: 3);
        editor.AddConnection(strengthen.FlowOut, leaderLockTimer.FlowIn);
        editor.AddConnection(trio.Fail, leaderLockTimer.FlowIn);
        editor.AddConnection(leaders.List, leaderLockTimer.Cards);

        // Visible Timer 3 on Letho must be explicitly decremented; InitialTimer only
        // initializes the UI value and does not advance it by itself.
        TurnTriggerEndpoints tick = editor.AddBeforeTurnEndTrigger(ownerLocation: 3);
        ChangeCardTimerEndpoints decrementVisibleTimer = editor.AddChangeCardTimer(operation: 0, value: 1);
        editor.AddConnection(owner, tick.PlayerFilter);
        editor.AddConnection(tick.FlowOut, decrementVisibleTimer.FlowIn);
        editor.AddConnection(ownerCards, decrementVisibleTimer.Cards);

        CardTimerElapsedEndpoints elapsed = editor.AddCardTimerElapsedTrigger();
        AddLeaderUnlockBranch(editor, elapsed.FlowOut, owner, opponent, ownerEntity);

        // If Letho leaves the battlefield first, unlock immediately. The independent
        // status timers on both leaders remain a final fallback even if this card dies.
        AfterMovedEndpoints leftField = editor.AddAfterMovedTrigger(
            ownerLocation: 379, triggerCard: 1, triggerPlayer: 3,
            fromLocation: 3, toLocation: 376, reason: 255);
        editor.AddConnection(owner, leftField.FromPlayer);
        editor.AddConnection(owner, leftField.ToPlayer);
        AddLeaderUnlockBranch(editor, leftField.FlowOut, owner, opponent, ownerEntity);
        editor.Finish();
    }

    private static void AddLeaderUnlockBranch(
        GraphEditor editor,
        int flow,
        int owner,
        int opponent,
        int attacker)
    {
        GetCardsEndpoints ownLeader = editor.AddGetCards(ignoreTokens: 0, locationId: 64, cardTypes: 1, cardTiers: 1, ignoreOwner: false);
        GetCardsEndpoints enemyLeader = editor.AddGetCards(ignoreTokens: 0, locationId: 64, cardTypes: 1, cardTiers: 1, ignoreOwner: false);
        CardListAppendEndpoints leaders = editor.AddCardListAppend();
        TokenEndpoints unlock = editor.AddChangeTokens(token: 4, elementType: 1, attackMethod: 0, operation: 1);
        editor.AddConnection(owner, ownLeader.PlayerId);
        editor.AddConnection(opponent, enemyLeader.PlayerId);
        editor.AddConnection(ownLeader.Out, leaders.List);
        editor.AddConnection(enemyLeader.Out, leaders.ListToAppend);
        editor.AddConnection(flow, leaders.FlowIn);
        editor.AddConnection(leaders.FlowOut, unlock.FlowIn);
        editor.AddConnection(attacker, unlock.Attacker);
        editor.AddConnection(leaders.List, unlock.Targets);
    }

    private static void EnsureTimedLeaderLockStatusAbility(AbilityDocument abilities)
    {
        XElement root = abilities.Document.Root
            ?? throw new InvalidDataException("Abilities.xml не содержит root.");
        XElement? statusAbility = root.Elements("Ability").FirstOrDefault(element =>
            (string?)element.Attribute("Type") == "CardStatusAbility" &&
            (int?)element.Attribute("CardStatus") == 4);
        if (statusAbility == null)
        {
            statusAbility = new XElement("Ability",
                new XAttribute("Type", "CardStatusAbility"),
                new XAttribute("NId", 1),
                new XAttribute("CardStatus", 4),
                new XAttribute("ExecuteMode", 2),
                new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
                new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
                new XElement("Nodes"),
                new XElement("Connections"));
            root.Add(statusAbility);
        }
        else
        {
            ClearAbilityGraph(statusAbility, clearVariables: true);
        }

        var editor = new GraphEditor(statusAbility);
        int owner = editor.AddGetOwnerPlayerId();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        int ownerEntity = editor.AddGetAbilityOwner();
        TurnTriggerEndpoints turn = editor.AddAfterTurnTrigger(ownerLocation: 64);
        HasStatusTimerEndpoints hasTimer = editor.AddHasCardStatusTimer(status: 4);
        ChangeStatusTimerEndpoints decrement = editor.AddChangeCardStatusTimer(status: 4, operation: 0, value: 1);
        editor.AddConnection(owner, turn.PlayerFilter);
        editor.AddConnection(turn.FlowOut, hasTimer.FlowIn);
        editor.AddConnection(ownerCard, hasTimer.Card);
        editor.AddConnection(hasTimer.True, decrement.FlowIn);
        editor.AddConnection(ownerCards, decrement.Cards);

        CardStatusTimerElapsedEndpoints elapsed = editor.AddCardStatusTimerElapsedTrigger();
        ElementListEndpoints elapsedCard = editor.AddCardElementToList();
        TokenEndpoints unlock = editor.AddChangeTokens(token: 4, elementType: 1, attackMethod: 0, operation: 1);
        editor.AddConnection(elapsed.Card, elapsedCard.Card);
        editor.AddConnection(elapsed.FlowOut, unlock.FlowIn);
        editor.AddConnection(ownerEntity, unlock.Attacker);
        editor.AddConnection(elapsedCard.List, unlock.Targets);
        editor.Finish();
        NormalizeAbilityNId(statusAbility);
    }

