        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int tributeVar = editor.EnsureIntVariable("Tribute", 2);
        int healVar = editor.EnsureIntVariable("Heal", 4);
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        GetCardsEndpoints friendly = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        NodeEndpoints damaged = editor.AddFilterCardPowerState(powerState: 1);

        // Tribute 2: heal one chosen friendly damaged unit by 4.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        TributeEndpoints tribute = editor.AddTributeSubAbility();
        int tributeValue = editor.AddGetIntVariable(tributeVar);
        FilterListEndpoints damagedForTribute = editor.AddFilterCardList();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 0);
        PowerEndpoints healFour = editor.AddChangePower(0, 4, 512, 1);
        int healValue = editor.AddGetIntVariable(healVar);
        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(deploy.FlowOut, tribute.FlowIn);
        editor.AddConnection(tributeValue, tribute.Cost);
        editor.AddConnection(tribute.Paid, damagedForTribute.FlowIn);
        editor.AddConnection(friendly.Out, damagedForTribute.Cards);
        editor.AddConnection(damaged.Out, damagedForTribute.Filter);
        editor.AddConnection(damagedForTribute.Success, target.FlowIn);
        editor.AddConnection(damagedForTribute.FilteredCards, target.ValidTargets);
        editor.AddConnection(target.Success, healFour.FlowIn);
        editor.AddConnection(ownerEntity, healFour.Attacker);
        editor.AddConnection(target.SelectedTargets, healFour.Targets);
        editor.AddConnection(healValue, healFour.Power);

        // End of owner's turn: fully heal a random friendly damaged unit.
        TurnTriggerEndpoints endTurn = editor.AddAfterOwnerTurnTrigger();
        FilterListEndpoints damagedForTurn = editor.AddFilterCardList();
        RandomCardEndpoints random = editor.AddRandomCard();
        ElementListEndpoints randomList = editor.AddCardElementToList();
        PowerEndpoints healFull = editor.AddChangePower(999999, 4, 512, 0);
        editor.AddConnection(owner, endTurn.PlayerFilter);
        editor.AddConnection(endTurn.FlowOut, damagedForTurn.FlowIn);
        editor.AddConnection(friendly.Out, damagedForTurn.Cards);
        editor.AddConnection(damaged.Out, damagedForTurn.Filter);
        editor.AddConnection(damagedForTurn.Success, random.FlowIn);
        editor.AddConnection(damagedForTurn.FilteredCards, random.List);
        editor.AddConnection(random.Card, randomList.Card);
        editor.AddConnection(random.FlowOut, healFull.FlowIn);
        editor.AddConnection(ownerEntity, healFull.Attacker);
        editor.AddConnection(randomList.List, healFull.Targets);
        editor.Finish();
    }

