    private static void AddTempleGuardSymbolBoost(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "TempleGuardSymbolBoostV1", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("TempleGuardSymbolBoostV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        XElement request = FindNode(ability, "RequestCardTargetsNode");
        XElement normalBoost = ability.Element("Nodes")!.Elements().Single(node =>
            IsNodeType(node, "ChangePowerNode") &&
            (string?)node.Element("Operation")?.Attribute("V") == "0" &&
            (string?)node.Element("ElementType")?.Attribute("V") == "512");
        int success = Id(request.Element("FlowOutSuccess")!);
        int targetsInShape = Id(request.Element("TargetsInShape")!);
        int normalFlow = Id(normalBoost.Element("FlowIn")!);
        int normalTargets = Id(normalBoost.Element("Targets")!);
        editor.TryRemoveConnection(success, normalFlow);
        editor.TryRemoveConnection(targetsInShape, normalTargets);

        ForeachEndpoints each = editor.AddCardListForeach();
        ElementListEndpoints one = editor.AddCardElementToList();
        NodeEndpoints symbol = editor.AddFilterCardCategory(0, 512, 0);
        FilterListEndpoints isSymbol = editor.AddFilterCardList();
        PowerEndpoints symbolBoost = editor.AddChangePower(2, 0, 512, 0);
        int ownerEntity = Id(FindNode(ability, "GetAbilityOwnerNode").Element("Out")!);

        editor.AddConnection(success, each.FlowIn);
        editor.AddConnection(targetsInShape, each.List);
        editor.AddConnection(each.Element, one.Card);
        editor.AddConnection(each.FlowFor, isSymbol.FlowIn);
        editor.AddConnection(one.List, isSymbol.Cards);
        editor.AddConnection(symbol.Out, isSymbol.Filter);
        editor.AddConnection(isSymbol.Success, symbolBoost.FlowIn);
        editor.AddConnection(ownerEntity, symbolBoost.Attacker);
        editor.AddConnection(one.List, symbolBoost.Targets);
        editor.AddConnection(isSymbol.Fail, normalFlow);
        editor.AddConnection(one.List, normalTargets);
        editor.Finish();
    }

    private static void RemoveGraphByVariablePrefix(XElement ability, string prefix)
    {
        EnsureAbilityContainers(ability);
        XElement variables = ability.Element("TemporaryVariables")!;
        foreach (XElement variable in variables.Elements()
                     .Where(v => ((string?)v.Attribute("Name"))?.StartsWith(prefix, StringComparison.Ordinal) == true)
                     .ToList())
        {
            variable.Remove();
        }
    }

    private static IReadOnlyList<int> RebuildArenaEndregaMadnessGrowth(
        XElement ability,
        XElement template,
        AbilityDocument abilities,
        TemplateDocument templates)
    {
        // The old design injected hooks into every Madness card. Remove every historical marker;
        // the current ability is completely self-contained.
        foreach (XElement sourceAbility in abilities.Document.Root?.Elements("Ability")
                     .Where(a => string.Equals((string?)a.Attribute("Type"), "CardAbility", StringComparison.Ordinal))
                 ?? Enumerable.Empty<XElement>())
        {
            RemoveGraphByVariablePrefix(sourceAbility, "ArenaEndregaMadnessGrowthHook");
            RemoveGraphByVariablePrefix(sourceAbility, "ArenaEndregaPowerOneGrowthV2");
            RemoveGraphByVariablePrefix(sourceAbility, "ArenaEndregaPowerOneGrowthV3");
            RemoveGraphByVariablePrefix(sourceAbility, "ArenaEndregaPowerOneGrowthV4");
        }

        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        SetTemplateText(template, "Madness", "True");
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("ArenaEndregaPowerOneGrowthV5", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int costVar = editor.EnsureIntVariable("Cost", 2);
        int damageVar = editor.EnsureIntVariable("Damage", 2);
        PaidForEndpoints fee = editor.AddPaidForTrigger(costVar);
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        GetCardsEndpoints friendly = editor.AddGetCards(264, 3, 4, 10, false);
        GetCardsEndpoints enemies = editor.AddGetCards(264, 3, 4, 10, true);
        CardListAppendEndpoints allUnits = editor.AddCardListAppend();
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 0);
        PowerEndpoints damage = editor.AddChangePower(0, 1, 1, 1);
        int damageValue = editor.AddGetIntVariable(damageVar);
        editor.AddConnection(owner, friendly.PlayerId);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(friendly.Out, allUnits.List);
        editor.AddConnection(enemies.Out, allUnits.ListToAppend);
        editor.AddConnection(fee.FlowOut, allUnits.FlowIn);
        editor.AddConnection(allUnits.FlowOut, target.FlowIn);
        editor.AddConnection(allUnits.List, target.ValidTargets);
        editor.AddConnection(target.Success, damage.FlowIn);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(target.SelectedTargets, damage.Targets);
        editor.AddConnection(damageValue, damage.Power);

        // Native current-turn gate: Kahir/Svalblod compare GetOwnerPlayerId with
        // GetCurrentPlayerId on every trigger. This avoids the unverified persistent turn flag.
        AfterChangePowerEndpoints changed = editor.AddAfterChangePowerTrigger(
            ownerLocation: 3, targetCard: 3, powerOp: 7);
        int currentPlayer = editor.AddGetCurrentPlayerId();
        PlayerIdCompareEndpoints ownerTurn = editor.AddPlayerIdCompare(compareOp: 0);
        BranchEndpoints duringOwnerTurn = editor.AddBranch();
        editor.AddConnection(owner, ownerTurn.A);
        editor.AddConnection(currentPlayer, ownerTurn.B);
        editor.AddConnection(ownerTurn.Result, duringOwnerTurn.Condition);
        editor.AddConnection(changed.FlowOut, duringOwnerTurn.FlowIn);

        // The trigger itself proves that power changed. Only after that event do we test that the
        // affected friendly unit's resulting current power is exactly 1. A unit merely played at
        // power 1 never enters this branch because no AfterChangePower event occurred.
        CardPowerAttackEachEndpoints each = editor.AddCardPowerAttackForEach();
        ElementListEndpoints affectedList = editor.AddCardElementToList();
        NodeEndpoints friendlyOwner = editor.AddFilterCardPlayerId();
        FilterListEndpoints friendlyChanged = editor.AddFilterCardList();
        NodeEndpoints exactlyOne = editor.AddFilterCardPower(compareOp: 0, power: 1);
        FilterListEndpoints nowOne = editor.AddFilterCardList();
        PowerEndpoints boostSelf = editor.AddChangePower(1, 0, 512, 0, effectType: 1);
        editor.AddConnection(duringOwnerTurn.True, each.FlowIn);
        editor.AddConnection(changed.CardPowerAttack, each.CardPowerAttack);
        editor.AddConnection(each.Card, affectedList.Card);
        editor.AddConnection(owner, friendlyOwner.PowerInput);
        editor.AddConnection(each.FlowFor, friendlyChanged.FlowIn);
        editor.AddConnection(affectedList.List, friendlyChanged.Cards);
        editor.AddConnection(friendlyOwner.Out, friendlyChanged.Filter);
        editor.AddConnection(friendlyChanged.Success, nowOne.FlowIn);
        editor.AddConnection(friendlyChanged.FilteredCards, nowOne.Cards);
        editor.AddConnection(exactlyOne.Out, nowOne.Filter);
        editor.AddConnection(nowOne.Success, boostSelf.FlowIn);
        editor.AddConnection(ownerEntity, boostSelf.Attacker);
        editor.AddConnection(ownerCards, boostSelf.Targets);
        editor.Finish();
        return Array.Empty<int>();
    }

    private static void RebuildCiriDashReactive(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        SetTemplateText(template, "InitialTimer", "-1");
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("CiriDashReactiveV6", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int savedCurrentPower = editor.EnsurePersistentIntVariable("CiriDashSavedCurrentPower", 0);
        editor.PersistentVariables.Elements().Single(v => (int?)v.Attribute("Id") == savedCurrentPower)
            .SetAttributeValue("HideInTooltip", "True");

        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerCards = editor.AddGetAbilityOwnerCardList();

        // PowerOp=3 subscribes to ordinary Boost/Damage changes but excludes Set.
        // The internal green-power restoration below uses Set, so it cannot retrigger the dash.
        // SourceCardTemplate=2 is the native "this card" restriction used by Torque.
        AfterChangePowerEndpoints handChanged = editor.AddAfterChangePowerTrigger(
            8, 1, 3, sourceCardTemplate: 2);
        AfterChangePowerEndpoints deckChanged = editor.AddAfterChangePowerTrigger(
            16, 1, 3, sourceCardTemplate: 2);
        AddCiriDashPulse(editor, handChanged.FlowOut, owner, opponent, ownerEntity, ownerCard, ownerCards,
            savedCurrentPower, returnLocation: 8, shuffleDeck: false);
        AddCiriDashPulse(editor, deckChanged.FlowOut, owner, opponent, ownerEntity, ownerCard, ownerCards,
            savedCurrentPower, returnLocation: 16, shuffleDeck: true);

        AfterPassedEndpoints handPassed = editor.AddAfterPassedTrigger(ownerLocation: 8);
        AfterPassedEndpoints deckPassed = editor.AddAfterPassedTrigger(ownerLocation: 16);
        AddCiriBothPassedSummon(editor, ability, handPassed.FlowOut, owner, opponent, ownerCard, ownerCards,
            destinationRow: 1, drawAfterSummon: true);
        AddCiriBothPassedSummon(editor, ability, deckPassed.FlowOut, owner, opponent, ownerCard, ownerCards,
            destinationRow: 2, drawAfterSummon: false);
        editor.Finish();
    }

    private static void AddCiriDashPulse(
        GraphEditor editor,
        int flowIn,
        int owner,
        int opponent,
        int ownerEntity,
        int ownerCard,
        int ownerCards,
        int savedCurrentPower,
        int returnLocation,
        bool shuffleDeck)
    {
        CardPowerEndpoints powerBeforePulse = editor.AddGetCardPower(powerType: 0);
        SetVarEndpoints rememberPower = editor.AddSetIntVariable(savedCurrentPower);
        editor.AddConnection(ownerCard, powerBeforePulse.Card);
        editor.AddConnection(flowIn, rememberPower.FlowIn);
        editor.AddConnection(powerBeforePulse.Power, rememberPower.In);

        PositionEndpoints randomRow = editor.AddGetRandomLastAvailablePosition(location: 3);
        MoveCardsEndpoints summon = editor.AddMoveCards();
        GetCardsEndpoints enemies = editor.AddGetCards(264, 3, 4, 10, true);
        PowerLevelEndpoints strongest = editor.AddFilterPowerLevel(powerFilter: 1, count: 1);
        RandomCardEndpoints randomStrongest = editor.AddRandomCard();
        ElementListEndpoints oneStrongest = editor.AddCardElementToList();
        PowerEndpoints damage = editor.AddChangePower(1, 1, 1, 1);
        MakeCardPositionEndpoints returnPosition = editor.AddMakeCardPosition(returnLocation, 0);
        MoveCardsEndpoints returnCard = editor.AddMoveCards();

        editor.AddConnection(owner, randomRow.PlayerId);
        editor.AddConnection(rememberPower.FlowOut, summon.FlowIn);
        editor.AddConnection(ownerCards, summon.Cards);
        editor.AddConnection(randomRow.Position, summon.Position);
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(summon.FlowOut, strongest.FlowIn);
        editor.AddConnection(enemies.Out, strongest.Cards);
        editor.AddConnection(strongest.Success, randomStrongest.FlowIn);
        editor.AddConnection(strongest.FilteredCards, randomStrongest.List);
        editor.AddConnection(randomStrongest.Card, oneStrongest.Card);
        editor.AddConnection(randomStrongest.FlowOut, damage.FlowIn);
        editor.AddConnection(oneStrongest.List, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);

        int rememberedPower = editor.AddGetIntVariable(savedCurrentPower);
        PowerEndpoints restoreGreenPower = editor.AddChangePower(
            amount: 0,
            operation: 2,
            elementType: 512,
            attackMethod: 0,
            targetedPower: 0);
        editor.AddConnection(damage.FlowOut, returnPosition.FlowIn);
        editor.AddConnection(strongest.Fail, returnPosition.FlowIn);
        editor.AddConnection(owner, returnPosition.PlayerId);
        editor.AddConnection(returnPosition.FlowOut, returnCard.FlowIn);
        editor.AddConnection(ownerCards, returnCard.Cards);
        editor.AddConnection(returnPosition.Position, returnCard.Position);
        editor.AddConnection(ownerEntity, restoreGreenPower.Attacker);
        editor.AddConnection(ownerCards, restoreGreenPower.Targets);
        editor.AddConnection(rememberedPower, restoreGreenPower.Power);

        if (shuffleDeck)
        {
            ShuffleDeckEndpoints shuffle = editor.AddShuffleDeck();
            editor.AddConnection(returnCard.FlowOut, shuffle.FlowIn);
            editor.AddConnection(owner, shuffle.PlayerId);
            editor.AddConnection(shuffle.FlowOut, restoreGreenPower.FlowIn);
        }
        else
        {
            editor.AddConnection(returnCard.FlowOut, restoreGreenPower.FlowIn);
        }
    }

    private static void AddCiriBothPassedSummon(
        GraphEditor editor,
        XElement ability,
        int flowIn,
        int owner,
        int opponent,
        int ownerCard,
        int ownerCards,
        int destinationRow,
        bool drawAfterSummon)
    {
        PlayerPassedEndpoints ownerPassed = editor.AddPlayerGetHasPassed();
        PlayerPassedEndpoints opponentPassed = editor.AddPlayerGetHasPassed();
        BranchEndpoints ownerGate = editor.AddBranch();
        BranchEndpoints opponentGate = editor.AddBranch();
        CardPowerEndpoints power = editor.AddGetCardPower(0);
        IntBranchEndpoints aboveEight = editor.AddIntBranch();
        IntModuloEndpoints parity = editor.AddIntModulo(2);
        IntBranchEndpoints odd = editor.AddIntBranch();
        PositionEndpoints row = editor.AddGetRandomLastAvailablePosition(destinationRow);
        MoveCardsEndpoints summon = editor.AddMoveCards();

        editor.AddConnection(owner, ownerPassed.PlayerId);
        editor.AddConnection(opponent, opponentPassed.PlayerId);
        editor.AddConnection(flowIn, ownerGate.FlowIn);
        editor.AddConnection(ownerPassed.Passed, ownerGate.Condition);
        editor.AddConnection(ownerGate.True, opponentGate.FlowIn);
        editor.AddConnection(opponentPassed.Passed, opponentGate.Condition);
        editor.AddConnection(opponentGate.True, aboveEight.FlowIn);
        editor.AddConnection(ownerCard, power.Card);
        editor.AddConnection(power.Power, aboveEight.A);
        SetEndpointValue(ability, aboveEight.B, "8");
        editor.AddConnection(aboveEight.Bigger, odd.FlowIn);
        editor.AddConnection(power.Power, parity.A);
        editor.AddConnection(parity.Result, odd.A);
        SetEndpointValue(ability, odd.B, "1");
        editor.AddConnection(owner, row.PlayerId);
        editor.AddConnection(odd.Equal, summon.FlowIn);
        editor.AddConnection(ownerCards, summon.Cards);
        editor.AddConnection(row.Position, summon.Position);

        if (drawAfterSummon)
        {
            DrawEndpoints draw = editor.AddDrawCards(1);
            editor.AddConnection(summon.FlowOut, draw.FlowIn);
            editor.AddConnection(owner, draw.PlayerId);
        }
    }

    private static void RebuildEnchantedArmorChoice(
        AbilityDocument abilities,
        XElement ability,
        XElement template,
        TemplateDocument templates,
        IDictionary<string, string> localizationEdits)
    {
        EnsureEnchantedArmorChoiceTemplates(abilities, templates, template, localizationEdits);
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "False");
        SetTemplateText(template, "VisibleTapCharges", "False");
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("EnchantedArmorChoiceV3", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Boost", 5);
        editor.EnsureIntVariable("Armor", 5);

        TriggerEndpoints order = editor.AddTappedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints hand = editor.AddGetCards(0, 8, 4, 10, false);
        CardChoiceEndpoints target = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0, revealChoices: true);
        int modeDefinitions = editor.AddCardDefinitionListVariable(
            "EnchantedArmorModes", EnchantedArmorBoostChoice, EnchantedArmorArmorChoice);
        int modes = editor.AddGetCardDefinitionListVariable(modeDefinitions);
        TemplateChoiceEndpoints mode = editor.AddRequestTemplateChoice(1, 1, choiceType: 0);
        int boostDefinition = editor.AddCardDefinitionListVariable(
            "EnchantedArmorBoostMode", EnchantedArmorBoostChoice);
        int boostReference = editor.AddGetCardDefinitionListVariable(boostDefinition);
        DefinitionFilterEndpoints boostFilter = editor.AddFilterCardDefinitionList();
        DefinitionListFilterEndpoints selectedBoost = editor.AddFilterCardDefinitionListNode();
        PowerEndpoints boost = editor.AddChangePower(5, 0, 512, 0, effectType: 1, targetedPower: 0);
        PowerEndpoints armor = editor.AddChangePower(5, 0, 0, 0, effectType: 1, targetedPower: 3);
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        BanishEndpoints banishAfterBoost = editor.AddBanishCards(elementType: 1, attackMethod: 0);
        BanishEndpoints banishAfterArmor = editor.AddBanishCards(elementType: 1, attackMethod: 0);

        editor.AddConnection(owner, hand.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(hand.Out, target.ValidChoices);
        editor.AddConnection(target.Success, mode.FlowIn);
        editor.AddConnection(modes, mode.ValidChoices);
        editor.AddConnection(boostReference, boostFilter.Definitions);
        editor.AddConnection(boostFilter.Out, selectedBoost.Filter);
        editor.AddConnection(mode.SelectedChoices, selectedBoost.Definitions);
        editor.AddConnection(mode.FlowOut, selectedBoost.FlowIn);
        editor.AddConnection(selectedBoost.Success, boost.FlowIn);
        editor.AddConnection(selectedBoost.Fail, armor.FlowIn);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(ownerEntity, armor.Attacker);
        editor.AddConnection(target.SelectedChoices, boost.Targets);
        editor.AddConnection(target.SelectedChoices, armor.Targets);
        editor.AddConnection(boost.FlowOut, banishAfterBoost.FlowIn);
        editor.AddConnection(armor.FlowOut, banishAfterArmor.FlowIn);
        editor.AddConnection(ownerEntity, banishAfterBoost.Attacker);
        editor.AddConnection(ownerEntity, banishAfterArmor.Attacker);
        editor.AddConnection(ownerCards, banishAfterBoost.Targets);
        editor.AddConnection(ownerCards, banishAfterArmor.Targets);
        editor.Finish();
    }

    private static void EnsureEnchantedArmorChoiceTemplates(
        AbilityDocument abilities,
        TemplateDocument templates,
        XElement sourceTemplate,
        IDictionary<string, string> localizationEdits)
    {
        EnsureEmptyChoiceCardAbility(abilities, EnchantedArmorBoostChoice);
        EnsureEmptyChoiceCardAbility(abilities, EnchantedArmorArmorChoice);

        XElement root = templates.Document.Root
            ?? throw new InvalidOperationException("Templates.xml does not have a root element.");
        foreach (int id in new[] { EnchantedArmorBoostChoice, EnchantedArmorArmorChoice })
            templates.FindById(id)?.Remove();

        XElement CreateChoice(int id, string debugName)
        {
            var clone = new XElement(sourceTemplate);
            clone.SetAttributeValue("Id", id);
            clone.SetAttributeValue("DebugName", debugName);
            clone.SetAttributeValue("Availability", "0");

            // Native cards used only as template-choice options (for example,
            // Shaping Nature 202700-202702) use Type=2 rather than retaining
            // the playable card type. Keeping Enchanted Armor's Type=16 made
            // these technical options appear as separate collection cards.
            SetTemplateText(clone, "Type", "2");
            SetTemplateText(clone, "InitialTimer", "-1");
            SetTemplateText(clone, "InitalTapCharges", "0");
            SetTemplateText(clone, "TapActive", "False");
            SetTemplateText(clone, "SummoningSickness", "False");
            SetTemplateText(clone, "VisibleTapCharges", "False");
            SetTemplateText(clone, "Madness", "False");

            XElement placement = clone.Element("Placement")
                ?? throw new InvalidDataException("Enchanted Armor choice template has no Placement.");
            placement.SetAttributeValue("PlayerSide", "1023");
            placement.SetAttributeValue("OpponentSide", "1023");
            return clone;
        }

        root.Add(
            CreateChoice(EnchantedArmorBoostChoice, "Enchanted Armor: Boost Choice"),
            CreateChoice(EnchantedArmorArmorChoice, "Enchanted Armor: Armor Choice"));

        localizationEdits[$"{EnchantedArmorBoostChoice}_name"] = "Усиление";
        localizationEdits[$"{EnchantedArmorBoostChoice}_tooltip"] =
            "Усильте отряд в вашей руке на 5 ед.";
        localizationEdits[$"{EnchantedArmorArmorChoice}_name"] = "Добавление брони";
        localizationEdits[$"{EnchantedArmorArmorChoice}_tooltip"] =
            "Добавьте отряду в вашей руке 5 ед. <keyword=armor>брони</keyword>.";
    }

    private static void EnsureEmptyChoiceCardAbility(AbilityDocument abilities, int cardId)
    {
        XElement root = abilities.Document.Root
            ?? throw new InvalidOperationException("Abilities.xml does not have a root element.");
        XElement? existing = abilities.FindCardAbility(cardId);
        if (existing != null)
            existing.Remove();

        int nextNId = root.Elements("Ability")
            .Select(element => (int?)element.Attribute("NId") ?? 0)
            .DefaultIfEmpty(0)
            .Max() + 1;
        root.Add(new XElement("Ability",
            new XAttribute("Type", "CardAbility"),
            new XAttribute("NId", nextNId),
            new XAttribute("Id", cardId),
            new XAttribute("TributeVarID", 0),
            new XAttribute("ProfitVarID", 0),
            new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("Nodes"),
            new XElement("Connections")));
    }

