    private static void NormalizeSwallowOrderHeal(XElement ability)
    {
        EnsureAbilityContainers(ability);

        List<XElement> heals = ability.Element("Nodes")?.Elements()
            .Where(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                string.Equals((string?)node.Element("Operation")?.Attribute("V"), "4", StringComparison.Ordinal) &&
                string.Equals((string?)node.Element("Power")?.Attribute("V"), "9999", StringComparison.Ordinal))
            .ToList() ?? new List<XElement>();
        if (heals.Count == 1)
            return;
        if (heals.Count > 1)
            throw new InvalidDataException(
                $"Swallow: найдено несколько полных Heal ChangePowerNode ({heals.Count}).");

        List<XElement> resets = ability.Element("Nodes")?.Elements()
            .Where(node =>
                string.Equals((string?)node.Attribute("Type"), "ResetCardsNode", StringComparison.Ordinal) &&
                string.Equals((string?)node.Element("ResetMode")?.Attribute("V"), "1", StringComparison.Ordinal))
            .ToList() ?? new List<XElement>();
        if (resets.Count != 1)
            throw new InvalidDataException(
                $"Swallow: ожидался один ResetCardsNode ResetMode=1, найдено {resets.Count}.");

        XElement reset = resets[0];
        int nextId = ability.DescendantsAndSelf()
            .Attributes("Id")
            .Select(attribute => int.TryParse(attribute.Value, out int id) ? id : 0)
            .DefaultIfEmpty(0)
            .Max() + 1;

        XElement Existing(string name) =>
            new XElement(reset.Element(name)
                ?? throw new InvalidDataException($"Swallow ResetCardsNode не содержит {name}."));

        XElement Field(string name, string type, string value, string? genericArgument = null)
        {
            var field = new XElement(name,
                new XAttribute("Type", type),
                new XAttribute("Id", nextId++),
                new XAttribute("ExternalOut", "False"),
                new XAttribute("ExternalIn", "False"),
                new XAttribute("ResetInInactive", "False"),
                new XAttribute("V", value));
            if (genericArgument != null)
                field.SetAttributeValue("GArg", genericArgument);
            return field;
        }

        var heal = new XElement("e",
            new XAttribute("Type", "ChangePowerNode"),
            new XAttribute("Id", (int?)reset.Attribute("Id")
                ?? throw new InvalidDataException("Swallow ResetCardsNode не содержит Id.")),
            new XAttribute("X", (int?)reset.Attribute("X") ?? 0),
            new XAttribute("Y", (int?)reset.Attribute("Y") ?? 0),
            Existing("FlowIn"),
            Existing("FlowOut"),
            Existing("Attacker"),
            Existing("Targets"),
            Field("ElementType", "EnumVar`1", "512", "EElementType"),
            Field("AttackMethod", "EnumVar`1", "1", "EAttackMethod"),
            Field("EffectType", "EnumVar`1", "0", "EEffectType"),
            Field("Operation", "EnumVar`1", "4", "ECardPowerOp"),
            Field("TargetedPower", "EnumVar`1", "0", "EPowerType"),
            Field("Power", "IntVar", "9999"),
            Field("IgnoreArmor", "BoolVar", "False"));

        reset.ReplaceWith(heal);
    }

    private static void RebuildIvoPotionDeckPlay(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("IvoPotionDeckPlayV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 14,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints potion = editor.AddFilterCardCategory(0, 32UL, 0);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        PlayEndpoints play = editor.AddPlayCards();

        TriggerEndpoints refresh = editor.AddOnPlayRefreshLocationTargetsTrigger();
        GetLocationsEndpoints melee = editor.AddGetLocations(locationMask: 1);
        RecommendedLocationsEndpoints recommended =
            editor.AddChangeRecommendedLocations(operation: 1);

        editor.AddConnection(deploy.FlowOut, row.FlowIn);
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(row.Melee, eligible.FlowIn);
        editor.AddConnection(deck.Out, eligible.Cards);
        editor.AddConnection(potion.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, choice.FlowIn);
        editor.AddConnection(eligible.FilteredCards, choice.ValidChoices);
        editor.AddConnection(choice.Success, play.FlowIn);
        editor.AddConnection(choice.SelectedChoices, play.Cards);
        editor.AddConnection(owner, melee.PlayerMask);
        editor.AddConnection(refresh.FlowOut, recommended.FlowIn);
        editor.AddConnection(melee.Out, recommended.Locations);
        editor.Finish();
    }

    private static void RebuildLambertPotionDeathblow(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("LambertPotionDeathblowV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Damage", 3);
        editor.EnsureIntVariable("DamageInfused", 6);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(
            min: 1, max: 1, aiHintE0: 8_388_608L);
        int ownerCard = editor.AddGetAbilityOwnerCardNode();
        int ownerEntity = editor.AddGetAbilityOwner();
        HasInjectedAbilityEndpoints hasInfusion = editor.AddHasInjectedAbility(
            injectableAbilityId: 0,
            hasAnyInjectableAbility: true);
        BranchEndpoints infusionBranch = editor.AddBranch();
        PowerEndpoints damageThree = editor.AddChangePower(3, operation: 1);
        PowerEndpoints damageSix = editor.AddChangePower(6, operation: 1);

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(deploy.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.Success, hasInfusion.FlowIn);
        editor.AddConnection(ownerCard, hasInfusion.Target);
        editor.AddConnection(hasInfusion.FlowOut, infusionBranch.FlowIn);
        editor.AddConnection(hasInfusion.Result, infusionBranch.Condition);

        editor.AddConnection(infusionBranch.False, damageThree.FlowIn);
        editor.AddConnection(target.SelectedTargets, damageThree.Targets);
        editor.AddConnection(ownerEntity, damageThree.Attacker);
        editor.AddConnection(infusionBranch.True, damageSix.FlowIn);
        editor.AddConnection(target.SelectedTargets, damageSix.Targets);
        editor.AddConnection(ownerEntity, damageSix.Attacker);

        AddLambertPotionDeathblowPath(
            editor,
            damageThree.FlowOut,
            target.SelectedTargets);
        AddLambertPotionDeathblowPath(
            editor,
            damageSix.FlowOut,
            target.SelectedTargets);
        editor.Finish();
    }

    private static void AddLambertPotionDeathblowPath(
        GraphEditor editor,
