        editor.AddConnection(eligible.FilteredCards, random.List);
        editor.AddConnection(random.Card, singleton.Card);
        editor.AddConnection(random.FlowOut, play.FlowIn);
        editor.AddConnection(singleton.List, play.Cards);
    }

    private static void RebuildPetrisPhilterWitcherInfusion(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("PetrisPhilterWitcherInfusionV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("BoostDeploy", 3);
        editor.EnsureIntVariable("BoostOrder", 1);
        editor.EnsureIntVariable("Armor", 2);
        int infusionVariable = editor.AddInjectableVariable(
            "InjectableAbility", PetriInvulnerabilityInjectable);
        int infusionValue = editor.AddGetInjectableVariable(infusionVariable);

        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints friendlies = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        editor.AddConnection(ownerPlayer, friendlies.PlayerId);
        NodeEndpoints witcher = editor.AddFilterCardCategory(2_147_483_648UL, 0, 0);

        // Deploy: Boost 3; Witchers also receive 2 Armor.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        TargetRequestEndpoints deployTarget = editor.AddRequestCardTargets(
            min: 1, max: 1, aiHintE0: 2_147_483_648L);
        PowerEndpoints deployBoost = editor.AddChangePower(
            3, operation: 0, elementType: 512, attackMethod: 0, effectType: 1);
        FilterListEndpoints deployWitcher = editor.AddFilterCardList();
        ArmorEndpoints deployArmor = editor.AddChangeArmor(
            amount: 2, operation: 0);

        editor.AddConnection(deploy.FlowOut, deployTarget.FlowIn);
        editor.AddConnection(friendlies.Out, deployTarget.ValidTargets);
        editor.AddConnection(deployTarget.Success, deployBoost.FlowIn);
        editor.AddConnection(deployTarget.SelectedTargets, deployBoost.Targets);
        editor.AddConnection(ownerEntity, deployBoost.Attacker);
        editor.AddConnection(deployBoost.FlowOut, deployWitcher.FlowIn);
        editor.AddConnection(deployTarget.SelectedTargets, deployWitcher.Cards);
        editor.AddConnection(witcher.Out, deployWitcher.Filter);
        editor.AddConnection(deployWitcher.Success, deployArmor.FlowIn);
        editor.AddConnection(deployWitcher.FilteredCards, deployArmor.Targets);
        editor.AddConnection(ownerEntity, deployArmor.Attacker);

        // Order: Witchers receive the Invulnerability Infusion instead of
        // Boost/Armor. Other units receive Boost 1 and Armor 2.
        TriggerEndpoints order = editor.AddTappedTrigger();
        TargetRequestEndpoints orderTarget = editor.AddRequestCardTargets(
            min: 1, max: 1, aiHintE0: 2_147_483_648L);
        FilterListEndpoints orderWitcher = editor.AddFilterCardList();
        SubAbilityEndpoints infusion = editor.AddInfusionSubAbility();
        TokenEndpoints immunity = editor.AddChangeTokens(
            token: 256, elementType: 1, attackMethod: 0);
        PowerEndpoints orderBoost = editor.AddChangePower(
            1, operation: 0, elementType: 512, attackMethod: 0, effectType: 1);
        ArmorEndpoints orderArmor = editor.AddChangeArmor(
            amount: 2, operation: 0);

        editor.AddConnection(order.FlowOut, orderTarget.FlowIn);
        editor.AddConnection(friendlies.Out, orderTarget.ValidTargets);
        editor.AddConnection(orderTarget.Success, orderWitcher.FlowIn);
        editor.AddConnection(orderTarget.SelectedTargets, orderWitcher.Cards);
        editor.AddConnection(witcher.Out, orderWitcher.Filter);

        editor.AddConnection(orderWitcher.Success, infusion.FlowIn);
        editor.AddConnection(orderWitcher.FilteredCards, infusion.Targets);
        editor.AddConnection(infusionValue, infusion.InjectableAbility);
        editor.AddConnection(infusion.FlowOut, immunity.FlowIn);
        editor.AddConnection(orderWitcher.FilteredCards, immunity.Targets);
        editor.AddConnection(ownerEntity, immunity.Attacker);

        editor.AddConnection(orderWitcher.Fail, orderBoost.FlowIn);
        editor.AddConnection(orderWitcher.NotFilteredCards, orderBoost.Targets);
        editor.AddConnection(ownerEntity, orderBoost.Attacker);
        editor.AddConnection(orderBoost.FlowOut, orderArmor.FlowIn);
        editor.AddConnection(orderWitcher.NotFilteredCards, orderArmor.Targets);
        editor.AddConnection(ownerEntity, orderArmor.Attacker);

        editor.Finish();
    }

    private static void RebuildBlackBloodWitcherInfusion(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("BlackBloodWitcherInfusionV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("SetPower", 1);
        int infusionVariable = editor.AddInjectableVariable(
            "InjectableAbility", BlackBloodRetaliationInjectable);
        int infusionValue = editor.AddGetInjectableVariable(infusionVariable);

        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        NodeEndpoints witcher = editor.AddFilterCardCategory(2_147_483_648UL, 0, 0);

        // Deploy: all friendly Witchers in hand, deck and on the board.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        GetCardsEndpoints witcherZones = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 27,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        FilterListEndpoints allWitchers = editor.AddFilterCardList();
        SubAbilityEndpoints infusion = editor.AddInfusionSubAbility();

        editor.AddConnection(owner, witcherZones.PlayerId);
        editor.AddConnection(deploy.FlowOut, allWitchers.FlowIn);
        editor.AddConnection(witcherZones.Out, allWitchers.Cards);
        editor.AddConnection(witcher.Out, allWitchers.Filter);
        editor.AddConnection(allWitchers.Success, infusion.FlowIn);
        editor.AddConnection(allWitchers.FilteredCards, infusion.Targets);
        editor.AddConnection(infusionValue, infusion.InjectableAbility);

        // Order: choose a bronze Witcher definition from the starting deck,
        // create and play it, then set its current power to 1.
        TriggerEndpoints order = editor.AddTappedTrigger();
        InitialDeckEndpoints initial = editor.AddGetInitialDeckDefinitions(
            unique: true,
            tier: 2,
            cardType: 4);
        NodeEndpoints initialWitcher =
            editor.AddFilterCardDefinitionCategory(2_147_483_648UL, 0, 0);
        DefinitionListFilterEndpoints eligible = editor.AddFilterCardDefinitionListNode();
        CreatePlayEndpoints create = editor.AddCreateAndPlaySubAbilityWithPlayFlag();
        PowerEndpoints setPower = editor.AddChangePower(
            1, operation: 2, elementType: 0, attackMethod: 0);

        editor.AddConnection(owner, initial.PlayerId);
        editor.AddConnection(order.FlowOut, eligible.FlowIn);
        editor.AddConnection(initial.Out, eligible.Definitions);
        editor.AddConnection(initialWitcher.Out, eligible.Filter);
        // SubAbility 44 already contains its own RequestTemplateChoiceNode.
        // Passing a preselected definition caused the same Witcher choice to
        // require confirmation twice.
        editor.AddConnection(eligible.Success, create.FlowIn);
        editor.AddConnection(eligible.FilteredDefinitions, create.Definitions);
        editor.AddConnection(create.FlowOut, setPower.FlowIn);
        editor.AddConnection(create.PlayedCards, setPower.Targets);
        editor.AddConnection(ownerEntity, setPower.Attacker);
        editor.Finish();
    }

    private static void EnsurePetriInvulnerabilityInjectable(
        AbilityDocument abilities)
    {
        XElement root = abilities.Document.Root
            ?? throw new InvalidOperationException("Abilities.xml does not have a root element.");
        XElement? existing = root.Elements("Ability").FirstOrDefault(candidate =>
            string.Equals((string?)candidate.Attribute("Type"), "InjectableAbility", StringComparison.Ordinal) &&
            (int?)candidate.Attribute("Id") == PetriInvulnerabilityInjectable);
        existing?.Remove();

        int nextNId = root.Elements("Ability")
            .Select(element => (int?)element.Attribute("NId") ?? 0)
            .DefaultIfEmpty(0)
            .Max() + 1;
        var injectable = new XElement("Ability",
            new XAttribute("Type", "InjectableAbility"),
            new XAttribute("NId", nextNId),
            new XAttribute("Id", PetriInvulnerabilityInjectable),
            new XAttribute("TributeVarID", 0),
            new XAttribute("ProfitVarID", 0),
            new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("Nodes"),
            new XElement("Connections"));
        root.Add(injectable);

        var editor = new GraphEditor(injectable);
        editor.EnsureIntVariable("Adrenaline", 2);
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        TurnTriggerEndpoints endTurn = editor.AddAfterTurnTrigger(ownerLocation: 3);
        GetCardsEndpoints hand = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 8,
            cardTypes: 14,
            cardTiers: 10,
            ignoreOwner: false);
        CardListLengthEndpoints handSize = editor.AddCardListLength();
        IntBranchEndpoints adrenaline = editor.AddIntBranch();

        // Do not call generic Purify SubAbility 45 from inside the Infusion.
        // Its first action is ClearAllInjectedAbilitiesNode, which removes the
        // currently executing Infusion before PurifyCardStatusesNode and the
        // ResetMode=128 client refresh can finish. The server state changes,
        // but the Purify animation and status icons may remain stale.
        AddVisibleSelfPurifyPath(
            editor,
            adrenaline.Equal,
            ownerEntity,
            ownerCards);
        AddVisibleSelfPurifyPath(
            editor,
            adrenaline.Smaller,
            ownerEntity,
            ownerCards);

        editor.AddConnection(ownerPlayer, endTurn.PlayerFilter);
        editor.AddConnection(ownerPlayer, hand.PlayerId);
        editor.AddConnection(hand.Out, handSize.List);
        editor.AddConnection(endTurn.FlowOut, adrenaline.FlowIn);
        editor.AddConnection(handSize.Length, adrenaline.A);
        SetEndpointValue(injectable, adrenaline.B, "2");
        editor.Finish();
    }

    private static void AddVisibleSelfPurifyPath(
        GraphEditor editor,
        int sourceFlow,
        int ownerEntity,
        int ownerCards)
    {
        StatusChangeEndpoints purify = editor.AddPurifyCardStatuses(
            elementType: 1,
            attackMethod: 1,
            effectType: 0);
        ResetEndpoints refresh = editor.AddResetCards(
            resetMode: 128,
            elementType: 0,
            attackMethod: 0,
            effectType: 0);
        StatusChangeEndpoints clearInfusions = editor.AddClearAllInjectedAbilities(
            elementType: 1,
            attackMethod: 0,
            effectType: 0);

        editor.AddConnection(sourceFlow, purify.FlowIn);
        editor.AddConnection(ownerEntity, purify.Attacker);
        editor.AddConnection(ownerCards, purify.Targets);

        editor.AddConnection(purify.FlowOut, refresh.FlowIn);
        editor.AddConnection(ownerEntity, refresh.Attacker);
        editor.AddConnection(ownerCards, refresh.Targets);

        // Remove IA 43 only after Purify VFX and the client status refresh.
        editor.AddConnection(refresh.FlowOut, clearInfusions.FlowIn);
        editor.AddConnection(ownerEntity, clearInfusions.Attacker);
        editor.AddConnection(ownerCards, clearInfusions.Targets);
    }

    private static void EnsureBlackBloodRetaliationInjectable(
        AbilityDocument abilities)
    {
        XElement root = abilities.Document.Root
            ?? throw new InvalidOperationException("Abilities.xml does not have a root element.");
        XElement? existing = root.Elements("Ability").FirstOrDefault(candidate =>
            string.Equals((string?)candidate.Attribute("Type"), "InjectableAbility", StringComparison.Ordinal) &&
            (int?)candidate.Attribute("Id") == BlackBloodRetaliationInjectable);
        existing?.Remove();

        int nextNId = root.Elements("Ability")
            .Select(element => (int?)element.Attribute("NId") ?? 0)
            .DefaultIfEmpty(0)
            .Max() + 1;
        var injectable = new XElement("Ability",
            new XAttribute("Type", "InjectableAbility"),
            new XAttribute("NId", nextNId),
            new XAttribute("Id", BlackBloodRetaliationInjectable),
            new XAttribute("TributeVarID", 0),
            new XAttribute("ProfitVarID", 0),
            new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables")),
            new XElement("Nodes"),
            new XElement("Connections"));
        root.Add(injectable);

        var editor = new GraphEditor(injectable);
        editor.EnsureIntVariable("Bleeding", 2);
        AfterChangePowerEndpoints damaged = editor.AddAfterChangePowerTrigger(
            ownerLocation: 3,
            targetCard: 1,
            powerOp: 2);
        CardPowerAttackDeltaEndpoints actualDamage =
            editor.AddCardPowerAttackGetTotalPowerDelta();
        IntBranchEndpoints positiveDamage = editor.AddIntBranch();
        CardAttackCardEndpoints attacker = editor.AddAttackGetCardAttacker();
        ElementListEndpoints attackerList = editor.AddCardElementToList();
        NodeEndpoints unit = editor.AddFilterCardType(4);
        FilterListEndpoints unitAttacker = editor.AddFilterCardList();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        NodeEndpoints opponentFilter = editor.AddFilterCardPlayerId();
        FilterListEndpoints enemyAttacker = editor.AddFilterCardList();
        StatusTimerEndpoints bleeding = editor.AddBleeding(2);
        int ownerEntity = editor.AddGetAbilityOwner();

        editor.AddConnection(damaged.CardPowerAttack, actualDamage.Attack);
        editor.AddConnection(damaged.CardPowerAttack, attacker.Attack);
        editor.AddConnection(actualDamage.Delta, positiveDamage.A);
        SetEndpointValue(injectable, positiveDamage.B, "0");
        editor.AddConnection(damaged.FlowOut, positiveDamage.FlowIn);
        editor.AddConnection(attacker.Card, attackerList.Card);

        editor.AddConnection(positiveDamage.Smaller, unitAttacker.FlowIn);
        editor.AddConnection(attackerList.List, unitAttacker.Cards);
        editor.AddConnection(unit.Out, unitAttacker.Filter);

        editor.AddConnection(opponent, opponentFilter.PowerInput);
        editor.AddConnection(unitAttacker.Success, enemyAttacker.FlowIn);
        editor.AddConnection(unitAttacker.FilteredCards, enemyAttacker.Cards);
        editor.AddConnection(opponentFilter.Out, enemyAttacker.Filter);

        editor.AddConnection(enemyAttacker.Success, bleeding.FlowIn);
        editor.AddConnection(enemyAttacker.FilteredCards, bleeding.Cards);
        editor.AddConnection(ownerEntity, bleeding.Attacker);
        editor.Finish();
    }

    private static void AddTemplateCategory(
        XElement template,
        string fieldName,
        CategoryDefinition category)
    {
        XElement field = template.Element(fieldName)
            ?? throw new InvalidDataException(
                $"Template {template.Attribute("Id")} не содержит {fieldName}.");
        XElement slot = field.Element($"e{category.Slot}")
            ?? throw new InvalidDataException(
                $"{fieldName}/e{category.Slot} не найден для Template {template.Attribute("Id")}.");

        ulong current = ulong.TryParse((string?)slot.Attribute("V"), out ulong parsed)
            ? parsed
            : throw new InvalidDataException(
                $"{fieldName}/e{category.Slot} не содержит корректный ulong V.");
        slot.SetAttributeValue("V", current | category.Mask);
    }

    private static void NormalizeAlzursThunderDamageVfx(XElement ability)
    {
        List<XElement> damageNodes = ability.Element("Nodes")?.Elements()
            .Where(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                string.Equals((string?)node.Element("Operation")?.Attribute("V"), "1", StringComparison.Ordinal))
            .ToList() ?? new List<XElement>();

        XElement primary = damageNodes.SingleOrDefault(node =>
            string.Equals((string?)node.Element("Power")?.Attribute("V"), "7", StringComparison.Ordinal))
            ?? throw new InvalidDataException(
                $"Alzur's Thunder: ожидался один основной ChangePowerNode урона 7, найдено " +
                $"{damageNodes.Count(node => (string?)node.Element("Power")?.Attribute("V") == "7")}.");

        XElement additional = damageNodes.SingleOrDefault(node =>
            string.Equals((string?)node.Element("Power")?.Attribute("V"), "1", StringComparison.Ordinal))
            ?? throw new InvalidDataException(
                $"Alzur's Thunder: ожидался один дополнительный ChangePowerNode урона 1, найдено " +
                $"{damageNodes.Count(node => (string?)node.Element("Power")?.Attribute("V") == "1")}.");

        CopyPowerVisualParameters(primary, additional);
    }

    private static void NormalizeNennekeInfusionVfx(
        AbilityDocument document,
        XElement ability)
    {
        XElement infusionVariable = ability.Element("TemporaryVariables")?.Elements()
            .Concat(ability.Element("PersistentVariables")?.Elements() ?? Enumerable.Empty<XElement>())
            .SingleOrDefault(variable =>
                string.Equals((string?)variable.Attribute("Type"), "InjectableAbilityVar", StringComparison.Ordinal) &&
                string.Equals((string?)variable.Attribute("Name"), "Infusion", StringComparison.Ordinal))
            ?? throw new InvalidDataException("Nenneke InjectableAbilityVar Infusion не найдена.");

        int sourceId = (int?)infusionVariable.Attribute("V")
            ?? throw new InvalidDataException("Nenneke Infusion не содержит InjectableAbility Id.");
        XElement root = document.Document.Root
            ?? throw new InvalidDataException("Abilities.xml не содержит root.");

        XElement? dedicated = root.Elements("Ability").FirstOrDefault(candidate =>
            string.Equals((string?)candidate.Attribute("Type"), "InjectableAbility", StringComparison.Ordinal) &&
            (int?)candidate.Attribute("Id") == NennekeStandardBoostInjectable);

        if (sourceId != NennekeStandardBoostInjectable)
        {
            XElement source = root.Elements("Ability").SingleOrDefault(candidate =>
                string.Equals((string?)candidate.Attribute("Type"), "InjectableAbility", StringComparison.Ordinal) &&
                (int?)candidate.Attribute("Id") == sourceId)
                ?? throw new InvalidDataException($"Nenneke source InjectableAbility Id={sourceId} не найдена.");

            dedicated?.Remove();
            dedicated = new XElement(source);
            dedicated.SetAttributeValue("Id", NennekeStandardBoostInjectable);
            root.Add(dedicated);
        }

        if (dedicated == null)
            throw new InvalidDataException("Nenneke dedicated standard-Boost InjectableAbility не создана.");

        List<XElement> boostNodes = dedicated.Element("Nodes")?.Elements()
            .Where(node =>
                string.Equals((string?)node.Attribute("Type"), "ChangePowerNode", StringComparison.Ordinal) &&
                string.Equals((string?)node.Element("Operation")?.Attribute("V"), "0", StringComparison.Ordinal))
            .ToList() ?? new List<XElement>();
        if (boostNodes.Count != 1)
            throw new InvalidDataException($"Nenneke standard Infusion: ожидался один Boost ChangePowerNode, найдено {boostNodes.Count}.");

        XElement boost = boostNodes[0];
        boost.Element("ElementType")?.SetAttributeValue("V", "512");
        boost.Element("AttackMethod")?.SetAttributeValue("V", "0");
        boost.Element("EffectType")?.SetAttributeValue("V", "1");
        infusionVariable.SetAttributeValue("V", NennekeStandardBoostInjectable);
    }

    private static void RebuildInspirationalBalladWithElf(XElement ability)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("InspirationalBalladElfV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        editor.EnsureIntVariable("Vitality", 6);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints friendly = editor.AddGetCards(0, 3, 4, 10, false);
        editor.AddConnection(owner, friendly.PlayerId);

        (ulong E0, ulong E1, ulong E2)[] categories =
        {
            (2_147_483_648UL, 0, 0),
            (140_737_488_355_328UL, 0, 0),
            (0, 16_384UL, 0),
            (65_536UL, 0, 0),
            (549_755_813_888UL, 0, 0)
        };
        int previousFlow = deploy.FlowOut;
        for (int index = 0; index < categories.Length; index++)
        {
            var category = categories[index];
            NodeEndpoints categoryFilter = editor.AddFilterCardCategory(category.E0, category.E1, category.E2);
            FilterListEndpoints matches = editor.AddFilterCardList();
            RandomCardEndpoints random = editor.AddRandomCard();
            ElementListEndpoints one = editor.AddCardElementToList();
            StatusTimerEndpoints vitality = editor.AddVitality(6);
            editor.AddConnection(previousFlow, matches.FlowIn);
            editor.AddConnection(friendly.Out, matches.Cards);
            editor.AddConnection(categoryFilter.Out, matches.Filter);
            editor.AddConnection(matches.Success, random.FlowIn);
            editor.AddConnection(matches.FilteredCards, random.List);
            editor.AddConnection(random.Card, one.Card);
            editor.AddConnection(random.FlowOut, vitality.FlowIn);
            editor.AddConnection(ownerEntity, vitality.Attacker);
            editor.AddConnection(one.List, vitality.Cards);
            if (index + 1 < categories.Length)
            {
                BranchEndpoints continueOnFail = editor.AddBranch();
                SetEndpointValue(ability, continueOnFail.Condition, "True");
                editor.AddConnection(matches.Fail, continueOnFail.FlowIn);
                editor.AddConnection(vitality.FlowOut, continueOnFail.FlowIn);
                previousFlow = continueOnFail.True;
            }
        }
        editor.Finish();
    }

