    private static IReadOnlyList<int> InstallVattierOpponentDeckLookGrowth(AbilityDocument abilities)
    {
        var changed = new List<int>();
        XElement? root = abilities.Document.Root;
        if (root == null) return changed;
        foreach (XElement ability in root.Elements("Ability").Where(a => (string?)a.Attribute("Type") == "CardAbility"))
        {
            if ((int?)ability.Attribute("Id") == VattierDeRideaux) continue;
            if (ability.Element("TemporaryVariables")?.Elements()
                .Any(v => (string?)v.Attribute("Name") == "VattierOpponentDeckLookBoostV2") == true)
            {
                continue;
            }
            if (ability.Element("Nodes") == null || ability.Element("Connections") == null) continue;
            var editor = new GraphEditor(ability);
            bool modified = false;
            foreach (XElement look in editor.Nodes.Elements().Where(n =>
                         (string?)n.Attribute("Type") is "RequestCardChoiceNode" or "RevealCardsNode").ToList())
            {
                if (!IsOpponentDeckLookNode(editor, look)) continue;
                XElement? flow = look.Element("FlowOutSuccess") ?? look.Element("FlowSuccess") ?? look.Element("FlowOut");
                if (flow == null) continue;
                int sourceFlow = Id(flow);
                List<int> oldTargets = editor.GetOutgoingTargets(sourceFlow).ToList();
                if (oldTargets.Count == 0) continue;
                foreach (int target in oldTargets) editor.RemoveConnection(sourceFlow, target);
                int owner = editor.AddGetOwnerPlayerId();
                int ownerEntity = editor.AddGetAbilityOwner();
                GetCardsEndpoints zones = editor.AddGetCards(ignoreTokens: 0, locationId: 27, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
                NodeEndpoints vattier = editor.AddFilterCardTemplateId(VattierDeRideaux);
                FilterListEndpoints copies = editor.AddFilterCardList();
                PowerEndpoints boost = editor.AddChangePower(1, 0, 512, 0);
                editor.AddConnection(owner, zones.PlayerId);
                editor.AddConnection(sourceFlow, copies.FlowIn);
                editor.AddConnection(zones.Out, copies.Cards);
                editor.AddConnection(vattier.Out, copies.Filter);
                editor.AddConnection(copies.Success, boost.FlowIn);
                editor.AddConnection(ownerEntity, boost.Attacker);
                editor.AddConnection(copies.FilteredCards, boost.Targets);
                foreach (int target in oldTargets)
                {
                    editor.AddConnection(boost.FlowOut, target);
                    editor.AddConnection(copies.Fail, target);
                }
                modified = true;
            }
            if (modified)
            {
                int marker = editor.EnsureIntVariable("VattierOpponentDeckLookBoostV2", 1);
                editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
                    .SetAttributeValue("HideInTooltip", "True");
                editor.Finish();
                changed.Add((int)ability.Attribute("Id")!);
            }
        }
        return changed;
    }

    private static bool IsOpponentDeckLookNode(GraphEditor editor, XElement look)
    {
        XElement? input = look.Element("ValidChoices") ?? look.Element("Cards");
        if (input == null) return false;
        var queue = new Queue<int>(editor.GetIncomingSources(Id(input)));
        var visited = new HashSet<int>();
        while (queue.Count > 0)
        {
            int endpoint = queue.Dequeue();
            if (!visited.Add(endpoint)) continue;
            XElement? node = editor.FindNodeOwningEndpoint(endpoint);
            if (node == null) continue;
            if ((string?)node.Attribute("Type") == "GetCardsNode" &&
                (string?)node.Element("LocationId")?.Attribute("V") == "16")
            {
                XElement? player = node.Element("PlayerId");
                if (player != null)
                {
                    foreach (int src in editor.GetIncomingSources(Id(player)))
                    {
                        XElement? playerNode = editor.FindNodeOwningEndpoint(src);
                        if ((string?)playerNode?.Attribute("Type") == "GetOwnerOpponentPlayerIdNode")
                            return true;
                    }
                }
            }
            foreach (XElement endpointElement in node.DescendantsAndSelf().Where(e => e.Attribute("Id") != null))
            {
                foreach (int src in editor.GetIncomingSources(Id(endpointElement))) queue.Enqueue(src);
            }
        }
        return false;
    }

    private static readonly HashSet<int> CreativeMadnessUnitIds = new()
    {
        202295, // Renegade Mage
        202357, // Arena Ghoul
        202351, // Arena Endrega
        202385, // Sir Skewertooth
        202564, // Greater Brothers
        202307, // Horst Borsodi
        202309, // Ewald Borsodi
        202333, // Boris
        202324, // Tinboy
    };

    private static int[] GetMadnessUnitTemplateIds(TemplateDocument templates) =>
        templates.CardTemplates
            .Where(template => string.Equals(template.Element("Type")?.Value, "4", StringComparison.Ordinal))
            .Where(template =>
            {
                int id = (int?)template.Attribute("Id") ?? 0;
                return string.Equals(template.Element("Madness")?.Value, "True", StringComparison.OrdinalIgnoreCase) ||
                       CreativeMadnessUnitIds.Contains(id);
            })
            .Select(template => (int?)template.Attribute("Id") ?? 0)
            .Where(id => id > 0)
            .Distinct()
            .OrderBy(id => id)
            .ToArray();

    private static int BuildTemplateIdCardFilter(GraphEditor editor, IEnumerable<int> templateIds)
    {
        int[] filters = templateIds
            .Distinct()
            .Select(id => editor.AddFilterCardTemplateId(id).Out)
            .ToArray();
        if (filters.Length == 0)
            throw new InvalidOperationException("Не найдено ни одной карты для динамического фильтра шаблонов.");
        return CombineCardFiltersOr(editor, filters);
    }

    private static void AddBartMissingGangDeckPlay(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "BartMissingGangDeckPlayV2", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("BartMissingGangDeckPlayV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int gangs = editor.AddCardCategoryVariable("BartGangCategories", 0, 2_262_374_023_168UL, 0);
        int candidatesVar = editor.AddCardListVariable("BartMissingGangCandidates");
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == candidatesVar)
            .SetAttributeValue("ResetInInactive", "True");

        int owner = editor.AddGetOwnerPlayerId();
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        GetCardsEndpoints board = editor.AddGetCards(8, 3, 4, 10, false);
        GetCardsEndpoints deck = editor.AddGetCards(0, 16, 14, 10, false);
        ForeachCategoryEndpoints eachGang = editor.AddForeachCategory();
        int gangValue = editor.AddGetCardCategoryVariable(gangs);

        NodeEndpoints boardGang = editor.AddFilterCardCategory(0, 0, 0);
        FilterListEndpoints controlled = editor.AddFilterCardList();
        NodeEndpoints deckGang = editor.AddFilterCardCategory(0, 0, 0);
        NodeEndpoints syndicate = editor.AddFilterCardFaction(64);
        NodeEndpoints bronze = editor.AddFilterCardTier(2);
        int deckFilter = CombineCardFiltersAnd(editor, deckGang.Out, syndicate.Out, bronze.Out);
        FilterListEndpoints eligibleDeck = editor.AddFilterCardList();
        CardListAppendEndpoints append = editor.AddCardListAppend();
        int candidatesForAppend = editor.AddGetCardListVariable(candidatesVar);
        int candidatesForPlay = editor.AddGetCardListVariable(candidatesVar);
        CardListBranchEndpoints anyCandidate = editor.AddCardListBranch();
        CardChoiceEndpoints choice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0, revealChoices: true);
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(owner, board.PlayerId);
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(deploy.FlowOut, eachGang.FlowIn);
        editor.AddConnection(gangValue, eachGang.Categories);
        editor.AddConnection(eachGang.FlowFor, controlled.FlowIn);
        editor.AddConnection(board.Out, controlled.Cards);
        editor.AddConnection(eachGang.Item, boardGang.PowerInput);
        editor.AddConnection(boardGang.Out, controlled.Filter);
        editor.AddConnection(controlled.Fail, eligibleDeck.FlowIn);
        editor.AddConnection(deck.Out, eligibleDeck.Cards);
        editor.AddConnection(eachGang.Item, deckGang.PowerInput);
        editor.AddConnection(deckFilter, eligibleDeck.Filter);
        editor.AddConnection(eligibleDeck.Success, append.FlowIn);
        editor.AddConnection(candidatesForAppend, append.List);
        editor.AddConnection(eligibleDeck.FilteredCards, append.ListToAppend);
        editor.AddConnection(eachGang.FlowOut, anyCandidate.FlowIn);
        editor.AddConnection(candidatesForPlay, anyCandidate.List);
        editor.AddConnection(anyCandidate.True, choice.FlowIn);
        editor.AddConnection(candidatesForPlay, choice.ValidChoices);
        editor.AddConnection(choice.Success, play.FlowIn);
        editor.AddConnection(choice.SelectedChoices, play.Cards);
        editor.Finish();
    }

