    private static void AddProphetLebiodaLostShieldBoost(XElement ability)
    {
        EnsureAbilityContainers(ability);
        if (ability.Descendants().Any(e =>
                string.Equals((string?)e.Attribute("Name"), "ProphetLebiodaLostShieldBoostV3", StringComparison.Ordinal)))
            return;

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("ProphetLebiodaLostShieldBoostV3", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        // Listen to any unit losing Shield, extract the actually affected cards, then
        // explicitly filter them to the ability owner's side. This avoids relying on
        // EPlayerSide/PlayerMask interaction inside the status trigger.
        ChangedStatusEndpoints shieldLost = editor.AddAfterChangedCardStatusTrigger(3, 3, 1, 2);
        CardAttackTargetsEndpoints targets = editor.AddCardAttackGetTargets();
        NodeEndpoints friendly = editor.AddFilterCardPlayerId();
        FilterListEndpoints friendlyTargets = editor.AddFilterCardList();
        PowerEndpoints boost = editor.AddChangePower(1, 0, 512, 0);

        editor.AddConnection(shieldLost.CardStatusAttack, targets.Attack);
        editor.AddConnection(shieldLost.FlowOut, friendlyTargets.FlowIn);
        editor.AddConnection(targets.Targets, friendlyTargets.Cards);
        editor.AddConnection(owner, friendly.PowerInput);
        editor.AddConnection(friendly.Out, friendlyTargets.Filter);
        editor.AddConnection(friendlyTargets.Success, boost.FlowIn);
        editor.AddConnection(ownerEntity, boost.Attacker);
        editor.AddConnection(friendlyTargets.FilteredCards, boost.Targets);
        editor.Finish();
    }

