    private static void RestoreMadamLuizaVanillaTribute(
        XElement ability,
        XElement template,
        AbilityDocument abilities,
        string abilitiesPath,
        string templatesPath)
    {
        XElement cleanAbility = TryLoadCleanCardAbilityReference(abilitiesPath, MadamLuiza)
            ?? throw new InvalidOperationException("Clean Madam Luiza CardAbility was not found.");
        XElement cleanTemplate = TryLoadCleanTemplateReference(templatesPath, MadamLuiza)
            ?? throw new InvalidOperationException("Clean Madam Luiza Template was not found.");
        CopyAbilityGraphAndOrderTemplate(ability, template, cleanAbility, cleanTemplate);

        RestoreSharedTributeVanilla(abilities, abilitiesPath);
        RequireMadamLuizaVanillaTributeState(abilities, "Madam Luiza operation");
    }

    private static void FinalizeMadamLuizaVanillaTribute(
        AbilityDocument abilities,
        string abilitiesPath)
    {
        RestoreSharedTributeVanilla(abilities, abilitiesPath);
    }

    private static void RestoreSharedTributeVanilla(
        AbilityDocument abilities,
        string abilitiesPath)
    {
        XElement cleanTribute = TryLoadCleanSubAbilityReference(abilitiesPath, 18)
            ?? throw new InvalidOperationException("Clean Tribute SubAbility 18 was not found.");
        XElement currentTribute = abilities.Document.Root?.Elements("Ability")
            .SingleOrDefault(element =>
                string.Equals((string?)element.Attribute("Type"), "SubAbility", StringComparison.Ordinal) &&
                (int?)element.Attribute("AbilityID") == 18)
            ?? throw new InvalidOperationException("Current Tribute SubAbility 18 was not found exactly once.");

        currentTribute.ReplaceWith(new XElement(cleanTribute));
    }

    private static void RequireMadamLuizaVanillaTributeState(
        AbilityDocument abilities,
        string phase)
    {
        XElement luiza = abilities.FindRequiredCardAbility(MadamLuiza);
        XElement[] luizaSetters = luiza.Element("Nodes")?.Elements()
            .Where(node => IsNodeType(node, "SetBlackboardVarNode"))
            .ToArray() ?? Array.Empty<XElement>();

        XElement tribute = abilities.Document.Root?.Elements("Ability")
            .SingleOrDefault(element =>
                string.Equals((string?)element.Attribute("Type"), "SubAbility", StringComparison.Ordinal) &&
                (int?)element.Attribute("AbilityID") == 18)
            ?? throw new InvalidDataException($"{phase}: Tribute SubAbility 18 was not found exactly once.");
        XElement[] tributeGets = tribute.Element("Nodes")?.Elements()
            .Where(node => IsNodeType(node, "GetBlackboardVarNode"))
            .ToArray() ?? Array.Empty<XElement>();
        XElement[] tributeSets = tribute.Element("Nodes")?.Elements()
            .Where(node => IsNodeType(node, "SetBlackboardVarNode"))
            .ToArray() ?? Array.Empty<XElement>();
        XElement[] tributeBoolGets = tributeGets
            .Where(node => string.Equals(
                (string?)node.Element("Out")?.Attribute("Type"), "BoolVar", StringComparison.Ordinal))
            .ToArray();
        XElement[] tributeIntGets = tributeGets
            .Where(node => string.Equals(
                (string?)node.Element("Out")?.Attribute("Type"), "IntVar", StringComparison.Ordinal))
            .ToArray();
        XElement[] tributeBoolSets = tributeSets
            .Where(node => string.Equals(
                (string?)node.Element("In")?.Attribute("Type"), "BoolVar", StringComparison.Ordinal))
            .ToArray();

        static bool IsVanillaRoundFlagNode(XElement node) =>
            (int?)node.Attribute("VarId") == 4 &&
            string.Equals((string?)node.Element("BlackboardType")?.Attribute("V"), "2", StringComparison.Ordinal);
        static bool IsVanillaCostNode(XElement node) =>
            (int?)node.Attribute("VarId") == 2 &&
            string.Equals((string?)node.Element("BlackboardType")?.Attribute("V"), "2", StringComparison.Ordinal);

        if (luizaSetters.Length != 1 || !IsVanillaRoundFlagNode(luizaSetters[0]) ||
            tributeGets.Length != 3 || tributeSets.Length != 1 ||
            tributeBoolGets.Length != 1 || !IsVanillaRoundFlagNode(tributeBoolGets[0]) ||
            tributeBoolSets.Length != 1 || !IsVanillaRoundFlagNode(tributeBoolSets[0]) ||
            tributeIntGets.Length != 2 || !tributeIntGets.All(IsVanillaCostNode))
        {
            string Describe(IEnumerable<XElement> nodes) => string.Join(", ", nodes.Select(node =>
                $"{node.Attribute("Type")?.Value}(VarId={node.Attribute("VarId")?.Value ?? "?"}, BlackboardType={node.Element("BlackboardType")?.Attribute("V")?.Value ?? "?"})"));
            throw new InvalidDataException(
                $"{phase}: Madam Luiza and shared Tribute SubAbility 18 must remain vanilla round-scoped. " +
                $"Luiza=[{Describe(luizaSetters)}], Get=[{Describe(tributeGets)}], Set=[{Describe(tributeSets)}].");
        }
    }


    private static void RebuildTinboyMadnessEngine(
        XElement ability, XElement template, TemplateDocument templates)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        SetTemplateText(template, "Madness", "True");
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "ResetInInactive", "True");

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("TinboyMadnessEngineV4", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int profitVar = editor.EnsurePersistentIntVariable("Profit", 0);
        int tributeVar = editor.EnsureIntVariable("Tribute", 3);
        int costVar = editor.EnsureIntVariable("Cost", 3);
        ability.SetAttributeValue("ProfitVarID", profitVar);
        int[] madnessIds = GetMadnessUnitTemplateIds(templates);
        int madnessCardFilter = BuildTemplateIdCardFilter(editor, madnessIds);
        int owner = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();

        // Profit equals the persistent counter accumulated while Tinboy is in hand or deck.
        IncomeEndpoints income = editor.AddIncomeTrigger();
        ProfitEndpoints profit = editor.AddProfitSubAbility();
        int currentProfit = editor.AddGetIntVariable(profitVar);
        editor.AddConnection(income.FlowOut, profit.FlowIn);
        editor.AddConnection(currentProfit, profit.Income);

        // While in hand/deck, each Madness unit actually played by the owner increments stored Profit.
        AfterMovedEndpoints played = editor.AddAfterMovedTrigger(
            ownerLocation: 24, triggerCard: 2, triggerPlayer: 1,
            fromLocation: 4095, toLocation: 3, reason: 1);
        FilterListEndpoints playedMadness = editor.AddFilterCardList();
        IntPlusEndpoints increment = editor.AddIntPlus();
        SetVarEndpoints storeProfit = editor.AddSetIntVariable(profitVar);
        int profitBeforeIncrement = editor.AddGetIntVariable(profitVar);
        editor.AddConnection(played.FlowOut, playedMadness.FlowIn);
        editor.AddConnection(played.CardsMoved, playedMadness.Cards);
        editor.AddConnection(madnessCardFilter, playedMadness.Filter);
        editor.AddConnection(playedMadness.Success, storeProfit.FlowIn);
        editor.AddConnection(profitBeforeIncrement, increment.A);
        SetEndpointValue(ability, increment.B, "1");
        editor.AddConnection(increment.Result, storeProfit.In);

        // Tribute 3: choose and play a bronze Madness unit from deck.
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        TributeEndpoints tribute = editor.AddTributeSubAbility();
        int tributeCost = editor.AddGetIntVariable(tributeVar);
        GetCardsEndpoints deck = editor.AddGetCards(0, 16, 4, 2, false);
        FilterListEndpoints madnessDeck = editor.AddFilterCardList();
        CardChoiceEndpoints tributeChoice = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0);
        PlayEndpoints play = editor.AddPlayCards();
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(deploy.FlowOut, tribute.FlowIn);
        editor.AddConnection(tributeCost, tribute.Cost);
        editor.AddConnection(tribute.Paid, madnessDeck.FlowIn);
        editor.AddConnection(deck.Out, madnessDeck.Cards);
        editor.AddConnection(madnessCardFilter, madnessDeck.Filter);
        editor.AddConnection(madnessDeck.Success, tributeChoice.FlowIn);
        editor.AddConnection(madnessDeck.FilteredCards, tributeChoice.ValidChoices);
        editor.AddConnection(tributeChoice.Success, play.FlowIn);
        editor.AddConnection(tributeChoice.SelectedChoices, play.Cards);

        // Fee 3: replay a chosen friendly bronze damaged unit whose current power is exactly 1.
        // This copies Teleportation (202930): save target -> stage in location 256 -> PlayCards -> Reset(-17).
        PaidForEndpoints fee = editor.AddPaidForTrigger(costVar);
        GetCardsEndpoints board = editor.AddGetCards(264, 3, 4, 2, true);
        NodeEndpoints damaged = editor.AddFilterCardPowerState(1);
        FilterListEndpoints damagedUnits = editor.AddFilterCardList();
        NodeEndpoints powerOne = editor.AddFilterCardPower(compareOp: 0, power: 1);
        FilterListEndpoints validUnits = editor.AddFilterCardList();
        TargetRequestEndpoints feeTarget = editor.AddRequestCardTargets(1, 1, 0);
        int replayTargetVar = editor.AddCardListVariable("TinboyReplayTarget");
        SetVarEndpoints rememberTarget = editor.AddSetCardListVariable(replayTargetVar);
        int replayTargetForMove = editor.AddGetCardListVariable(replayTargetVar);
        int replayTargetForPlay = editor.AddGetCardListVariable(replayTargetVar);
        int replayTargetForReset = editor.AddGetCardListVariable(replayTargetVar);
        MakeCardPositionEndpoints staging = editor.AddMakeCardPosition(location: 256, index: 0);
        MoveCardsEndpoints moveToStaging = editor.AddMoveCards();
        PlayEndpoints replay = editor.AddPlayCards();
        ResetEndpoints finalReset = editor.AddResetCards(resetMode: -17);
        editor.AddConnection(owner, board.PlayerId);
        editor.AddConnection(fee.FlowOut, damagedUnits.FlowIn);
        editor.AddConnection(board.Out, damagedUnits.Cards);
        editor.AddConnection(damaged.Out, damagedUnits.Filter);
        editor.AddConnection(damagedUnits.Success, validUnits.FlowIn);
        editor.AddConnection(damagedUnits.FilteredCards, validUnits.Cards);
        editor.AddConnection(powerOne.Out, validUnits.Filter);
        editor.AddConnection(validUnits.Success, feeTarget.FlowIn);
        editor.AddConnection(validUnits.FilteredCards, feeTarget.ValidTargets);
        editor.AddConnection(feeTarget.Success, rememberTarget.FlowIn);
        editor.AddConnection(feeTarget.SelectedTargets, rememberTarget.In);
        editor.AddConnection(rememberTarget.FlowOut, staging.FlowIn);
        editor.AddConnection(owner, staging.PlayerId);
        editor.AddConnection(staging.FlowOut, moveToStaging.FlowIn);
        editor.AddConnection(staging.Position, moveToStaging.Position);
        editor.AddConnection(replayTargetForMove, moveToStaging.Cards);
        editor.AddConnection(moveToStaging.FlowOut, replay.FlowIn);
        editor.AddConnection(replayTargetForPlay, replay.Cards);
        editor.AddConnection(replay.FlowOut, finalReset.FlowIn);
        editor.AddConnection(ownerEntity, finalReset.Attacker);
        editor.AddConnection(replayTargetForReset, finalReset.Targets);

        TriggerEndpoints refreshFee = editor.AddRefreshTargetsTrigger(0);
        FilterListEndpoints refreshDamaged = editor.AddFilterCardList();
        FilterListEndpoints refreshPowerOne = editor.AddFilterCardList();
        ChangeTapActiveEndpoints enableFee = editor.AddChangeOwnerPayActive(true);
        ChangeTapActiveEndpoints disableFee = editor.AddChangeOwnerPayActive(false);
        editor.AddConnection(refreshFee.FlowOut, refreshDamaged.FlowIn);
        editor.AddConnection(board.Out, refreshDamaged.Cards);
        editor.AddConnection(damaged.Out, refreshDamaged.Filter);
        editor.AddConnection(refreshDamaged.Success, refreshPowerOne.FlowIn);
        editor.AddConnection(refreshDamaged.FilteredCards, refreshPowerOne.Cards);
        editor.AddConnection(powerOne.Out, refreshPowerOne.Filter);
        editor.AddConnection(refreshPowerOne.Success, enableFee.FlowIn);
        editor.AddConnection(refreshPowerOne.Fail, disableFee.FlowIn);
        editor.AddConnection(refreshDamaged.Fail, disableFee.FlowIn);
        editor.Finish();
    }

