    private static int RebuildIgorMadnessProfitSafe(
        XElement ability,
        XElement template,
        AbilityDocument abilities,
        TemplateDocument templates,
        string abilitiesPath,
        string templatesPath)
    {
        int removedHooks = RemoveIgorMadnessTurnHooks(abilities);

        XElement cleanAbility = TryLoadCleanCardAbilityReference(abilitiesPath, IgorTheHook)
            ?? throw new InvalidOperationException("Clean Igor the Hook CardAbility was not found.");
        XElement cleanTemplate = TryLoadCleanTemplateReference(templatesPath, IgorTheHook)
            ?? throw new InvalidOperationException("Clean Igor the Hook Template was not found.");
        CopyAbilityGraphAndOrderTemplate(ability, template, cleanAbility, cleanTemplate);

        EnsureAbilityContainers(ability);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("IgorMadnessProfitSafeV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int profitVar = editor.EnsureIntVariable("Profit", 0);
        ability.SetAttributeValue("ProfitVarID", profitVar);
        int[] madnessIds = GetMadnessUnitTemplateIds(templates);
        int madnessCardFilter = BuildTemplateIdCardFilter(editor, madnessIds);
        int owner = editor.AddGetOwnerPlayerId();

        IncomeEndpoints income = editor.AddIncomeTrigger();
        GetCardsEndpoints hand = editor.AddGetCards(264, 8, 4, 10, false);
        FilterListEndpoints madnessHand = editor.AddFilterCardList();
        CardListLengthEndpoints count = editor.AddCardListLength();
        ProfitEndpoints profit = editor.AddProfitSubAbility();
        editor.AddConnection(owner, hand.PlayerId);
        editor.AddConnection(income.FlowOut, madnessHand.FlowIn);
        editor.AddConnection(hand.Out, madnessHand.Cards);
        editor.AddConnection(madnessCardFilter, madnessHand.Filter);
        editor.AddConnection(madnessHand.FilteredCards, count.List);
        editor.AddConnection(madnessHand.Success, profit.FlowIn);
        editor.AddConnection(madnessHand.Fail, profit.FlowIn);
        editor.AddConnection(count.Length, profit.Income);
        editor.Finish();
        return removedHooks;
    }

    private static int RemoveIgorMadnessTurnHooks(AbilityDocument abilities)
    {
        const int madnessTurnFlag = 20_232_301;
        int changed = 0;
        IEnumerable<XElement> cardAbilities = abilities.Document.Root?.Elements("Ability")
            .Where(a => string.Equals((string?)a.Attribute("Type"), "CardAbility", StringComparison.Ordinal))
            ?? Enumerable.Empty<XElement>();

        foreach (XElement sourceAbility in cardAbilities)
        {
            XElement? nodes = sourceAbility.Element("Nodes");
            XElement? connections = sourceAbility.Element("Connections");
            XElement? variables = sourceAbility.Element("TemporaryVariables");
            if (nodes is null || connections is null || variables is null)
                continue;

            List<XElement> setters = nodes.Elements()
                .Where(node =>
                    string.Equals((string?)node.Attribute("Type"), "SetBlackboardVarNode", StringComparison.Ordinal) &&
                    (int?)node.Attribute("VarId") == madnessTurnFlag)
                .ToList();
            bool hasMarker = variables.Elements().Any(variable =>
                ((string?)variable.Attribute("Name"))?.StartsWith("IgorMadnessTurnHook", StringComparison.Ordinal) == true);
            if (setters.Count == 0 && !hasMarker)
                continue;

            var removeNodes = new HashSet<XElement>(setters);
            var setterFlowInputs = setters
                .Select(node => (int?)node.Element("FlowIn")?.Attribute("Id"))
                .Where(id => id.HasValue)
                .Select(id => id!.Value)
                .ToHashSet();
            foreach (XElement branch in nodes.Elements().Where(node =>
                         string.Equals((string?)node.Attribute("Type"), "BranchNode", StringComparison.Ordinal)))
            {
                int? trueId = (int?)branch.Element("FlowOutTrue")?.Attribute("Id");
                if (!trueId.HasValue)
                    continue;
                bool feedsSetter = connections.Elements().Any(connection =>
                    (int?)connection.Attribute("SrcId") == trueId.Value &&
                    setterFlowInputs.Contains((int?)connection.Attribute("DstId") ?? -1));
                if (feedsSetter)
                    removeNodes.Add(branch);
            }

            HashSet<int> removedEndpointIds = removeNodes
                .SelectMany(node => node.DescendantsAndSelf())
                .Select(element => (int?)element.Attribute("Id"))
                .Where(id => id.HasValue)
                .Select(id => id!.Value)
                .ToHashSet();
            foreach (XElement connection in connections.Elements().Where(connection =>
                         removedEndpointIds.Contains((int?)connection.Attribute("SrcId") ?? -1) ||
                         removedEndpointIds.Contains((int?)connection.Attribute("DstId") ?? -1)).ToList())
                connection.Remove();
            foreach (XElement node in removeNodes)
                node.Remove();
            foreach (XElement variable in variables.Elements().Where(variable =>
                         ((string?)variable.Attribute("Name"))?.StartsWith("IgorMadnessTurnHook", StringComparison.Ordinal) == true).ToList())
                variable.Remove();
            NormalizeAbilityNId(sourceAbility);
            changed++;
        }
        return changed;
    }


    private static int RebuildDonarBloodthirstAura(
        XElement ability, XElement template, AbilityDocument abilities, TemplateDocument templates)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");
        var editor = new GraphEditor(ability);
        editor.EnsureIntVariable("Damage", 2);
        TriggerEndpoints order = editor.AddTappedTrigger();
        GetCardsEndpoints units = editor.AddGetCards(
            ignoreTokens: 264, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608L);
        int ownerEntity = editor.AddGetAbilityOwner();
        PowerEndpoints damage = editor.AddChangePower(2, 1, 1, 1);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(units.Out, target.ValidTargets);
        editor.AddConnection(target.Success, damage.FlowIn);
        editor.AddConnection(target.SelectedTargets, damage.Targets);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.Finish();

        int patched = 0;
        foreach (XElement bronzeTemplate in templates.CardTemplates.Where(item => item.Element("Tier")?.Value == "2"))
        {
            int cardId = (int?)bronzeTemplate.Attribute("Id") ?? 0;
            XElement? bronzeAbility = abilities.FindCardAbility(cardId);
            if (bronzeAbility == null || bronzeAbility.Element("Nodes") == null)
                continue;
            List<XElement> branches = bronzeAbility.Element("Nodes")!.Elements()
                .Where(node => IsNodeType(node, "BloodthirstBranchNode")).ToList();
            if (branches.Count == 0 || bronzeAbility.Descendants().Any(element =>
                    string.Equals((string?)element.Attribute("Name"), "DonarBloodthirstAuraV1", StringComparison.Ordinal)))
                continue;

            var bronzeEditor = new GraphEditor(bronzeAbility);
            bool changed = false;
            foreach (XElement branch in branches)
            {
                int originalFlowIn = Id(branch.Element("FlowIn")!);
                int trueFlow = Id(branch.Element("True")!);
                List<int> incoming = bronzeEditor.GetIncomingSources(originalFlowIn).ToList();
                List<int> trueTargets = bronzeEditor.GetOutgoingTargets(trueFlow).ToList();
                if (incoming.Count == 0 || trueTargets.Count == 0)
                    continue;

                int ownerPlayer = bronzeEditor.AddGetOwnerPlayerId();
                GetCardsEndpoints board = bronzeEditor.AddGetCards(
                    ignoreTokens: 0, locationId: 3, cardTypes: 4, cardTiers: 10, ignoreOwner: false);
                NodeEndpoints donar = bronzeEditor.AddFilterCardTemplateId(DonarAnHindar);
                FilterListEndpoints hasDonar = bronzeEditor.AddFilterCardList();
                foreach (int source in incoming)
                {
                    bronzeEditor.RemoveConnection(source, originalFlowIn);
                    bronzeEditor.AddConnection(source, hasDonar.FlowIn);
                }
                bronzeEditor.AddConnection(ownerPlayer, board.PlayerId);
                bronzeEditor.AddConnection(board.Out, hasDonar.Cards);
                bronzeEditor.AddConnection(donar.Out, hasDonar.Filter);
                bronzeEditor.AddConnection(hasDonar.Fail, originalFlowIn);
                foreach (int targetId in trueTargets)
                    bronzeEditor.AddConnection(hasDonar.Success, targetId);
                changed = true;
            }
            if (!changed)
                continue;
            int marker = bronzeEditor.EnsureIntVariable("DonarBloodthirstAuraV1", 1);
            bronzeEditor.TemporaryVariables.Elements().First(v => (int?)v.Attribute("Id") == marker)
                .SetAttributeValue("HideInTooltip", "True");
            bronzeEditor.Finish();
            patched++;
        }
        return patched;
    }

