    private static int AddRandomSpellPlay(
        GraphEditor editor,
        int entryFlow,
        int ownerPlayer,
        int tier)
        => AddRandomSpellPlay(editor, new[] { entryFlow }, ownerPlayer, tier);

    private static int AddRandomSpellPlay(
        GraphEditor editor,
        IEnumerable<int> entryFlows,
        int ownerPlayer,
        int tier)
    {
        GetCardsEndpoints deck = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 16,
            cardTypes: 2,
            cardTiers: tier,
            ignoreOwner: false);
        NodeEndpoints spell = editor.AddFilterCardCategory(1_048_576UL, 0, 0);
        FilterListEndpoints eligible = editor.AddFilterCardList();
        RandomCardEndpoints random = editor.AddRandomCard();
        ElementListEndpoints singleton = editor.AddCardElementToList();
        PlayEndpoints play = editor.AddPlayCards();

        editor.AddConnection(ownerPlayer, deck.PlayerId);
        foreach (int entryFlow in entryFlows)
            editor.AddConnection(entryFlow, eligible.FlowIn);
        editor.AddConnection(deck.Out, eligible.Cards);
        editor.AddConnection(spell.Out, eligible.Filter);
        editor.AddConnection(eligible.Success, random.FlowIn);
        editor.AddConnection(eligible.FilteredCards, random.List);
        editor.AddConnection(random.Card, singleton.Card);
        editor.AddConnection(random.FlowOut, play.FlowIn);
        editor.AddConnection(singleton.List, play.Cards);
        return play.FlowOut;
    }


