    private static void RebuildMadmanLugosDiscardWarrior(
        XElement ability,
        XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", "True");
        SetTemplateText(template, "VisibleTapCharges", "False");

        var editor = new GraphEditor(ability);
        int discards = editor.EnsurePersistentIntVariable("Discards", 0);
        int destroyPlayedWarriorArmed = editor.EnsurePersistentIntVariable("LugosDestroyPlayedWarriorArmed", 0);
        AddDiscardCounter(editor, discards, ownerLocation: 1019);

        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int ownerPlayer = editor.AddGetOwnerPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints graveyard = editor.AddGetCards(
            ignoreTokens: 0,
            locationId: 32,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: false);
        NodeEndpoints bronze = editor.AddFilterCardTier(2);
        FilterListEndpoints bronzeUnits = editor.AddFilterCardList();
        NodeEndpoints warrior = editor.AddFilterCardCategory(0, 4_194_304UL, 0);
        FilterListEndpoints bronzeWarriors = editor.AddFilterCardList();
        CardChoiceEndpoints chooseWarrior = editor.AddRequestCardChoice(
            min: 1, max: 1, aiHintE0: 0, choiceType: 0);
        SetVarEndpoints armDestroyAfterPlay = editor.AddSetIntVariable(destroyPlayedWarriorArmed);
        SetEndpointValue(ability, armDestroyAfterPlay.In, "1");
        PlayEndpoints playWarrior = editor.AddPlayCards();

        editor.AddConnection(ownerPlayer, graveyard.PlayerId);
        editor.AddConnection(deploy.FlowOut, bronzeUnits.FlowIn);
        editor.AddConnection(graveyard.Out, bronzeUnits.Cards);
        editor.AddConnection(bronze.Out, bronzeUnits.Filter);
        editor.AddConnection(bronzeUnits.Success, bronzeWarriors.FlowIn);
        editor.AddConnection(bronzeUnits.FilteredCards, bronzeWarriors.Cards);
        editor.AddConnection(warrior.Out, bronzeWarriors.Filter);
        editor.AddConnection(bronzeWarriors.Success, chooseWarrior.FlowIn);
        editor.AddConnection(bronzeWarriors.FilteredCards, chooseWarrior.ValidChoices);
        editor.AddConnection(chooseWarrior.Success, armDestroyAfterPlay.FlowIn);
        editor.AddConnection(armDestroyAfterPlay.FlowOut, playWarrior.FlowIn);
        editor.AddConnection(chooseWarrior.SelectedChoices, playWarrior.Cards);

        // PlayCardsNode can resolve asynchronously: its FlowOut may fire before the
        // chosen graveyard unit has actually entered the board.  Destroying
        // SelectedChoices from PlayCards.FlowOut therefore kills the card before it
        // is played.  Instead, arm a short-lived flag and wait for the physical
        // played unit to arrive on the owner's board, then destroy CardsMoved.
        AfterMovedEndpoints playedWarriorToBoard = editor.AddAfterMovedTrigger(
            ownerLocation: 3,
            triggerCard: 2,
            triggerPlayer: 1,
            fromLocation: 32,
            toLocation: 3,
            reason: 1);
        int armedValue = editor.AddGetIntVariable(destroyPlayedWarriorArmed);
        IntBranchEndpoints armedBranch = editor.AddIntBranch();
        SetEndpointValue(ability, armedBranch.B, "0");
        DestroyEndpoints destroyWarrior = editor.AddDestroyCards(
            elementType: 1,
            attackMethod: 0);
        SetVarEndpoints disarmDestroyAfterPlay = editor.AddSetIntVariable(destroyPlayedWarriorArmed);
        SetEndpointValue(ability, disarmDestroyAfterPlay.In, "0");

        editor.AddConnection(ownerPlayer, playedWarriorToBoard.ToPlayer);
        editor.AddConnection(playedWarriorToBoard.FlowOut, armedBranch.FlowIn);
        editor.AddConnection(armedValue, armedBranch.A);
        editor.AddConnection(armedBranch.Bigger, destroyWarrior.FlowIn);
        editor.AddConnection(ownerEntity, destroyWarrior.Attacker);
        editor.AddConnection(playedWarriorToBoard.CardsMoved, destroyWarrior.Targets);
        editor.AddConnection(destroyWarrior.FlowOut, disarmDestroyAfterPlay.FlowIn);

        TriggerEndpoints order = editor.AddTappedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        GetCardsEndpoints enemyUnits = editor.AddGetCards(
            ignoreTokens: 264,
            locationId: 3,
            cardTypes: 4,
            cardTiers: 10,
            ignoreOwner: true);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(
            min: 1,
            max: 1,
            aiHintE0: 8_388_608);
        int discardDamage = editor.AddGetIntVariable(discards);
        PowerEndpoints orderDamage = editor.AddChangePower(
            amount: 0,
            operation: 1,
            elementType: 1,
            attackMethod: 1);

        editor.AddConnection(opponent, enemyUnits.PlayerId);
        editor.AddConnection(order.FlowOut, target.FlowIn);
        editor.AddConnection(enemyUnits.Out, target.ValidTargets);
        editor.AddConnection(target.Success, orderDamage.FlowIn);
        editor.AddConnection(target.SelectedTargets, orderDamage.Targets);
        editor.AddConnection(ownerEntity, orderDamage.Attacker);
        editor.AddConnection(discardDamage, orderDamage.Power);
        editor.Finish();
    }

