        editor.AddConnection(spying.FlowOut, notPassed.FlowIn);
        editor.AddConnection(opponent, passed.PlayerId);
        editor.AddConnection(passed.Passed, notPassed.Condition);
        editor.AddConnection(opponent, opponentHand.PlayerId);
        editor.AddConnection(opponentHand.Out, handCount.List);
        editor.AddConnection(notPassed.False, belowTen.FlowIn);
