        editor.AddConnection(opponent, opponentDraw.PlayerId);
        editor.AddConnection(opponentDraw.FlowOut, ownerDraw.FlowIn);
        editor.AddConnection(owner, ownerDraw.PlayerId);
        editor.Finish();
