    private static void ConfigureCooldownOrderTemplate(XElement template, bool zeal)
    {
        SetTemplateText(template, "InitialTimer", "-1");
        SetTemplateText(template, "ResetInInactive", "True");
        SetTemplateText(template, "InitalTapCharges", "1");
        SetTemplateText(template, "TapActive", "True");
        SetTemplateText(template, "SummoningSickness", zeal ? "False" : "True");
        SetTemplateText(template, "VisibleTapCharges", "False");
    }

    private static void AddCooldownCycle(
        GraphEditor editor,
        XElement ability,
        int completedFlow,
        int cooldownVariable,
        int owner,
        int ownerEntity,
        int ownerCards)
    {
        ChangeCardTimerEndpoints start = editor.AddChangeCardTimer(operation: 2, value: 1);
        int cooldown = editor.AddGetIntVariable(cooldownVariable);
        editor.AddConnection(completedFlow, start.FlowIn);
        editor.AddConnection(ownerCards, start.Cards);
        editor.AddConnection(cooldown, start.Value);

        TurnTriggerEndpoints ownerTurn = editor.AddBeforeTurnTrigger(ownerLocation: 3);
        ChangeCardTimerEndpoints decrement = editor.AddChangeCardTimer(operation: 0, value: 1);
        editor.AddConnection(owner, ownerTurn.PlayerFilter);
        editor.AddConnection(ownerTurn.FlowOut, decrement.FlowIn);
        editor.AddConnection(ownerCards, decrement.Cards);

        CardTimerElapsedEndpoints elapsed = editor.AddCardTimerElapsedTrigger();
        ChangeTapChargesEndpoints restore = editor.AddChangeTapCardCharges(operation: 2, value: 1);
        editor.AddConnection(elapsed.FlowOut, restore.FlowIn);
        editor.AddConnection(ownerEntity, restore.Attacker);
        editor.AddConnection(ownerCards, restore.Targets);
    }

    private static void RebuildRegisRowOrder(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        ConfigureCooldownOrderTemplate(template, zeal: true);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("RegisRowOrderV6", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int cooldownVar = editor.EnsureIntVariable("Cooldown", 3);
        int preDamageTargetsVar = editor.AddCardListVariable("RegisPreDamageTargets");
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        int ownerCards = editor.AddGetAbilityOwnerCardList();
        TriggerEndpoints order = editor.AddTappedTrigger();
        LocationTargetRequestEndpoints row = editor.AddRequestLocationTargets(
            min: 1, max: 1, validPlayers: 3, validTargets: 3, aiHintE0: 8_388_608);
        LocationElementEndpoints selectedRow = editor.AddLocationListGetElement(0);
        LocationCardsEndpoints rowUnits = editor.AddGetLocationCards(cardType: 4);

        // GetLocationCards is a live query. If it is connected directly to the
        // Deathblow subability, it is evaluated again after damage and no longer
        // contains destroyed cards. Freeze the complete pre-damage row list once,
        // then use that exact snapshot for both damage and Deathblow.
        SetVarEndpoints savePreDamageTargets = editor.AddSetCardListVariable(preDamageTargetsVar);
        int targetsForDamage = editor.AddGetCardListVariable(preDamageTargetsVar);
        int targetsForDeathblow = editor.AddGetCardListVariable(preDamageTargetsVar);

        PowerEndpoints damage = editor.AddChangePower(
            amount: 1,
            operation: 1,
            elementType: 1024,
            attackMethod: 2,
            effectType: 0);
        DeathblowEndpoints deathblow = editor.AddDeathblowSubAbility();

        // After a confirmed Deathblow, query the row again and apply Bleeding
        // one-by-one only to cards that are still alive.
        LocationCardsEndpoints survivingRowUnits = editor.AddGetLocationCards(cardType: 4);
        ForeachEndpoints survivorLoop = editor.AddCardListForeach();
        CardPowerEndpoints survivorPower = editor.AddGetCardPower(powerType: 0);
        IntBranchEndpoints alive = editor.AddIntBranch();
        ElementListEndpoints survivorSingleton = editor.AddCardElementToList();
        StatusTimerEndpoints bleed = editor.AddBleeding(1);
        BranchEndpoints finish = editor.AddBranch();
        SetEndpointValue(ability, alive.B, "0");
        SetEndpointValue(ability, finish.Condition, "True");

        editor.AddConnection(opponent, row.ValidPlayers);
        editor.AddConnection(order.FlowOut, row.FlowIn);
        editor.AddConnection(row.Locations, selectedRow.List);
        editor.AddConnection(selectedRow.Location, rowUnits.Location);

        editor.AddConnection(row.Success, savePreDamageTargets.FlowIn);
        editor.AddConnection(rowUnits.Cards, savePreDamageTargets.In);
        editor.AddConnection(savePreDamageTargets.FlowOut, damage.FlowIn);
        editor.AddConnection(ownerEntity, damage.Attacker);
        editor.AddConnection(targetsForDamage, damage.Targets);
        editor.AddConnection(damage.FlowOut, deathblow.FlowIn);
        editor.AddConnection(targetsForDeathblow, deathblow.Targets);

        editor.AddConnection(selectedRow.Location, survivingRowUnits.Location);
        editor.AddConnection(deathblow.Deathblow, survivorLoop.FlowIn);
        editor.AddConnection(survivingRowUnits.Cards, survivorLoop.List);
        editor.AddConnection(survivorLoop.FlowFor, alive.FlowIn);
        editor.AddConnection(survivorLoop.Element, survivorPower.Card);
        editor.AddConnection(survivorPower.Power, alive.A);
        editor.AddConnection(survivorLoop.Element, survivorSingleton.Card);
        editor.AddConnection(alive.Bigger, bleed.FlowIn);
        editor.AddConnection(ownerEntity, bleed.Attacker);
        editor.AddConnection(survivorSingleton.List, bleed.Cards);
        editor.AddConnection(survivorLoop.FlowOut, finish.FlowIn);
        editor.AddConnection(deathblow.Fail, finish.FlowIn);
        AddCooldownCycle(editor, ability, finish.True, cooldownVar, owner, ownerEntity, ownerCards);
        editor.Finish();
    }

    private static void RebuildRegisHigherVampireBleeding(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
