        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608);
        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        GetStatusTimerEndpoints selectedTimer = editor.AddGetCardStatusTimer(16);
        CardPowerEndpoints selectedPowerBeforeDrain = editor.AddGetCardPower(powerType: 0);
        IntBranchEndpoints activeBleeding = editor.AddIntBranch();
        DrainEndpoints drain = editor.AddDrainSubAbility(2);
