        SetEndpointValue(ability, activeBleeding.B, "0");
        SetEndpointValue(ability, finish.Condition, "True");
        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(order.FlowOut, bleedingEnemies.FlowIn);
        editor.AddConnection(enemies.Out, bleedingEnemies.Cards);
        editor.AddConnection(bleedingToken.Out, bleedingEnemies.Filter);
        editor.AddConnection(bleedingEnemies.Success, target.FlowIn);
        editor.AddConnection(bleedingEnemies.FilteredCards, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, selected.List);
        editor.AddConnection(selected.Card, selectedTimer.Card);
        editor.AddConnection(selected.Card, selectedPowerBeforeDrain.Card);
        editor.AddConnection(target.Success, activeBleeding.FlowIn);
        editor.AddConnection(selectedTimer.Value, activeBleeding.A);
        editor.AddConnection(activeBleeding.Bigger, drain.FlowIn);
        editor.AddConnection(selectedPowerBeforeDrain.Power, drain.Power);
        editor.AddConnection(target.SelectedTargets, drain.Targets);
        editor.AddConnection(drain.Success, finish.FlowIn);
        editor.AddConnection(drain.Fail, finish.FlowIn);
        AddCooldownCycle(editor, ability, finish.True, cooldownVar, owner, ownerEntity, ownerCards);

        ChangedStatusTimerEndpoints changed = editor.AddAfterChangedCardStatusTimerTrigger(
            ownerLocation: 16, targetCard: 3, triggerPlayer: 3, operationValue: 0, statusMask: 16);
        editor.AddConnection(opponent, changed.PlayerMask);
        SetVarEndpoints clearTotal = editor.AddSetIntVariable(totalVar);
        SetEndpointValue(ability, clearTotal.In, "0");
        ForeachEndpoints each = editor.AddCardListForeach();
        GetStatusTimerEndpoints timer = editor.AddGetCardStatusTimer(16);
        int currentTotal = editor.AddGetIntVariable(totalVar);
        IntPlusEndpoints add = editor.AddIntPlus();
        SetVarEndpoints save = editor.AddSetIntVariable(totalVar);
        int finalTotal = editor.AddGetIntVariable(totalVar);
        IntBranchEndpoints enough = editor.AddIntBranch();
        GetCardsEndpoints deck = editor.AddGetCards(0, 16, 4, 10, false);
        NodeEndpoints selfTemplate = editor.AddFilterCardTemplateId(RegisHigherVampire);
        FilterListEndpoints selfInDeck = editor.AddFilterCardList();
        PositionEndpoints melee = editor.AddGetRandomLastAvailablePosition(1);
        MoveCardsEndpoints summon = editor.AddMoveCards();

        editor.AddConnection(changed.FlowOut, clearTotal.FlowIn);
        editor.AddConnection(clearTotal.FlowOut, each.FlowIn);
        editor.AddConnection(enemies.Out, each.List);
        editor.AddConnection(each.Element, timer.Card);
        editor.AddConnection(each.FlowFor, save.FlowIn);
        editor.AddConnection(currentTotal, add.A);
        editor.AddConnection(timer.Value, add.B);
        editor.AddConnection(add.Result, save.In);
        editor.AddConnection(each.FlowOut, enough.FlowIn);
        editor.AddConnection(finalTotal, enough.A);
        SetEndpointValue(ability, enough.B, "8");
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(enough.Equal, selfInDeck.FlowIn);
        editor.AddConnection(enough.Bigger, selfInDeck.FlowIn);
        editor.AddConnection(deck.Out, selfInDeck.Cards);
        editor.AddConnection(selfTemplate.Out, selfInDeck.Filter);
        editor.AddConnection(owner, melee.PlayerId);
        editor.AddConnection(selfInDeck.Success, summon.FlowIn);
        editor.AddConnection(selfInDeck.FilteredCards, summon.Cards);
        editor.AddConnection(melee.Position, summon.Position);
        editor.Finish();
    }

    private static void RebuildUndyingThirstActivateBleeding(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("UndyingThirstActivateBleedingV2", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        int bleedVar = editor.EnsureIntVariable("Bleed", 6);
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        int ownerEntity = editor.AddGetAbilityOwner();
        GetCardsEndpoints enemies = editor.AddGetCards(264, 3, 4, 10, true);
        TargetRequestEndpoints target = editor.AddRequestCardTargets(1, 1, 8_388_608);
        CardElementEndpoints selected = editor.AddCardListGetElement(0);
        GetStatusTimerEndpoints oldTimer = editor.AddGetCardStatusTimer(16);
        IntBranchEndpoints hadBleeding = editor.AddIntBranch();
        PowerEndpoints activateDamage = editor.AddChangePower(1, 1, 1, 0);
        XElement activateDamageNode = editor.FindNodeOwningEndpoint(activateDamage.FlowIn)
            ?? throw new InvalidDataException("Undying Thirst activation damage node missing.");
        activateDamageNode.Element("IgnoreArmor")?.SetAttributeValue("V", "True");
        StatusTimerEndpoints consume = editor.AddActivateBleeding(0);
        StatusTimerEndpoints apply = editor.AddBleeding(0);
        int newBleed = editor.AddGetIntVariable(bleedVar);

        editor.AddConnection(opponent, enemies.PlayerId);
        editor.AddConnection(deploy.FlowOut, target.FlowIn);
        editor.AddConnection(enemies.Out, target.ValidTargets);
        editor.AddConnection(target.SelectedTargets, selected.List);
        editor.AddConnection(selected.Card, oldTimer.Card);
        editor.AddConnection(target.Success, hadBleeding.FlowIn);
        editor.AddConnection(oldTimer.Value, hadBleeding.A);
        SetEndpointValue(ability, hadBleeding.B, "0");
        editor.AddConnection(hadBleeding.Bigger, activateDamage.FlowIn);
        editor.AddConnection(oldTimer.Value, activateDamage.Power);
        editor.AddConnection(ownerEntity, activateDamage.Attacker);
        editor.AddConnection(target.SelectedTargets, activateDamage.Targets);
        editor.AddConnection(activateDamage.FlowOut, consume.FlowIn);
        editor.AddConnection(ownerEntity, consume.Attacker);
        editor.AddConnection(target.SelectedTargets, consume.Cards);
        editor.AddConnection(oldTimer.Value, consume.DeltaTime);
        editor.AddConnection(consume.FlowOut, apply.FlowIn);
        editor.AddConnection(hadBleeding.Equal, apply.FlowIn);
        editor.AddConnection(hadBleeding.Smaller, apply.FlowIn);
        editor.AddConnection(ownerEntity, apply.Attacker);
        editor.AddConnection(target.SelectedTargets, apply.Cards);
        editor.AddConnection(newBleed, apply.DeltaTime);
        editor.Finish();
    }

    private static void RebuildAguaraTrueFormFactionSpecials(XElement ability, XElement template)
    {
        ClearAbilityGraph(ability, clearVariables: true);
        DisableOrderTemplate(template);
        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("AguaraTrueFormFactionSpecialsV4", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        OwnerLocationBranchEndpoints row = editor.AddOwnerLocationBranch();
        int owner = editor.AddGetOwnerPlayerId();
        int opponent = editor.AddGetOwnerOpponentPlayerId();
        // Vanilla dynamic-faction graphs always read leader cards with IgnoreOwner=True.
        GetCardsEndpoints ownerLeader = editor.AddGetCards(0, 64, 1, 1, true);
        GetCardsEndpoints opponentLeader = editor.AddGetCards(0, 64, 1, 1, true);
        CardElementEndpoints ownerLeaderCard = editor.AddCardListGetElement(0);
        CardElementEndpoints opponentLeaderCard = editor.AddCardListGetElement(0);
        FactionEndpoints ownerFaction = editor.AddGetFaction();
        FactionEndpoints opponentFaction = editor.AddGetFaction();
        CardDefinitionsEndpoints ownerSpecials = editor.AddGetCardsDefinitions(0, 10, 2, 0, 0, 0);
        CardDefinitionsEndpoints opponentSpecials = editor.AddGetCardsDefinitions(0, 10, 2, 0, 0, 0);
        CreatePlayEndpoints createOwner = editor.AddCreateAndPlaySubAbilityWithPlayFlag();
        CreatePlayEndpoints createOpponent = editor.AddCreateAndPlaySubAbilityWithPlayFlag();

        editor.AddConnection(deploy.FlowOut, row.FlowIn);
        editor.AddConnection(owner, ownerLeader.PlayerId);
        editor.AddConnection(opponent, opponentLeader.PlayerId);
        editor.AddConnection(ownerLeader.Out, ownerLeaderCard.List);
        editor.AddConnection(opponentLeader.Out, opponentLeaderCard.List);
        editor.AddConnection(ownerLeaderCard.Card, ownerFaction.Card);
        editor.AddConnection(opponentLeaderCard.Card, opponentFaction.Card);
        editor.AddConnection(ownerFaction.Faction, ownerSpecials.Faction);
        editor.AddConnection(opponentFaction.Faction, opponentSpecials.Faction);
        editor.AddConnection(row.Melee, createOpponent.FlowIn);
        editor.AddConnection(opponentSpecials.Out, createOpponent.Definitions);
        editor.AddConnection(row.Ranged, createOwner.FlowIn);
        editor.AddConnection(ownerSpecials.Out, createOwner.Definitions);
        editor.Finish();
    }

    private static void RebuildVaedermakarWeatherOrder(
        XElement ability,
        XElement template,
        string abilitiesPath,
        string templatesPath)
    {
        XElement cleanAbility = TryLoadCleanCardAbilityReference(abilitiesPath, Vaedermakar)
            ?? throw new InvalidOperationException("Clean Vaedermakar CardAbility was not found.");
        XElement cleanTemplate = TryLoadCleanTemplateReference(templatesPath, Vaedermakar)
            ?? throw new InvalidOperationException("Clean Vaedermakar Template was not found.");
        CopyAbilityGraphAndOrderTemplate(ability, template, cleanAbility, cleanTemplate);
        EnsureAbilityContainers(ability);
        XElement played = ability.Element("Nodes")!.Elements().Single(n =>
            string.Equals((string?)n.Attribute("Type"), "PlayedTrigger", StringComparison.Ordinal));
        XElement priority = new(played.Element("Priority")
            ?? throw new InvalidDataException("Vaedermakar PlayedTrigger lacks Priority."));
        XElement flowOut = new(played.Element("FlowOut")
            ?? throw new InvalidDataException("Vaedermakar PlayedTrigger lacks FlowOut."));
        XElement tapped = new(played.Name,
            new XAttribute("Type", "TappedTrigger"),
            new XAttribute("Id", Id(played)),
            new XAttribute("X", (string?)played.Attribute("X") ?? "0"),
            new XAttribute("Y", (string?)played.Attribute("Y") ?? "0"),
            priority,
            flowOut);
        played.ReplaceWith(tapped);
        ConfigureCooldownOrderTemplate(template, zeal: true);

        var editor = new GraphEditor(ability);
        int marker = editor.EnsureIntVariable("VaedermakarWeatherOrderV1", 1);
        editor.TemporaryVariables.Elements().Single(v => (int?)v.Attribute("Id") == marker)
            .SetAttributeValue("HideInTooltip", "True");
        PlayedEndpoints deploy = editor.AddPlayedTrigger();
        int owner = editor.AddGetOwnerPlayerId();
        GetCardsEndpoints deck = editor.AddGetCards(0, 16, 10, 10, false);
        NodeEndpoints frost = editor.AddFilterCardTemplateId(BitingFrost);
        NodeEndpoints fog = editor.AddFilterCardTemplateId(ImpenetrableFog);
        NodeEndpoints rain = editor.AddFilterCardTemplateId(TorrentialRain);
        LogicEndpoints frostOrFog = editor.AddFilterLogic(orOperation: true);
        LogicEndpoints weather = editor.AddFilterLogic(orOperation: true);
        FilterListEndpoints weatherCards = editor.AddFilterCardList();
        CardChoiceEndpoints choose = editor.AddRequestCardChoice(1, 1, 0, choiceType: 0, revealChoices: true);
        PlayEndpoints play = editor.AddPlayCards();
        editor.AddConnection(frost.Out, frostOrFog.Input0);
        editor.AddConnection(fog.Out, frostOrFog.Input1);
        editor.AddConnection(frostOrFog.Out, weather.Input0);
        editor.AddConnection(rain.Out, weather.Input1);
        editor.AddConnection(owner, deck.PlayerId);
        editor.AddConnection(deploy.FlowOut, weatherCards.FlowIn);
        editor.AddConnection(deck.Out, weatherCards.Cards);
        editor.AddConnection(weather.Out, weatherCards.Filter);
        editor.AddConnection(weatherCards.Success, choose.FlowIn);
        editor.AddConnection(weatherCards.FilteredCards, choose.ValidChoices);
        editor.AddConnection(choose.Success, play.FlowIn);
        editor.AddConnection(choose.SelectedChoices, play.Cards);
        editor.Finish();
    }

