    private sealed class GraphEditor
    {
        public XElement Ability { get; }
        public XElement Nodes { get; }
        public XElement Connections { get; }
        public XElement TemporaryVariables { get; }
        public XElement PersistentVariables { get; }
        private int _nextId;

        public GraphEditor(XElement ability)
        {
            Ability = ability;
            Nodes = ability.Element("Nodes")
                ?? throw new InvalidDataException("Ability не содержит Nodes.");
            Connections = ability.Element("Connections")
                ?? throw new InvalidDataException("Ability не содержит Connections.");
            TemporaryVariables = ability.Element("TemporaryVariables")
                ?? throw new InvalidDataException("Ability не содержит TemporaryVariables.");
            PersistentVariables = ability.Element("PersistentVariables")
                ?? throw new InvalidDataException("Ability не содержит PersistentVariables.");
            int max = ability.Elements()
                .Where(element => element.Name.LocalName is
                    "TemporaryVariables" or "PersistentVariables" or "Nodes" or "Connections")
                .SelectMany(element => element.DescendantsAndSelf())
                .Where(element => element.Attribute("Id") != null)
                .Select(element => (int)element.Attribute("Id")!)
                .DefaultIfEmpty(0)
                .Max();
            _nextId = Math.Max((int?)ability.Attribute("NId") ?? 1, max + 1);
        }

        public int NewId() => _nextId++;

        public void AddConnection(int source, int target)
        {
            if (HasConnection(source, target))
                return;
            Connections.Add(new XElement("e" + Connections.Elements().Count(),
                new XAttribute("Type", "Connection"),
                new XAttribute("Id", NewId()),
                new XAttribute("SrcId", source),
                new XAttribute("DstId", target)));
        }

        public bool HasConnection(int source, int target) =>
            Connections.Elements().Any(element =>
                (int?)element.Attribute("SrcId") == source &&
                (int?)element.Attribute("DstId") == target);

        public bool TryRemoveConnection(int source, int target)
        {
            XElement? connection = Connections.Elements().FirstOrDefault(element =>
                (int?)element.Attribute("SrcId") == source &&
                (int?)element.Attribute("DstId") == target);
            if (connection == null)
                return false;
            connection.Remove();
            return true;
        }

        public void RemoveConnection(int source, int target)
        {
            if (!TryRemoveConnection(source, target))
                throw new InvalidOperationException($"Connection {source}->{target} не найдена.");
        }

        public void RemoveIncomingConnections(int target)
        {
            foreach (XElement connection in Connections.Elements()
                         .Where(element => (int?)element.Attribute("DstId") == target)
                         .ToList())
            {
                connection.Remove();
            }
        }

        public IReadOnlyList<int> GetIncomingSources(int target) =>
            Connections.Elements()
                .Where(element => (int?)element.Attribute("DstId") == target)
                .Select(element => (int)element.Attribute("SrcId")!)
                .ToList();

        public IReadOnlyList<int> GetOutgoingTargets(int source) =>
            Connections.Elements()
                .Where(element => (int?)element.Attribute("SrcId") == source)
                .Select(element => (int)element.Attribute("DstId")!)
                .ToList();

        public XElement? FindNodeOwningEndpoint(int endpointId) =>
            Nodes.Elements().FirstOrDefault(node =>
                node.DescendantsAndSelf().Any(element =>
                    (int?)element.Attribute("Id") == endpointId));

        public XElement AddNode(XElement node)
        {
            node.Name = "e" + Nodes.Elements().Count();
            Nodes.Add(node);
            return node;
        }

        public PlayedEndpoints AddPlayedTrigger()
        {
            int node = NewId(), priority = NewId(), flow = NewId(), card = NewId();
            int from = NewId(), to = NewId(), forced = NewId();
            AddNode(new XElement("e",
                new XAttribute("Type", "PlayedTrigger"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                Var("Priority", "EnumVar`1", priority, "0", "ETriggerPriority"),
                new XElement("FlowOut", new XAttribute("Type", "FlowConnector"), new XAttribute("Id", flow)),
                Var("CardPlayed", "CardVar", card),
                CardPositionVar("From", from),
                CardPositionVar("To", to),
                Var("Forced", "BoolVar", forced, "False")));
            return new PlayedEndpoints(flow, to);
        }


        public IncomeEndpoints AddIncomeTrigger()
        {
            int node = NewId(), priority = NewId(), flow = NewId(), forced = NewId();
            AddNode(new XElement("e",
                new XAttribute("Type", "IncomeTrigger"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                Var("Priority", "EnumVar`1", priority, "0", "ETriggerPriority"),
                Flow("FlowOut", flow),
                Var("Forced", "BoolVar", forced, "False")));
            return new IncomeEndpoints(flow);
        }

        public PaidForEndpoints AddPaidForTrigger(int costVariableId)
        {
            int node = NewId(), priority = NewId(), flow = NewId(), costRef = NewId();
            int spent = NewId(), madness = NewId();
            XElement costs = new("Costs",
                new XElement("e0",
                    new XAttribute("Type", "IntReferenceVar"),
                    new XAttribute("Id", costRef),
                    new XAttribute("ExternalOut", "False"),
                    new XAttribute("ExternalIn", "False"),
                    new XAttribute("ResetInInactive", "False"),
                    new XAttribute("V", costVariableId)));
            XElement switchOut = new("SwitchOut", Flow("e0", flow));
            AddNode(new XElement("e",
                new XAttribute("Type", "PaidForTrigger"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                Var("Priority", "EnumVar`1", priority, "0", "ETriggerPriority"),
                costs,
                switchOut,
                Var("Spent", "IntVar", spent, "0"),
                Var("Madness", "BoolVar", madness, "False")));
            return new PaidForEndpoints(flow, spent, madness);
        }

        public ProfitEndpoints AddProfitSubAbility()
        {
            int node = NewId(), flowIn = NewId(), flowOut = NewId(), income = NewId();
            XElement connectionMappings = new("ConnectionMappings",
                ConnectionMapping("e0", "FlowConnector", flowIn, 1, true),
                ConnectionMapping("e1", "FlowConnector", flowOut, 14, false));
            XElement varMappings = new("VarMappings",
                VariableMapping("e0", "IntVar", income, "Income", 9, true, "0"));
            AddNode(new XElement("e",
                new XAttribute("Type", "UseSubAbilityNode"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                new XElement("SubAbilityID", "16"),
                connectionMappings,
                varMappings));
            return new ProfitEndpoints(flowIn, flowOut, income);
        }

