        public InitialDeckEndpoints AddGetInitialDeckDefinitions(
            bool unique = false,
            int tier = 0,
            int cardType = 0)
        {
            int node = NewId(), output = NewId(), faction = NewId(), tierId = NewId(), typeId = NewId();
            int tokens = NewId(), rarity = NewId(), triggerType = NewId(), initialPosition = NewId();
            int availability = NewId(), category = NewId(), categoryCompare = NewId();
            int playerSide = NewId(), opponentSide = NewId(), definitions = NewId();
            int player = NewId(), uniqueId = NewId();

            XElement outField = Var("Out", "CardDefinitionListVar", output);
            outField.SetAttributeValue("HideInTooltip", "False");
            XElement definitionsField = Var("Definitions", "CardDefinitionListVar", definitions);
            definitionsField.SetAttributeValue("HideInTooltip", "False");
            XElement availabilityField = Var("Availability", "AvailabilityVar", availability);
            availabilityField.Add(new XElement("V",
                new XAttribute("Type", "EnumBitArray`1"),
                new XAttribute("GArg", "EAvailability"),
                new XElement("e0", new XAttribute("V", 2))));
            XElement categoryField = Var("Category", "CardCategoryVar", category);
            categoryField.Add(new XElement("V",
                new XAttribute("Type", "CardCategory"),
                new XElement("e0", new XAttribute("V", 0)),
                new XElement("e1", new XAttribute("V", 0)),
                new XElement("e2", new XAttribute("V", 0))));

            AddNode(new XElement("e",
                new XAttribute("Type", "GetInitialDeckDefinitions"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                outField,
                Var("Faction", "EnumVar`1", faction, "0", "EFactionId"),
                Var("Tier", "EnumVar`1", tierId, tier.ToString(), "ECardTier"),
                Var("Type", "EnumVar`1", typeId, cardType.ToString(), "ECardType"),
                Var("Tokens", "EnumVar`1", tokens, "0", "ECardToken"),
                Var("Rarity", "EnumVar`1", rarity, "0", "ERarity"),
                Var("TriggerType", "EnumVar`1", triggerType, "0", "EActiveTriggerType"),
                Var("InitialPosition", "EnumVar`1", initialPosition, "0", "EInitialCardPosition"),
                availabilityField,
                categoryField,
                Var("CategoryCompare", "EnumVar`1", categoryCompare, "1", "ECategoryCompareMethod"),
                Var("PlayerSide", "ELocationVar", playerSide, "0"),
                Var("OpponentSide", "ELocationVar", opponentSide, "0"),
                definitionsField,
                Var("PlayerId", "PlayerIdVar", player, "3"),
                Var("Unique", "BoolVar", uniqueId, unique.ToString())));

            // Every native GetInitialDeckDefinitions graph feeds the current game-mode
            // availability mask from GetDefaultAvailabilityNode. Leaving only the
            // serialized fallback value (2) can make the query return an empty list
            // for cards from other availability sets, including Gimpy Gerwin.
            int defaultAvailability = AddGetDefaultAvailability();
            AddConnection(defaultAvailability, availability);

            return new InitialDeckEndpoints(output, player, definitions);
        }

