        public int AddCardDefinitionListVariable(string name, params int[] templateIds)
        {
            if (templateIds.Length == 0)
                throw new ArgumentException("At least one template ID is required.", nameof(templateIds));

            int id = NewId();
            var value = new XElement("V");
            for (int index = 0; index < templateIds.Length; index++)
            {
                value.Add(new XElement("e" + index,
                    new XAttribute("Type", "CardDefinition"),
                    new XAttribute("TemplateId", templateIds[index]),
                    new XAttribute("IsPremium", "False")));
            }

            TemporaryVariables.Add(new XElement("e" + TemporaryVariables.Elements().Count(),
                new XAttribute("Type", "CardDefinitionListVar"),
                new XAttribute("Id", id),
                new XAttribute("Name", name),
                new XAttribute("ExternalOut", "False"),
                new XAttribute("ExternalIn", "False"),
                new XAttribute("ResetInInactive", "False"),
                new XAttribute("HideInTooltip", "False"),
                value));
            return id;
        }

