            int countId = NewId(), spawned = NewId(), position = NewId();

            XElement definitionField = Var("CardDefinition", "CardDefinitionVar", definition);
            definitionField.Name = "Data";
            definitionField.SetAttributeValue("Name", "CardDefinition");
            definitionField.SetAttributeValue("HideInTooltip", "False");
            definitionField.Add(new XElement("V",
                new XAttribute("Type", "CardDefinition"),
                new XAttribute("TemplateId", templateId),
                new XAttribute("IsPremium", "False")));

            XElement positionField = CardPositionVar("Position", position);
            positionField.Name = "Data";
            positionField.SetAttributeValue("Name", "Position");
            XElement connectionMappings = new("ConnectionMappings",
                ConnectionMapping("e0", "FlowConnector", flowIn, 8, true),
                ConnectionMapping("e1", "FlowConnector", flowOut, 11, false),
                ConnectionMapping("e2", "FlowConnector", positionFlowIn, 59, true));
            XElement varMappings = new("VarMappings",
                VariableMapping("e0", "PlayerIdVar", player, "PlayerId", 18, true, "3"),
                VariableMapping("e1", "ELocationVar", locationId, "Location", 19, true, location.ToString()),
                new XElement("e2",
                    new XAttribute("Type", "ConnectionMapping"),
                    definitionField,
                    new XElement("IdOfDataInAbility", 40),
                    new XElement("IsInput", "True")),
                VariableMapping("e3", "IntVar", countId, "Count", 42, true, count.ToString()),
                VariableMapping("e4", "CardListVar", spawned, "Spawned", 50, false, null),
                new XElement("e5",
                    new XAttribute("Type", "ConnectionMapping"),
                    positionField,
                    new XElement("IdOfDataInAbility", 63),
                    new XElement("IsInput", "True")));
            AddNode(new XElement("e",
                new XAttribute("Type", "UseSubAbilityNode"),
                new XAttribute("Id", node),
                new XAttribute("X", 0), new XAttribute("Y", 0),
                new XElement("SubAbilityID", "30"),
                connectionMappings,
                varMappings));
            return new SpawnCopyEndpoints(flowIn, flowOut, positionFlowIn, player, position, spawned);
        }

