        public void Finish()
        {
            int index = 0;
            foreach (XElement node in Nodes.Elements())
                node.Name = "e" + index++;
            index = 0;
            foreach (XElement connection in Connections.Elements())
                connection.Name = "e" + index++;
            index = 0;
            foreach (XElement variable in TemporaryVariables.Elements())
                variable.Name = "e" + index++;
            XElement? persistent = Ability.Element("PersistentVariables");
            if (persistent != null)
            {
                index = 0;
                foreach (XElement variable in persistent.Elements())
                    variable.Name = "e" + index++;
            }
            Ability.SetAttributeValue("NId", _nextId);
        }

        private static XElement ConnectionMapping(
            string elementName,
            string dataType,
            int dataId,
            int idInAbility,
            bool input)
        {
            return new XElement(elementName,
                new XAttribute("Type", "ConnectionMapping"),
                new XElement("Data", new XAttribute("Type", dataType), new XAttribute("Id", dataId)),
                new XElement("IdOfDataInAbility", idInAbility),
                new XElement("IsInput", input ? "True" : "False"));
        }

        private static XElement VariableMapping(
            string elementName,
            string dataType,
            int dataId,
            string name,
            int idInAbility,
            bool input,
            string? value)
        {
            var data = new XElement("Data",
                new XAttribute("Type", dataType),
                new XAttribute("Id", dataId),
                new XAttribute("Name", name),
                new XAttribute("ExternalOut", "False"),
                new XAttribute("ExternalIn", "False"),
                new XAttribute("ResetInInactive", "False"));
            if (value != null)
                data.SetAttributeValue("V", value);
            return new XElement(elementName,
                new XAttribute("Type", "ConnectionMapping"),
                data,
                new XElement("IdOfDataInAbility", idInAbility),
                new XElement("IsInput", input ? "True" : "False"));
        }
    }

