    private static XElement Var(
        string name,
        string type,
        int id,
        string? value = null,
        string? genericArgument = null)
    {
        var element = new XElement(name,
            new XAttribute("Type", type),
            new XAttribute("Id", id),
            new XAttribute("ExternalOut", "False"),
            new XAttribute("ExternalIn", "False"),
            new XAttribute("ResetInInactive", "False"));
        if (!string.IsNullOrWhiteSpace(genericArgument))
            element.SetAttributeValue("GArg", genericArgument);
        if (value != null)
            element.SetAttributeValue("V", value);
        return element;
    }

    private static XElement CardPositionVar(string name, int id)
    {
        XElement element = Var(name, "CardPositionVar", id);
        element.Add(new XElement("V",
            new XAttribute("Type", "CardPosition"),
            new XAttribute("PlayerId", 0),
            new XAttribute("Location", 0),
            new XAttribute("Index", 0)));
        return element;
    }

    private static XElement Flow(string name, int id) =>
        new(name, new XAttribute("Type", "FlowConnector"), new XAttribute("Id", id));

    private static int Id(XElement element) =>
        (int?)element.Attribute("Id")
        ?? throw new InvalidDataException($"{element.Name} не содержит Id.");

    private static void SetEndpointValue(XElement ability, int endpointId, string value)
    {
        XElement endpoint = ability.DescendantsAndSelf().FirstOrDefault(element =>
            (int?)element.Attribute("Id") == endpointId)
            ?? throw new InvalidOperationException($"Endpoint Id={endpointId} not found.");
        endpoint.SetAttributeValue("V", value);
    }

    private static XElement FindNode(XElement ability, string type) =>
        ability.Element("Nodes")?.Elements().FirstOrDefault(node =>
            string.Equals((string?)node.Attribute("Type"), type, StringComparison.Ordinal))
        ?? throw new InvalidOperationException($"Node Type={type} не найден.");

    private static bool IsNodeType(XElement? node, string type) =>
        node != null && string.Equals((string?)node.Attribute("Type"), type, StringComparison.Ordinal);

    private static void EnsureAbilityGraphContainers(XElement ability)
    {
        XElement persistent = ability.Element("PersistentVariables")
            ?? throw new InvalidDataException("Ability не содержит PersistentVariables.");
        if (ability.Element("Nodes") == null)
            persistent.AddAfterSelf(new XElement("Nodes"));
        if (ability.Element("Connections") == null)
            ability.Element("Nodes")!.AddAfterSelf(new XElement("Connections"));
    }

    private static void ClearAbilityGraph(XElement ability, bool clearVariables)
    {
        EnsureAbilityContainers(ability);

        ability.Element("Nodes")!.RemoveNodes();
        ability.Element("Connections")!.RemoveNodes();
        if (clearVariables)
        {
            ability.Element("TemporaryVariables")!.RemoveNodes();
            ability.Element("PersistentVariables")!.RemoveNodes();
        }
        ability.SetAttributeValue("NId", 1);
    }

    private static void EnsureAbilityContainers(XElement ability)
    {
        XElement? temporary = ability.Element("TemporaryVariables");
        if (temporary == null)
        {
            temporary = new XElement("TemporaryVariables", new XAttribute("Type", "AbilityVariables"));
            ability.AddFirst(temporary);
        }
        else
        {
            temporary.SetAttributeValue("Type", temporary.Attribute("Type")?.Value ?? "AbilityVariables");
        }

        XElement? persistent = ability.Element("PersistentVariables");
        if (persistent == null)
        {
            persistent = new XElement("PersistentVariables", new XAttribute("Type", "AbilityVariables"));
            temporary.AddAfterSelf(persistent);
        }
        else
        {
            persistent.SetAttributeValue("Type", persistent.Attribute("Type")?.Value ?? "AbilityVariables");
        }

        XElement? nodes = ability.Element("Nodes");
        if (nodes == null)
        {
            nodes = new XElement("Nodes");
            persistent.AddAfterSelf(nodes);
        }

        XElement? connections = ability.Element("Connections");
        if (connections == null)
        {
            connections = new XElement("Connections");
            nodes.AddAfterSelf(connections);
        }
    }

    private static void SetTemplateText(XElement template, string field, string value)
    {
        XElement element = template.Element(field)
            ?? throw new InvalidDataException($"Template не содержит {field}.");
        element.Value = value;
    }

    private static string RequireOriginalTooltip(string localizationPath, int cardId)
    {
        string key = $"{cardId}_tooltip";
        string? cleanLocalizationPath = TryResolveCleanReferencePath(localizationPath, "ru-ru.csv");
        string? tooltip = cleanLocalizationPath is null
            ? null
            : LocalizationService.ReadValue(cleanLocalizationPath, key);

        if (string.IsNullOrWhiteSpace(tooltip)
            || tooltip.Contains("примените исходную способность", StringComparison.OrdinalIgnoreCase))
        {
            tooltip = LocalizationService.ReadValue(localizationPath, key);
        }

        if (string.IsNullOrWhiteSpace(tooltip)
            || tooltip.Contains("примените исходную способность", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                $"Исходное описание {key} не найдено в чистом ru-ru.csv. Операция остановлена, чтобы не дублировать или не сохранять текст-заглушку.");
        }

        LocalizationService.ValidateLocalizationValue(tooltip);
        return tooltip;
    }

    private static void RequireCard(CardRecord card, int expectedId)
    {
        if (card.Id != expectedId)
        {
            throw new InvalidOperationException(
                $"Операция 0.27.9 ожидает Card Id={expectedId}, но '{card.DebugName}' имеет Id={card.Id}.");
        }
    }

    private static void ValidateRecipe(SemanticCardPackRecipe recipe)
    {
        if (recipe.FormatVersion != 1)
            throw new InvalidDataException($"Неподдерживаемый FormatVersion={recipe.FormatVersion}.");
        if (recipe.Operations.Count == 0)
            throw new InvalidDataException("Semantic card pack не содержит operations.");
        foreach (SemanticCardPackOperationRecipe operation in recipe.Operations)
        {
            if (string.IsNullOrWhiteSpace(operation.Type))
                throw new InvalidDataException("Operation не содержит Type.");
            if (string.IsNullOrWhiteSpace(operation.Card))
                throw new InvalidDataException($"Operation {operation.Type} не содержит Card.");
        }
    }

    private static string BuildReport(
        SemanticCardPackRecipe recipe,
        SemanticCardPackPreview preview)
    {
        var builder = new StringBuilder();
        builder.AppendLine($"Semantic card pack: {recipe.Name}");
        builder.AppendLine($"Changed cards: {string.Join(", ", preview.ChangedCardIds)}");
        if (preview.AddedInjectableAbilityId.HasValue)
            builder.AppendLine($"Added InjectableAbility: {preview.AddedInjectableAbilityId}");
        builder.AppendLine();
        builder.AppendLine("Changes:");
        foreach (string change in preview.Changes)
            builder.AppendLine("  " + change);
        builder.AppendLine();
        builder.AppendLine("Validation:");
        foreach ((int cardId, GraphValidationReport report) in preview.Validation)
        {
            builder.AppendLine($"  {cardId}: errors={report.ErrorCount}, warnings={report.WarningCount}");
            foreach (ValidationIssue issue in report.Issues)
                builder.AppendLine($"    [{issue.Severity}] {issue.Code}: {issue.Message}");
        }
        builder.AppendLine();
        builder.AppendLine("Warnings:");
        foreach (string warning in preview.Warnings)
            builder.AppendLine("  " + warning);
        return builder.ToString();
    }
}
